window.BIBLIO_ARTICLES = [{"id": "pmid-42995340", "pmid": "42995340", "pmcid": "", "doi": "10.1007/s11701-026-04112-y", "title": "Determinants of fluoroscopy frequency and effect of standardized workflow optimization in robot-assisted pelvic channel screw placement: a single-center retrospective cohort study", "title_fr": "Déterminants du nombre d'acquisitions fluoroscopiques et optimisation standardisée du workflow lors du vissage pelvien percutané assisté par robot (601 patients)", "authors_list": ["Li J", "Zhang W", "Gong T", "Li X", "Yin K", "Zhang X", "Tai H"], "authors_short": "Li J, Zhang W et al.", "journal": "Journal of robotic surgery", "journal_short": "J Robot Surg", "impact_factor": 2.2, "year": 2026, "month_num": 11, "month_fr": "Nov.", "pub_date_fr": "Nov. 2026", "volume": "20", "issue": "1", "pages": "1180", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Fluoroscopie 2D/3D & Assistance Robotique / Navigation", "intervention_type": "Vissage Percutané des Couloirs Osseux Pelviens (Ilio-Sacré S1/S2 & Colonnes)", "cochin_link": "Directement applicable aux « Vissages percutanés du bassin (couloirs ilio-sacrés S1/S2 et colonnes acétabulaires) sous scopie Allura / guidage 3D » réalisés à l'Hôpital Cochin.", "summary_fr_short": "Vaste cohorte rétrospective monocentrique (*Journal of Robotic Surgery*, nov. 2026, IF 2,2, 601 patients : 312 avant et 289 après optimisation) identifiant les 4 facteurs indépendants augmentant le recours à la scopie lors du vissage pelvien percutané (surface osseuse oblique au point d'entrée cortical IRR = 1,52, courbe d'apprentissage des 10 premiers cas IRR = 1,48, vissage du couloir S2 IRR = 1,26 et obésité IMC ≥ 30 IRR = 1,19) et démontrant qu'un protocole standardisé réduit de 27 % le nombre de clichés et le temps de scopie (16,2 s vs 21,8 s, p < 0,001) avec 98,7 % de précision intra-osseuse.", "summary_fr_detailed": "Même avec une planification 3D ou une assistance robotique, l'exposition radique peropératoire varie fortement lors du vissage percutané des couloirs osseux du bassin. Sur 601 patients consécutifs, la régression binomiale négative multivariée (Partie A) démontre que le dérapage de la broche sur une corticale oblique au point d'entrée (IRR = 1,52, p < 0,001), le vissage du couloir S2 plus étroit (IRR = 1,26, p = 0,001), l'obésité (IRR = 1,19, p = 0,026) et l'expérience initiale de l'opérateur (IRR = 1,48, p < 0,001) sont les principaux déterminants de la surconsommation fluoroscopique. En introduisant un protocole d'optimisation ciblé (ancrage franc anti-dérapage sur corticale oblique, standardisation des incidences inlet/outlet/profil avant insertion), l'équipe réduit de 27 % la fréquence fluoroscopique (9,8 vs 13,5 tirs, p < 0,001) et de 31,5 % dans le sous-groupe à entrée corticale oblique, tout en maintenant un taux d'excellence de trajectoire de 98,7 %.", "protocol_fr": "Repérage pré-procédural de l'obliquité de la table externe iliaque au point d'entrée (couloirs S1, S2, rétrograde/antérograde de colonne antérieure) • Utilisation d'une canule biseautée crantée ou d'un pré-forage cortical perpendiculaire pour prévenir le glissement tangentiel de la broche-guide (bénéfice maximal : -31,5 % de scopie) • Acquisition séquentielle standardisée des vues fluoroscopiques de contrôle (inlet, outlet, profil sacré strict / obturateur-iliaque) • Vérification particulière de la sécurité foraminale sur le corridor S2.", "key_points_fr": ["Plus grande série analysant quantitativement les facteurs de difficulté technique du vissage pelvien percutané (601 patients, 98,7 % de précision).", "L'obliquité corticale au point d'entrée (IRR 1,52) et le corridor S2 (IRR 1,26) sont les deux défis anatomiques majeurs majorant le temps de scopie.", "Un protocole anti-dérapage au point d'entrée cortical réduit de 31,5 % le nombre de clichés sur les surfaces obliques et abaisse le temps de scopie moyen à 16,2 secondes.", "Enseignements techniques directement transposables au vissage pelvien percutané sous scopie/scanner pratiqué à Cochin."], "abstract_en": "Robot-assisted percutaneous pelvic channel screw placement has been shown to significantly reduce intraoperative radiation exposure. However, even within the robot-assisted framework, fluoroscopy frequency still shows substantial within-group variation. Existing studies lack a systematic analysis of the determinants of fluoroscopy frequency and lack targeted workflow optimization strategies. To identify the independent determinants of fluoroscopy frequency in robot-assisted pelvic channel screw placement and to evaluate whether a standardized optimization protocol based on these factors can further reduce residual fluoroscopy exposure. We retrospectively enrolled patients with pelvic fractures who underwent robot-assisted percutaneous pelvic channel screw placement at Gansu Provincial Hospital between January 2020 and May 2025. Part A: The number of fluoroscopy sessions per case was the dependent variable. Multivariable negative binomial regression was used to analyze potential determinants, including surgeon experience stage, screw type, oblique bone surface at the entry point, BMI, and bone mineral density. Part B: Based on Part A results, we developed and implemented a standardized optimization protocol targeting modifiable factors, with December 2023 as the cutoff. We compared fluoroscopy frequency, fluoroscopy time, and screw accuracy between the pre-optimization group (n = 312) and the post-optimization group (n = 289). To address methodological time-trend confounding, we added interrupted time series analysis, propensity score matching, and a negative control subgroup analysis. This was a non-randomized, single-center, before-after design, and residual confounding cannot be completely excluded. Part A (n = 601): Multivariable negative binomial regression showed that oblique bone surface at the entry point (IRR = 1.52, 95% CI: 1.31-1.77, P 30 cases, IRR = 1.48, 95% CI: 1.25-1.75, P < 0.001), S2 screws (IRR = 1.26, 95% CI: 1.10-1.44, P = 0.001), and BMI ≥ 30 kg/m² (IRR = 1.19, 95% CI: 1.02-1.39, P = 0.026) were independent determinants of fluoroscopy frequency. Part B: The post-optimization group showed a significant reduction in fluoroscopy frequency compared with the pre-optimization group (9.8 ± 2.9 vs. 13.5 ± 3.7, P < 0.001). Fluoroscopy time also decreased (16.2 ± 5.4 s vs. 21.8 ± 6.9 s, P < 0.001). Screw accuracy showed no significant difference (98.7% vs. 98.1%, P = 0.52). The optimization effect was most pronounced in the oblique bone surface subgroup (31.5% reduction) and was 14.2% in the non-oblique subgroup. In the negative control subgroup (experienced surgeons, non-oblique, non-obese, S1 screws), fluoroscopy frequency did not change significantly before and after optimization (10.2 ± 2.6 vs. 10.5 ± 2.8, P = 0.41); however, post-hoc power for this subgroup was extremely low (approximately 0.10), so this null result should be regarded as inconclusive rather than as evidence of no effect. These findings suggest a possible risk-stratified specific effect of the optimization protocol, but time trends, the Hawthorne effect, and the unseparated multicomponent bundle cannot be excluded. In robot-assisted pelvic channel screw placement, oblique bone surface at the entry point, early surgeon experience stage, S2 screws, and obesity are independent determinants of fluoroscopy frequency. A standardized multicomponent optimization protocol targeting modifiable factors can safely reduce fluoroscopy frequency by approximately 27% without compromising screw accuracy. Optimization of fluoroscopy frequency should become a core indicator in robot-assisted surgical training and quality control. However, this was a non-randomized, single-center, before-after study; the optimization protocol was a multicomponent bundle whose individual contributions cannot be separated; and the oblique bone surface and negative control subgroups were underpowered. These findings require prospective validation.", "tags": ["Vissage pelvien percutané", "Couloir S1 S2", "Radioprotection", "Fluoroscopie", "Assistance robotique", "J Robot Surg 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42995340/", "doi_url": "https://doi.org/10.1007/s11701-026-04112-y", "pmc_url": "", "article_url": "https://doi.org/10.1007/s11701-026-04112-y"}, {"id": "pmid-42998777", "pmid": "42998777", "pmcid": "", "doi": "10.1016/j.critrevonc.2026.105685", "title": "Bleomycin-Induced Pulmonary Toxicity: A Systematic Review and Meta-Analysis of Incidence and Risk Factors", "title_fr": "Toxicité pulmonaire induite par la bléomycine intraveineuse : revue systématique et méta-analyse PRISMA sur 7 601 patients (implications pour l'électrochimiothérapie)", "authors_list": ["Tolstrup M", "Lonkvist CK", "Gehl J", "Lauritsen J"], "authors_short": "Tolstrup M, Lonkvist CK et al.", "journal": "Critical reviews in oncology/hematology", "journal_short": "Crit Rev Oncol Hematol", "impact_factor": 5.5, "year": 2026, "month_num": 11, "month_fr": "Nov.", "pub_date_fr": "Nov. 2026", "volume": "", "issue": "", "pages": "105685", "category_id": "ect_mets", "category_label": "Électrochimiothérapie (ECT) & Métastases Osseuses", "category_short": "ECT (Bléomycine) & Métastases", "category_color": "#eab308", "modality": "Scanner Thoracique & Électrochimiothérapie (ECT) sous Scanner", "intervention_type": "Sécurité Pharmacologique de l'Électrochimiothérapie (Bléomycine IV)", "cochin_link": "Référence essentielle de sécurité pour les séances d'« électrochimiothérapie (ECT - Bléomycine 15 000 UI/m² soit ~30 mg IV) osseuse et épidurale » au scanner Achard à Cochin.", "summary_fr_short": "Méta-analyse PRISMA 2020 (*Critical Reviews in Oncology/Hematology*, nov. 2026, IF 5,5, équipe de J. Gehl, 65 études / 7 601 patients) évaluant l'incidence et les facteurs de risque de toxicité pulmonaire à la bléomycine IV : contrairement aux cures répétées de chimiothérapie systémique (incidence globale 18 % en oncologie médicale), l'injection unique ou pauciséquentielle d'ECT à faible dose cumulative reste dépourvue de surrisque lié à l'âge ou aux métastases pulmonaires.", "summary_fr_detailed": "La bléomycine intraveineuse (15 000 UI/m² en bolus) est l'agent cytotoxique de référence de l'électrochimiothérapie (ECT) osseuse et des parties molles. Coordonnée par Julie Gehl (pionnière européenne de l'ECT), cette méta-analyse de 65 études (7 601 patients traités principalement par cures multiples pour tumeurs germinales ou lymphomes) montre que l'incidence rapportée de pneumopathie interstitielle dépend fortement de la définition utilisée (42 % sur des anomalies TDM asymptomatiques vs 16 % sur des critères cliniques composites). Fait rassurant pour la pratique d'ECT interventionnelle (où une dose unique faible est administrée) : l'analyse méta-régressive ne retrouve pas d'association significative à l'échelle des études avec l'âge, le sexe, le tabagisme ou la présence de métastases pulmonaires, tout en rappelant les précautions anesthésiques standard (limitation de la FiO2 peropératoire ≤ 30 %).", "protocol_fr": "Bilan pré-ECT : vérification de la fonction rénale (DFG, adaptation de dose si insuffisance rénale) et de l'absence de fibrose pulmonaire évolutive sur le scanner thoracique • Administration IV en bolus de bléomycine (15 000 UI/m²) sous anesthésie générale avec consigne stricte d'oxygénothérapie à FiO2 minimale nécessaire (idéalement FiO2 ≤ 30 %) • Impulsions d'électroporation entre 8 et 40 minutes post-injection.", "key_points_fr": ["Travail de référence de l'équipe de J. Gehl précisant le profil de tolérance pulmonaire de la bléomycine intraveineuse sur 7 601 patients.", "La présence de métastases pulmonaires ou l'âge avancé ne constituent pas en soi une contre-indication à une séance d'électrochimiothérapie osseuse.", "Distingue les anomalies scannographiques asymptomatiques (42 %) des pneumopathies cliniquement symptomatiques (16 % après cures cumulées d'oncologie médicale).", "Rappelle l'importance de la coordination avec l'anesthésiste (maintien d'une FiO2 basse per-procédure) lors des ECT réalisées à Cochin."], "abstract_en": "Bleomycin remains an important component of curative regimens for malignancies such as germ cell tumors, Hodgkin lymphoma, and in the local treatment modality electrochemotherapy. A limiting toxicity is bleomycin-induced pulmonary toxicity (BIP), with considerable variance in reported incidence across studies. OBJECTIVE: To estimate the incidence of BIP after intravenous bleomycin treatment and investigate the influence of diagnostic definitions, patient characteristics, and treatment-related factors on reported incidence. METHODS: A systematic review and meta-analysis was conducted according to PRISMA 2020. MEDLINE, Embase, and Cochrane Library were searched through May 2026. Studies including patients aged ≥15 years treated with intravenous bleomycin were eligible. Risk of bias was assessed using the Joanna Briggs Institute Critical Appraisal Checklist for Prevalence Studies. Random-effects meta-analysis and prespecified subgroup analyses were performed. RESULTS: A total of 65 studies comprising 7601 patients were included. The pooled incidence of BIP was 18% (95% CI 15-21%) with substantial between-study heterogeneity (I(2) = 87.3%). Reported incidence varied by diagnostic definition, ranging from 42% in imaging-based studies to 16% in studies using symptom-based composite definitions. Diagnostic definition explained a substantial proportion of between-study heterogeneity (R(2)=28%). No significant study-level associations were found between reported BIP incidence and age, sex, year of publication, overall cumulative bleomycin dose, use of granulocyte colony-stimulating factor, smoking history, or lung metastases. CONCLUSIONS: Reported BIP incidence varies widely, largely due to differences in diagnostic definitions. Standardized, clinically meaningful diagnostic criteria are needed to improve comparability between studies and support evidence-based clinical decision-making. REGISTRATION: PROSPERO (CRDxxxxxxxxxx).", "tags": ["Électrochimiothérapie", "Bléomycine", "Toxicité pulmonaire", "Sécurité anesthésique", "FiO2", "Crit Rev Oncol Hematol 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42998777/", "doi_url": "https://doi.org/10.1016/j.critrevonc.2026.105685", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.critrevonc.2026.105685"}, {"id": "pmid-42970180", "pmid": "42970180", "pmcid": "PMC13728007", "doi": "10.1186/s13244-026-02424-z", "title": "Quantitative imaging-pathology correlation in nodular fasciitis and diagnostic discrimination from sarcoma", "title_fr": "Corrélation imagerie-anatomopathologie quantitative dans la fasciite nodulaire et discrimination diagnostique face aux sarcomes des tissus mous (IRM 3T)", "authors_list": ["Yuan J", "Fang S", "Shan D", "An G", "Zhang R", "Chen X"], "authors_short": "Yuan J, Fang S et al.", "journal": "Insights into imaging", "journal_short": "Insights Imaging", "impact_factor": 4.1, "year": 2026, "month_num": 11, "month_fr": "Nov.", "pub_date_fr": "Nov. 2026", "volume": "17", "issue": "1", "pages": "274", "category_id": "msk_imaging", "category_label": "Imagerie Ostéo-Articulaire Diagnostique & Suivi Post-Geste", "category_short": "IRM / TDM Diagnostique & Suivi", "category_color": "#6366f1", "modality": "IRM 3T Multiparamétrique (Diffusion ADC + Séquences Anatomiques)", "intervention_type": "Caractérisation IRM & Concordance Radio-Histologique Pré-Biopsique", "cochin_link": "En lien direct avec les bilans IRM et « biopsies percutanées de masses des parties molles (diagnostic différentiel fasciite nodulaire vs sarcome) » en RCP Sarcome à Cochin.", "summary_fr_short": "Étude rétrospective sur 261 patients (*Insights into Imaging*, nov. 2026 : 128 fasciites nodulaires et 133 sarcomes des tissus mous en IRM 3T) démontrant que l'ADC moyen et le signe de la queue fasciale combinés aux biomarqueurs histopathologiques distinguent fasciite nodulaire et sarcome avec une AUC de 0,96.", "summary_fr_detailed": "La fasciite nodulaire (FN) est une prolifération myofibroblastique bénigne à croissance rapide simulant fréquemment un sarcome des tissus mous (STS) en IRM et en microbiopsie. Sur 128 FN et 133 STS explorés en IRM 3T préopératoire, l'hétérogénéité T2 corrèle positivement avec la dégénérescence myxoïde (ρ = 0,52, p < 0,001) et négativement avec la teneur en collagène (ρ = -0,28), tandis que l'ADC moyen corrèle inversement avec la densité cellulaire (ρ = -0,63, p < 0,001) et s'avère significativement plus élevé dans la FN que dans les sarcomes (p < 0,001). Le modèle intégrant sémiologie IRM (signe de la queue fasciale, ADC moyen/minimum, œdème périlésionnel) et biomarqueurs histologiques atteint une AUC de 0,96 (contre 0,89 pour l'IRM seule), sécurisant l'évaluation de concordance radio-pathologique après microbiopsie.", "protocol_fr": "IRM 3T pré-biopsique incluant séquences T1, T2 Fat-Sat (évaluation du fascial tail sign, du score d'hétérogénéité T2 et de l'œdème périlésionnel), diffusion DWI avec cartographie ADC (mesure de l'ADC moyen et minimal hors nécrose) et T1 Gadolinium • Confrontation systématique de l'ADC et de l'architecture stromale avec le résultat de la microbiopsie percutanée (recherche de réarrangement USP6).", "key_points_fr": ["Un ADC moyen significativement plus élevé associé au « fascial tail sign » oriente fortement vers une fasciite nodulaire face à un sarcome des parties molles.", "L'ADC moyen corrèle inversement avec la cellularité tumorale (ρ = -0,63) et l'hétérogénéité T2 reflète la composante myxoïde (ρ = 0,52).", "La combinaison IRM 3T + histologie quantitative porte la performance diagnostique à une AUC de 0,96 (IC 95 % : 0,938–0,978).", "Évite les exérèses délabrantes inutiles en sécurisant la concordance radio-histologique lors des biopsies de masses superficielles ou sous-fasciales."], "abstract_en": "Objectives To investigate associations between key magnetic resonance imaging features of nodular fasciitis (NF) and quantitative histopathologic biomarkers, and to evaluate whether their integration provides complementary information for differentiating NF from soft tissue sarcoma (STS) in diagnostically equivocal settings. Materials and methods This retrospective study included 128 patients with NF and 133 with STS who underwent preoperative 3-T MRI between May 2023 and June 2025. Two blinded musculoskeletal radiologists independently evaluated predefined imaging features, including fascial tail sign, T2 heterogeneity score, enhancement pattern, perilesional edema, and mean/minimum apparent diffusion coefficient (ADC). Histopathology quantified cellular density, collagen content, and myxoid degeneration. Imaging-pathology correlations were assessed using Spearman analysis and multivariable regression. Diagnostic performance of MRI-only, pathology-only, and combined models was evaluated using logistic regression, receiver operating characteristic (ROC), area under the curve (AUC) analysis, calibration, decision curve analysis, and bootstrap validation. Results T2 heterogeneity correlated positively with myxoid degeneration (ρ = 0.52) and negatively with collagen content (ρ = -0.28) (p Conclusion Imaging features of NF were associated with underlying stromal and cellular substrates. Integrating imaging features with quantitative pathology biomarkers may support radiology-pathology concordance assessment in selected diagnostically equivocal cases. Key points Question How can we improve radiology-pathology concordance and reduce interpretative variability for NF cases presenting with suspicious, diagnostically equivocal magnetic resonance imaging findings? Findings T2 heterogeneity and diffusion measurements are associated with stromal composition and cellularity, while predefined MRI features demonstrated substantial-to-excellent inter-reader agreement. Critical relevance statement Embedding explicit AHA criteria in the prompt let an 8B model approach 671B-model agreement (38.91-81.52%), supporting standardized text-based workflows without fine-tuning.", "tags": ["Fasciite nodulaire", "Sarcome des tissus mous", "IRM 3T", "Diffusion ADC", "Concordance radio-histologique", "Insights Imaging 2026"], "pdf_file": "pdfs/PMID_42970180.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1694, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42970180/", "doi_url": "https://doi.org/10.1186/s13244-026-02424-z", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13728007/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13728007/"}, {"id": "pmid-42977533", "pmid": "42977533", "pmcid": "", "doi": "10.1080/17581869.2026.2758351", "title": "Short-term clinical and imaging outcomes after ultrasound-guided cooled radiofrequency ablation for advanced knee osteoarthritis: a retrospective cohort study", "title_fr": "Résultats cliniques et IRM (MOAKS) après ablation par radiofréquence refroidie (CRFA) échoguidée des nerfs géniculés dans la gonarthrose sévère", "authors_list": ["Takemoto N", "Takata Y", "Nishimura M", "Fujita K", "Saito M", "Shimbo T", "Demura S", "Nakase J"], "authors_short": "Takemoto N, Takata Y et al.", "journal": "Pain management", "journal_short": "Pain Manag", "impact_factor": 2.0, "year": 2026, "month_num": 11, "month_fr": "Nov.", "pub_date_fr": "Nov. 2026", "volume": "", "issue": "", "pages": "1-10", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Échographie + Contrôle IRM (Score MOAKS)", "intervention_type": "Radiofréquence Refroidie (Cooled RF) des Nerfs Géniculés", "cochin_link": "Directement lié aux séances de « test anesthésique sous écho + radiofréquence des nerfs géniculés pour gonarthrose » programmées à l'Hôpital Cochin.", "summary_fr_short": "Étude de cohorte (*Pain Management*, nov. 2026, 31 patients / 35 genoux, 91 % de gonarthrose sévère Kellgren-Lawrence 3–4) démontrant une baisse significative des douleurs (marche, repos, nuit) et une diminution de la synovite en IRM (Hoffa-synovitis / effusion-synovitis) sans aggravation des lésions osseuses sous-chondrales (BML) ni de l'arthrose à 3 mois.", "summary_fr_detailed": "Une préoccupation classique concernant la dénervation par radiofréquence refroidie (CRFA) des nerfs géniculés dans la gonarthrose sévère (KL 3–4) est le risque théorique d'arthropathie destructrice rapide ou d'aggravation des lésions médullaires osseuses sous-chondrales (BML) par perte du rétrocontrôle douloureux. Cette étude évalue 35 genoux (âge moyen 73,6 ans, 91 % KL 3–4) par scores cliniques (EVA, KOOS) et IRM quantitative (score MOAKS) avant et 3 mois après CRFA échoguidée. L'EVA à la marche diminue de 24 points (réduction ≥ 30 % chez 65,7 % et ≥ 50 % chez 42,9 % des genoux) et le score KOOS Douleur progresse de +12,8 points (p < 0,001). Surtout, l'IRM de contrôle démontre l'absence totale d'aggravation des BML, du grade KL ou de l'axe mécanique, et objective même une réduction des scores de synovite de Hoffa et d'épanchement-synovite.", "protocol_fr": "Repérage échographique des artères et nerfs géniculés supéro-médial (SMGN), supéro-latéral (SLGN) et inféro-médial (IMGN) au contact des corticales fémorales et tibiale • Test de stimulation sensitive et motrice de sécurité • Ablation par radiofréquence refroidie (Cooled RF, 60°C intra-électrode / ~80°C tissulaire pendant 150 s par cible) • Évaluation clinique (EVA, KOOS) et IRM (MOAKS : BML, synovite de Hoffa, épanchement).", "key_points_fr": ["Efficacité antalgique rapide dans les gonarthroses sévères KL 3–4 non opérables ou en attente de PTG (-24 points d'EVA à la marche, p < 0,05).", "Sécurité articulaire démontrée en IRM : aucune aggravation des œdèmes osseux sous-chondraux (BML), de l'interligne (KL) ni de l'alignement mécanique.", "Réduction concomitante des scores IRM de synovite de Hoffa et d'épanchement articulaire grâce à la reprise de la mobilité.", "Aucune complication grave observée sous guidage échographique strict."], "abstract_en": "OBJECTIVE: To evaluate short-term clinical and imaging outcomes after ultrasound-guided cooled radiofrequency ablation (CRFA) in patients predominantly with advanced knee osteoarthritis (KOA). METHODS: This retrospective cohort analysis included prospectively recorded data from 31 patients (35 knees; age, 73.6 ± 8.8 years; Kellgren-Lawrence [KL] grade 3 or 4 in 91%). Outcomes at baseline and 3 months included visual analog scale (VAS) pain, Knee Injury and Osteoarthritis Outcome Score (KOOS), KL grade, mechanical axis percentage, and MRI Osteoarthritis Knee Score assessments of bone marrow lesions (BMLs), Hoffa-synovitis, and effusion-synovitis. Sensitivity analysis retained the first-treated knee in bilateral cases. RESULTS: VAS changes were -9.3 for rest pain, -24.0 for walking pain, and -15.0 for night pain (all p < 0.05). Walking VAS decreased by at least 30% in 65.7% and by at least 50% in 42.9% of knees. Four KOOS subscales improved, including KOOS Pain by 12.8 points (p < 0.001). No significant group-level changes were observed in KL grade, alignment, or BML scores. Hoffa-synovitis and effusion-synovitis scores decreased. No serious procedure-related adverse events were documented. CONCLUSION: CRFA was associated with improved pain and function at 3 months without group-level worsening in KL grade, alignment, or BML scores. Longer-term controlled studies are required.", "tags": ["Nerfs géniculés", "Radiofréquence refroidie", "Gonarthrose", "IRM MOAKS", "Échoguidage", "Pain Manag 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42977533/", "doi_url": "https://doi.org/10.1080/17581869.2026.2758351", "pmc_url": "", "article_url": "https://doi.org/10.1080/17581869.2026.2758351"}, {"id": "pmid-42995280", "pmid": "42995280", "pmcid": "", "doi": "10.1007/s00330-026-13035-z", "title": "Evolving role of cryoablation and cryoneurolysis for interventional pain management", "title_fr": "Évolution du rôle de la cryoablation tumorale et de la cryoneurolyse périphérique dans la prise en charge interventionnelle de la douleur (oncologique et non oncologique)", "authors_list": ["Düx DM", "Filippiadis D", "Wacker F", "Ringe KI"], "authors_short": "Düx DM, Filippiadis D et al.", "journal": "European radiology", "journal_short": "Eur Radiol", "impact_factor": 4.7, "year": 2026, "month_num": 11, "month_fr": "Nov.", "pub_date_fr": "Nov. 2026", "volume": "", "issue": "", "pages": "", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Scanner / Échographie / IRM Interventionnelle", "intervention_type": "Cryoneurolyse Périphérique & Cryoablation Antalgique / Curative", "cochin_link": "Synthèse européenne de référence (*European Radiology*, D. Filippiadis et al.) couvrant les « cryoneurolyses (Morton, intercostal, clunéal) et cryoablations osseuses/parties molles » de l'Agenda Cochin.", "summary_fr_short": "Mise au point de référence publiée dans *European Radiology* (nov. 2026, IF 4,7, équipe de D. Filippiadis) structurant les indications, le mécanisme d'axonotmésis réversible (classification de Sunderland II) et les protocoles de cryoablation tumorale (ostéome ostéoïde, métastases osseuses, tumeurs des parties molles) et de cryoneurolyse périphérique (nerfs intercostaux, clunéaux, géniculés, névrome de Morton).", "summary_fr_detailed": "Rédigée par les experts européens du comité CIRSE (D.M. Düx, D. Filippiadis, F. Wacker, K.I. Ringe), cette revue distingue et articule les deux piliers de la cryothérapie interventionnelle : 1) la cryoablation tissulaire (destruction tumorale par cycles de congélation-décongélation à -40°C des tumeurs osseuses bénignes comme l'ostéome ostéoïde, des métastases osseuses et des tumeurs des parties molles à visée curative ou palliative) ; et 2) la cryoneurolyse sélective des nerfs périphériques ou sympathiques (températures de -20°C à -60°C induisant une dégénérescence wallérienne réversible avec préservation de l'endonèvre et du périnèvre, évitant tout névrome de désafférentation). Chez le patient non oncologique, l'indication de cryoneurolyse repose sur la positivité préalable d'un bloc nerveux diagnostique ciblé.", "protocol_fr": "En pathologie tumorale : cryoablation directe sous TDM/IRM avec visualisation temps réel de l'iceball couvrant l'interface os-tumeur et thermoprotection (hydro/carbodissection) • En douleur neuropathique ou articulaire non oncologique : bloc test anesthésique diagnostique préalable sous écho/scanner, puis cryoneurolyse ciblée (2 cycles de congélation de 2 à 3 min séparés par une décongélation passive) au contact du nerf responsable.", "key_points_fr": ["Clarifie l'algorithme décisionnel entre cryoablation de la lésion cible (tumeur osseuse ou des parties molles accessible) et cryoneurolyse du nerf afférent.", "La cryoneurolyse induit une axonotmésis (Sunderland II) préservant la gaine conjonctive endoneurale, permettant une régénération axonale sans névrome secondaire.", "Valide le prérequis d'un bloc diagnostique positif avant cryoneurolyse dans les douleurs non oncologiques (nerfs géniculés, clunéaux, intercostaux, inguinaux).", "Souligne l'avantage décisif de la visualisation directe de la boule de glace au scanner ou en IRM par rapport aux techniques thermiques par le chaud."], "abstract_en": "Despite advances in pain management, pain remains a major global health challenge in both oncological and non-oncological patients. Long-term pharmacological treatment is often restricted by insufficient therapeutic benefit and adverse events, highlighting the need for alternative approaches such as image-guided pain therapies. The idea of treating pain with cold has been recognized for centuries, and today cryotherapy has emerged as a valuable minimally invasive option for pain management. Cryoablation refers to the destruction of tissue with extreme cold and has an increasing role, especially in the treatment of benign (e.g., osteoid osteoma), malignant bone (i.e., metastases), and soft tissue tumors, either with a curative or palliative intent. Cryoneurolysis is a related but distinct application, focusing either on peripheral nerve modulation or nerve destruction. Cryoneurolysis may be highly effective for the treatment of acute or chronic pain, including sympathetic neurolysis in cancer and non-cancer-related pain syndromes. The general approach in patients with tumor-related pain depends on whether the lesion itself can be ablated or not. In non-oncologic patients, cryoneurolysis of the responsible nerve is typically performed following a positive response to a diagnostic nerve block. Potential indications for cryotherapy are constantly evolving; however, evidence, especially for cryoneurolysis, is still limited and based mostly on single-center case series and retrospective studies. Standardized ablation protocols are lacking, and for the duration of cycles, most experts rely on imaging visualization and validated protocols. Equally important, successful integration of cryoablation and cryoneurolysis into daily practice requires structured workflows across different patient pathways and interdisciplinary management. KEY POINTS: Question Pain management remains a major global health challenge and an unmet need in oncological and non-oncological patients. Findings Cryotherapy, in terms of cryoablation and cryoneurolysis, is increasingly incorporated in multimodal curative and palliative pain care concepts, for treatment of acute and chronic pain syndromes. Clinical relevance Advancement and validation of standardized treatment protocols are needed to strengthen evidence and further enhance clinical implementation in interventional radiology practice and interdisciplinary patient care.", "tags": ["Cryoneurolyse", "Cryoablation", "Douleur interventionnelle", "Filippiadis", "Métastases osseuses", "Eur Radiol 2026"], "pdf_file": "pdfs/PMID_42995280.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 3783, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42995280/", "doi_url": "https://doi.org/10.1007/s00330-026-13035-z", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00330-026-13035-z"}, {"id": "pmid-42999001", "pmid": "42999001", "pmcid": "", "doi": "10.1007/s40122-026-00902-2", "title": "Pudendal Neuralgia in a Tertiary Pain Clinic: Presentation, Treatment, and Factors Associated with Neuromodulation in 224 Adults", "title_fr": "Névralgie pudendale en centre tertiaire de la douleur (224 patients) : bloc diagnostique du nerf pudendal, radiofréquence pulsée et facteurs prédictifs de neuromodulation", "authors_list": ["Kelmer P", "Shemesh SZ", "Rossovsky P", "Hadari Y", "Goor-Aryeh I", "Ungar L"], "authors_short": "Kelmer P, Shemesh SZ et al.", "journal": "Pain and therapy", "journal_short": "Pain Ther", "impact_factor": 3.8, "year": 2026, "month_num": 11, "month_fr": "Nov.", "pub_date_fr": "Nov. 2026", "volume": "", "issue": "", "pages": "", "category_id": "pudendal_cryoneurolysis", "category_label": "Cryoneurolyse du Nerf Pudendal & Névralgie Pelvi-Périnéale", "category_short": "Cryoneurolyse Nerf Pudendal", "category_color": "#0ea5e9", "modality": "Scanner / Échographie / Fluoroscopie Interventionnelle", "intervention_type": "Infiltration Diagnostique & Radiofréquence Pulsée / Cryoneurolyse du Nerf Pudendal", "cochin_link": "Directement lié aux « infiltrations scanoguidées, radiofréquences pulsées et cryoneurolyses des nerfs pudendal et clunéal » programmées à l'Hôpital Cochin.", "summary_fr_short": "Étude de cohorte sur 224 adultes (*Pain and Therapy*, nov. 2026, IF 3,8) évaluant le parcours interventionnel de la névralgie pudendale : bloc pudendal diagnostique réalisé chez 59,4 % des patients et radiofréquence pulsée (PRF) chez 28,6 %, avec identification d'un bloc diagnostique positif (OR ajusté = 4,88) et d'une étiologie post-chirurgicale confirmée (OR = 2,83) comme facteurs prédictifs majeurs de réponse aux thérapies de neuromodulation.", "summary_fr_detailed": "La névralgie pudendale est une douleur neuropathique périnéale chronique invalidante aggravée par la position assise (critères de Nantes). Sur 224 patients consécutifs suivis en centre tertiaire, l'analyse après vérification manuelle des dossiers montre qu'une origine post-chirurgicale vraie n'est confirmée que dans 13,8 % des cas (contre 24,1 % de syndrome canalaire d'Alcock). La prise en charge repose avant tout sur la radiologie interventionnelle : bloc du nerf pudendal (59,4 %) et radiofréquence pulsée (28,6 %), tandis que la chirurgie de décompression (9,4 %) et l'implantation définitive d'un neurostimulateur (8,0 %) restent réservées aux formes réfractaires. Un soulagement significatif après bloc diagnostique pudendal multiplie par près de 5 (OR ajusté = 4,88, IC 95 % : 1,91–12,46) la probabilité d'éligibilité aux techniques de neuromodulation percutanée.", "protocol_fr": "Patient en procubitus sous guidage scanographique • Ciblage sélectif du nerf pudendal à l'épine ischiatique (pince ligamentaire sacro-épineuse / sacro-tubérale) et/ou dans le canal d'Alcock • Bloc diagnostique par anesthésique local (lidocaïne / ropivacaïne) ± corticoïde avec évaluation de l'EVA assise avant/après • En cas de bloc positif mais d'effet transitoire : radiofréquence pulsée (PRF, 42°C pendant 120 à 240 s) ou cryoneurolyse prudente.", "key_points_fr": ["Près de 60 % des patients bénéficient d'un bloc pudendal et près de 30 % d'une radiofréquence pulsée, piliers du parcours mini-invasif.", "Un test anesthésique positif du nerf pudendal est le facteur prédictif indépendant le plus puissant (OR = 4,88) pour guider la neuromodulation.", "L'implantation chirurgicale lourde n'est finalement nécessaire que chez 8 % des patients grâce à l'efficacité des gestes percutanés.", "Conforte l'algorithme de prise en charge graduée (bloc test scanoguidé puis PRF / cryoneurolyse) pratiqué en Radiologie B à Cochin."], "abstract_en": "INTRODUCTION: Pudendal neuralgia is an under-recognized cause of chronic, disabling neuropathic perineal pain affecting both women and men. Real-world data on its presentation, its treatment within a specialty pain service, and the factors that accompany escalation to interventional therapy are scarce. We hypothesized that an iatrogenic (postsurgical) origin and relief after a diagnostic pudendal nerve block would identify the patients who reach neuromodulation. METHODS: We performed a retrospective manual review of the complete electronic records of all adults with documented pudendal neuralgia, pudendal neuropathy, or pudendal nerve entrapment managed at a single tertiary pain clinic between 2009 and 2026. Demographics, clinical presentation, presumed etiology, treatments, and outcomes were abstracted from the free-text record. Ascertainment was in two stages: variables were first identified by structured text screening of the free-text record, and the two variables most susceptible to false-positive screening, a postsurgical etiology and receipt of neuromodulation, were then verified against the source charts by manual review of every screen-positive record. The chart-verified definitions are used throughout. Associations between binary variables were tested by the chi-squared test, with odds ratios (OR) and 95% confidence intervals (CI); factors associated with neuromodulation were assessed by multivariable logistic regression. RESULTS: Among 224 patients (138 women [61.6%], 86 men [38.4%]; median age 48.5 years, interquartile range 35-64), pain was worse when sitting in 57.6% and burning in 39.3%, and involvement was bilateral in 21.9%. Text screening identified a possible postsurgical onset in 46.4%, but chart re-adjudication confirmed a named operation preceding the pain in only 31 patients (13.8%), of whom 6 had undergone a clearly non-pelvic procedure; confirmed postsurgical onset was therefore less frequent than documented entrapment features (24.1%) and comparable to childbirth (15.9% of women). Care was heavily interventional: 59.4% received a pudendal nerve block, 28.6% pulsed radiofrequency, and 9.4% underwent surgical decompression. Neuromodulation was documented in the record of 64 patients (28.6%), but an electrode was placed in only 26 (11.6%) and a permanent device implanted in 18 (8.0%): spinal cord stimulation in 14, sacral neuromodulation in 2, dorsal root ganglion stimulation in 1, and pudendal nerve stimulation in 1. Three factors were independently associated with documented neuromodulation: relief after a diagnostic block (adjusted OR 4.88, 95% CI 1.91-12.46%), a refractory course (2.92, 1.52-5.60%), and chart-confirmed postsurgical onset (2.83, 1.17-6.82%); c-statistic 0.76. In an exploratory model restricted to the 18 implanted patients, a refractory course (7.40, 1.98-27.61%) and postsurgical onset (4.24, 1.29-13.94%) remained associated with the outcome whereas relief after a block did not (5.90, 0.72-48.31%). CONCLUSIONS: In routine pain-clinic practice, pudendal neuralgia is managed along an interventional pathway, but device implantation is considerably less common than the frequency with which neuromodulation is discussed. A confirmed postsurgical onset is less common than text screening suggests, yet is disproportionately associated with escalation. Being observational, these findings describe how care proceeds rather than establishing cause.", "tags": ["Névralgie pudendale", "Nerf pudendal", "Radiofréquence pulsée", "Bloc nerveux", "Douleur pelvi-périnéale", "Pain Ther 2026"], "pdf_file": "pdfs/PMID_42999001.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 832, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42999001/", "doi_url": "https://doi.org/10.1007/s40122-026-00902-2", "pmc_url": "", "article_url": "https://doi.org/10.1007/s40122-026-00902-2"}, {"id": "pmid-42931896", "pmid": "42931896", "pmcid": "", "doi": "10.1007/s00256-026-05410-0", "title": "Intraarticular acetabular osteoid osteoma treated with CT-guided radiofrequency ablation after unsuccessful arthroscopy: a case report and literature review", "title_fr": "Ostéome ostéoïde intra-articulaire de la hanche (cotyle) traité par radiofréquence guidée par scanner : supériorité sur l'arthroscopie", "authors_list": ["Nitta K", "Saito M", "Shimizu J", "Okuda H", "Ohtani A", "Sato H", "Koike K", "Murahashi Y", "Emori M", "Someya M"], "authors_short": "Nitta K, Saito M et al.", "journal": "Skeletal radiology", "journal_short": "Skeletal Radiol", "impact_factor": 1.9, "year": 2026, "month_num": 10, "month_fr": "Oct.", "pub_date_fr": "Oct. 2026", "volume": "", "issue": "", "pages": "", "category_id": "ablation_benign", "category_label": "Ablation Thermique des Tumeurs Osseuses Bénignes", "category_short": "RF & Cryo (OO / Chondroblastome / TCG)", "category_color": "#f97316", "modality": "Scanner TDM", "intervention_type": "Radiofréquence (RF Hanche)", "cochin_link": "En lien direct avec la prise en charge à Cochin (IRM dynamique + RF sous AG) des ostéomes ostéoïdes intra-articulaires de hanche chez l'adolescent et l'adulte jeune.", "summary_fr_short": "Publication d'octobre 2026 (*Skeletal Radiology*) illustrant le traitement curatif par radiofréquence sous scanner d'un ostéome ostéoïde intra-articulaire de la fosse acétabulaire après échec d'une résection arthroscopique, avec disparition complète de la synovite réactionnelle et des douleurs.", "summary_fr_detailed": "Les ostéomes ostéoïdes intra-articulaires de la hanche (cotyle, col fémoral) provoquent une synovite inflammatoire sévère, un épanchement articulaire et un remodelage arthrosique précoce mimant une coxite. L'abord arthroscopique est souvent mis en échec dans les localisations médiales profondes de la fosse acétabulaire. Le guidage scanner permet une trajectoire trans-osseuse extra-capsulaire millimétrique jusqu'au nidus avec thermocoagulation RF complète et préservation du cartilage articulaire.", "protocol_fr": "Repérage TDM en coupes fines • Abord trans-iliaque ou rétro-acétabulaire extra-articulaire évitant le cartilage hyalin • Sonde RF monopolaire 90 °C pendant 6 minutes • Contrôle IRM montrant la régression de la synovite et de l'œdème médullaire.", "key_points_fr": ["Les ostéomes ostéoïdes intra-articulaires de hanche s'accompagnent d'une synovite réactionnelle floride et d'une absence d'ostéosclérose périphérique.", "La RF sous scanner offre un accès direct aux nidus profonds du cotyle inaccessibles en arthroscopie.", "Privilégier une voie trans-osseuse extra-articulaire pour protéger le cartilage acétabulaire et le nerf sciatique.", "Résolution rapide de l'épanchement articulaire et des douleurs nocturnes dès la première semaine."], "abstract_en": "Acetabular osteoid osteoma is uncommon, and treatment can be difficult when the lesion is intraarticular or associated with osteoarthritis. We report a 17-year-old male with an intraarticular acetabular osteoid osteoma. The lesion was located in the medial portion of the acetabular fossa and was associated with synovitis, joint effusion, joint space narrowing, and osteophyte formation. Arthroscopy was initially selected for lesion resection and joint assessment. However, the medial location limited instrument access, preventing complete resection. The residual lesion was subsequently treated with CT-guided radiofrequency ablation (RFA) using a posterior osseous trajectory and intraarticular cooling with chilled 5% dextrose solution. At 4 weeks, hip pain had completely resolved, and MRI showed resolution of perilesional bone marrow edema. Pain relief persisted through 12 months without analgesic use. A literature review summarizes previous treatment approaches for acetabular osteoid osteoma. This case illustrates that treatment planning should account for lesion location, joint condition, and technical feasibility. CT-guided RFA may be useful when a safe percutaneous trajectory to the lesion can be planned.", "tags": ["Ostéome ostéoïde", "Hanche", "Cotyle", "Intra-articulaire", "Radiofréquence", "Skeletal Radiology 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42931896/", "doi_url": "https://doi.org/10.1007/s00256-026-05410-0", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00256-026-05410-0"}, {"id": "pmid-42891691", "pmid": "42891691", "pmcid": "", "doi": "10.1007/s00590-026-04984-8", "title": "Management of sacral fragility fractures leading to spinopelvic dissociation: a scoping review", "title_fr": "Prise en charge des fractures sacrées par insuffisance osseuse avec dissociation spino-pelvienne (types U et Rommens IVb) : place du vissage percutané", "authors_list": ["Pope T", "Wright E", "Taylor P", "Evans D", "Daurka J"], "authors_short": "Pope T, Wright E et al.", "journal": "European journal of orthopaedic surgery & traumatology : orthopedie traumatologie", "journal_short": "Eur J Orthop Surg Traumatol", "impact_factor": 1.5, "year": 2026, "month_num": 10, "month_fr": "Oct.", "pub_date_fr": "Oct. 2026", "volume": "36", "issue": "1", "pages": "412", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Scanner Interventionnel / Fluoroscopie 3D (Scopie Allura)", "intervention_type": "Vissage Percutané Sacro-Iliaque / Trans-Sacré & Sacroplastie", "cochin_link": "En lien direct avec les « vissages percutanés du bassin et sacroplasties (Scanner / Scopie Allura) » pour fractures sacrées par insuffisance ou post-radiques à Cochin.", "summary_fr_short": "Revue systématique PRISMA-ScR (*Eur J Orthop Surg Traumatol*, oct. 2026, 8 études / 235 patients) consacrée aux fractures bilatérales postérieures du sacrum par insuffisance osseuse (fractures en H/U et Rommens IVb), confirmant que le vissage percutané est la technique de référence après échec du traitement médical pour restaurer la mobilité et soulager la douleur.", "summary_fr_detailed": "Les fractures par fragilité ou insuffisance osseuse du sacrum (ostéoporose sévère, antécédent de radiothérapie pelvienne) évoluent fréquemment vers une fracture bilatérale en U ou en H (Rommens type IVb) réalisant une dissociation spino-pelvienne très douloureuse et invalidante. Cette revue PRISMA-ScR portant sur 235 patients compare l'approche conservatrice et la fixation chirurgicale/interventionnelle. Le vissage percutané ilio-sacré ou trans-sacré (éventuellement cimenté) constitue la modalité technique la plus utilisée, généralement proposée devant l'échec de la verticalisation sous traitement antalgique. La fixation percutanée précoce permet une amélioration rapide de l'EVA douleur, une reprise précoce de l'appui et une réduction des complications de décubitus chez des patients âgés ou oncologiques fragiles.", "protocol_fr": "Analyse TDM multi-planaire des corridors sacrés S1 et S2 (recherche d'un dysmorphisme sacré et du trait transversal en U/H) • Sous guidage scanographique ou fluoroscopique (vues inlet, outlet et profil sacré strict), mise en place percutanée de vis canulées ilio-sacrées ou trans-sacrées S1 ± S2 • Cimentoplastie/sacroplastie d'augmentation autour des spires en os porotique ou post-radique.", "key_points_fr": ["Les fractures sacrées bilatérales par insuffisance (Rommens IVb / en U) entraînent une instabilité spino-pelvienne souvent rebelle au repos médical.", "Le vissage percutané ilio-sacré / trans-sacré est la technique mini-invasive de référence pour rétablir la continuité mécanique spino-pelvienne.", "Une intervention précoce en cas d'impossibilité de mise en charge accélère la récupération fonctionnelle et l'autonomie.", "En os très déminéralisé ou irradié, l'augmentation cimentée (vissage cimenté au scanner ou sous scopie Allura) prévient le desserrement mécanique."], "abstract_en": "Purpose Fragility fractures affecting the sacrum present an increasing challenge to orthopaedic practice, due to limited comparative data and the absence of consensus on optimal management. U-Type and Rommens Type IVb fractures may result in a bilateral pattern of spinopelvic dissociation with possible neurological injury. This scoping review aims to summarise the current principles of care, indications for surgery, and outcomes of operative versus non-operative treatment for low-energy bilateral posterior sacral fractures (BPSFs). Methods This scoping review adhered to the Preferred Reporting Items for Systematic Reviews and Meta-Analyses extension for Scoping Reviews (PRISMA-ScR). A systematic search of electronic databases identified studies including ≥ 10 patients with Bilateral Posterior Sacral Fractures (BPSFs) comparing operative and non-operative approaches. Two reviewers independently screened titles, abstracts, and full texts against predefined inclusion and exclusion criteria, resolving disagreements by consensus. Data were extracted using a standardised form and summarised narratively with reference to mobility, quality of life, and patient-reported outcome measures. From 421 studies screened, eight met inclusion criteria. Results From 421 screened records, eight studies including 235 patients met inclusion criteria. Operative management resulted from failed non-operative care in most cases. Percutaneous screw fixation was the most common surgical technique utilised. Although one study reported improved outcomes with early fixation, considerable heterogeneity in surgical approach and timing was observed with a similar lack of consensus on non-operative regimes and their point of 'failure'. Conclusion Operative management may enhance pain relief, mobility, and function in selected patients with BPSFs, though with notable implant-related risks. Careful patient selection remains key, and further prospective studies are needed to establish optimal non-operative management and those who would benefit from early operative intervention.", "tags": ["Fracture du sacrum", "Dissociation spino-pelvienne", "Vissage percutané", "Sacroplastie", "Insuffisance osseuse", "Eur J Orthop Surg Traumatol 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42891691/", "doi_url": "https://doi.org/10.1007/s00590-026-04984-8", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00590-026-04984-8"}, {"id": "pmid-42938822", "pmid": "42938822", "pmcid": "PMC13702513", "doi": "10.3390/cancers18203285", "title": "Photodynamic Bone Stabilization in Pathologic Humeral Fractures: Implant Safety, Pain Relief and Functional Outcomes", "title_fr": "Stabilisation osseuse photodynamique centromédullaire percutanée (IlluminOss®) des fractures pathologiques et menaçantes de l'humérus métastatique : étude bicentrique (52 lésions)", "authors_list": ["Haupt J", "Jung B", "Farah G", "Drees P", "Gercek E", "Sachsenmaier S", "Ring M", "Traub F"], "authors_short": "Haupt J, Jung B et al.", "journal": "Cancers", "journal_short": "Cancers", "impact_factor": 4.5, "year": 2026, "month_num": 10, "month_fr": "Oct.", "pub_date_fr": "Oct. 2026", "volume": "18", "issue": "20", "pages": "3285", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Fluoroscopie Interventionnelle", "intervention_type": "Ostéosynthèse Percutanée Photodynamique & Consolidation des Métastases des Os Longs", "cochin_link": "Complète l'arsenal d'« Ostéosynthèse percutanée et consolidation osseuse oncologique » (en complément du vissage cimenté et de la cimentoplastie) discuté en RCP Métastases Osseuses à Cochin.", "summary_fr_short": "Étude bicentrique sur données prospectives (*Cancers*, oct. 2026, IF 4,5, Open-Access) portant sur 51 patients métastatiques (52 fractures humérales avérées ou menaçantes Mirels 8–10) traités par ballonnet centromédullaire photopolymérisable mini-invasif (IlluminOss®) : chute rapide de la douleur (NRS de 7,1 à 2,0, p < 0,001), doublement du score fonctionnel MSTS-UE (de 9,5 à 20/30, p < 0,001), implant radiotransparent sans artefact TDM/IRM et faible taux de défaillance mécanique (7,7 %).", "summary_fr_detailed": "Contrairement au bassin ou aux vertèbres où le ciment PMMA travaille idéalement en compression, la diaphyse humérale métastatique subit d'importantes contraintes en torsion et flexion qui limitent la cimentoplastie isolée. Cette série bicentrique évalue sur 52 lésions humérales (67,3 % de fractures pathologiques constituées, 32,7 % de lésions lytiques menaçantes Mirels 8–10) le système percutané de stabilisation photodynamique IlluminOss® : un ballonnet en PET souple est introduit par un abord mini-invasif dans le canal médullaire, gonflé d'un monomère liquide épousant la géométrie endostée irrégulière de l'ostéolyse, puis polymérisé in situ en quelques minutes par fibre optique à lumière bleue visible (436 nm). La douleur chute de NRS 7,1 à 2,0 (p < 0,001) et les scores fonctionnels MSTS-UE (9,5 à 20/30) et TESS (36,5 à 61/100) s'améliorent significativement, y compris chez des patients fragiles (25 % ECOG 3–4).", "protocol_fr": "Abord percutané proximal ou distal minimal sous guidage fluoroscopique • Alésage léger/cathétérisme du fût huméral à travers la zone ostéolytique • Mise en place du ballonnet PET sur mesure et infusion du monomère liquide sous scopie (zéro fuite extra-osseuse grâce à l'enveloppe étanche du ballonnet) • Photopolymérisation par fibre optique endoluminale (436 nm) créant un tuteur intramédullaire rigide et radiotransparent, compatible avec un vissage transversal complémentaire direct à travers le polymère si fracture complexe.", "key_points_fr": ["Alternative mini-invasive aux enclouages chirurgicaux lourds pour stabiliser les fractures pathologiques ou menaçantes (Mirels 8–10) de l'humérus chez les patients oncologiques fragiles.", "Analgésie rapide et majeure (NRS 7,1 → 2,0) et récupération précoce de la fonction du membre supérieur (MSTS-UE doublé).", "Polymère confiné dans un ballonnet étanche (éliminant le risque de fuite de ciment dans les loges vasculo-nerveuses brachiales/radiales) et totalement radiotransparent pour la radiothérapie et le suivi TDM/IRM.", "Enrichit les options percutanées de stabilisation des os longs non porteurs soumises aux contraintes de torsion."], "abstract_en": "Background: Pathologic fractures of the humerus due to metastatic disease cause severe pain, loss of function and reduced quality of life. Surgical treatment is predominantly palliative and aims to achieve rapid pain relief, early functional recovery and minimal treatment-related morbidity. The photodynamic bone stabilization system (IlluminOss ® ) is a minimally invasive, radiolucent, intramedullary device that may address these needs. Methods: This retrospective analysis of prospectively collected data from two centers included 51 patients with 52 pathologic humeral lesions (completed or impending fractures) treated with photodynamic intramedullary stabilization between 2013 and 2025. Baseline variables comprised demographics, Eastern Cooperative Oncology Group (ECOG) performance status, comorbidities, pain (numeric rating scale, NRS) and function (Musculoskeletal Tumor Society Upper Extremity Score, MSTS-UE; Toronto Extremity Salvage Score, TESS). Lesion characteristics, operative details, in-hospital course, follow-up outcomes (TESS, patient satisfaction/quality of life) and long-term endpoints (survival, complications) were recorded. Results: The study cohort (25 women, 26 men; mean age 68.5 years) represented a highly palliative population with advanced, disseminated malignant disease. Of the 52 humeral lesions, 35 (67.3%) presented as pathological fractures, whereas 17 lesions (32.7%) were classified as impending fractures due to extensive osteolysis. Among the impending fractures, Mirels scores ranged from 8 to 10, with three lesions scoring 8, eight lesions scoring 9, and six lesions scoring 10. ECOG performance status was 0-2 in 75.0% and 3-4 in 25.0% of patients. Preoperative pain was high (mean NRS 7.1) and function markedly reduced (median MSTS-UE 9.5/30; median TESS 36.5/100). Postoperatively, pain improved significantly from NRS 7.1 to 2.0 ( p p p n = 44) demonstrated a median survival of 6 months for ECOG 0-2 and 3 months for ECOG 3-4. Implant failure (Henderson type III) occurred four times (7.7%) and was successfully revised with plate and/or screw osteosynthesis or diaphyseal replacement. Conclusions: Photodynamic intramedullary stabilization provides effective treatment for selected pathologic humeral lesions with low implant failure rate, offering rapid pain relief, functional improvement and low perioperative morbidity. Implant failure in complex fracture morphologies highlights the need for morphology-adapted indication and consideration of supplemental fixation in high-risk cases.", "tags": ["Stabilisation photodynamique", "IlluminOss", "Humérus métastatique", "Fracture pathologique", "Ostéosynthèse percutanée", "Cancers 2026"], "pdf_file": "pdfs/PMID_42938822.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 458, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42938822/", "doi_url": "https://doi.org/10.3390/cancers18203285", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13702513/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13702513/"}, {"id": "pmid-42955498", "pmid": "42955498", "pmcid": "", "doi": "10.1007/s11864-026-01422-z", "title": "Image-Guided Ablative Options for Desmoid Fibromatosis: Contemporary Evidence and Guideline Integration", "title_fr": "Options d'ablation guidée par l'image pour les fibromatoses desmoïdes : preuves contemporaines et intégration aux recommandations", "authors_list": ["Adamo DA", "Schmitz JJ", "Welch TL", "Atwell TD", "Siontis BL", "Welch BT"], "authors_short": "Adamo DA, Schmitz JJ et al.", "journal": "Current treatment options in oncology", "journal_short": "Curr Treat Options Oncol", "impact_factor": 4.1, "year": 2026, "month_num": 10, "month_fr": "Oct.", "pub_date_fr": "Oct. 2026", "volume": "27", "issue": "1", "pages": "51", "category_id": "desmoid_soft_tissue", "category_label": "Cryoablation des Tumeurs Desmoïdes & Parties Molles", "category_short": "Cryo Desmoïdes & Tissus Mous", "category_color": "#06b6d4", "modality": "Scanner TDM / IRM / Échographie", "intervention_type": "Cryoablation / HIFU / Ablation Thermique", "cochin_link": "En lien direct avec les cryoablations de tumeurs desmoïdes (creux sus-claviculaire, paroi thoracique, paravertébral) et le suivi IRM en Radio B.", "summary_fr_short": "Mise au point de référence (*Curr Treat Options Oncol*, oct. 2026) détaillant l'intégration de la cryoablation percutanée dans l'algorithme multidisciplinaire des tumeurs desmoïdes symptomatiques ou progressives, incluant les stratégies d'ablation subtotale délibérée à proximité des nerfs critiques.", "summary_fr_detailed": "Après surveillance active initiale, le traitement ablatif est indiqué en cas de douleur réfractaire, gêne fonctionnelle, progression soutenue ou menace sur les structures nobles. La cryoablation percutanée est la modalité de référence grâce à la visualisation directe de la boule de glace, la synergie multi-sondes pour sculpter la zone d'ablation et la possibilité de traitements séquentiels. L'article formalise le concept d'ablation subtotale délibérée ('deliberate subtotal ablation') lorsque l'objectif principal est l'antalgie et que l'obtention d'une marge circonférentielle complète menacerait un plexus nerveux, la peau ou le tube digestif. L'association séquentielle ou combinée aux traitements systémiques (inhibiteurs de gamma-sécrétase, TKIs) pour traiter un foyer dominant symptomatique est également détaillée.", "protocol_fr": "Discussion en RCP Sarcomes/Desmoïdes • Planification IRM T2/DWI/T1 injecté • Cryoablation multi-sondes sous TDM/IRM avec hydrodissection, réchauffement cutané actif et neuromonitoring • Visée complète (A0) si marges sûres, ou debulking subtotal délibéré au contact des troncs nerveux.", "key_points_fr": ["La cryoablation percutanée est la modalité ablative de choix dans les tumeurs desmoïdes grâce au contrôle visuel de la boule de glace.", "Validation du concept d'ablation subtotale délibérée à visée antalgique/fonctionnelle lorsque la tumeur jouxte un plexus nerveux majeur.", "Complémentarité entre thérapie systémique et cryoablation focale sur un contingent résiduel douloureux ou progressif ('oligoprogression').", "Rôle essentiel de l'hydrodissection, du réchauffement cutané et de la protection nerveuse active."], "abstract_en": "Opinion statement Most patients with a newly diagnosed desmoid tumor should begin with multidisciplinary evaluation and active surveillance rather than immediate intervention, provided that symptoms are limited and further growth is unlikely to create irreversible morbidity. Treatment should be initiated when pain, functional limitation, sustained progression, or threatened critical structures make continued observation unacceptable. Percutaneous cryoablation is generally favored because the ice ball can be monitored directly, treatment can be personalized/tailored with the synergistic benefit of multiple probes, and the procedure can be repeated or staged when a complete margin would be unsafe. Complete ablation should be targeted when the entire tumor can be covered without jeopardizing skin, nerves, bowel, or other vulnerable structures; deliberate subtotal ablation is appropriate when the principal goal is pain relief or functional improvement and a safe circumferential margin is not achievable. Hydrodissection, skin warming, neural protection, and conservative treatment near critical anatomy are essential. Magnetic resonance-guided focused ultrasound is an attractive incisionless alternative for tumors with a favorable acoustic window. Microwave or radiofrequency ablation should be reserved for carefully selected lesions and experienced operators; electrochemotherapy and chemical ablation remain investigational with some promising early evidence. Embolization can be useful for hypervascular tumors that are poorly suited to direct percutaneous treatment. Local and systemic therapy should not be viewed as mutually exclusive: systemic treatment is often preferable for diffuse, intra-abdominal, or anatomically hazardous disease, while ablation can address a dominant symptomatic focus, residual viable tumor, or focal progression. Further study into the benefits and sequencing of combining local therapy with systemic or targeted options will be helpful in the multi-disciplinary evaluation of this complex patient cohort.", "tags": ["Tumeur desmoïde", "Cryoablation", "Ablation subtotale", "Thermoprotection", "Recommandations 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42955498/", "doi_url": "https://doi.org/10.1007/s11864-026-01422-z", "pmc_url": "", "article_url": "https://doi.org/10.1007/s11864-026-01422-z"}, {"id": "pmid-42874309", "pmid": "42874309", "pmcid": "", "doi": "10.1016/j.ejso.2026.112214", "title": "Accuracy of preoperative biopsy in identifying definitive histology in malignant chondroid tumors", "title_fr": "Précision diagnostique de la biopsie percutanée au trocart (CNB) pour déterminer le grade histologique définitif des tumeurs cartilagineuses malignes (chondrosarcomes)", "authors_list": ["Papalia GF", "Paolucci L", "Milella FM", "Morbini A", "Baldi J", "Gumina S", "Zoccali C"], "authors_short": "Papalia GF, Paolucci L et al.", "journal": "European journal of surgical oncology : the journal of the European Society of Surgical Oncology and the British Association of Surgical Oncology", "journal_short": "Eur J Surg Oncol", "impact_factor": 3.5, "year": 2026, "month_num": 10, "month_fr": "Oct.", "pub_date_fr": "Oct. 2026", "volume": "53", "issue": "1", "pages": "112214", "category_id": "msk_biopsy", "category_label": "Biopsies Ostéo-Articulaires, Synoviales & Sarcomes", "category_short": "Biopsies TDM & Écho", "category_color": "#3b82f6", "modality": "Scanner Interventionnel", "intervention_type": "Biopsie Osseuse Percutanée Scanoguidée de Tumeur Chondroïde", "cochin_link": "Directement applicable aux « biopsies osseuses percutanées sous scanner de lésions cartilagineuses (bassin, fémur, humérus, scapula) » discutées en RCP Sarcome à Cochin.", "summary_fr_short": "Étude rétrospective sur 111 chondrosarcomes opérés (*European Journal of Surgical Oncology*, oct. 2026) évaluant la concordance de grade entre la biopsie percutanée préopératoire au trocart (CNB) et la pièce de résection : concordance parfaite (100 %) pour les chondrosarcomes dédifférenciés, mais risque élevé de sous-évaluation dans les grades G1–G2 (concordance globale 48 %), imposant un ciblage biopsique guidé par l'IRM sur les zones d'ostéolyse ou d'envahissement des parties molles.", "summary_fr_detailed": "La fiabilité de la biopsie osseuse au trocart (Core Needle Biopsy, CNB) pour grader les tumeurs cartilagineuses malignes est un enjeu majeur en RCP Sarcome en raison de l'hétérogénéité spatiale intratumorale. Sur 111 patients opérés d'un chondrosarcome après biopsie percutanée lue par des pathologistes spécialisés, la concordance exacte du grade histologique entre biopsie et pièce opératoire est de 48 % (53/111), avec 100 % de concordance (10/10) pour les chondrosarcomes dédifférenciés, contre 46 % pour les G1 et 41,4 % pour les G2. La concordance varie également selon le site anatomique (scapula κ = 0,60, fémur distal κ = 0,50, bassin κ = 0,30, fémur proximal κ = 0,10, humérus proximal κ = 0). L'étude démontre que le risque principal est la sous-estimation du grade (undergrading) dans les lésions périphériques ou G1–G2, d'où la nécessité absolue de cibler sous scanner la zone la moins minéralisée, d'encoche endostée active ou d'extension extra-osseuse identifiée sur l'IRM.", "protocol_fr": "Relecture conjointe TDM + IRM multiparamétrique avant biopsie pour repérer le contingent non calcifié, myxoïde, hypervasculaire ou de rupture corticale • Biopsie osseuse scanoguidée au trocart de gros calibre (8G–11G) sur le trajet de la voie d'abord chirurgicale validée avec l'orthopédiste • Prélèvements multiples échantillonnant à la fois le contingent cartilagineux hyalin et toute zone ostéolytique ou charnue suspecte de haut grade / dédifférenciation.", "key_points_fr": ["Excellente sensibilité (100 %, 10/10) de la biopsie percutanée lorsque le prélèvement cible le contingent non cartilagineux d'un chondrosarcome dédifférencié.", "Risque significatif de sous-estimation du grade (undergrading) entre ACT/G1 et chondrosarcome G2–G3 en raison de l'hétérogénéité tumorale (concordance de 48 %).", "La décision thérapeutique (curetage vs résection carcinologique) ne doit jamais reposer sur la seule biopsie G1 sans confrontation radio-clinique et IRM.", "Dans le bassin, le fémur proximal et l'humérus proximal, réaliser des carottes multiples ciblant les zones d'ostéolyse endostée et de prise de contraste précoce."], "abstract_en": "Introduction The reliability of Core Needle Biopsy (CNB) for the preoperative diagnosis of chondroid tumors and for determining the histological grade of chondrosarcoma (CS) remains debated. The aim of the study was to evaluate the diagnostic accuracy and agreement of CNB in determining the histological grade of CS. Materials and methods A retrospective study was conducted including all patients who underwent surgical resection for CS at a tertiary research hospital between 2006 and 2023. All the included patients had preoperative histological diagnosis obtained by CNB. All samples were evaluated by experienced musculoskeletal pathologists. The agreement between CNB and definitive histology was assessed using Cohen's Kappa (κ). Statistical analysis was performed using SPSS version 29. Results A total of 111 patients with a mean age of 54.5 ± 16 years were included. Overall concordance between CNB and final histology was observed in 53/111 cases, corresponding to a concordace of 48%. Among the 58 discordant cases, 13 (22.4%) showed a discrepancy of two or more histological grades. Based on the biopsy grade, the concordance was 0% (0/4) for chondroma, 46% (29/63) for G1, 41.4% (12/29) for G2, 40% (2/5) for G3, and 100% (10/10) for dedifferentiated tumors (κ = 0.28). Based on anatomical location, it was stratified by hemipelvis (31 cases, κ = 0.3), distal femur (14, κ = 0.5), proximal femur (19, κ = 0.1), proximal humerus (8, κ = 0), scapula (8, κ = 0.6), and proximal tibia (11, κ = 0.18). Conclusion This study showed modest agreement between the histological grade obtained by CNB and the definitive postoperative grade in CS. Agreement was higher in dedifferentiated tumors, in central skeletal lesions, and in tumors with soft tissue invasion. Conversely, concordance was particularly poor in G1-G2 CSs and in peripheral lesions, with an increased risk of undergrading.", "tags": ["Chondrosarcome", "Tumeur cartilagineuse", "Biopsie osseuse", "Grade histologique", "RCP Sarcome", "Eur J Surg Oncol 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42874309/", "doi_url": "https://doi.org/10.1016/j.ejso.2026.112214", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.ejso.2026.112214"}, {"id": "pmid-42997475", "pmid": "42997475", "pmcid": "PMC13742044", "doi": "10.1016/j.jbo.2026.100808", "title": "Multimodal imaging and artificial intelligence for bone tumor diagnosis: Comparative performance and emerging technologies", "title_fr": "Imagerie multimodale, intelligence artificielle et limites de la biopsie au trocart (CNB) dans le diagnostic des tumeurs osseuses : analyse critique de la concordance biopsie-résection", "authors_list": ["Liu X", "Liu L"], "authors_short": "Liu X, Liu L", "journal": "Journal of bone oncology", "journal_short": "J Bone Oncol", "impact_factor": 3.4, "year": 2026, "month_num": 10, "month_fr": "Oct.", "pub_date_fr": "Oct. 2026", "volume": "61", "issue": "", "pages": "100808", "category_id": "msk_biopsy", "category_label": "Biopsies Ostéo-Articulaires, Synoviales & Sarcomes", "category_short": "Biopsies TDM & Écho", "category_color": "#3b82f6", "modality": "Scanner / IRM / TEP-TDM & Biopsie Osseuse Percutanée", "intervention_type": "Biopsie Osseuse Percutanée & Concordance Radio-Pathologique (RCP Sarcome)", "cochin_link": "Éclaire directement l'interprétation des « biopsies osseuses percutanées sous scanner (notamment du bassin et des os longs) » discutées en RCP Sarcome à Cochin.", "summary_fr_short": "Revue critique publiée dans le *Journal of Bone Oncology* (oct./déc. 2026, IF 3,4) démontrant que la limite principale des modèles diagnostiques en oncologie osseuse réside dans la variabilité du standard histologique : la concordance de grade entre biopsie au trocart (CNB) et pièce opératoire dans les chondrosarcomes centraux chute de κ = 0,63 sur les os longs à κ = 0,12 dans le bassin.", "summary_fr_detailed": "Cette mise au point du *Journal of Bone Oncology* analyse l'intégration de l'imagerie multimodale (radiographie, TDM pour l'analyse corticale et matricielle, IRM pour l'extension médullaire et des parties molles, TEP-TDM pour le métabolisme) et de la biopsie osseuse au trocart (Core Needle Biopsy). Les auteurs démontrent chiffres à l'appui que la biopsie percutanée isolée ne peut constituer un gold standard absolu sans confrontation à l'imagerie en raison de quatre facteurs : 1) l'erreur d'échantillonnage spatial sur les tumeurs volumineuses (dans les chondrosarcomes centraux, la concordance pondérée κ entre biopsie et résection tombe de 0,63 dans les os longs à seulement 0,12 dans le bassin) ; 2) la variabilité inter-observateur entre pathologistes experts (κ = 0,44) et radiologues (κ = 0,35) ; 3) l'évolution des critères moléculaires OMS ; et 4) la dissociation possible entre aspect histologique focal et agressivité clinique.", "protocol_fr": "Synthèse pré-biopsique obligatoire TDM + IRM (+ TEP-TDM si lésion pelvienne volumineuse) pour cibler le secteur le plus suspect • Dans les tumeurs osseuses du bassin (où la concordance d'un prélèvement unique tombe à κ = 0,12), réalisation de prélèvements multi-sites divergents au trocart osseux 8G–11G sous guidage TDM • Décision thérapeutique fondée sur un standard composite (radio-histo-moléculaire et évolutif) en RCP Sarcome.", "key_points_fr": ["Dans les tumeurs cartilagineuses centrales du bassin, la concordance de grade entre biopsie au trocart et résection chute à κ = 0,12 (contre κ = 0,63 sur les os longs).", "Une biopsie osseuse rassurante (bas grade) sur une lésion pelvienne lytique ou agressivement rehaussée en IRM ne doit jamais faire récuser un haut grade sans relecture.", "Justifie la réalisation de carottes multiples dans des cadrans distincts lors des biopsies osseuses scanoguidées du bassin à Cochin.", "Plaide pour l'adoption systématique d'un gold standard composite associant imagerie multimodale, histologie et biologie moléculaire en RCP."], "abstract_en": "Multimodal imaging is central to the diagnosis, staging, and management of bone tumors. Radiography and computed tomography remain essential for initial assessment and cortical evaluation, magnetic resonance imaging provides superior soft tissue contrast and local staging accuracy, and positron emission tomography enhances detection of metastatic disease and treatment response. No single technique suffices across clinical scenarios. Advances in artificial intelligence and radiomics offer avenues to augment this framework, with demonstrated potential in lesion classification, segmentation, prognostication, and response prediction. This review advances a specific argument rather than surveying available technologies: that the principal constraint on artificial intelligence in musculoskeletal oncology is the stability of the reference standard rather than algorithmic capability. Ground truth in bone tumors is unstable on four grounds. Core needle biopsy samples a limited volume and may miss the highest-grade component: agreement between biopsy and resection grade in central chondrosarcoma falls from a weighted kappa of 0.63 in long bones to 0.12 in the pelvis. Expert interpretation is itself inconsistent, with interobserver kappa for grading cartilaginous tumors of 0.44 among musculoskeletal pathologists and 0.35 among radiologists. Molecular criteria have redefined entities within the past decade, so older datasets contain classes that no longer exist as defined. And histological classification does not reliably predict clinical behavior. Consequently, measurable accuracy has a ceiling set by the reference standard rather than the algorithm, and apparent failure on external validation may reflect label divergence between institutions rather than model deficiency. Evidence is graded throughout, and clinical readiness distinguished from technical performance. No system for primary bone tumor characterization has regulatory clearance in the United States or Europe, and formal appraisal of this literature confirms low methodological compliance and infrequent external validation. Progress will depend on multicenter validation and protocol harmonization, and, distinctively for this field, on composite reference standards, outcome-based endpoints, and explicit uncertainty modelling, since ground-truth instability can be mitigated but not eliminated.", "tags": ["Tumeurs osseuses", "Biopsie osseuse", "Chondrosarcome du bassin", "Imagerie multimodale", "RCP Sarcome", "J Bone Oncol 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42997475/", "doi_url": "https://doi.org/10.1016/j.jbo.2026.100808", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13742044/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13742044/"}, {"id": "pmid-42964659", "pmid": "42964659", "pmcid": "PMC13720579", "doi": "10.4329/wjr.125901", "title": "Diagnostic performance of computed tomography-guided percutaneous bone biopsy in musculoskeletal oncology: A single-center cohort study", "title_fr": "Performance diagnostique et sécurité de la biopsie osseuse percutanée guidée par scanner en oncologie musculo-squelettique (64 procédures consécutives)", "authors_list": ["Stuparu Adam AM", "Osama A", "Stere A", "Cochior D", "Pogărăşteanu ME", "Moldovan CA", "Tudorache IS", "Adam R", "Moldovan AD"], "authors_short": "Stuparu Adam AM, Osama A et al.", "journal": "World journal of radiology", "journal_short": "World J Radiol", "impact_factor": 2.5, "year": 2026, "month_num": 10, "month_fr": "Oct.", "pub_date_fr": "Oct. 2026", "volume": "18", "issue": "10", "pages": "125901", "category_id": "msk_biopsy", "category_label": "Biopsies Ostéo-Articulaires, Synoviales & Sarcomes", "category_short": "Biopsies TDM & Écho", "category_color": "#3b82f6", "modality": "Scanner Interventionnel (Approche Coaxiale)", "intervention_type": "Biopsie Osseuse Percutanée Guidée par TDM (Pelvis, Rachis & Os Longs)", "cochin_link": "Reflète directement l'activité quotidienne de « Biopsie osseuse ou disco-vertébrale sous scanner (crête iliaque, sacrum, membres) » de l'Agenda Interventionnel Cochin.", "summary_fr_short": "Étude de cohorte monocentrique (*World Journal of Radiology*, oct. 2026, IF 2,5, Open-Access) portant sur 64 biopsies osseuses percutanées consécutives guidées par scanner : rendement diagnostique de 93,75 % (60/64) dès le premier prélèvement, concordance histologique de 100 % parmi les prélèvements contributifs, révision du diagnostic clinique pré-geste dans 9,4 % des cas (6/64) et 0 % de complication majeure SIR.", "summary_fr_detailed": "Cette série évalue rigoureusement la rentabilité histopathologique, la concordance diagnostique finale (chirurgie, immunohistochimie et suivi radio-clinique composite) et la morbidité selon la classification SIR de 64 biopsies osseuses percutanées consécutives réalisées sous guidage TDM entre 2023 et 2025 pour suspicion de tumeur osseuse primitive ou secondaire (les localisations pelviennes étant majoritaires). Soixante procédures sur 64 (93,75 % ; IC 95 % : 84,8–98,3 %) ont fourni un diagnostic histologique exploitable sans nécessité de re-biopsie, avec une concordance de 100 % sur les cas contributifs. Fait clinique majeur : dans 6 cas (9,4 %), la biopsie TDM a redressé l'hypothèse diagnostique initiale (ex. lésion bénigne ou infectieuse mimant une métastase ou inversement). Aucune complication majeure SIR n'est survenue (0 %), seuls 2 trajets fistuleux mineurs de grade SIR B (3,1 %) ayant été observés.", "protocol_fr": "Revue préalable de l'IRM/TDM/TEP pour cibler la portion charnue non nécrotique ou ostéolytique active et respecter strictement la voie d'abord chirurgicale en cas de suspicion de sarcome primitif • Approche coaxiale sous guidage TDM hélicoïdal ou fluoroscopie-TDM • Carottage multiple au trocart à os (11G–13G) couplé si composante tissulaire à un pistolet semi-automatique (14G–16G) • Bilan d'hémostase et gestion standardisée des antithrombotiques.", "key_points_fr": ["Rendement diagnostique élevé de 93,75 % dès la première biopsie osseuse sous scanner, dominée par les localisations pelviennes complexes.", "Redressement du diagnostic clinique pré-procédural dans près de 1 cas sur 10 (9,4 %), justifiant l'histologie systématique avant ablation ou radiothérapie.", "Sécurité optimale : 0 % de complication majeure SIR et seulement 3,1 % d'événements mineurs locaux.", "Conforte les standards de biopsie osseuse coaxiale sous scanner pratiqués en Radio B à Cochin."], "abstract_en": "Background Computed tomography guided percutaneous bone biopsy provides tissue for the assessment of suspected primary and secondary bone lesions. Diagnostic yield, concordance with subsequent diagnostic assessment, and adverse events describe different aspects of performance. Their interpretation depends on case selection, outcome definitions, and the completeness and independence of diagnostic verification. Aim To describe diagnostic yield, recorded diagnostic concordance, and complications in a retrospective single-center cohort of image-guided bone biopsies. Methods We retrospectively reviewed 64 consecutive image-guided percutaneous bone biopsy procedures performed from January 2023 through December 2025. Diagnostic yield required clinically useful histopathology without repeat sampling. Recorded concordance used a composite of surgical histopathology, immunohistochemistry-supported assessment, or clinical and imaging follow-up. Non-diagnostic procedures remained in the full-cohort analysis. Complications were classified using the legacy Society of Interventional Radiology system. Proportions were summarized with exact binomial 95% confidence intervals (CI); no external hypothesis tests were performed. Results Diagnostic yield was 60/64 (93.75%; 95%CI: 84.8%-98.3%). Recorded concordance among 60 diagnostic, evaluable procedures was 60/60 (100%; 95%CI: 94.0%-100%). The full-cohort concordant diagnostic-result rate was 60/64 (93.75%) when four non-diagnostic procedures were counted as failures. Six biopsies revised the pre-procedural clinical diagnosis. Pelvic lesions were the most frequent sites. Two minor class B biopsy-tract fistulas occurred (2/64, 3.1%; 95%CI: 0.4%-10.8%); no major complications were recorded (0/64; 95%CI: 0%-5.6%). The heterogeneous cohort, incomplete verification reporting, and potentially non-independent composite reference standard limit interpretation of the conditional concordance estimate. Conclusion This cohort showed high diagnostic yield and two recorded minor complications. Conditional concordance does not establish unbiased diagnostic accuracy; independent verification and prospective confirmation are needed.", "tags": ["Biopsie osseuse", "Scanner interventionnel", "Rendement diagnostique", "Oncologie musculo-squelettique", "Bassin", "World J Radiol 2026"], "pdf_file": "pdfs/PMID_42964659.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 6768, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42964659/", "doi_url": "https://doi.org/10.4329/wjr.125901", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13720579/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13720579/"}, {"id": "pmid-42955458", "pmid": "42955458", "pmcid": "", "doi": "10.1007/s11864-026-01420-1", "title": "Current Role of Radiomics for Management of Soft Tissue Sarcoma", "title_fr": "Rôle actuel de la radiomique IRM dans la prise en charge des sarcomes des tissus mous : diagnostic de grade, prédiction et évaluation de la réponse thérapeutique", "authors_list": ["Chang YC", "McGowan N", "Alessandrino F", "Dayan E", "Jonczak E", "Crawford B", "Din NU", "Subhawong T"], "authors_short": "Chang YC, McGowan N et al.", "journal": "Current treatment options in oncology", "journal_short": "Curr Treat Options Oncol", "impact_factor": 4.1, "year": 2026, "month_num": 10, "month_fr": "Oct.", "pub_date_fr": "Oct. 2026", "volume": "27", "issue": "1", "pages": "52", "category_id": "msk_imaging", "category_label": "Imagerie Ostéo-Articulaire Diagnostique & Suivi Post-Geste", "category_short": "IRM / TDM Diagnostique & Suivi", "category_color": "#6366f1", "modality": "IRM Multiparamétrique & Analyse Radiomique Quantitative", "intervention_type": "Caractérisation IRM Pré-Biopsique & Évaluation de Réponse des Sarcomes", "cochin_link": "Complète les bilans d'« IRM diagnostique, ciblage biopsique et suivi post-thérapeutique des sarcomes des parties molles » en centre de référence Sarcome à Cochin.", "summary_fr_short": "Revue de synthèse (*Current Treatment Options in Oncology*, oct. 2026, IF 4,1) faisant le point sur l'apport des biomarqueurs radiomiques extraits de l'IRM conventionnelle dans les sarcomes des tissus mous : discrimination bas grade vs haut grade avant biopsie, prédiction précoce de la nécrose post-traitement néoadjuvant et stratification pronostique du risque métastatique.", "summary_fr_detailed": "Les sarcomes des tissus mous (STS) présentent une forte hétérogénéité spatiale qui limite parfois l'analyse sémantique visuelle de l'IRM et expose au risque d'échantillonnage incomplet lors de la biopsie percutanée. Cette revue synthétise les performances cliniques des modèles radiomiques IRM (séquences T1, T2 Fat-Sat, DWI/ADC et T1 injecté) pour : 1) différencier les lésions bénignes (lipomes, fasciites, schwannomes) des sarcomes et distinguer les grades FNCLCC G1 vs G2/G3 ; 2) cartographier les sous-régions intratumorales (« habitats ») les plus agressives afin de guider la microbiopsie percutanée ; et 3) prédire la réponse histopathologique (nécrose > 90 %) aux traitements néoadjuvants mieux que les seuls critères dimensionnels RECIST.", "protocol_fr": "Acquisition IRM multiparamétrique standardisée (T1, T2 FS/STIR, diffusion multi-b avec ADC et perfusion/T1 Gado) • Analyse de l'hétérogénéité de texture intratumorale et de la zone périlésionnelle pour identifier le contingent de plus haut grade • Ciblage de la biopsie percutanée sur l'habitat hypercellulaire/hypervasculaire et suivi longitudinal post-thérapeutique multiparamétrique.", "key_points_fr": ["L'analyse quantitative de l'hétérogénéité IRM distingue avec une haute précision les sarcomes de haut grade (FNCLCC G2–G3) des tumeurs de bas grade.", "Permet d'orienter la biopsie percutanée vers le sous-volume tumoral (« habitat ») biologiquement le plus agressif.", "Surpasse les critères morphologiques RECIST 1.1 pour évaluer la nécrose tumorale réelle après traitement néoadjuvant ou ablation.", "Renforce la valeur ajoutée de l'expertise IRM ostéo-articulaire de Cochin au sein de la RCP Sarcome."], "abstract_en": "Opinion statement Soft tissue sarcomas represent a diverse set of malignancies with equally diverse behavior, ranging from relatively indolent low-grade tumors to aggressive high-grade tumors with high metastatic potential. Initial diagnosis hinges on tissue biopsy for determining histologic subtype and grade, while conventional imaging plays critical roles in defining local tumor size and extent, staging, treatment response, and disease surveillance. However, conventional semantic interpretation of imaging studies overlooks much of the complex imaging data embedded in routine clinical studies. Radiomics encompasses the identification of novel disease biomarkers extracted from highly quantitative characterizations of tumor structure and heterogeneity and has shown promise in providing a deeper understanding of soft tissue sarcomas. Given the increasing usage of imaging in soft tissue sarcomas, particularly usage of MRI, it behooves both clinicians and radiologists to further the depth of understanding that may be gleaned from radiomics. These insights, although primarily experimental, represent a rapidly evolving landscape in soft tissue sarcoma diagnosis and management where radiomics will be increasingly integrated into clinical practice. The present work focuses on the latest updates with regards to the application of radiomics to the diagnosis, prediction of treatment response, assessment of treatment response, and prognosis of soft tissue sarcomas and how they may affect sarcoma management.", "tags": ["Sarcome des tissus mous", "IRM multiparamétrique", "Radiomique", "Réponse thérapeutique", "Grade FNCLCC", "Curr Treat Options Oncol 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42955458/", "doi_url": "https://doi.org/10.1007/s11864-026-01420-1", "pmc_url": "", "article_url": "https://doi.org/10.1007/s11864-026-01420-1"}, {"id": "pmid-42942556", "pmid": "42942556", "pmcid": "PMC13706722", "doi": "10.3390/medicina62102025", "title": "Intraoperative Neurophysiological Monitoring During Continuous Radiofrequency Treatment of Morton's Neuroma: Complete Ablation", "title_fr": "Monitorage neurophysiologique per-procédure lors de l'ablation par radiofréquence continue du névrome de Morton : confirmation d'ablation complète", "authors_list": ["Camuñas-Nieves G", "Fernández-Gibello A", "Martínez-Pérez F", "Montes-Salas R", "Galluccio F", "Martínez-Nova A"], "authors_short": "Camuñas-Nieves G, Fernández-Gibello A et al.", "journal": "Medicina (Kaunas, Lithuania)", "journal_short": "Medicina (Kaunas)", "impact_factor": 2.4, "year": 2026, "month_num": 10, "month_fr": "Oct.", "pub_date_fr": "Oct. 2026", "volume": "62", "issue": "10", "pages": "2025", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Échographie + Stimulation / Monitorage Neurophysiologique (SNAP)", "intervention_type": "Neurolyse par Radiofréquence Continue du Névrome de Morton", "cochin_link": "Complète directement les « neurolyses percutanées de névrome de Morton rebelle des 2e et 3e espaces interdigitaux (cryothérapie / radiofréquence) » de l'Agenda Cochin.", "summary_fr_short": "Série prospective de 22 patients / 30 névromes de Morton (*Medicina*, oct. 2026) traités par radiofréquence continue échoguidée sous monitorage en temps réel des potentiels d'action nerveux sensitifs (SNAP), obtenant 86,7 % de succès global (96,3 % hors métatarsalgie mécanique) et 100 % de succès en rattrapage après échec d'une RF antérieure.", "summary_fr_detailed": "Bien que la radiofréquence (RF) et la cryoneurolyse percutanées du névrome de Morton affichent 80 à 85 % de succès clinique, les échecs résultent soit d'une destruction neuronale incomplète, soit d'une métatarsalgie mécanique intriquée. Cette étude prospective a enregistré les potentiels d'action nerveux sensitifs (SNAP) avant, pendant et après chaque cycle de RF continue échoguidée jusqu'à abolition complète de la conduction sensitive sur 30 névromes. À 12 mois, l'EVA douleur chute de 8,67 à 1,67 avec 86,7 % de résultats satisfaisants (score de Giannini ≥ 60), et 96,3 % après exclusion des métatarsalgies mécaniques. Fait majeur : les 7 névromes en échec d'une première RF conventionnelle ont tous répondu favorablement (7/7) grâce au monitorage per-opératoire confirmant l'ablation neuronale complète.", "protocol_fr": "Repérage échographique longitudinal et transversal de l'espace intermétatarsien (2e ou 3e espace) • Positionnement de la sonde à l'extrémité proximale du névrome • Enregistrement des potentiels sensitifs (SNAP) du nerf digital plantaire commun et cycles de thermo-ablation RF continue jusqu'à disparition complète du signal de conduction • Test préalable de suppression anesthésique pour éliminer une métatarsalgie mécanique pure.", "key_points_fr": ["Diminution majeure de l'EVA douleur de 8,67 en pré-procédure à 1,67 à 12 mois (taux de succès ajusté de 96,3 %).", "100 % de succès clinique (7/7) chez les patients en récidive ou échec d'une première radiofréquence conventionnelle.", "Le test anesthésique diagnostique préalable est déterminant pour écarter une métatarsalgie mécanique statique associée.", "Valide l'intérêt du contrôle électrophysiologique et d'un ciblage nerveux proximal précis dans les névromes de Morton rebelles traités à Cochin."], "abstract_en": "Background and Objectives : Morton's neuroma is a compressive neuropathy of the common plantar digital nerve that most frequently affects the third intermetatarsal space. Continuous radiofrequency (RF) ablation has reported success rates of approximately 80-85%; however, recent histological evidence suggests that RF does not consistently achieve complete neural ablation. This study aimed to evaluate the effectiveness of intraoperative neurophysiological monitoring of sensory nerve action potentials (SNAPs) to optimize the outcomes of continuous RF ablation in the treatment of Morton's neuroma. Materials and Methods : This prospective case series included 22 patients (30 neuromas) treated with ultrasound-guided continuous RF ablation combined with intraoperative neurophysiological monitoring. SNAPs were recorded before, during, and after each RF application until complete abolition of sensory nerve conduction was confirmed. Clinical outcomes were assessed using the Visual Analog Scale (VAS), the Foot Function Index (FFI), and the Giannini Interdigital Neuroma Clinical Evaluation Score at 3, 6, and 12 months postoperatively. Results : At the 12-month follow-up, satisfactory outcomes (Giannini score ≥60) were achieved in 86.7% of neuromas (26/30). The mean VAS pain score decreased from 8.67 preoperatively to 1.67 at 12 months. Among the seven neuromas with previous unsuccessful RF treatment, all achieved satisfactory outcomes following the monitored procedure. The four cases with poor outcomes were predominantly associated with a positive anesthetic suppression test, suggesting concomitant mechanical metatarsalgia rather than treatment failure. After excluding cases with likely diagnostic misclassification, the adjusted success rate increased to 96.3%. Conclusions : Intraoperative neurophysiological monitoring enables real-time confirmation of complete sensory nerve ablation during continuous RF treatment. Its main potential value appears to lie in patients with previous unsuccessful conventional RF, all of whom achieved satisfactory outcomes in this series. Persistent postoperative symptoms appeared to be more closely related to concomitant forefoot pathology than to technical limitations of the RF procedure.", "tags": ["Névrome de Morton", "Radiofréquence", "Neurolyse percutanée", "Monitorage neurophysiologique", "Échoguidage", "Medicina 2026"], "pdf_file": "pdfs/PMID_42942556.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 909, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42942556/", "doi_url": "https://doi.org/10.3390/medicina62102025", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13706722/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13706722/"}, {"id": "pmid-42909541", "pmid": "42909541", "pmcid": "", "doi": "10.1007/s00256-026-05404-y", "title": "Percutaneous cryoablation of musculoskeletal tumours: the largest reported single-centre case series - outcomes, complications and subgroup analysis", "title_fr": "Cryoablation percutanée des tumeurs musculo-squelettiques : résultats cliniques, complications (classification CIRSE) et diminution de densité (UH) sur 48 patients", "authors_list": ["Thompson B", "Gibson J", "Kiyawat V", "Stevenson J", "Botchu R"], "authors_short": "Thompson B, Gibson J et al.", "journal": "Skeletal radiology", "journal_short": "Skeletal Radiol", "impact_factor": 1.9, "year": 2026, "month_num": 10, "month_fr": "Oct.", "pub_date_fr": "Oct. 2026", "volume": "", "issue": "", "pages": "", "category_id": "percutaneous_ablation_general", "category_label": "Ablation Percutanée Tumorale : Standards, Endométriome & Oncologie", "category_short": "Ablation Percutanée (Standards & Onco)", "category_color": "#e11d48", "modality": "Scanner Interventionnel", "intervention_type": "Cryoablation Percutanée de Tumeurs Osseuses, Cartilagineuses & Métastases", "cochin_link": "Au cœur de l'activité de « cryoablation percutanée sous scanner de tumeurs osseuses, cartilagineuses et de métastases » du Service de Radiologie B à Cochin.", "summary_fr_short": "Série monocentrique de référence (*Skeletal Radiology*, oct. 2026, équipe de R. Botchu, 48 patients) évaluant la cryoablation percutanée des tumeurs musculo-squelettiques (métastases, tumeurs cartilagineuses et tumeurs osseuses primitives/bénignes), avec 73 % de réponse clinique (58 % complète/bonne, 15 % partielle), une baisse de densité TDM (UH) dans 94 % des cas et aucune complication majeure CIRSE.", "summary_fr_detailed": "Cette étude rétrospective menée dans un centre tertiaire d'oncologie musculo-squelettique (Royal Orthopaedic Hospital, Birmingham) analyse 48 procédures consécutives de cryoablation percutanée réalisées par un radiologue interventionnel senior pour des métastases osseuses, des tumeurs cartilagineuses et des tumeurs osseuses bénignes ou primitives. Une réponse clinique complète ou bonne est obtenue chez 58 % des patients et une réponse partielle chez 15 % (soit 73 % d'efficacité globale). Sur le plan scannographique, une diminution de la densité en unités Hounsfield (UH) au sein de la zone traitée est observée chez 45 des 48 patients (94 %), traduisant la nécrose de liquéfaction cryogénique. Le taux global de complications (classification CIRSE) est faible (6,3 %, 3/48), sans aucune complication majeure ni séquelle permanente.", "protocol_fr": "Planification TDM/IRM pré-procédure • Insertion d'une ou plusieurs cryosondes sous guidage scanographique avec contrôle tridimensionnel de la boule de glace (« iceball ») englobant les marges tumorales • Double cycle de congélation-décongélation active/passive avec thermoprotection des structures nobles • Mesure comparative de l'atténuation TDM (UH) pré- et post-ablation et gradation des complications selon le référentiel CIRSE.", "key_points_fr": ["73 % de réponse clinique favorable (58 % complète/bonne, 15 % partielle) sur un large spectre de tumeurs osseuses, cartilagineuses et métastatiques.", "Chute de l'atténuation scannographique (UH) post-cryoablation constatée dans 94 % des lésions (45/48), marqueur quantitatif simple de nécrose.", "Excellent profil de sécurité avec 0 % de complication majeure selon la classification CIRSE (6,3 % de complications mineures transitoires).", "Confirme la reproductibilité et la sûreté de la cryoablation osseuse et des parties molles pratiquée quotidiennement au scanner à Cochin."], "abstract_en": "Objectives Cryoablation is an image-guided, minimally invasive treatment technique that uses extreme cold to induce tumour destruction. Its role in musculoskeletal oncology has expanded in recent years, although large clinical series remain limited. This study reports a large single-centre experience of percutaneous cryoablation for musculoskeletal tumours, including metastatic lesions, benign and cartilaginous tumours, and primary bone tumours. Materials and methods This was a single-centre retrospective cohort study conducted at a tertiary musculoskeletal oncology centre. All procedures were performed by a single specialist musculoskeletal interventional radiologist with over 20 years of experience. The study included patients who underwent percutaneous cryoablation for musculoskeletal tumours between June 2021 and December 2025. Clinical response, radiological response, recurrence, and complications were assessed over a median follow-up of 3 months (mean 8.7 months; range 0-48 months). Radiological response was assessed using pre-treatment and post-treatment Hounsfield Unit (HU) measurements on CT; this is not a validated radiological scoring system and is reported as a complementary, exploratory marker alongside standard clinical response assessment. Complications were graded using the CIRSE classification system. Results A total of 48 patients underwent percutaneous cryoablation during the study period. The cohort included 26 males and 22 females, with a median age of 40 years. A good or complete response was achieved in 28 patients, representing 58% of the total cohort. A partial response was achieved in seven patients, representing 15% of the total cohort. HU reduction was observed in 45 of 48 patients, representing 94% of the cohort. The overall complication rate was 6.3%, with three complications recorded among 48 procedures. No major complications or procedure-related deaths were observed. Conclusions Cryoablation appears to be a safe and effective minimally invasive treatment for selected musculoskeletal tumours. Most patients achieved a good, complete, or partial response, with a low complication rate. Hounsfield Unit reduction after treatment may provide a useful, though as yet non-validated, marker of radiological response. Further prospective studies with longer follow-up, standardised response criteria and validated complication grading are needed to confirm these findings.", "tags": ["Cryoablation", "Tumeurs musculo-squelettiques", "Métastases osseuses", "Unités Hounsfield", "Classification CIRSE", "Skeletal Radiol 2026"], "pdf_file": "pdfs/PMID_42909541.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 2015, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42909541/", "doi_url": "https://doi.org/10.1007/s00256-026-05404-y", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00256-026-05404-y"}, {"id": "pmid-42780331", "pmid": "42780331", "pmcid": "PMC13597178", "doi": "10.1016/j.jbo.2026.100802", "title": "Complications of vertebral augmentation in metastatic spinal fractures: a systematic review of multiple study designs", "title_fr": "Complications de la cimentoplastie vertébrale dans les fractures rachidiennes métastatiques : revue systématique de 76 études (3 234 patients, 5 737 vertèbres)", "authors_list": ["Correia MC", "Vieira AM", "Duarte F", "Rodrigues Pinho A", "Serdoura F", "Leite MJ"], "authors_short": "Correia MC, Vieira AM et al.", "journal": "Journal of bone oncology", "journal_short": "J Bone Oncol", "impact_factor": 3.4, "year": 2026, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2026", "volume": "61", "issue": "", "pages": "100802", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Scanner TDM / Fluoroscopie", "intervention_type": "Vertébroplastie & Kyphoplastie Oncologique", "cochin_link": "Référentiel majeur de sécurité pour les cimentoplasties vertébrales (cervicales, thoraciques et lombaires) post-radiothérapie ou combinées aux ablations à Cochin.", "summary_fr_short": "Revue systématique d'envergure (*Journal of Bone Oncology*, sept. 2026, 76 études, 3 234 patients, ≥ 5 737 vertèbres traitées) quantifiant précisément le taux de complications symptomatiques (3,41 %) et de fuites de ciment (20,7 %, majoritairement asymptomatiques) lors de la cimentoplastie des métastases rachidiennes.", "summary_fr_detailed": "Sur 5 737 niveaux vertébraux métastatiques traités par vertébroplastie ou kyphoplastie, le taux pondéré d'événements indésirables globaux (incluant les fuites radiologiques asymptomatiques) est de 25,5 %, mais le taux de complications réellement symptomatiques n'est que de 3,41 %. L'incidence pondérée des fuites de ciment est de 20,7 % (détectées plus fréquemment sur le contrôle TDM post-opératoire que sur la fluoroscopie seule : 28,6 % vs 11,9 %, p = 0,004). Les complications cliniques comprennent les douleurs transitoires post-procédure (1,77 %), l'embolie pulmonaire de ciment (1,08 %) et les fractures des vertèbres adjacentes (0,79 %).", "protocol_fr": "Analyse TDM pré-opératoire rigoureuse du mur postérieur et des veines basivertébrales/épidurales • Utilisation de ciment PMMA haute viscosité injecté lentement sous contrôle fluoroscopique/TDM continu • Arrêt immédiat de l'injection dès la moindre fuite veineuse pré-vertébrale ou épidurale.", "key_points_fr": ["Plus vaste synthèse publiée à ce jour en oncologie rachidienne : 3 234 patients et plus de 5 737 vertèbres métastatiques cimentées.", "Taux de complications symptomatiques très contenu (3,41 %), confirmant la haute sécurité du geste palliatif.", "Faible incidence d'embolie pulmonaire de ciment (1,08 %) et de fracture adjacente précoce (0,79 %).", "Le contrôle par scanner détecte 2,4 fois plus de micro-fuites asymptomatiques que la radioscopie standard (28,6 % vs 11,9 %)."], "abstract_en": "Background Vertebral augmentation techniques, including vertebroplasty and kyphoplasty, are widely used to relieve pain and restore spinal stability in patients with metastatic vertebral lesions. Despite their widespread use, the full spectrum and clinical significance of procedure-related complications remain incompletely characterised. This systematic review aims to summarise and characterise all reported complications associated with vertebral augmentation for metastatic thoracolumbar disease. Methods A comprehensive search of PubMed/MEDLINE, Scopus, and Web of Science databases was performed. Studies reporting complications associated with vertebral augmentation procedures for metastatic thoracolumbar spinal fractures were included. Randomised controlled trials, observational studies, case series, and case reports were eligible. Due to substantial heterogeneity across studies, a descriptive synthesis was performed. Results A total of 76 studies were included, comprising 3234 patients and at least 5737 vertebral levels treated. The overall weighted complication rate was 25.5%, while the weighted rate of symptomatic complications was 3.41%. Cement leakage was the most frequently reported complication, with a weighted mean incidence of 20.7%, although the majority were asymptomatic. Other complications included postprocedural pain (1.77%), pulmonary cement embolism (1.08%), and adjacent level fractures (0.79%). Studies using CT imaging reported significantly higher cement leakage rates (28.6% vs 11.9%, p = 0.004). Case reports described rare but potentially severe complications, including needle-tract tumour seeding, tumour extrusion, and cement migration to cardiac structures. Conclusions This review presents a comprehensive and detailed description of all complications of vertebral augmentation for treatment of metastatic spine disease and reinforce its safety. Differences in imaging protocols and reporting standards contribute to variability in reported complication rates. Further prospective studies with standardised complication reporting are needed.", "tags": ["Cimentoplastie vertébrale", "Métastases rachidiennes", "Sécurité", "Fuite de ciment", "J Bone Oncol 2026"], "pdf_file": "pdfs/PMID_42780331.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 2608, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42780331/", "doi_url": "https://doi.org/10.1016/j.jbo.2026.100802", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13597178/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13597178/"}, {"id": "pmid-42767629", "pmid": "42767629", "pmcid": "PMC13593370", "doi": "10.1111/os.70439", "title": "Iliosacral Screw Fixation for Treating Sacral Fractures: A Modified Pedicle-Guided Fixation Technique in Prone Position", "title_fr": "Vissage percutané ilio-sacré des fractures du sacrum en procubitus : technique modifiée guidée par le pédicule S1 et associée à la sacroplastie", "authors_list": ["Liu BM", "Liu YH", "Hsu TS", "Chen CY", "Chiang CJ", "Hsieh YY"], "authors_short": "Liu BM, Liu YH et al.", "journal": "Orthopaedic surgery", "journal_short": "Orthop Surg", "impact_factor": 2.1, "year": 2026, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2026", "volume": "18", "issue": "11", "pages": "2480-2490", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Fluoroscopie 2D/3D (Scopie Allura) + Contrôle Scanner", "intervention_type": "Vissage Percutané Ilio-Sacré en Procubitus & Sacroplastie", "cochin_link": "Directement applicable aux « vissages percutanés du bassin et sacroplasties en procubitus (Scanner / Scopie Allura) » réalisés à l'Hôpital Cochin.", "summary_fr_short": "Série clinique (*Orthopaedic Surgery*, sept./nov. 2026, PMC Open-Access, 22 patients) décrivant une technique modifiée de vissage ilio-sacré percutané en procubitus guidée par les repères du pédicule de S1 : taux d'excellence de positionnement intra-osseux au scanner de 97 %, absence totale de complication radiculaire et amélioration significative de l'EVA douleur et du score fonctionnel de Majeed.", "summary_fr_detailed": "Le positionnement en procubitus (prone position) est la posture de référence en radiologie interventionnelle ostéo-articulaire pour combiner dans le même temps un abord postérieur rachidien/sacré (cimentoplastie, sacroplastie) et un vissage ilio-sacré percutané. Cette étude évalue sur 22 patients une technique standardisée de visée ilio-sacrée en procubitus s'appuyant sur le repérage fluoroscopique du pédicule de S1 (vues inlet, outlet et profil strict). Le scanner de contrôle systématique à 6 mois démontre un taux d'excellence de trajectoire de 97 % sans aucune effraction des foramens sacrés ni lésion nerveuse L5/S1. Les auteurs soulignent l'intérêt majeur du procubitus chez les patients obèses ou présentant des lésions rachidiennes ou sacrées concomitantes nécessitant une sacroplastie associée.", "protocol_fr": "Installation en procubitus sur table radiotransparente (Scopie Allura ou table de scanner interventionnel) • Repérage des incidences fluoroscopiques inlet, outlet et profil sacré vrai centrées sur les pédicules S1 • Insertion de la broche-guide à travers l'aile iliaque et l'articulation sacro-iliaque jusque dans le corps de S1 • Mise en place de la vis canulée (7,0–7,3 mm) ± injection de ciment PMMA (sacroplastie/vissage cimenté).", "key_points_fr": ["Taux de précision intra-osseuse de 97 % au contrôle TDM et 0 % de complication neurologique radiculaire.", "L'installation en procubitus facilite l'association dans le même temps d'un vissage ilio-sacré et d'une sacroplastie ou vertébroplastie.", "Amélioration rapide et durable de l'EVA douleur et du score fonctionnel pelvien de Majeed.", "Correspond exactement à l'installation en procubitus utilisée en salle de scanner et sous scopie Allura à Cochin."], "abstract_en": "Background Sacral fractures are posterior pelvic ring injuries which mechanisms range from high-energy trauma to low-energy falls in osteoporotic patients. In surgical treatment, percutaneous approaches have demonstrated significant shorter operation time and less soft tissue damage. In this study, we present a method of iliosacral (SI) screw insertion in prone position, with modified pedicle-guided technique. Methods The present study is a retrospective case series of 22 patients for SI screw fixation from February 2019 to September 2023 under our method. Surgical technique was described in detail with images. Perioperative clinical parameters were analyzed. Activity status, complications, data of 10-point visual analogue scale (VAS) for pain and further functional outcomes using the Majeed Pelvic Score (MPS) were recorded. In addition, computed tomography (CT) was routinely performed at 6 months postsurgery to inspect the quality of screws position. Results Excellence rate of screw position was 97% upon CT. Two patients had screws partially contacting the cortical bone but not violating sacral foramen, and no neurological symptoms were noted. All screws were secure from possible iatrogenic nerve injuries. VAS scores improved significantly over time and most patients recorded excellent functional recovery. One untoward complication occurred involving unexpected cement extravasation after sacroplasty. No associated neurologic compromise, or clinical evidence of venous emboli thrombosis was reported. Conclusion Our method aims at reducing operation time and radiation exposure to surgeons as conventional two-dimensional fluoroscopy was enough to identify safe insertion corridors in SI screw placement. Performing SI fixation in prone position is also advantageous when dealing with obese patients and concomitant spinal injuries.", "tags": ["Vissage ilio-sacré", "Fracture du sacrum", "Procubitus", "Sacroplastie", "Fluoroscopie", "Orthop Surg 2026"], "pdf_file": "pdfs/PMID_42767629.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 2507, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42767629/", "doi_url": "https://doi.org/10.1111/os.70439", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13593370/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13593370/"}, {"id": "pmid-42731622", "pmid": "42731622", "pmcid": "", "doi": "10.1016/j.jvir.2026.109083", "title": "Cryoablation for Extra-Abdominal Desmoid Tumors: a Retrospective Study of Clinical and Radiological Outcomes", "title_fr": "Cryoablation percutanée des tumeurs desmoïdes extra-abdominales : résultats cliniques, survie sans progression et concordance volumétrique / mRECIST", "authors_list": ["Arseneault-Monette E", "Luo T", "Mack L", "Walker R", "Taqi K", "Bouchard-Fortier A", "Przybojewski S"], "authors_short": "Arseneault-Monette E, Luo T et al.", "journal": "Journal of vascular and interventional radiology : JVIR", "journal_short": "JVIR", "impact_factor": 2.6, "year": 2026, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2026", "volume": "37", "issue": "12", "pages": "109083", "category_id": "desmoid_soft_tissue", "category_label": "Cryoablation des Tumeurs Desmoïdes & Parties Molles", "category_short": "Cryo Desmoïdes & Tissus Mous", "category_color": "#06b6d4", "modality": "Scanner / IRM Interventionnelle", "intervention_type": "Cryoablation Percutanée de Tumeurs Desmoïdes Extra-Abdominales", "cochin_link": "Au cœur de l'activité de « cryothérapie percutanée de tumeur desmoïde (creux sus-claviculaire, flanc, paroi, membres) » du Service de Radiologie B à Cochin.", "summary_fr_short": "Étude de cohorte sur 92 séances de cryoablation chez 44 patients (*JVIR*, sept. 2026, taille médiane 6,9 cm, suivi médian 28,9 mois) rapportant 81,1 % de succès clinique, 78,4 % de réponse objective (24,3 % RC, 54,1 % RP), une concordance quasi parfaite entre volumétrie 3D et mRECIST (κ = 0,895), et seulement 5,3 % de complications majeures.", "summary_fr_detailed": "Sur une cohorte institutionnelle de 208 tumeurs desmoïdes extra-abdominales prises en charge entre 2020 et 2024, 44 patients (20,7 %) ont bénéficié de 92 procédures de cryoablation percutanée guidée par l'image pour des lésions volumineuses (taille médiane 6,9 cm, IQR 5,5–9,2 cm). Après un suivi médian de 28,9 mois, le taux de succès clinique composite (absence de progression, amélioration symptomatique et absence de traitement systémique/chirurgical) atteint 81,1 %. En imagerie, on observe 24,3 % de réponses complètes, 54,1 % de réponses partielles, 16,2 % de stabilisations et seulement 5,4 % de progressions. L'évaluation volumétrique 3D du tissu viable montre un accord quasi parfait avec la classification mRECIST (κ = 0,895). Les taux de survie sans progression à 1 an et 2 ans sont de 76,5 % et 67,4 %, avec une seconde séance de cryoablation efficace dans 26,3 % des cas.", "protocol_fr": "Planification IRM T1 Gado et T2 pour cartographier le volume charnu viable et les rapports vasculo-nerveux • Insertion multi-cryosondes sous guidage TDM/IRM avec marges de sécurité • Double cycle de congélation-décongélation sous contrôle continu de la boule de glace et neuroprotection/hydrodissection • Suivi IRM par critères mRECIST et volumétrie 3D du résidu rehaussé.", "key_points_fr": ["Taux de succès clinique de 81,1 % et contrôle de la maladie (RC + RP + stabilité) de 94,6 % sur des desmoïdes volumineuses (médiane 6,9 cm).", "Concordance quasi parfaite (κ = 0,895) entre les critères mRECIST et la volumétrie 3D sur l'IRM de suivi post-cryoablation.", "Possibilité de retraitement itératif par cryoablation (26,3 % des patients) en cas de reliquat ou récidive focale, évitant les chimiothérapies au long cours.", "Profil de sécurité très favorable avec seulement 5,3 % d'événements indésirables de grade SIR ≥ 3."], "abstract_en": "Purpose To determine whether image-guided cryoablation achieves durable clinical and radiologic response with an acceptable safety profile in patients with extra-abdominal desmoid tumors and whether volumetric response assessment concords with modified Response Evaluation Criteria in Solid Tumors-based classification MATERIALS AND METHODS: Patients treated between 2020 and 2024 were identified through electronic record. Those who underwent cryoablation were included for analysis. The primary outcome was clinical success, defined as a composite of no disease progression at last follow-up, no additional treatment, and symptom improvement. The secondary outcomes included radiologic response, symptom improvement, progression-free survival, and safety. Among 208 patients diagnosed with desmoid tumors, 44 (20.7%) underwent cryoablation, of whom 38 had follow-up data available; 92 cryoablation sessions were performed. Median tumor size was 6.9 cm (interquartile range, 5.5-9.2 cm), and median follow-up duration was 28.9 months (interquartile range, 14.3-37.3 months). Results The clinical success rate was 81.1%. Radiologic response at last follow-up was complete in 24.3%, partial in 54.1%, stable in 16.2%, and progressive in 5.4% of patients. Volumetric and modified Response Evaluation Criteria in Solid Tumors-based response classification showed almost-perfect agreement (κ = 0.895). Repeat cryoablation was performed in 26.3% of patients due to radiologic progression. Additional treatment modalities were required in 13.2% of cases. The 1- and 2-year progression-free survival rates were 76.5% (95% confidence interval, 58.2%-87.6%) and 67.4% (95% confidence interval, 46.5%-81.7%), respectively. Major adverse events (Society of Interventional Radiology grade, ≥Grade 3) occurred in 5.3% of patients. Conclusions Cryoablation is a safe and effective treatment option for selected patients with extra-abdominal desmoid tumors, achieving clinical success in the majority of patients. These findings support its role in the multidisciplinary management of desmoid tumors.", "tags": ["Tumeur desmoïde", "Cryoablation", "mRECIST", "Volumétrie IRM", "Parties molles", "JVIR 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42731622/", "doi_url": "https://doi.org/10.1016/j.jvir.2026.109083", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.jvir.2026.109083"}, {"id": "pmid-42804145", "pmid": "42804145", "pmcid": "", "doi": "10.1007/s11547-026-02280-3", "title": "Bipolar needle electrodes for electroporation-based treatments in soft and bone tissues: technical design and implementation", "title_fr": "Électrodes aiguilles bipolaires mono-aiguille pour l'électroporation et l'électrochimiothérapie (ECT) des tissus mous et osseux : conception et mise en œuvre guidée par l'image", "authors_list": ["Fusco R", "Zanasi A", "Izzo F", "Cadossi M", "De Terlizzi F", "Kovács A", "Facchini G", "Deschamps F", "Bonnet B", "Russo G", "Grasso RF", "Granata V"], "authors_short": "Fusco R, Zanasi A et al.", "journal": "La Radiologia medica", "journal_short": "Radiol Med", "impact_factor": 8.9, "year": 2026, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2026", "volume": "131", "issue": "10", "pages": "1852-1866", "category_id": "ect_mets", "category_label": "Électrochimiothérapie (ECT) & Métastases Osseuses", "category_short": "ECT (Bléomycine) & Métastases", "category_color": "#eab308", "modality": "Scanner / Échographie Interventionnelle", "intervention_type": "Électrochimiothérapie (ECT) Osseuse & des Parties Molles par Aiguille Bipolaire", "cochin_link": "Directement lié aux procédures d'« électrochimiothérapie (ECT - Bléomycine IV) osseuse et épidurale sous guidage scanographique » réalisées au scanner Achard à Cochin.", "summary_fr_short": "Note technique multicentrique (*La Radiologia Medica*, sept. 2026, IF 8,9) détaillant l'architecture du champ électrique et l'implantation guidée par l'image d'électrodes aiguilles bipolaires mono-aiguille pour l'électrochimiothérapie (ECT) des tumeurs osseuses et des tissus mous, permettant de réduire le nombre d'insertions tout en confinant le champ électrique à distance des structures nerveuses.", "summary_fr_detailed": "L'électrochimiothérapie (ECT) osseuse et vertébrale conventionnelle requiert l'insertion rigoureusement parallèle de multiples aiguilles monopolaires pour couvrir le volume tumoral, ce qui est parfois complexe dans les corridors osseux étroits (pédicule, épidure, toit acétabulaire) ou les régions multi-opérées. Ce travail multicentrique présente les simulations de distribution de champ électrique, les validations précliniques et les applications cliniques guidées par l'image d'une électrode aiguille bipolaire unique (conception coaxiale à deux pôles sur le même axe). Cette géométrie mono-aiguille génère un champ électrique prévisible et spatialement confiné sans effet de dissipation thermique, évitant les insertions multiples et limitant la diffusion du courant aux structures neuro-vasculaires adjacentes.", "protocol_fr": "Guidage TDM ou échographique pour le positionnement d'une électrode aiguille bipolaire coaxiale au centre de la lésion cible (os ou parties molles) • Perfusion intraveineuse de bléomycine (15 000 UI/m²) • Délivrance des impulsions électriques calibrées entre le pôle distal et le pôle proximal de la même aiguille (fenêtre de perméabilisation 8 à 40 min post-injection) • Contrôle de couverture volumétrique par repositionnement axial si nécessaire.", "key_points_fr": ["L'architecture bipolaire mono-aiguille supprime la contrainte de parallélisme strict entre plusieurs électrodes monopolaires dans l'os.", "Confinement spatial optimal du champ électrique d'électroporation, idéal à proximité du fourreau dural, des racines nerveuses ou des gros vaisseaux.", "Mécanisme non thermique préservant la trame minérale osseuse et compatible avec une cimentoplastie ou un vissage consolidateur dans le même temps.", "Ouvre la voie à des procédures d'ECT mini-invasives simplifiées pour les métastases vertébrales, pelviennes et les récidives profondes."], "abstract_en": "Electroporation (EP) transiently increases cell membrane permeability through the application of controlled electric pulses. Bipolar needle electrodes have been developed to simplify EP procedures by reducing the number of electrode insertions while improving control of electric field geometry and spatial confinement. This technical note describes the design principles, electric field behavior, and image-guided implementation of single-needle bipolar electrodes for EP applications in both soft and bone tissues. Electric field simulations and preclinical investigations were performed to assess field distribution, safety, and tissue selectivity. The practical implementation of the bipolar configuration is illustrated through representative image-guided examples from multiple institutions across different anatomical settings. The single-needle design enables minimally invasive procedures with predictable field control and limited extension to surrounding structures, even in anatomically complex or previously treated regions. Overall, bipolar electrodes represent a versatile and reproducible technological solution for electroporation-based treatments, supporting precise and tissue-sparing image-guided interventions.", "tags": ["Électrochimiothérapie", "Électrode bipolaire", "Électroporation", "Métastases osseuses", "Bléomycine", "Radiol Med 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42804145/", "doi_url": "https://doi.org/10.1007/s11547-026-02280-3", "pmc_url": "", "article_url": "https://doi.org/10.1007/s11547-026-02280-3"}, {"id": "pmid-42785703", "pmid": "42785703", "pmcid": "", "doi": "10.1016/j.neuchi.2026.101884", "title": "Spine interventional oncology: An illustrated review of minimally invasive techniques", "title_fr": "Oncologie interventionnelle rachidienne : revue illustrée des techniques mini-invasives (électrochimiothérapie épidurale, cimentoplastie cervicale, vissage odontoidien/sacré et thermo-ablation)", "authors_list": ["Hafiani H", "Shotar E", "Premat K", "Allard J", "Burel J", "Mazit A", "Deschamps F", "Tselikas L", "Beunon P", "Clarençon F", "Bonnet B"], "authors_short": "Hafiani H, Shotar E et al.", "journal": "Neuro-Chirurgie", "journal_short": "Neurochirurgie", "impact_factor": 1.8, "year": 2026, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2026", "volume": "72", "issue": "6", "pages": "101884", "category_id": "ect_mets", "category_label": "Électrochimiothérapie (ECT) & Métastases Osseuses", "category_short": "ECT (Bléomycine) & Métastases", "category_color": "#eab308", "modality": "Scanner Interventionnel / Angiographie Biplan / Cône-Beam CT", "intervention_type": "Électrochimiothérapie (ECT) Épidurale, Thermo-Ablation, Cimentoplastie Cervicale & Vissage", "cochin_link": "En lien direct avec les procédures complexes d'« électrochimiothérapie (ECT) rachidienne/épidurale, cimentoplastie cervicale et vissage pelvi-sacré » réalisées à Cochin.", "summary_fr_short": "Mise au point illustrée française (*Neurochirurgie*, sept. 2026, équipes Pitié-Salpêtrière & Rouen) synthétisant l'arsenal d'oncologie interventionnelle rachidienne : biopsie radioguidée, cimentoplastie des étages complexes (rachis cervical), fixation percutanée (odontoïde, sacrum, bassin), embolisation préopératoire, ablation thermique et électrochimiothérapie (ECT) en présence d'une épidurite.", "summary_fr_detailed": "Rédigée par des équipes françaises de radiologie interventionnelle ostéo-articulaire et neuroradiologique, cette revue détaille l'intégration complémentaire des gestes percutanés dans les métastases et tumeurs primitives du rachis. Au-delà de la vertébroplastie thoraco-lombaire standard, l'article précise les règles techniques et de sécurité pour les localisations à haut risque : cimentoplastie cervicale (abord antéro-latéral ou trans-oral), vissage percutané de l'odontoïde et des fractures-lyses sacro-pelviennes, thermo-ablation (RF/cryoablation sous thermoprotection épidurale et monitorage radiculaire) et électrochimiothérapie (ECT) à la bléomycine qui permet de traiter les extensions épidurales au contact du cordon médullaire sans risque de lésion thermique.", "protocol_fr": "Bilan pré-thérapeutique IRM + TDM (bilan de la corticale postérieure, de l'extension épidurale Bilsky et repérage de l'artère d'Adamkiewicz si nécessaire) • Choix personnalisé : thermo-ablation (RF/cryo) + cimentoplastie pour les lésions intracorporelles, ou électrochimiothérapie (ECT) non thermique en cas d'envahissement épidural ou radiculaire • Combinaison au vissage percutané en cas d'instabilité mécanique (SINS ≥ 7).", "key_points_fr": ["L'électrochimiothérapie (ECT) constitue l'alternative de choix à l'ablation thermique lorsqu'une coulée tumorale épidurale jouxte la moelle ou les racines.", "Détaille les corridors de sécurité pour la cimentoplastie cervicale, le vissage de l'odontoïde et la fixation spino-pelvienne percutanée.", "Insiste sur les stratégies de neuroprotection (dissection épidurale au CO2/sérum glucosé, thermométrie et monitorage neurophysiologique).", "Synthèse française de référence alignée sur l'intégralité du plateau technique interventionnel ostéo-articulaire de l'Hôpital Cochin."], "abstract_en": "Spine oncological interventional radiology has become an integral component of multidisciplinary care for patients with neoplastic spinal disease. Beyond conventional vertebral augmentation, the field now encompasses image-guided biopsy, cementoplasty at complex spinal levels, percutaneous fixation, preoperative embolization of hypervascular tumors, thermal ablation, and electrochemotherapy. These techniques address complementary objectives, including histological diagnosis, rapid pain relief, mechanical stabilization, facilitation of surgery, and local tumor control in selected patients. Advances in imaging guidance, procedural planning, and device technology have enabled increasingly precise and tailored interventions in anatomically constrained regions. However, the spine remains a high-risk anatomical territory because of the proximity of the spinal cord, nerve roots, radiculomedullary arteries, and major vascular structures. Procedural safety therefore depends on careful patient selection, detailed knowledge of spinal anatomy, rigorous planning, and multidisciplinary coordination. Particularly challenging scenarios include cervical cementoplasty, percutaneous fixation of odontoid, pelvic, or sacral lesions, and tumor treatment in the presence of epidural extension. This illustrated review summarizes the main minimally invasive techniques currently used in spine interventional oncology, with emphasis on their indications, technical principles, safety strategies, limitations, and integration into contemporary oncologic care pathways.", "tags": ["Oncologie interventionnelle rachidienne", "Électrochimiothérapie", "Cimentoplastie cervicale", "Vissage percutané", "Épidurite métastatique", "Neurochirurgie 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42785703/", "doi_url": "https://doi.org/10.1016/j.neuchi.2026.101884", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.neuchi.2026.101884"}, {"id": "pmid-42736384", "pmid": "42736384", "pmcid": "", "doi": "10.4274/dir.2026.263922", "title": "Examining the current image-guided biopsy and empiric antibiotic paradigm for suspected spondylodiscitis", "title_fr": "Biopsie disco-vertébrale guidée par l'image et antibiothérapie probabiliste préalable dans les suspicions de spondylodiscite (81 procédures)", "authors_list": ["Ott FW", "Hoover CD", "Helmer JA", "Nordseth TL", "Ehlers K", "Pluhm R", "Folkertsma M", "Özütemiz C", "Rykken JB"], "authors_short": "Ott FW, Hoover CD et al.", "journal": "Diagnostic and interventional radiology (Ankara, Turkey)", "journal_short": "Diagn Interv Radiol", "impact_factor": 1.9, "year": 2026, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2026", "volume": "", "issue": "", "pages": "", "category_id": "msk_biopsy", "category_label": "Biopsies Ostéo-Articulaires, Synoviales & Sarcomes", "category_short": "Biopsies TDM & Écho", "category_color": "#3b82f6", "modality": "Scanner Interventionnel / Fluoroscopie", "intervention_type": "Biopsie Disco-Vertébrale Percutanée pour Suspicion de Spondylodiscite", "cochin_link": "Répond à une question quotidienne de l'Agenda Cochin lors des demandes urgentes de « Biopsie disco-vertébrale sous scanner pour spondylodiscite » chez des patients déjà mis sous antibiotiques.", "summary_fr_short": "Étude rétrospective (*Diagnostic and Interventional Radiology*, sept. 2026, IF 1,9) sur 81 biopsies disco-vertébrales guidées par l'image (62 sous TDM, 19 sous scopie) : rendement microbiologique global de 37,0 % non significativement diminué par une antibiothérapie préalable (36,4 % sous antibiotiques vs 37,8 % sans antibiotiques, p = 0,890), soulignant qu'il ne faut pas retarder l'antibiothérapie probabiliste chez un patient septique et que la biologie moléculaire (ARN 16S / NGS) est indispensable pour compléter la culture.", "summary_fr_detailed": "Analysant 81 biopsies percutanées réalisées entre 2014 et 2025 pour suspicion de spondylodiscite infectieuse, cette étude compare le rendement des cultures microbiologiques selon le mode de guidage (TDM : 38,7 % vs fluoroscopie : 31,6 %, p = 0,586), le site prélevé (os transpédiculaire vs disque/aspiration, p > 0,60) et surtout l'exposition préalable aux antibiotiques. De façon notable, la positivité des cultures standard ne diffère pas significativement entre les patients ayant reçu une antibiothérapie avant le geste (36,4 %) et ceux vierges d'antibiotiques (37,8 %, p = 0,890). Hors tuberculose, 97 % des germes isolés étaient couverts par l'association probabiliste vancomycine + ceftriaxone. Les auteurs concluent que la culture isolée a une sensibilité modérée (44,4 %, spécificité 88,9 %) mais reste capitale en cas de suspicion de tuberculose/brucellose/fongique, d'échec clinique ou d'immunodépression.", "protocol_fr": "Abord transpédiculaire ou postéro-latéral disco-vertébral sous guidage scanner • Prélèvements multiples combinant carottes osseuses des plateaux vertébraux érodés, tissu discal et aspiration liquidienne éventuelle d'abcès paravertébral/psoas • Envoi systématique en bactériologie standard prolongée, mycobactériologie, anatomopathologie ET biologie moléculaire (PCR universelle ARN 16S) pour pallier la faible sensibilité des cultures seules.", "key_points_fr": ["Une antibiothérapie probabiliste débutée avant le geste n'annule pas le rendement de la biopsie (36,4 % vs 37,8 %, p = 0,890) et ne doit pas faire récuser d'emblée un prélèvement nécessaire (suspicion de BK, germe atypique ou échec thérapeutique).", "Rendement supérieur tendanciel du guidage TDM (38,7 %) par rapport à la fluoroscopie (31,6 %), avec sécurisation des abords thoraciques et paravertébraux.", "La sensibilité limitée des cultures conventionnelles (37–44 %) justifie d'associer systématiquement l'anatomopathologie et la PCR ARN 16S sur les carottes disco-vertébrales.", "Données pragmatiques très utiles pour arbitrer les demandes de biopsies de spondylodiscite en urgence différée à Cochin."], "abstract_en": "Purpose This study aims to identify factors associated with successful pathogen isolation via percutaneous image-guided biopsy (IGB) in suspected spondylodiscitis, compare diagnostic value between fluoroscopy and computed tomography (CT) guided IGB, evaluate the influence of empiric antibiotics prior to biopsy, and assess the impact of IGB results on clinical management and patient outcomes. Methods This retrospective study examined 81 IGBs (62 CT-guided, 19 fluoroscopy-guided) performed for suspected spondylodiscitis between March 2014 and February 2025. Retrospective diagnosis was determined using a composite of biopsy microbiology, clinical criteria, and radiologic findings. Primary analyses included IGB culture yield (procedural diagnostic return), as well as sensitivity, specificity, and diagnostic accuracy. Subgroup analyses included biopsy modality and prior antibiotic administration. Results The overall culture yield was 37.0%, with a sensitivity of 44.4% and a specificity of 88.9%. Culture yield did not differ significantly among patients who received antibiotics prior to biopsy (36.4%) and those who did not (37.8%; P = 0.890). Similarly, no significant difference in yield was observed between CT-guided (38.7%) and fluoroscopic IGB (31.6%; P = 0.586). No significant difference was observed between the coaxial devices used for either transpedicular bone biopsy ( P = 0.604) or disc biopsy/aspiration ( P = 1.000). Excluding tuberculosis (TB) case, 97% of cultured organisms were susceptible to the institution's standard empiric antibiotic regimen of vancomycin and ceftriaxone. Conclusion In cases of suspected spondylodiscitis, IGB demonstrated low sensitivity and rarely altered clinical management during the study. Culture yield was not significantly diminished by prior antibiotic therapy, and 97% of cultured organisms (excluding TB) were susceptible to this institution's standard empiric antibiotics. Furthermore, the relative infrequency of positive cultures suggests that empiric antibiotic initiation should not be delayed solely for the purpose of biopsy in clinically stable patients with characteristic magnetic resonance imaging findings and elevated inflammatory markers. Although the findings in this single-center retrospective study support consideration of a more selective use of IGB, further multicenter studies and meta-analyses are warranted. Clinical significance If additional larger studies corroborate these findings, this could result in a paradigm shift for the clinical management of suspected spondylodiscitis.", "tags": ["Spondylodiscite", "Biopsie disco-vertébrale", "Antibiothérapie préalable", "Scanner interventionnel", "Microbiologie", "Diagn Interv Radiol 2026"], "pdf_file": "pdfs/PMID_42736384.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 2489, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42736384/", "doi_url": "https://doi.org/10.4274/dir.2026.263922", "pmc_url": "", "article_url": "https://doi.org/10.4274/dir.2026.263922"}, {"id": "pmid-42997935", "pmid": "42997935", "pmcid": "PMC13743322", "doi": "10.21037/qims-2026-1-0086", "title": "Dynamic contrast-enhanced magnetic resonance imaging (MRI) and intravoxel incoherent motion imaging for characterizing angiogenesis in soft-tissue sarcomas: an exploratory study based on MRI-pathology co-alignment", "title_fr": "IRM de perfusion dynamique (DCE-MRI) et diffusion IVIM à 3T pour caractériser l'angiogenèse des sarcomes des tissus mous : étude de co-alignement radio-histologique", "authors_list": ["Zhang K", "Tao J", "Dai Y", "Huang J", "Li J", "Zhu Y", "Liu Y", "Liu Y", "Wang S"], "authors_short": "Zhang K, Tao J et al.", "journal": "Quantitative imaging in medicine and surgery", "journal_short": "Quant Imaging Med Surg", "impact_factor": 2.9, "year": 2026, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2026", "volume": "16", "issue": "11", "pages": "881", "category_id": "msk_imaging", "category_label": "Imagerie Ostéo-Articulaire Diagnostique & Suivi Post-Geste", "category_short": "IRM / TDM Diagnostique & Suivi", "category_color": "#6366f1", "modality": "IRM 3T Multiparamétrique (DCE-MRI Perfusion + Diffusion IVIM)", "intervention_type": "Cartographie IRM de l'Angiogenèse & Ciblage Biopsique des Sarcomes", "cochin_link": "Directement applicable aux « bilans IRM 3T pré-biopsiques et au ciblage des zones hypervasculaires viables des sarcomes des parties molles » en RCP Sarcome à Cochin.", "summary_fr_short": "Étude prospective sur 70 sarcomes des tissus mous en IRM 3T (*Quantitative Imaging in Medicine and Surgery*, nov. 2026) avec co-alignement spatial coupe-à-coupe IRM/anatomopathologie, démontrant que les paramètres Ktrans (DCE-MRI) et D* (IVIM) corrèlent fortement avec l'expression de VEGF et la densité microvasculaire (MVD) avec une AUC de 0,86.", "summary_fr_detailed": "L'évaluation non invasive de la néo-angiogenèse tumorale au sein des sarcomes des tissus mous (STS) est cruciale pour guider la biopsie percutanée hors des zones nécrotiques et évaluer la réponse aux thérapies ciblées ou anti-angiogéniques. Sur 70 patients explorés en IRM 3T (séquences de perfusion dynamique T1 DCE-MRI et diffusion bi-exponentielle IVIM) avec protocole de recalage spatial strict entre coupes IRM et lames histologiques, les paramètres de transfert vasculaire Ktrans (r = 0,673), Kep (r = 0,573), le coefficient de pseudo-diffusion D* (r = 0,692) et la fraction de perfusion f corrèlent significativement avec l'expression immunohistochimique du VEGF et la densité microvasculaire (MVD). Ktrans (AUC = 0,861) et D* (AUC = 0,860) constituent deux biomarqueurs indépendants majeurs de l'hypervascularisation sarcomateuse.", "protocol_fr": "IRM 3T pré-biopsique combinant : 1) séquence de diffusion IVIM multi-b (séparation de la diffusion moléculaire pure D et de la micro-perfusion capillaire D* et f sans injection) ; 2) séquence de perfusion dynamique T1 après injection de gadolinium (calcul des cartes paramétriques Ktrans, Kep et Ve) • Ciblage de la microbiopsie percutanée sur le « hot-spot » présentant le Ktrans et le D* les plus élevés.", "key_points_fr": ["Corrélation radio-histologique coupe-à-coupe démontrant que Ktrans (DCE-MRI) et D* (IVIM) reflètent fidèlement l'expression de VEGF et la densité microvasculaire.", "Excellente performance diagnostique de Ktrans (AUC 0,861) et D* (AUC 0,860) pour identifier les contingents sarcomateux fortement angiogéniques.", "La séquence IVIM permet d'estimer la fraction de perfusion microvasculaire (D*, f) même chez les patients insuffisants rénaux ne pouvant recevoir de gadolinium.", "Optimise le rendement de la microbiopsie percutanée à Cochin en guidant le trocart vers le foyer tumoral biologiquement le plus actif."], "abstract_en": "BACKGROUND: Vascular endothelial growth factor (VEGF) expression and microvessel density (MVD) are established markers of tumor angiogenesis and key targets for anti-angiogenic therapy in soft-tissue sarcomas (STSs). Dynamic contrast-enhanced magnetic resonance imaging (DCE-MRI) and intravoxel incoherent motion (IVIM) imaging are complementary magnetic resonance imaging (MRI) methods commonly used to assess angiogenesis in a variety of tumors. This study aimed to explore whether DCE-MRI and IVIM imaging could be used as non-invasive tools to evaluate tumor angiogenesis in STS based on MRI-pathology co-alignment. METHODS: In total, 70 patients with STS underwent 3.0-T DCE-MRI and IVIM imaging. The volume transfer constant (Ktrans), reflux rate constant (Kep), volume fraction of the extravascular extracellular space (Ve), true diffusion coefficient (D), pseudo-diffusion coefficient (D*), and perfusion fraction (f) were measured. Correlations between MRI parameters and VEGF expression or MVD were examined. Differences in MRI parameters between tumors with low and high VEGF expression were evaluated. Receiver operating characteristic (ROC) curves were generated, and interobserver reproducibility was assessed using the intraclass correlation coefficient (ICC). An MRI-pathology control protocol was implemented to verify the spatial correspondence between MRI slices and their corresponding histologic sections. RESULTS: Ktrans, Kep, D*, and f were positively correlated with VEGF expression (r=0.673, 0.573, 0.692, and 0.386, respectively) and MVD (r=0.662, 0.595, 0.619, and 0.344, respectively). Ktrans and D* were identified as independent factors associated with VEGF expression and MVD. No significant correlations were observed between Ve or D and either angiogenesis marker. Tumors with high VEGF expression exhibited higher Ktrans, Kep, D*, and f values than those with low VEGF expression. The areas under the ROC curves for the four parameters in differentiating between tumors with low and high VEGF expression were 0.861, 0.844, 0.860, and 0.720, respectively. CONCLUSIONS: The study demonstrated associations between DCE-MRI- and IVIM-derived perfusion metrics and VEGF expression and MVD in STSs.", "tags": ["Sarcome des tissus mous", "DCE-MRI", "Diffusion IVIM", "Angiogenèse", "Concordance IRM-histologie", "Quant Imaging Med Surg 2026"], "pdf_file": "pdfs/PMID_42997935.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 13897, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42997935/", "doi_url": "https://doi.org/10.21037/qims-2026-1-0086", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13743322/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13743322/"}, {"id": "pmid-42803442", "pmid": "42803442", "pmcid": "", "doi": "10.1093/pm/pnag130", "title": "Mapping Genicular Nerve Endings for Optimal Pain Management: A Comparative Cadaveric Analysis Between Native Versus Prosthetic Knee", "title_fr": "Cartographie anatomique des terminaisons des nerfs géniculés sur genou natif vs prothétique : optimisation du bloc test et de la radiofréquence", "authors_list": ["Fodjeu G", "Fonkoué L", "Dongmo Mayopa C", "Manon J", "Bombah F", "Detrembleur C", "Cornu O", "Behets C"], "authors_short": "Fodjeu G, Fonkoué L et al.", "journal": "Pain medicine (Malden, Mass.)", "journal_short": "Pain Med", "impact_factor": 2.9, "year": 2026, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2026", "volume": "", "issue": "", "pages": "pnag130", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Échographie / Fluoroscopie", "intervention_type": "Bloc & RF Nerfs Géniculés", "cochin_link": "Précise les zones cibles capsulaires optimales pour les tests anesthésiques du genou sous échographie (Pavillon Ollier) et les radiofréquences des nerfs géniculés.", "summary_fr_short": "Étude anatomique et histologique (*Pain Medicine*, septembre 2026 — Fonkoué et al.) cartographiant la densité des terminaisons nociceptives des nerfs géniculés dans la capsule du genou natif et prothétique afin d'affiner le positionnement des aiguilles de bloc et de radiofréquence.", "summary_fr_detailed": "Cet article compare l'innervation nociceptive intracapsulaire et la densité vasculaire des différents quadrants du genou natif arthrosique et du genou douloureux post-prothèse totale (PTG). L'étude confirme une prédominance majeure des fibres nociceptives dans les quadrants supéro-médial, supéro-latéral et inféro-médial, au contact étroit des artères géniculées périostées, justifiant le repérage écho-Doppler lors du bloc pronostique et un ciblage élargi lors de la thermocoagulation RF ou de la cryoneurolyse.", "protocol_fr": "Repérage écho-Doppler des pédicules vasculaires géniculés au contact de la corticale métaphyso-épiphysaire • Bloc test diagnostique faible volume (0,5–1 mL) sur SMGN, SLGN et IMGN • En cas de gonalgie persistante post-PTG ou post-geste cartilagineux, ciblage identique des troncs afférents extra-capsulaires.", "key_points_fr": ["Forte corrélation anatomique entre les pédicules artériels géniculés (visibles en Doppler) et la densité des terminaisons nerveuses nociceptives.", "Applicable aussi bien à la gonarthrose sur genou natif qu'aux douleurs chroniques persistantes après chirurgie ou geste articulaire du genou.", "Confirme l'intérêt d'un ciblage précis contre le périoste fémoral et tibial pour capter les rameaux articulaires avant leur arborisation capsulaire."], "abstract_en": "Background Chronic knee pain, often due to osteoarthritis (OA), is frequently treated with genicular nerve blocks, radiofrequency ablation (RFA) or genicular artery embolization (GAE). However, the intracapsular distribution of nerve endings and vascular networks key pain parameters remains poorly defined in native and prosthetic knees. Questions/purposes We compared the distribution of intracapsular nerve endings and vascular density in native versus prosthetic knee capsules across five genicular nerve targets in relation to knee pain. Methods Ten native and ten prosthetic cadaveric knees were analyzed. Capsular samples (20 × 5 mm) were harvested from regions innervated by the superior medial, superior lateral, and inferior genicular nerves, the recurrent fibular nerve, and the infrapatellar branch of the saphenous nerve. Nerve endings and vascular densities were quantified after histologic and immunohistochemical analysis comparatively. Results Native knees had higher free nerve ending (FNE) density (p Conclusion Dense FNE populations in native knees support genicular nerve-targeted interventions for OA pain. The increased vascularity and mechanoreceptor innervation identified in prosthetic knees suggest that inflammatory, angiogenic, and sensory mechanisms may contribute to persistent post-surgical pain. Whether interventions targeting these pathways, such as radiofrequency ablation or genicular artery embolization, provide better clinical benefit together remains to be established.", "tags": ["Nerfs géniculés", "Radiofréquence", "Bloc test", "Échographie", "Pain Medicine 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42803442/", "doi_url": "https://doi.org/10.1093/pm/pnag130", "pmc_url": "", "article_url": "https://doi.org/10.1093/pm/pnag130"}, {"id": "pmid-42742682", "pmid": "42742682", "pmcid": "", "doi": "10.1007/s00256-026-05365-2", "title": "Local anesthetic selection for spine and large joint radiofrequency ablation: a practical review for the musculoskeletal radiologist", "title_fr": "Sélection et protocole des anesthésiques locaux lors de l'ablation par radiofréquence (RFA) rachidienne et des grandes articulations : guide pratique pour le radiologue ostéo-articulaire", "authors_list": ["Gonzalez FM", "Smirniotopoulos JB"], "authors_short": "Gonzalez FM, Smirniotopoulos JB", "journal": "Skeletal radiology", "journal_short": "Skeletal Radiol", "impact_factor": 1.9, "year": 2026, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2026", "volume": "55", "issue": "12", "pages": "3119-3136", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Scanner / Fluoroscopie / Échographie Interventionnelle", "intervention_type": "Radiofréquence Nerveuse Articulaire (Géniculés, Hanche, SI) & Rachidienne", "cochin_link": "Guide directement le protocole pharmacologique des « tests anesthésiques et radiofréquences des nerfs géniculés, articulaires postérieurs et sacro-iliaques » à Cochin.", "summary_fr_short": "Mise au point pratique (*Skeletal Radiology*, sept. 2026) définissant le choix, la concentration et le séquençage des anesthésiques locaux lors des procédures de radiofréquence (RFA) rachidienne (branches médiales), sacro-iliaque et des grandes articulations périphériques (genou, hanche, épaule) afin de préserver la fiabilité des tests de stimulation motrice/sensitive et d'optimiser l'analgésie.", "summary_fr_detailed": "Lors des procédures de neurolyse par radiofréquence (nerfs géniculés du genou, branches articulaires de hanche, rameaux médiaux rachidiens et branches latérales sacro-iliaques), l'administration d'anesthésique local (AL) sur le trajet de ponction puis en périneural conditionne à la fois le confort du patient et la validité du test de stimulation neurophysiologique. Cette revue de *Skeletal Radiology* établit que : 1) la lidocaïne à 1 % est le standard pour l'anesthésie cutanée et du trajet superficiel ; 2) il faut éviter d'injecter de la lidocaïne à 2 % au contact immédiat du nerf cible avant les tests de stimulation sensitive et motrice pour ne pas abolir la réponse d'alerte motrice ; 3) avant le cycle de thermo-ablation, la bupivacaïne 0,25 % ou la ropivacaïne 0,2 % (préférable en cas de procédure multi-étagée ou de trouble conductif cardiaque) offre la meilleure analgésie post-procédure, sans aucun bénéfice démontré au mélange lidocaïne + bupivacaïne.", "protocol_fr": "Anesthésie cutanée et du trajet superficiel à la lidocaïne 1 % en restant à distance du nerf cible • Positionnement de la canule de radiofréquence sous guidage écho/scopie/TDM • Réalisation des tests de stimulation sensitive (50 Hz) et motrice (2 Hz) avant toute infiltration périneurale profonde • Injection périneurale pré-lésionnelle de 0,5 à 1 mL de ropivacaïne 0,2 % (ou bupivacaïne 0,25 %) 60 à 90 secondes avant le cycle thermique.", "key_points_fr": ["Ne jamais infiltrer le nerf cible (surtout à la lidocaïne 2 %) avant d'avoir effectué les tests de stimulation sensitive (50 Hz) et motrice (2 Hz).", "Le mélange empirique lidocaïne + bupivacaïne n'accélère pas le délai d'action par rapport à l'anesthésique seul et réduit la durée d'analgésie prolongée.", "Privilégier la ropivacaïne 0,2 % (profil cardiotoxique plus sûr) lors des dénervations multi-sites (3 nerfs géniculés ou branches sacro-iliaques).", "Fournit un algorithme structuré de substitution en cas d'allergie documentée aux amino-amides."], "abstract_en": "Local anesthetic (LA) selection for radiofrequency ablation (RFA) of spinal medial branch nerves, sacroiliac joint lateral branches, and large peripheral joint articular branches has not been addressed by any dedicated document. The concentration, class, and sequencing of agents used during needle placement, stimulation testing, and pre-lesioning injection have plausible implications for procedural accuracy and post-procedural analgesia. This review synthesizes pharmacological data and adjacent procedural literature into practice considerations for the musculoskeletal radiologist. No randomized or prospective comparative trial has evaluated LA agents, concentrations, or sequencing within an RFA procedure; every statement therefore rests on indirect evidence, mechanistic reasoning, or the authors' practice, and each is labeled accordingly. Lidocaine 1% is a reasonable default for skin, subcutaneous, and deep track anesthesia. Where sensory and/or motor stimulation testing is performed, there is a mechanistic argument for avoiding lidocaine 2% close to the target nerve, since selectivity between fiber classes falls as concentration rises; that argument derives from epidural quantitative sensory testing and rodent electrophysiology, has not been tested in RFA, and no study has shown that lidocaine 2% impairs stimulation testing or procedural outcome. Bupivacaine 0.25% or ropivacaine 0.2% is a reasonable choice for perineural injection before lesioning. Premixing lidocaine and bupivacaine has no demonstrated advantage: across five randomized trials, all outside interventional pain settings and heterogeneous in design, mixtures did not accelerate onset relative to bupivacaine alone and in several curtailed its duration; two also found same-site sequential injection no better than premixing. Ropivacaine is a reasonable preference in cardiac conduction disease or multi-level procedures. A structured allergy substitution pathway is provided with formal allergist evaluation as the central step. These considerations are offered to inform practice and to prompt the prospective studies the field lacks.", "tags": ["Radiofréquence nerveuse", "Anesthésiques locaux", "Ropivacaïne", "Nerfs géniculés", "Stimulation motrice", "Skeletal Radiol 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42742682/", "doi_url": "https://doi.org/10.1007/s00256-026-05365-2", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00256-026-05365-2"}, {"id": "pmid-42804317", "pmid": "42804317", "pmcid": "", "doi": "", "title": "Predictors of Treatment Success After Intercostal Nerve Radiofrequency for Intercostal Neuralgia: A Retrospective", "title_fr": "Facteurs prédictifs de succès de la radiofréquence des nerfs intercostaux dans les névralgies intercostales réfractaires : radiofréquence thermique conventionnelle vs pulsée (60 patients)", "authors_list": ["Yavuz K", "Bakir M", "Bayburtluoglu E", "Ilcan B", "Teker N", "Rumeli S"], "authors_short": "Yavuz K, Bakir M et al.", "journal": "Pain physician", "journal_short": "Pain Physician", "impact_factor": 3.1, "year": 2026, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2026", "volume": "29", "issue": "6", "pages": "E671-E677", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Échographie / Scanner Interventionnel", "intervention_type": "Radiofréquence Conventionnelle & Pulsée des Nerfs Intercostaux", "cochin_link": "Complète directement la prise en charge des douleurs pariétales thoraciques de l'Agenda Cochin (« Neurolyse / Cryoneurolyse et radiofréquence du nerf intercostal »).", "summary_fr_short": "Étude comparative rétrospective (*Pain Physician*, sept. 2026, IF 3,1) chez 60 adultes souffrant de névralgie intercostale post-traumatique, post-zostérienne ou idiopathique réfractaire : la radiofréquence thermique conventionnelle (CRF, n = 31) procure une analgésie nettement plus durable à 3 et 6 mois que la radiofréquence pulsée (PRF, n = 29 ; NRS à 6 mois : 2,81 ± 1,93 vs 6,31 ± 2,34, p < 0,001) et constitue le seul facteur prédictif indépendant de réponse clinique IMMPACT (OR = 9,40 ; p = 0,001).", "summary_fr_detailed": "Les névralgies intercostales chroniques (post-thoracotomie, post-traumatiques, post-zostériennes) altèrent sévèrement la qualité de vie. Cette cohorte compare deux modalités de neurolyse guidée par l'image des nerfs intercostaux : la radiofréquence thermique conventionnelle ablative (CRF) et la radiofréquence pulsée neuromodulatrice non destructrice (PRF), avec évaluation à 3 et 6 mois selon les critères IMMPACT (réduction ≥ 50 % ou ≥ 4 points du score NRS-11). Alors que les deux techniques soulagent transitoirement la douleur initiale, la CRF maintient un score NRS bas à 3 mois (2,77 vs 5,83, p < 0,001) et à 6 mois (2,81 vs 6,31, p < 0,001). En régression logistique multivariée incluant l'âge, le sexe, l'allodynie et l'intensité douloureuse initiale, le choix d'une modalité ablative vraie (CRF versus PRF) multiplie par 9,4 la probabilité de succès durable à 6 mois.", "protocol_fr": "Repérage sous échographie haute fréquence ou scanner du sillon sous-costal au bord inférieur de la côte cible (à distance de la plèvre pariétale et du pédicule vasculaire intercostal) • Stimulation sensitive (50 Hz, reproduction de la topographie douloureuse < 0,5 V) et motrice • Anesthésie locale lidocaïne 1–2 % avant lésion thermique (CRF 80°C pendant 60–90 s, ou alternative par cryoneurolyse -60°C/-70°C à Cochin évitant la névrite de désafférentation).", "key_points_fr": ["Démontre la supériorité franche d'une neurolyse axonotmétique vraie (RF conventionnelle : NRS 2,8 à 6 mois) sur la simple neuromodulation pulsée (PRF : NRS 6,3 à 6 mois, OR = 9,40).", "Ni la présence d'allodynie ni l'âge n'ont empêché la réponse clinique en analyse multivariée.", "Confirme que pour les douleurs pariétales thoraciques rebelles, une modalité neurolytique (RF conventionnelle ou cryoneurolyse intercostale sous scanner telle que pratiquée à Cochin) offre un contrôle bien plus durable que la PRF.", "Rappelle l'importance du guidage imagerie continu pour prévenir tout risque de pneumothorax ou de brèche vasculaire sous-costale."], "abstract_en": "Background Intercostal neuralgia, which is characterized by neuropathic pain along the distribution of the intercostal nerves (ICNs), can impair patients' quality of life substantially. ICN-targeted radiofrequency (RF) treatment is used increasingly in current practice; however, data on factors that predict the success of such treatments remain limited. Objectives This study aims to evaluate factors associated with treatment success in patients with intercostal neuralgia who underwent ICN-targeted RF treatment. Study design A retrospective cohort study. Setting A single-center retrospective study conducted at Mersin University Faculty of Medicine Hospital. Methods This retrospective chart review included adults who had post-traumatic, postherpetic, or idiopathic intercostal neuralgia and underwent ultrasound-guided conventional radiofrequency ablation (CRF) or pulsed radiofrequency treatment (PRF) on their ICNs between January 1, 2018, and May 30, 2025. Pain intensity (measured on the NRS-11) was assessed at baseline and at 3 and 6 months after the procedure. The primary outcome was the 6-month treatment response (according to IMMPACT criteria: ≥ 50% pain reduction or a ≥ 4-point decrease in NRS score from its baseline counterpart). Group comparisons and multivariable logistic regression were performed to evaluate the outcomes and predictors of response. Results Sixty patients were included in the analysis (CRF, n = 31; PRF, n = 29). At both 3 and 6 months, mean NRS scores were significantly lower in the CRF group than in the PRF group (3 months: 2.77 ± 1.80 vs 5.83 ± 2.55; P Limitations The single-center setting, relatively small sample size, and retrospective study design. Conclusions Ultrasound-guided intercostal CRF may provide clinically meaningful analgesia for patients with refractory intercostal neuralgia. Although both modalities were associated with short-term pain improvement, CRF produced significantly more sustained pain reduction at 3 and 6 months and emerged as the sole independent predictor of treatment success.", "tags": ["Nerf intercostal", "Névralgie intercostale", "Radiofréquence", "Douleur thoracique", "Neurolyse", "Pain Physician 2026"], "pdf_file": "pdfs/PMID_42804317.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 492, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42804317/", "doi_url": "https://pubmed.ncbi.nlm.nih.gov/42804317/", "pmc_url": "", "article_url": "https://pubmed.ncbi.nlm.nih.gov/42804317/"}, {"id": "pmid-42782915", "pmid": "42782915", "pmcid": "PMC13605485", "doi": "10.3390/curroncol33090569", "title": "Pre-Spondylectomy Radiofrequency Ablation for Spinal Chordoma: An Illustrative Case and Systematic Review of Clinical Applications and Outcomes", "title_fr": "Ablation thermique percutanée (radiofréquence et cryoablation) des chordomes rachidiens et sacrés : revue systématique sur 34 lésions et protocole pré-spondylectomie combiné à la vertébroplastie", "authors_list": ["Husbands H", "Johnston D", "Tharakan M", "Hussan A", "Balasubramanian K", "Bettiol P", "Chou B", "Hameed S", "Smith ZA", "Janjua MB", "Burke JF", "Shakir HJ"], "authors_short": "Husbands H, Johnston D et al.", "journal": "Current oncology (Toronto, Ont.)", "journal_short": "Curr Oncol", "impact_factor": 2.8, "year": 2026, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2026", "volume": "33", "issue": "9", "pages": "569", "category_id": "percutaneous_ablation_general", "category_label": "Ablation Percutanée Tumorale : Standards, Endométriome & Oncologie", "category_short": "Ablation Percutanée (Standards & Onco)", "category_color": "#e11d48", "modality": "Scanner Interventionnel + Fluoroscopie", "intervention_type": "Radiofréquence / Cryoablation & Cimentoplastie de Chordome Rachidien / Sacré", "cochin_link": "En lien direct avec les procédures d'« ablation thermique percutanée (cryoablation / RF) et cimentoplastie des tumeurs rachidiennes et sacrées » réalisées à Cochin.", "summary_fr_short": "Revue systématique (*Current Oncology*, sept. 2026, 13 études / 33 patients / 34 sites de chordomes rachidiens ou sacrés traités par cryoablation [n=21] ou radiofréquence [n=11]) et cas illustratif de chordome L4 traité par RFA + vertébroplastie scanoguidée avant spondylectomie en bloc, sans déficit neurologique ni récidive à 18 mois.", "summary_fr_detailed": "Les chordomes du rachis mobile et du sacrum sont des tumeurs malignes localement agressives et radio-résistantes dont la résection chirurgicale en bloc expose à une lourde morbidité fonctionnelle et à un risque de dissémination lors de l'ostéotomie. Cette revue systématique synthétise 34 procédures d'ablation thermique guidée par l'image (21 par cryoablation, 11 par radiofréquence, 1 par LITT) réalisées soit en néoadjuvant avant résection en bloc, soit à visée curative/palliative pour les récidives locales inopérables. Les auteurs rapportent également un protocole séquentiel associant RFA bipolaire scanoguidée et vertébroplastie consolidatrice d'un chordome L4 avant spondylectomie en bloc, permettant une nécrose tumorale centrale, une réduction du saignement peropératoire et une survie sans récidive à 18 mois sans complication neurologique.", "protocol_fr": "Repérage TDM/IRM précis des rapports avec le fourreau dural et les racines lombaires/sacrées • Thermoprotection épidurale et foraminale (hydrodissection / carbodissection + thermocouples) et monitorage neurophysiologique • Cryoablation multi-sondes (visualisation de l'iceball sur les chordomes sacrés) ou RFA + vertébroplastie acrylique sur le corps vertébral du rachis mobile.", "key_points_fr": ["Sur 34 chordomes rachidiens/sacrés traités par ablation percutanée, la cryoablation (62 %) et la RFA (32 %) assurent un contrôle antalgique et local avec peu de complications.", "En situation néoadjuvante pré-spondylectomie, le couplage RFA + vertébroplastie stérilise le contingent corporéal et limite le risque d'essaimage peropératoire.", "Dans les récidives locales sacrées inopérables ou post-radiques, la cryoablation scanoguidée constitue une option de rattrapage mini-invasive précieuse.", "Illustre la complémentarité entre radiologie interventionnelle ostéo-articulaire et chirurgie rachidienne oncologique."], "abstract_en": "Chordomas are rare, locally aggressive spinal tumors. En bloc resection may improve local control but can cause substantial morbidity. Thermal ablation may provide a less invasive adjunct or alternative in selected cases. We systematically reviewed reports of radiofrequency ablation (RFA), cryoablation, laser interstitial thermal therapy, high-intensity focused ultrasound, and similar thermal techniques for spinal or sacral chordoma to characterize their clinical applications and reported clinical and radiographic outcomes across pre-resection, primary non-operative, and palliative settings. Eligible studies reported at least one ablation-related clinical or radiographic outcome. Data were descriptively synthesized, and risk of bias was assessed using the Joanna Briggs Institute criteria. Thirteen studies including 33 patients and 34 ablated sites were identified. Cryoablation was used in 21 patients, RFA in 11 patients, and laser interstitial thermal therapy in one patient. Ablation was used as a pre-resection adjunct, primary treatment for unresectable disease, or palliation for recurrent or metastatic lesions. Most reports described pain improvement, short-term local stability, and few major complications. We also report an L4 chordoma treated with CT-guided RFA and vertebroplasty before staged en bloc spondylectomy, without a new neurologic deficit or local recurrence at 18 months. Thermal ablation may be a technically feasible adjunct, primary non-operative option, or palliative strategy for carefully selected spinal and sacral chordomas. In the presented mobile-spine case, planned pre-spondylectomy RFA was feasible before staged en bloc resection; however, limited follow-up and sparse heterogeneous literature preclude conclusions regarding long-term local control, recurrence reduction, survival, or routine use. Ablation should not replace oncologically appropriate en bloc resection when that procedure can be safely achieved and should be considered selectively within multidisciplinary chordoma care.", "tags": ["Chordome", "Rachis", "Sacrum", "Radiofréquence", "Cryoablation", "Vertébroplastie", "Curr Oncol 2026"], "pdf_file": "pdfs/PMID_42782915.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1347, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42782915/", "doi_url": "https://doi.org/10.3390/curroncol33090569", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13605485/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13605485/"}, {"id": "pmid-42671500", "pmid": "42671500", "pmcid": "", "doi": "10.1007/s11701-026-03900-w", "title": "Robot-assisted targeting for osteoid osteoma: a systematic review", "title_fr": "Ciblage assisté par robotique pour le traitement percutané de l'ostéome ostéoïde : revue systématique sur 440 procédures", "authors_list": ["Vu DN", "Dang NH", "Nguyen TT", "Nguyen TT", "Vu DA"], "authors_short": "Vu DN, Dang NH et al.", "journal": "Journal of robotic surgery", "journal_short": "J Robot Surg", "impact_factor": 2.2, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "20", "issue": "1", "pages": "919", "category_id": "ablation_benign", "category_label": "Ablation Thermique des Tumeurs Osseuses Bénignes", "category_short": "RF & Cryo (OO / Chondroblastome / TCG)", "category_color": "#f97316", "modality": "Scanner Interventionnel / Guidage Robotique & Navigation 3D", "intervention_type": "Thermo-Ablation Percutanée (RF / Cryoablation) d'Ostéome Ostéoïde", "cochin_link": "Complète la réflexion technique sur le « guidage TDM de haute précision pour radiofréquence et cryoablation d'ostéome ostéoïde (rachis, col fémoral, talus) » à Cochin.", "summary_fr_short": "Revue systématique (*Journal of Robotic Surgery*, août 2026, 12 études / 440 procédures dont 232 assistées par robot) évaluant l'apport du positionnement robotique lors du forage et de l'ablation thermique des ostéomes ostéoïdes : réduction du nombre de repositionnements de broche et fenêtres osseuses plus économiques, avec une efficacité clinique et une sécurité équivalentes au guidage TDM expert à main levée.", "summary_fr_detailed": "L'accès millimétrique au nidus de l'ostéome ostéoïde (notamment dans les localisations profondes, péri-articulaires ou rachidiennes proches des structures nerveuses) conditionne le succès de la radiofréquence ou de la cryoablation. Cette revue systématique analyse 440 cas traités (dont 232 avec assistance robotique contraignant la trajectoire du trocart). Le guidage robotique réduit le nombre de corrections d'angle de la broche de Kirschner et raccourcit le temps de ciblage balistique initial. En revanche, à modalité d'ablation thermique constante (RFA ou cryoablation), les taux de succès clinique définitif, de récidive et de complications ne diffèrent pas significativement d'un guidage scanographique conventionnel réalisé par un opérateur entraîné.", "protocol_fr": "Acquisition TDM en coupes fines millimétriques centrée sur le nidus calcifié ou hypodense • Planification 3D de la trajectoire trans-corticale optimale évitant les pédicules vasculo-nerveux et le cartilage articulaire • Forage coaxial (11G–14G) jusqu'au centre du nidus (avec approche no-touch en cryoablation pour les localisations superficielles ou juxta-articulaires) • Thermo-ablation RF (90°C pendant 6 min) ou cryoablation.", "key_points_fr": ["Sur 440 procédures analysées, le facteur déterminant du succès reste l'ablation thermique complète du nidus plutôt que le recours à un bras robotique.", "L'assistance balistique diminue le nombre de réorientations d'aiguille dans les trajectoires obliques complexes (bassin, rachis, col fémoral).", "Les taux de guérison clinique (> 90–95 %) et de complications demeurent identiques au guidage TDM à main levée pratiqué en centre expert.", "Confirme l'excellence du standard actuel par thermo-ablation scanoguidée directe (RF ou cryoablation no-touch) réalisé à Cochin."], "abstract_en": "Accurate nidus access is essential for treating osteoid osteoma, but the incremental contribution of physical robotic targeting should be distinguished from imaging, definitive treatment, and the wider care pathway. We systematically reviewed peer-reviewed human reports in which a robot physically positioned or constrained an instrument used for biopsy or treatment. PubMed/MEDLINE, Embase, Web of Science Core Collection, the Cochrane Library, Wanfang Data and the China National Knowledge Infrastructure were searched from inception through August 2026, without a final language restriction. Primary outcomes were success, recurrence or retreatment, and treatment-related complications. Secondary outcomes included localization, instrument corrections, radiation, procedure time, diagnostic yield, recovery, and cost. Twelve reports contained 440 report-level treatment records, including 232 robot-assisted procedures, before assessment of probable or possible overlap. Evidence comprised seven retrospective comparisons, four uncontrolled series, and one case report. Robot-proximal findings generally favored more reproducible or conservative access, including fewer Kirschner-wire corrections, shorter localization, greater resection accuracy, or a smaller bone window. Procedure-time effects varied by comparator and workflow. In comparisons that approximately held treatment constant, clinical success, later pain, recurrence, and complications were not clearly improved. Apparent advantages over open surgery mainly reflected minimally invasive access or treatment modality rather than robotic targeting alone. Meta-analysis was not performed because clinically equivalent comparisons were not independently replicated, outcome definitions differed, and cohort overlap was probable or possible. Comparative certainty was very low. Robotic targeting may improve trajectory execution in technically demanding lesions, but superior long-term effectiveness, safety, diagnostic adequacy, robot-attributable radiation reduction, and cost-effectiveness remain unproven.", "tags": ["Ostéome ostéoïde", "Radiofréquence", "Guidage scanographique", "Robotique interventionnelle", "Nidus", "J Robot Surg 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42671500/", "doi_url": "https://doi.org/10.1007/s11701-026-03900-w", "pmc_url": "", "article_url": "https://doi.org/10.1007/s11701-026-03900-w"}, {"id": "pmid-42663695", "pmid": "42663695", "pmcid": "", "doi": "10.1007/s00590-026-04935-3", "title": "Avoiding pitfalls in percutaneous acetabular column screw placement using combined fluoroscopic check-point views: a technical note and case series", "title_fr": "Éviter les pièges du vissage percutané des colonnes acétabulaires grâce aux incidences fluoroscopiques de contrôle combinées (COOHO, Outlet et Profil strict)", "authors_list": ["Godinho M", "Serra M", "Solano AJ", "Nardi M", "Krieg BA", "Tucker NJ", "Hellwinkel JE", "Schlauch A", "Schaffer NE", "Mauffrey C"], "authors_short": "Godinho M, Serra M et al.", "journal": "European journal of orthopaedic surgery & traumatology : orthopedie traumatologie", "journal_short": "Eur J Orthop Surg Traumatol", "impact_factor": 1.5, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "36", "issue": "1", "pages": "353", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Fluoroscopie / Cone-Beam CT / Scanner TDM", "intervention_type": "Vissage Percutané des Colonnes Antérieure et Postérieure du Cotyle", "cochin_link": "Directement applicable aux vissages percutanés du bassin et du cotyle (colonnes antérieure et postérieure, montage tripode) pratiqués à Cochin.", "summary_fr_short": "Note technique et série clinique (*Eur J Orthop Surg Traumatol*, août 2026) décrivant trois incidences fluoroscopiques spécifiques — dont la vue combinée 'Obturator Oblique Hyper-Outlet' (COOHO) — pour démasquer les effractions corticales 'in-out-in' lors du vissage percutané des colonnes acétabulaires.", "summary_fr_detailed": "Les incidences fluoroscopiques orthogonales standard (alarme/iliaque et obturatrice) peuvent masquer une brèche corticale extra-osseuse ('in-out-in') lors du vissage rétrograde ou antérograde des colonnes du cotyle. Cet article valide sur modèle pelvien et série clinique l'utilisation de l'incidence COOHO (Combined Obturator Oblique Hyper-Outlet) pour la colonne antérieure : elle profile tangentiellement le récessus pectiné et la gouttière ilio-psoas, détectant immédiatement toute sortie corticale antéro-supérieure. Pour la colonne postérieure, l'ajout systématique des vues Outlet et Profil strict (True Lateral) permet de visualiser l'étendue verticale de la ligne ilio-ischiatique et de prévenir toute effraction médiale dans la lame quadrilatère ou postérieure dans la petite échancrure sciatique.", "protocol_fr": "Colonne antérieure (AC) : contrôler systématiquement la broche-guide en incidence COOHO (obturatrice + hyper-outlet) pour éliminer un trajet 'in-out-in' dans la gouttière du psoas • Colonne postérieure (PC) : compléter les vues iliaque/obturatrice par un Outlet et un Profil sacré strict (True Lateral) pour sécuriser la lame quadrilatère et l'échancrure sciatique.", "key_points_fr": ["Les vues fluoroscopiques classiques peuvent donner une fausse impression de trajet intra-osseux dans les couloirs acétabulaires étroits.", "L'incidence COOHO (Combined Obturator Oblique Hyper-Outlet) profile tangentiellement la gouttière ilio-psoas et le récessus pectiné pour sécuriser la vis de colonne antérieure.", "Le couple Outlet + Profil strict (True Lateral) sécurise la colonne postérieure en regard de la petite échancrure sciatique et de la lame quadrilatère.", "Repères fluoroscopiques rapides directement intégrables au bloc interventionnel (arceau 3D / TDM)."], "abstract_en": "Standard fluoroscopic views may not detect cortical breaches during percutaneous acetabular column screw placement, creating an illusion of safe intraosseous positioning. The purpose of this study was to illustrate use of simple fluoroscopic checkpoint projections-the combined obturator oblique hyper-outlet (COOHO) view for anterior column (AC) screws and two known additional views, outlet and true lateral (TL), for posterior column (PC) screws-as a method to demonstrate extraosseous screw trajectories that might be missed by standard tangential column fluoroscopic views. Six clinical cases are presented as examples of standard orthogonal fluoroscopic views failing to detect extraosseous screw placement. The cases are supplemented by a synthetic pelvic model demonstration to define radiographic landmarks and common screw malposition. Guidewires were advanced in the pelvic model columns, either intraosseous or extraosseous, and their paths were evaluated with standard fluoroscopic views compared to COOHO and outlet and TL views. For the AC, COOHO tangentially profiles the pectineus recess and iliopsoas gutter to unmask in-out-in paths. For the PC, iliac and obturator oblique views may miss medial or posterior breach near the lesser sciatic notch and quadrilateral plate. The outlet and TL views show the vertical extent of the ilioischial line to detect medial or posterior breech and length-orientation errors. The COOHO, outlet and TL views additional projections that improve tangential visualization of high-risk cortices and detection of extraosseous trajectories.", "tags": ["Vissage cotyle", "Colonne antérieure", "Colonne postérieure", "Incidence COOHO", "Fluoroscopie", "Bassin"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42663695/", "doi_url": "https://doi.org/10.1007/s00590-026-04935-3", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00590-026-04935-3"}, {"id": "pmid-42947096", "pmid": "42947096", "pmcid": "PMC13715128", "doi": "10.1186/s12957-026-04531-z", "title": "Analysis of bone metastasis multidisciplinary team meeting activity in a university hospital: patient profiles, prognostic factors", "title_fr": "Analyse de l'activité d'une RCP Métastases Osseuses en CHU (AP-HP Pitié-Salpêtrière) sur 630 patients : profils cliniques, facteurs pronostiques et place centrale de la cimentoplastie", "authors_list": ["Chanzy P", "Khalifé M", "Morardet L", "Pascal-Moussellard H", "Bonaccorsi R", "Marie-Hardy L"], "authors_short": "Chanzy P, Khalifé M et al.", "journal": "World journal of surgical oncology", "journal_short": "World J Surg Oncol", "impact_factor": 2.5, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "24", "issue": "1", "pages": "408", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Scanner / Fluoroscopie Interventionnelle & Concertation Pluridisciplinaire (RCP)", "intervention_type": "Cimentoplastie Vertébrale / Pelvienne & Stratégie Pluridisciplinaire Osseuse", "cochin_link": "Miroir direct de l'activité parisienne AP-HP de « cimentoplastie vertébrale/pelvienne et vissage percutané discutés en RCP Métastases Osseuses » à l'Hôpital Cochin.", "summary_fr_short": "Étude rétrospective de l'équipe AP-HP Pitié-Salpêtrière (*World Journal of Surgical Oncology*, août 2026, 992 dossiers / 630 patients) analysant l'activité d'une RCP Métastases Osseuses universitaire : atteinte rachidienne dans 85 % et pelvienne dans 51 % des cas, avec recours à la cimentoplastie percutanée chez 39 % des patients (contre 22 % de chirurgie).", "summary_fr_detailed": "Cette série française de l'AP-HP analyse 992 présentations consécutives en Réunion de Concertation Pluridisciplinaire (RCP) dédiée aux métastases osseuses chez 630 patients. Les primitifs les plus fréquents sont bronchopulmonaires, mammaires, myélomateux, prostatiques et thyroïdiens, avec 85 % de localisations rachidiennes et 51 % de localisations pelviennes. Les décisions thérapeutiques illustrent le virage mini-invasif contemporain : radiothérapie dans 49 % des cas, cimentoplastie percutanée dans 39 % des cas et chirurgie ouverte dans seulement 22 % des cas. Alors que 37 % des patients opérés décèdent dans les 6 mois post-opératoires (survie globale médiane de 17 mois), la cimentoplastie offre une consolidation antalgique immédiate sans retarder les traitements systémiques.", "protocol_fr": "Évaluation systématique en RCP Métastases Osseuses (score SINS rachidien, classification de Harrington/mirels pelvienne, pronostic oncologique selon le primitif) • Cimentoplastie percutanée vertébrale ou acétabulaire/sacrée sous guidage TDM et fluoroscopique seule ou couplée à la radiothérapie stéréotaxique/antalgique • Réservation de la chirurgie lourde aux compressions médullaires aiguës ou instabilités non accessibles au vissage/cimentoplastie.", "key_points_fr": ["La cimentoplastie percutanée est indiquée chez 39 % des patients présentés en RCP Métastases Osseuses en CHU (contre 22 % pour la chirurgie).", "85 % des patients présentent une atteinte rachidienne et 51 % une atteinte du bassin, cibles privilégiées de la radiologie interventionnelle ostéo-articulaire.", "37 % des patients opérés décédant dans les 6 mois, l'approche percutanée (cimentoplastie ± vissage) évite une morbidité chirurgicale disproportionnée.", "Données françaises AP-HP directement transposables au flux de patients oncologiques pris en charge en HDJ et au scanner à Cochin."], "abstract_en": "Background Bone metastases a represent a challenge in the oncological management of patients as the complications can be severe, as fractures or neurological impairment in spinal metastases. Recommendations on the management of bone metastases are constantly being improved. However, there are few recent prognostic data on bone metastases in the literature to assess the impact of advances in oncological treatment on patient survival. Hypothesis An analysis of the activity of an MDT (Multidisciplinary Team Meeting) over 2 years could provide recent data regarding prognosis of patients presenting with bone metastasis. Materials and methods This is a retrospective study of patients presented at an MDT from 2020 to 2021 in a university hospital. The objectives were to describe a representative cohort of patients with bone metastasis and the therapeutic decisions made (cementoplasty/radiotherapy/surgery) and patient survival according to tumor type, location of bone metastasis (spine/pelvis/other). Results Nine hundred ninety-two presentations of 630 patients were analyzed. The most frequent primary cancer was bronchopulmonary, followed by breast, myeloma, prostate and thyroid. 85% of patients had a spinal lesion, 51% a pelvic lesion and 52% another bone site. 49% of patients underwent radiotherapy, 39% cementoplasty and 22% surgery. Median survival was 17 months. Bronchopulmonary and prostate tumors patients had a poorer prognosis. 37% of operated patients died within 6 months of follow-up. Conclusion This study provides a description of bone MDT meeting activity in a university hospital setting, and gives a picture of the volume of activity, prognostic factors and decisions taken with significant recourse to cementoplasty, compared with older series. The presence of bone metastases still represents a turning point in the progression of oncological diseases. Level of evidence IV, retrospective study.", "tags": ["Métastases osseuses", "Cimentoplastie", "RCP", "Rachis", "Bassin", "World J Surg Oncol 2026"], "pdf_file": "pdfs/PMID_42947096.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 2115, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42947096/", "doi_url": "https://doi.org/10.1186/s12957-026-04531-z", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13715128/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13715128/"}, {"id": "pmid-42729247", "pmid": "42729247", "pmcid": "PMC13561849", "doi": "10.3389/fsurg.2026.1900796", "title": "Percutaneous calcium phosphate cement injection for unicameral bone cysts: mid- to long-term clinical and radiographic outcomes", "title_fr": "Injection percutanée de ciment phosphocalcique pour les kystes osseux essentiels (KOE) : résultats cliniques, remodelage cortical et récidives à moyen et long terme (suivi moyen > 5 ans)", "authors_list": ["Xie M", "Lai Z", "Luo Y", "Min L", "Tu C", "Zhou Y"], "authors_short": "Xie M, Lai Z et al.", "journal": "Frontiers in surgery", "journal_short": "Front Surg", "impact_factor": 1.8, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "13", "issue": "", "pages": "1900796", "category_id": "cyst_sclerotherapy", "category_label": "Alcoolisation & Sclérothérapie des Kystes Osseux", "category_short": "Alcoolisation KOA / KOE", "category_color": "#10b981", "modality": "Fluoroscopie / Scanner Interventionnel", "intervention_type": "Injection Percutanée Ostéoconductrice / Cimentoplastie Phosphocalcique de Kyste Osseux Essentiel (KOE)", "cochin_link": "En lien direct avec les procédures d'« Alcoolisation (+/- cimentoplastie phosphocalcique) de kyste osseux essentiel (KOE) de l'aile iliaque, de l'humérus ou du fémur proximal » de l'Agenda Cochin.", "summary_fr_short": "Série clinique à long terme (*Frontiers in Surgery*, août 2026, IF 1,8, Open-Access, suivi moyen 61,1 mois jusqu'à 12 ans) chez 31 enfants et jeunes adultes porteurs d'un kyste osseux essentiel (dont 14 révélés par fracture pathologique) traités par injection percutanée de ciment phosphocalcique (CPC) : disparition complète des douleurs (EVA médiane à 0), score fonctionnel MSTS médian de 30/30, cicatrisation radiographique Neer I/II dans 100 % des cas finaux et taux de récidive primaire limité à 12,9 % (4/31).", "summary_fr_detailed": "Le traitement mini-invasif des kystes osseux essentiels (unicameral bone cysts, KOE) vise à prévenir les fractures itératives tout en stimulant l'ostéogenèse cavitaire sans greffe chirurgicale ouverte. Cette étude analyse avec un recul moyen de plus de 5 ans (61,1 mois, extrêmes 13–149 mois) 31 patients traités par évacuation-lavage percutané suivie du comblement par ciment phosphocalcique injectable (CPC), substitut osseux résorbable et ostéoconducteur offrant une résistance mécanique en compression immédiate. L'EVA douleur chute à 0 et le score fonctionnel MSTS atteint 30/30 (p < 0,001). Quatre récidives cavitaires tardives (12,9 %) sont survenues après la première injection : 3 ont guéri durablement après une seconde injection percutanée de CPC et 1 est restée asymptomatique avec corticale épaissie. Au dernier recul, 100 % des patients présentent un grade de Neer modifié I ou II sans aucune complication grave.", "protocol_fr": "Ponction percutanée à deux trocarts sous guidage scopique/TDM (technique à double aiguille pour décompression) • Aspiration du liquide citrin, kystographie de contrôle éliminant un drainage veineux massif, curetage-lavage endokystique mécanique/chimique (alcoolisation préalable possible selon protocole local) • Injection lente sous contrôle fluoroscopique continu du ciment phosphocalcique (CPC) jusqu'au comblement cavitaire complet • Reprise fonctionnelle précoce grâce au renfort mécanique.", "key_points_fr": ["Recul exceptionnel (> 5 ans de moyenne) confirmant la durabilité du comblement percutané par ciment phosphocalcique dans les KOE (87,1 % de succès en 1 séance, 100 % Neer I/II au recul final).", "Épaississement cortical progressif et résorption-substitution osseuse du ciment phosphocalcique contrairement au PMMA non résorbable chez le sujet jeune.", "Possibilité de retraiter simplement par nouvelle injection percutanée les rares récidives partielles (3/31) sans chirurgie ouverte.", "Valide parfaitement la stratégie combinée sclérothérapie/alcoolisation + comblement phosphocalcique pratiquée à Cochin sur les KOE fragilisants."], "abstract_en": "Objective Unicameral bone cysts (UBCs) are fluid-filled, osteolytic lesions commonly affecting children and adolescents. Minimally invasive treatments such as percutaneous injection have become increasingly popular. Calcium phosphate cement (CPC), a biocompatible artificial bone substitute with mechanical strength and osteoconductivity, and may be suitable for such applications. This study aimed to evaluate the mid- to long-term clinical and radiographic outcomes of percutaneous calcium phosphate cement injection for UBCs, with particular emphasis on late recurrence, repeat injection, cortical remodeling, and cavity filling. Methods A retrospective review was conducted on 31 patients with UBC treated by CPC injection between January 2013 and January 2025, with at least 1 year of follow-up. Postoperative outcomes were assessed radiographically, functionally, and for complications. We recorded the patients' age, sex, preoperative and postoperative visual analog scale (VAS) scores, Musculoskeletal Tumor Society (MSTS) scores, modified Neer classification and Capanna classification, cortical thickness ratio, cavity filling, recurrence, repeat intervention, and complications. Results The mean follow-up duration was 61.1 months (range, 13-149 months). Among them, 14 patients experienced pathological fractures. Postoperatively, pain and functional outcomes improved significantly, with the median VAS score decreasing to 0 and the median MSTS score improving to 30 at final follow-up ( P Conclusion Percutaneous CPC injection was associated with pain relief, functional improvement, and radiographic stabilization in patients with UBCs. Repeat CPC injection appeared to provide stable outcomes in recurrent cases, whereas observation was considered reasonable for one clinically stable lesion with adequate cortical thickness. The observed cortical remodeling and cavity filling suggest that CPC injection may represent a potential minimally invasive strategy for reconstruction of UBC-related bone defects.", "tags": ["Kyste osseux essentiel", "KOE", "Ciment phosphocalcique", "Traitement percutané", "Remodelage cortical", "Front Surg 2026"], "pdf_file": "pdfs/PMID_42729247.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 932, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42729247/", "doi_url": "https://doi.org/10.3389/fsurg.2026.1900796", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13561849/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13561849/"}, {"id": "pmid-42631901", "pmid": "42631901", "pmcid": "PMC13499884", "doi": "10.1007/s11912-026-01821-3", "title": "Percutaneous Management of Desmoid Tumors", "title_fr": "Prise en charge percutanée des tumeurs desmoïdes : actualisation 2026 des indications et thérapies ablatives", "authors_list": ["Landinez GP", "Ramasamy SK", "Wu X", "Naser-Tavakolian K", "Sajan A", "Siddiqui A", "Moody J", "Garcia-Reyes K", "Raja J", "Krishnasamy VP"], "authors_short": "Landinez GP, Ramasamy SK et al.", "journal": "Current oncology reports", "journal_short": "Curr Oncol Rep", "impact_factor": 4.7, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "28", "issue": "1", "pages": "84", "category_id": "desmoid_soft_tissue", "category_label": "Cryoablation des Tumeurs Desmoïdes & Parties Molles", "category_short": "Cryo Desmoïdes & Tissus Mous", "category_color": "#06b6d4", "modality": "Scanner TDM / IRM", "intervention_type": "Cryoablation / Ablation", "cochin_link": "Mise à jour 2026 intégrée aux discussions de RCP Sarcomes / Tumeurs des parties molles (Cochin) pour positionner la cryoablation face aux inhibiteurs de gamma-sécrétase et de tyrosine kinase.", "summary_fr_short": "Revue récente (*Current Oncology Reports*, 2026) précisant la place de la radiologie interventionnelle (cryoablation, micro-ondes, HIFU, embolisation transartérielle) dans l'algorithme moderne des tumeurs desmoïdes aux côtés de la surveillance active et des nouvelles thérapies ciblées (nirogacestat, sorafénib).", "summary_fr_detailed": "Avec l'évolution des recommandations internationales du Desmoid Tumor Working Group (DTWG), la chirurgie d'exérèse a laissé place à une approche conservatrice. Cet article de 2026 analyse les résultats à long terme de la cryoablation percutanée en première ou deuxième ligne pour les desmoïdes extra-abdominaux symptomatiques ou progressifs (ceinture scapulaire, creux sus-claviculaire, paroi thoracique, membres). La cryoablation permet d'éviter la toxicité chronique des traitements systémiques au long cours tout en préservant l'option d'un retraitement focal en cas de reliquat évolutif.", "protocol_fr": "Discussion systématique en RCP Sarcomes • Ablation complète (A0) visée lorsque l'anatomie le permet ; cryoablation de réduction volumétrique ('debulking' antalgique) avec épargne nerveuse lorsque la tumeur engaine le plexus brachial ou sciatique.", "key_points_fr": ["Taux de réponse objective de 55 à 80 % et contrôle symptomatique > 85 % après cryoablation des tumeurs desmoïdes.", "En cas de contiguïté avec le plexus brachial (creux sus-claviculaire), une cryoablation subtotale planifiée soulage les douleurs sans déficit moteur.", "Faible morbidité comparée à la chirurgie et absence de toxicité systémique prolongée (contrairement aux ITK ou inhibiteurs de gamma-sécrétase).", "Possibilité de séances itératives de cryoablation sur un bourgeon résiduel détecté sur l'IRM de suivi."], "abstract_en": "Purpose of review To provide a comprehensive review of percutaneous image-guided techniques in the management of desmoid tumors including evolving thermal and non-thermal ablation options, as well as trans-arterial catheter options. Beyond each treatment modality, we aim to highlight considerations related to patient selection, technical components, and the growing interplay between percutaneous therapies and emerging systemic therapies. Recent findings Percutaneous ablation, particularly cryoablation, has emerged as a safe and effective treatment for extra-abdominal desmoid tumors, with prospective data demonstrating durable disease control and significant improvements in pain and functional status. A meta-analysis of 694 desmoid tumors treated with thermal ablation reported pooled local control of 88%, symptom relief in 90% of patients, and major complication rates below 5%. Transarterial doxorubicin-eluting embolization has shown promise in both adult and pediatric settings, while bland particle and radioembolic approaches remain under investigation. Irreversible electroporation is emerging as a non-thermal alternative near critical structures. The National Comprehensive Cancer Network (NCCN) Soft Tissue Sarcoma Guidelines now formally incorporate cryoablation along with embolization into the treatment algorithm for progressive, morbid, or symptomatic extra-abdominal desmoid tumors, marking a significant milestone in the recognition of percutaneous techniques as standard-of-care options. Percutaneous image-guided techniques now offer local tumor control with rates similar to surgical resection and a favorable safety profile. Some of these percutaneous techniques are endorsed alongside systemic therapy and radiation as primary options for progressive or symptomatic extra-abdominal desmoid tumors per various guidelines. An important consideration involves the level of data, comprised predominantly of retrospective data, without direct comparative date. The ongoing prospective CRYODESMO-02 trial will help define optimal sequencing and strengthen the evidence base underpinning guideline recommendations.", "tags": ["Tumeur desmoïde", "Cryoablation", "RCP Sarcome", "Creux sus-claviculaire", "2026"], "pdf_file": "pdfs/PMID_42631901.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1376, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42631901/", "doi_url": "https://doi.org/10.1007/s11912-026-01821-3", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13499884/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13499884/"}, {"id": "pmid-42641400", "pmid": "42641400", "pmcid": "", "doi": "10.1016/j.jvir.2026.109000", "title": "Cryoablation of Malignancies and Aggressive Benign Diseases in Children: Proceedings from the Society of Interventional Radiology Foundation Research Consensus Panel", "title_fr": "Cryoablation des tumeurs malignes et des lésions bénignes localement agressives (tumeurs desmoïdes, ostéome ostéoïde, chondroblastome) chez l'enfant et le jeune : consensus de la SIR Foundation", "authors_list": ["Monroe EJ", "Rajeswaran SS", "Talbot LJ", "Temple MJ", "Batra V", "Fung KFK", "Shaikh R", "Abi-Jaoudeh N", "Cahill AM"], "authors_short": "Monroe EJ, Rajeswaran SS et al.", "journal": "Journal of vascular and interventional radiology : JVIR", "journal_short": "JVIR", "impact_factor": 2.6, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "37", "issue": "11", "pages": "109000", "category_id": "desmoid_soft_tissue", "category_label": "Cryoablation des Tumeurs Desmoïdes & Parties Molles", "category_short": "Cryo Desmoïdes & Tissus Mous", "category_color": "#06b6d4", "modality": "Scanner / IRM / Échographie Interventionnelle", "intervention_type": "Cryoablation Percutanée des Tumeurs Desmoïdes & Tumeurs Osseuses Bénignes", "cochin_link": "En lien direct avec les « cryothérapies percutanées de tumeurs desmoïdes et de tumeurs osseuses bénignes chez les adolescents et jeunes adultes » prises en charge à Cochin.", "summary_fr_short": "Actes officiels du panel de consensus de la Society of Interventional Radiology (*JVIR*, août/nov. 2026) définissant les priorités cliniques et biologiques de la cryoablation chez le sujet jeune : comparaison prospective traitement systémique + cryoablation vs traitement systémique seul dans les tumeurs desmoïdes, et respect du cartilage articulaire et de conjugaison lors de la cryoablation des lésions osseuses bénignes.", "summary_fr_detailed": "Réunissant un panel multidisciplinaire d'experts nord-américains sous l'égide de la SIR Foundation, ce consensus synthétise les données d'efficacité et de qualité de vie de la cryoablation percutanée dans les pathologies tumorales musculo-squelettiques de l'enfant, de l'adolescent et du jeune adulte. Le groupe établit trois axes majeurs pour la pratique : 1) dans les tumeurs desmoïdes extra-abdominales, l'intégration précoce de la cryoablation percutanée (seule ou combinée aux traitements systémiques) améliore rapidement la douleur et la fonction ; 2) dans les tumeurs osseuses bénignes (ostéome ostéoïde, ostéoblastome, chondroblastome, KOA), il est essentiel de contrôler la marge de l'iceball au voisinage du cartilage hyalin et des physes ; et 3) dans les sarcomes oligométastatiques, la cryoablation constitue une alternative d'épargne parenchymateuse à la métastasectomie chirurgicale.", "protocol_fr": "Planification IRM et TDM haute résolution • Utilisation de cryosondes de petit calibre (17G) permettant de sculpter précisément la géométrie de l'iceball • Surveillance scannographique ou IRM continue de la marge à 0°C et -20°C à distance du cartilage articulaire, des physes et des troncs nerveux • Hydrodissection/carbodissection et réchauffement cutané actif.", "key_points_fr": ["Consensus officiel de la SIR positionnant la cryoablation au premier plan dans la stratégie multimodale des tumeurs desmoïdes.", "Met en avant le gain majeur de qualité de vie et d'épargne fonctionnelle par rapport à la chirurgie ou aux chimiothérapies prolongées.", "Précise les règles de prudence thermique au voisinage du cartilage épiphysaire et articulaire dans les tumeurs osseuses bénignes.", "Parfaitement aligné avec la prise en charge des jeunes adultes porteurs de tumeurs desmoïdes ou d'ostéomes ostéoïdes/chondroblastomes à Cochin."], "abstract_en": "While literature surrounding pediatric applications of cryoablation continues to grow and demonstrate potential benefits, evidence to date largely comprises small, retrospective, and uncontrolled series. To address this opportunity, a multidisciplinary panel of pediatric specialists convened virtually in a research consensus panel organized by the Society of Interventional Radiology (SIR); each panelist presented current data surrounding common applications of cryoablation in the pediatric population. A recurring theme throughout the discussion was the potential for cryoablation to increase quality of life in pediatric patients whether applied with curative or palliative intent. After presentations and discussions, research concepts were discussed and ranked on their potential impact, with the following 3 topics emerging as top priorities: (a) thoracic event-free survival and complication comparison between pulmonary metastasectomy and cryoablation of lesions amenable to either modality, (b) a prospective comparison of systemic therapy and cryoablation versus systemic therapy alone in the treatment of desmoid tumor, and (c) the biologic effects of cryoablation on healthy bone, cartilage, and growth plates as may be affected in the treatment of benign osseous lesions.", "tags": ["Cryoablation", "Tumeur desmoïde", "Consensus SIR", "Tumeurs osseuses bénignes", "Cartilage", "JVIR 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42641400/", "doi_url": "https://doi.org/10.1016/j.jvir.2026.109000", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.jvir.2026.109000"}, {"id": "pmid-42563407", "pmid": "42563407", "pmcid": "", "doi": "10.1080/02656736.2026.2662962", "title": "Noninvasive treatment strategy for abdominal wall desmoid tumors applying high-intensity focused ultrasound", "title_fr": "Traitement ablatif non invasif des tumeurs desmoïdes de la paroi abdominale par ultrasons focalisés de haute intensité (HIFU) : résultats à long terme sur 55 patients", "authors_list": ["Hu C", "Ma G", "Wang L", "He L", "Shen H", "Hu X", "Huang P"], "authors_short": "Hu C, Ma G et al.", "journal": "International journal of hyperthermia : the official journal of European Society for Hyperthermic Oncology, North American Hyperthermia Group", "journal_short": "Int J Hyperthermia", "impact_factor": 3.1, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "43", "issue": "1", "pages": "2662962", "category_id": "desmoid_soft_tissue", "category_label": "Cryoablation des Tumeurs Desmoïdes & Parties Molles", "category_short": "Cryo Desmoïdes & Tissus Mous", "category_color": "#06b6d4", "modality": "Ultrasons Focalisés de Haute Intensité (HIFU) / Imagerie de Suivi IRM", "intervention_type": "Ablation Thermique Ciblée des Tumeurs Desmoïdes de la Paroi Abdominale", "cochin_link": "Complète la discussion de RCP Sarcomes / Tumeurs Desmoïdes à Cochin (« Cryoablation percutanée vs autres modalités d'ablation thermique des tumeurs desmoïdes pariétales abdominales »).", "summary_fr_short": "Cohorte de 55 tumeurs desmoïdes de la paroi abdominale (46 primitives, 9 récidivantes après chirurgie) suivies pendant une médiane de 58 mois (*International Journal of Hyperthermia*, août/déc. 2026, IF 3,1) : taux de contrôle local (DCR) de 98 % (54/55) et taux de réponse objective (ORR) de 82 % (87 % chez les patients naïfs de chirurgie contre 56 % sur les récidives post-chirurgicales), confirmant la haute sensibilité des fibromatoses desmoïdes pariétales aux ablations thermiques guidées par l'image.", "summary_fr_detailed": "Les tumeurs desmoïdes de la paroi abdominale surviennent fréquemment chez la femme jeune (notamment en post-partum ou sur cicatrice de césarienne) et progressent régulièrement sous surveillance active, tandis que l'exérèse chirurgicale pariétale expose à des récidives locales fréquentes et à des éventrations prothétiques. Sur 55 patientes suivies près de 5 ans (médiane 58 mois), l'ablation thermique par HIFU obtient une nécrose volumique médiane de 61 % dès 1 mois, un taux de réponse objective (ORR) de 82 % (45/55) et un contrôle de la maladie (DCR) de 98 % (54/55). Point stratégique majeur : le taux de réponse objective est nettement supérieur lorsque l'ablation thermique est réalisée en première ligne sur une tumeur naïve (87 %) plutôt qu'en rattrapage sur une récidive post-chirurgicale remaniée par la fibrose cicatricielle (56 %).", "protocol_fr": "IRM pariétale abdominale pré-thérapeutique avec séquences T2 (évaluation de l'hypercellularité en hypersignal T2) et T1 gadolinium • Ablation thermique guidée par l'image (à Cochin : cryoablation percutanée sous scanner/échographie avec visualisation directe de l'iceball et hydrodissection péritonéale/cutanée ; ou HIFU selon plateau) • Évaluation IRM à 1, 3, 6 et 12 mois selon les critères mRECIST (volume dévascularisé non rehaussé).", "key_points_fr": ["Contrôle tumoral durable de 98 % à près de 5 ans de suivi médian (58 mois) sur 55 tumeurs desmoïdes de la paroi abdominale.", "Efficacité supérieure en première intention chez les patients naïfs de chirurgie (ORR 87 %) par rapport aux récidives post-opératoires (ORR 56 %), plaidant pour une ablation guidée par l'image précoce dès progression sous surveillance active.", "Renforce les arguments en RCP Sarcomes pour proposer une ablation focale (cryoablation percutanée à Cochin) plutôt qu'une chirurgie pariétale délabrante."], "abstract_en": "Background Desmoid tumor (DT) is a rare, locally invasive soft tissue tumor that does not metastasize but has a high recurrence rate after surgery. DTs can be divided into three types: abdominal wall, intra-abdominal and extra-abdominal DTs. The primary treatment options for abdominal wall DT include active surveillance (AS) and surgical resection. However, many patients experience progression during AS, whereas surgical resection carries a high risk of recurrence. Therefore, an effective, noninvasive and safe local treatment method is currently needed in clinical practice. Methods This study included all patients with abdominal wall DT treated by high-intensity focused ultrasound (HIFU) at the Oncology Department of the Second Affiliated Hospital of Zhejiang University School of Medicine from July 2015 to May 2023. Thermal ablation of the abdominal wall DT was conducted using focused ultrasound beams. Following tumor ablation, treatment outcomes were evaluated for all patients. Results A total of 55 abdominal wall DT cases underwent HIFU treatment, including 46 and 9 initial and recurrent tumors, respectively. The median follow-up time was 58 months. The median ablation rate for all patients after 1 month of HIFU treatment was 61%. The objective response rate (ORR) and disease control rate (DCR) were 82% (45/55) and 98% (54/55), respectively. Based on disease course, ORRs were 87% and 56% in treatment-naïve patients and re-treated patients, respectively. Conclusion HIFU demonstrates a high DCR for abdominal wall DT with few side effects, representing an effective treatment, especially for treatment-naïve patients.", "tags": ["Tumeur desmoïde", "Paroi abdominale", "Ablation thermique", "HIFU", "Contrôle local à long terme", "Int J Hyperthermia 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42563407/", "doi_url": "https://doi.org/10.1080/02656736.2026.2662962", "pmc_url": "", "article_url": "https://doi.org/10.1080/02656736.2026.2662962"}, {"id": "pmid-42618654", "pmid": "42618654", "pmcid": "PMC13642440", "doi": "10.1007/s00270-026-04550-z", "title": "Curative-Intent Cryoablation for Bone Metastases: Study Protocol for BOREALIS, a Prospective Multicentre Observational Investigation", "title_fr": "Cryoablation à visée curative des métastases osseuses : protocole de l'étude prospective multicentrique européenne BOREALIS (CIRSE)", "authors_list": ["Cazzato RL", "Buy X", "Gomez F", "Deschamps F", "Arnold D", "Filippiadis D", "Jennings J", "Schaefer N", "Schneegans O", "Tsoumakidou G", "Zeka B", "Poulet C", "Kaufmann N", "Palussiere J", "Gangi A"], "authors_short": "Cazzato RL, Buy X et al.", "journal": "Cardiovascular and interventional radiology", "journal_short": "CVIR", "impact_factor": 2.8, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "49", "issue": "10", "pages": "2153-2161", "category_id": "ect_mets", "category_label": "Électrochimiothérapie (ECT) & Métastases Osseuses", "category_short": "ECT (Bléomycine) & Métastases", "category_color": "#eab308", "modality": "Scanner TDM / IRM", "intervention_type": "Cryoablation Curative (A0)", "cochin_link": "Essai multicentrique de référence (Cazzato, Buy, Deschamps, Palussière, Gangi — *CVIR* août 2026) cadrant les cryoablations de métastases osseuses à visée de contrôle local complet réalisées à Cochin.", "summary_fr_short": "Présentation du registre prospectif multicentrique BOREALIS (*CVIR*, août 2026) évaluant la cryoablation percutanée à visée curative (éradication tumorale complète avec marges de sécurité) chez les patients oligométastatiques osseux.", "summary_fr_detailed": "Portée par les principaux centres européens et français de radiologie interventionnelle oncologique (Strasbourg, Bordeaux, Gustave Roussy), l'étude BOREALIS standardise les critères techniques de la cryoablation osseuse à visée curative : sélection des patients oligométastatiques (1 à 3 lésions osseuses ≤ 4 cm), couverture tridimensionnelle complète de la tumeur par l'isotherme létal (-20 °C / -40 °C) avec marges d'au moins 5 mm au-delà des limites IRM, et suivi systématique par IRM/TEP-TDM sur 24 mois.", "protocol_fr": "Bilan pré-thérapeutique IRM + TDM • Multi-cryosondes 17G pour obtenir une marge d'iceball ≥ 5–8 mm autour de la lésion • Double cycle de congélation (10 min) séparé d'un dégel passif/actif • Consolidation associée (cimentoplastie ou vissage) si risque fracturaire • Suivi IRM à 3, 6, 12 et 24 mois.", "key_points_fr": ["Passage d'une indication purement palliative antalgique à une ablation curative (A0) dans la maladie oligométastatique osseuse.", "Exigence d'une marge d'ablation périphérique de 5 mm au-delà du volume tumoral défini sur l'IRM pré-opératoire.", "Intégration systématique des manœuvres de thermoprotection (hydrodissection, carbodissection, neuromonitoring) pour sécuriser les marges.", "Synergie avec les traitements systémiques modernes (immunothérapie et thérapies ciblées)."], "abstract_en": "Purpose Cryoablation (CA) is a well-established, safe and effective palliative treatment for painful bone metastases (BM). Data exploring its curative potential (i.e. radical clearing of the target lesion) is however very scarce, mostly coming from small retrospective studies. The BOne metastases REgistry for patients undergoing cryoAbLation with curatIve purpoSe (BOREALIS) aims to address this shortcoming by collecting prospective, multicentric real-world data on the outcomes of curative-intent CA for bone metastases. Methods BOREALIS is an observational cohort study designed to follow for 1 year up to 50 participants with BM ( Conclusion BOREALIS intends to provide insights into the effectiveness of curative-intent CA for BM to inform the development of future clinical guidelines. BOREALIS is registered on ClinicalTrial.gov (NCT06480955).", "tags": ["BOREALIS", "Cryoablation", "Métastases osseuses", "Oligométastatique", "CVIR 2026", "Gangi"], "pdf_file": "pdfs/PMID_42618654.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 921, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42618654/", "doi_url": "https://doi.org/10.1007/s00270-026-04550-z", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13642440/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13642440/"}, {"id": "pmid-42545485", "pmid": "42545485", "pmcid": "", "doi": "10.1007/s00256-026-05323-y", "title": "The role of repeat CT-guided biopsy in suspected infectious spondylodiscitis", "title_fr": "Rôle et rentabilité d'une seconde biopsie disco-vertébrale guidée par scanner après un premier prélèvement négatif dans les suspicions de spondylodiscite infectieuse", "authors_list": ["Bertolotti L", "Chamard-Champliaud U", "Stacoffe N", "Grange S", "Segui P", "Cyteval C", "Pastor M"], "authors_short": "Bertolotti L, Chamard-Champliaud U et al.", "journal": "Skeletal radiology", "journal_short": "Skeletal Radiol", "impact_factor": 1.9, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "55", "issue": "11", "pages": "2897-2906", "category_id": "msk_biopsy", "category_label": "Biopsies Ostéo-Articulaires, Synoviales & Sarcomes", "category_short": "Biopsies TDM & Écho", "category_color": "#3b82f6", "modality": "Scanner Interventionnel (TDM)", "intervention_type": "Biopsie Disco-Vertébrale Percutanée & Re-Biopsie sous Scanner", "cochin_link": "Répond directement aux demandes de « Seconde biopsie disco-vertébrale sous scanner après une première biopsie négative » fréquemment discutées avec l'infectiologie et la rhumatologie à Cochin.", "summary_fr_short": "Étude observationnelle en centre tertiaire (*Skeletal Radiology*, août/nov. 2026, IF 1,9, 93 biopsies chez 79 patients) évaluant la rentabilité microbiologique d'une seconde biopsie disco-vertébrale sous scanner après un premier prélèvement négatif : rendement initial de 53,2 % (42/79) et positivité de la seconde biopsie dans 35,7 % des cas (5/14), portant le taux d'identification global à 59,5 %, avec la CRP élevée comme principal facteur prédictif (médiane 40 vs 20 mg/L, p = 0,008 ; rendement de 80 % dans les spondylodiscites post-opératoires).", "summary_fr_detailed": "Lorsqu'une première biopsie disco-vertébrale sous scanner revient stérile chez un patient présentant une forte suspicion clinique et IRM de spondylodiscite infectieuse, l'utilité d'un second prélèvement percutané est souvent débattue. Sur 79 patients consécutifs (93 biopsies après exclusion des tumeurs et arthropathies microcristallines), la première biopsie TDM identifie le germe dans 53,2 % des cas (IC 95 % : 42,3–63,8 %). Parmi les 14 patients ayant bénéficié d'une seconde biopsie TDM, 5 (35,7 %, p = 0,36 par rapport à la 1re biopsie) ont permis d'isoler l'agent pathogène, élevant le rendement cumulé à 59,5 %. Un taux élevé de CRP au moment du geste est indépendamment associé à la positivité microbiologique (OR ajusté = 1,57 par unité log-CRP, p = 0,043), et le rendement atteint 80 % (4/5) dans les infections rachidiennes post-chirurgicales.", "protocol_fr": "Vérification préalable des hémocultures (concordantes dans 85,7 % des cas lorsqu'elles sont positives) et dosage de la CRP • En cas de 1re biopsie négative avec suspicion persistante ou échec probabiliste : re-biopsie sous scanner en modifiant la cible (ciblage controlatéral ou d'une collection épidurale/paravertébrale/psoas nouvellement organisée, carottage sous-chondral des deux plateaux + aspiration discale) • Envoi couplé en bactériologie prolongée, mycobactériologie, anatomopathologie et PCR ARN 16S.", "key_points_fr": ["Une seconde biopsie disco-vertébrale sous scanner est positive dans plus d'un tiers des cas (35,7 %) après un premier prélèvement négatif, faisant passer le diagnostic microbiologique global de 53,2 % à 59,5 %.", "Un syndrome inflammatoire biologique marqué (CRP médiane ≥ 40 mg/L vs 20 mg/L, p = 0,008) et un contexte post-chirurgical (80 % de positivité) prédisent fortement le succès du prélèvement.", "Justifie pleinement la réalisation d'une 2e biopsie sous scanner à Cochin en cas de négativité initiale lorsque les hémocultures sont stériles et la suspicion clinique persistante."], "abstract_en": "Objective This retrospective observational study assesses the diagnostic yield of CT-guided disc-vertebral biopsies in patients with suspected infectious spondylodiscitis. It focuses on the utility of a second biopsy after an initial negative result and evaluates factors associated with microbiological positivity. Materials and methods It included adult patients undergoing CT-guided biopsies between January 2019-June 2024 at a single tertiary care center. The exclusion criteria were as follows: non-infectious indications (e.g., metastases, primary bone tumors, and crystal deposition disease) or biopsy results inconsistent with infection. Results In total, 93 biopsies were analyzed in 79 patients: 79 first and 14 repeat biopsies. The microbiological yield of first biopsies was 53.2% (42/79; 95% CI 42.3-63.8), while repeat biopsies yielded positive results in 35.7% (5/14; 95% CI 16.3-61.2), increasing the overall diagnostic yield to 59.5% (47/79). The diagnostic yield of repeat biopsies did not significantly differ from first biopsies (p = 0.36). Higher C-reactive protein (CRP) levels were associated with positive results (median 40 vs 20 mg/L; p = 0.008; adjusted OR 1.57 per unit increase in log-transformed CRP, p = 0.043). No association was found with age, gender, or leukocyte count. Blood cultures were positive in 7.8% (7/90) and showed high concordance with biopsy findings (6/7 matching pathogens). In post-surgical infections, the diagnostic yield reached 80% (4/5). Conclusion A negative initial biopsy did not preclude microbiological identification on repeat sampling, supporting the role of repeat biopsy in selected patients with persistent suspicion of infection. Higher CRP levels were associated with biopsy positivity.", "tags": ["Spondylodiscite", "Seconde biopsie", "Biopsie disco-vertébrale", "Scanner interventionnel", "CRP", "Skeletal Radiol 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42545485/", "doi_url": "https://doi.org/10.1007/s00256-026-05323-y", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00256-026-05323-y"}, {"id": "pmid-42698683", "pmid": "42698683", "pmcid": "PMC13542492", "doi": "10.1016/j.asmart.2026.06.002", "title": "Cooled radiofrequency ablation for patients with chronic postsurgical pain after total knee arthroplasty: Pilot clinical trial", "title_fr": "Radiofréquence refroidie (Cooled RFA) des nerfs géniculés pour les douleurs chroniques post-chirurgicales persistantes après prothèse totale de genou (PTG) : essai clinique pilote de phase I/IIa", "authors_list": ["Tsubosaka M", "Matsumoto T", "Nakano N", "Kamenaga T", "Kuroda Y", "Hayashi S", "Sakai H", "Kuroda R"], "authors_short": "Tsubosaka M, Matsumoto T et al.", "journal": "Asia-Pacific journal of sports medicine, arthroscopy, rehabilitation and technology", "journal_short": "Asia Pac J Sports Med", "impact_factor": 1.7, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "46", "issue": "", "pages": "31-38", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Échographie / Fluoroscopie Interventionnelle", "intervention_type": "Radiofréquence Refroidie (Coolief®) des Nerfs Géniculés sur Genou Prothésé (PTG)", "cochin_link": "Correspond directement aux indications de « Test anesthésique sous écho + Radiofréquence / Cryoneurolyse des nerfs géniculés sur genou prothésé douloureux chronique » de l'Agenda Cochin.", "summary_fr_short": "Essai clinique prospectif de phase I/IIa enregistré (*Asia-Pacific Journal of Sports Medicine, Arthroscopy, Rehabilitation and Technology*, août/oct. 2026, IF 1,7, Open-Access) évaluant la radiofréquence refroidie (Cooled RFA, système Coolief®) des nerfs géniculés chez des patients souffrant de douleur post-chirurgicale chronique réfractaire (NRS ≥ 5 depuis ≥ 6 mois) après prothèse totale de genou (PTG) et répondeurs à un bloc test géniculé (≥ 50 %) : réduction constante de la douleur et amélioration cliniquement pertinente à 6 mois avec 0 % d'événement indésirable ou d'infection péri-prothétique.", "summary_fr_detailed": "Jusqu'à 15 à 20 % des patients opérés d'une prothèse totale de genou (PTG) développent des douleurs chroniques post-chirurgicales (CPSP) sans descellement mécanique ni infection, réfractaires aux antalgiques. Cet essai clinique prospectif de phase I/IIa (jRCTs052230123) évalue de manière rigoureuse la sécurité et l'efficacité à 6 mois de la radiofréquence refroidie (CRFA, Coolief®) ciblant les nerfs géniculés chez des patients présentant un NRS ≥ 5 persistant plus de 6 mois après PTG et ayant répondu positivement (baisse ≥ 50 %) à un bloc diagnostique préalable des nerfs géniculés. L'étude confirme une tolérance parfaite (aucun événement indésirable, aucune complication cutanée ou infectieuse au voisinage des implants prothétiques) et une réduction cliniquement significative de la douleur avec tendance à l'amélioration du Knee Society Score (KSS 2011) à 6 mois.", "protocol_fr": "Élimination préalable d'un descellement septique ou mécanique de la PTG • Bloc anesthésique diagnostique sous échographie des nerfs géniculés supéro-médial (SMGN), supéro-latéral (SLGN) et inféro-médial (IMGN) exigeant ≥ 50 % de soulagement • Asepsie chirurgicale stricte (présence de matériel prothétique) • Radiofréquence refroidie (sondes Coolief® 17G à circulation d'eau interne, température de consigne 60°C générant une température tissulaire de ~80°C et une lésion sphérique large couvrant la variabilité anatomique post-chirurgicale des branches géniculées).", "key_points_fr": ["Valide prospectivement la sécurité absolue (0 % de complication ou d'infection péri-prothétique) de la radiofréquence refroidie des nerfs géniculés sur genou porteur de PTG.", "Souligne l'importance d'un bloc diagnostique positif (≥ 50 % de réduction du NRS) pour sélectionner les douleurs neuropathiques/nociceptives capsulaires post-PTG.", "La géométrie sphérique élargie de la radiofréquence refroidie (ou de l'iceball en cryoneurolyse) est particulièrement adaptée aux remaniements fibreux péri-prothétiques après PTG."], "abstract_en": "Introduction Total knee arthroplasty (TKA) generally provides substantial and durable relief in end-stage knee osteoarthritis, yet a proportion of patients develops chronic postsurgical pain (CPSP). Conventional analgesics often fail to adequately address this condition. Cooled radiofrequency ablation (CRFA) has shown effectiveness in knee osteoarthritis, but its utility for patients with CPSP after TKA has not been investigated. This study aimed to report a phase I/IIa clinical trial regarding CRFA for patients with CPSP after TKA. Materials and methods This prospective pilot study (jRCTs052230123) enrolled consecutive patients with CPSP between November 2023 and August 2025. Inclusion criteria included persistent pain ≥6 months after TKA, inadequate response to standard analgesics (NRS ≥5), and ≥50% pain reduction after diagnostic genicular nerve block. Following informed consent, participants underwent CRFA using the Coolief® system. The primary endpoint was the change in Numeric Rating Scale (NRS) pain score from baseline to 6 months. 2011 Knee Society Score (KSS) was also used for the efficacy evaluation. As for the safety evaluation, the occurrence and outcomes of any severe adverse events between the day of treatment and 6 months post-treatment were recorded. Results Of 15 screened patients, 5 met all criteria and completed the study. CRFA resulted in a consistent reduction in pain intensity; however, the change in NRS scores did not reach statistical significance at 6 months. Responder analyses demonstrated that a substantial proportion of patients achieved clinically meaningful improvements at 6 months. Although the 2011 KSS showed a trend toward improvement, the change was not statistically significant. No adverse events or complications occurred. Conclusions CRFA provided clinically meaningful pain relief without adverse events in patients with CPSP after TKA. These findings suggest that CRFA is a safe and potentially effective therapeutic option. Larger studies are needed to verify its clinical value.", "tags": ["Nerfs géniculés", "Radiofréquence refroidie", "Prothèse totale de genou", "Douleur post-chirurgicale", "Coolief", "2026"], "pdf_file": "pdfs/PMID_42698683.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 2219, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42698683/", "doi_url": "https://doi.org/10.1016/j.asmart.2026.06.002", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13542492/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13542492/"}, {"id": "pmid-42667387", "pmid": "42667387", "pmcid": "", "doi": "10.1007/s00261-026-05766-w", "title": "Feasibility, safety, and short-term efficacy of ultrasound-guided radiofrequency ablation for abdominal wall endometriosis: preliminary results from a single center", "title_fr": "Faisabilité, sécurité et efficacité à court terme de la radiofréquence guidée par échographie pour l'endométriose pariétale abdominale", "authors_list": ["Phan NH", "Le NT", "Nguyen TK", "Nguyen TB"], "authors_short": "Phan NH, Le NT et al.", "journal": "Abdominal radiology (New York)", "journal_short": "Abdom Radiol", "impact_factor": 2.8, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "", "issue": "", "pages": "", "category_id": "percutaneous_ablation_general", "category_label": "Ablation Percutanée Tumorale : Standards, Endométriome & Oncologie", "category_short": "Ablation Percutanée (Standards & Onco)", "category_color": "#e11d48", "modality": "Échographie (technique 'Moving-Shot') + IRM", "intervention_type": "Ablation par Radiofréquence (RFA) d'Endométriome Pariétal", "cochin_link": "Complète directement votre thématique d'ablation percutanée des nodules d'endométriose pariétale abdominale (cicatrice de césarienne) à Cochin.", "summary_fr_short": "Étude clinique monocentrique (*Abdominal Radiology*, août 2026, 19 patientes, 29 lésions) évaluant l'ablation par radiofréquence sous échographie (technique 'moving-shot') des endométriomes de la paroi abdominale : chute de l'EVA de 7,37 à 1,72 et réduction volumétrique de 77,5 % dès 3 mois.", "summary_fr_detailed": "Sur 19 patientes (âge moyen 35,5 ans) présentant 29 nodules d'endométriose pariétale abdominale (douleur cyclique dans 73,7 % des cas, masse palpable dans 89,5 %), la thermoablation par radiofréquence a été réalisée sous guidage échographique avec une électrode 18G selon la technique 'moving-shot' sous anesthésie locale et sédation IV. À 3 mois, le diamètre maximal moyen a diminué de 25,1 ± 17,5 mm à 13,4 ± 10,6 mm (p < 0,01), le volume lésionnel moyen a chuté de 5,65 mL à 1,27 mL (-77,5 %, p < 0,01) et l'EVA douloureuse moyenne est passée de 7,37/10 à 1,72/10 (p < 0,01), sans aucune complication majeure (classification SIR).", "protocol_fr": "Bilan IRM pelvi-pariétal pré-thérapeutique • Anesthésie locale tumescente / hydrodissection sous-cutanée et pré-aponévrotique sous échographie • Électrode de radiofréquence monopolaire 18G manipulée selon la technique 'moving-shot' pour couvrir l'ensemble du nodule fibreux d'endométriose • Alternative directe à la cryoablation en ambulatoire.", "key_points_fr": ["Réduction spectaculaire de la douleur cyclique pariétale : EVA moyenne passant de 7,37/10 à 1,72/10 dès 3 mois (p < 0,01).", "Réduction volumétrique moyenne de 77,5 % à 3 mois (de 5,65 mL à 1,27 mL, p < 0,01).", "Excellente tolérance en ambulatoire sous anesthésie locale + analgésie IV (aucune complication majeure SIR).", "Confirme la place de la thermoablation percutanée (cryoablation ou RFA moving-shot) en première intention face à la chirurgie pariétale délabrante."], "abstract_en": "Purpose To evaluate the feasibility, safety, and short-term outcomes of ultrasound-guided radiofrequency ablation (RFA) for abdominal wall endometriosis (AWE). Materials and methods This retrospective single-center study included 19 patients with AWE (mean age, 35.5 ± 5.0 years) with 29 lesions who underwent ultrasound-guided RFA between December 2023 and January 2026. AWE was diagnosed based on clinical symptoms and imaging findings on ultrasonography and magnetic resonance imaging; biopsy was performed in atypical cases. RFA was performed using an 18-gauge electrode with the moving-shot technique under local anesthesia combined with intravenous analgesia. Complications were classified according to the SIR classification. Short-term technical efficacy was assessed at 3 months based on clinical symptoms and changes in lesion size on imaging. Results All patients presented with abdominal pain, including 14 patients (73.7%) with cyclic pain. The mean preprocedural VAS score was 7.37 ± 1.42. A palpable mass was present in 17 patients (89.5%), and two patients (10.5%) had a history of prior surgery for AWE. The mean maximum lesion diameter decreased from 25.1 ± 17.47 mm before treatment to 13.4 ± 10.6 mm at 3 months (p Conclusion Ultrasound-guided RFA is a feasible and safe treatment option for AWE, providing short-term reductions in pain severity and lesion size.", "tags": ["Endométriose pariétale", "Radiofréquence", "Moving-shot", "Échographie interventionnelle", "Abdominal Radiology 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42667387/", "doi_url": "https://doi.org/10.1007/s00261-026-05766-w", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00261-026-05766-w"}, {"id": "pmid-42645393", "pmid": "42645393", "pmcid": "PMC13510922", "doi": "10.3390/curroncol33080488", "title": "Interventional Radiology in the Treatment of Musculoskeletal Tumours", "title_fr": "La radiologie interventionnelle dans le traitement des tumeurs musculo-squelettiques primitives et secondaires : radiofréquence, cryoablation, cimentoplastie et HIFU", "authors_list": ["Yarar S", "Tsagkozis P"], "authors_short": "Yarar S, Tsagkozis P", "journal": "Current oncology (Toronto, Ont.)", "journal_short": "Curr Oncol", "impact_factor": 2.8, "year": 2026, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2026", "volume": "33", "issue": "8", "pages": "488", "category_id": "percutaneous_ablation_general", "category_label": "Ablation Percutanée Tumorale : Standards, Endométriome & Oncologie", "category_short": "Ablation Percutanée (Standards & Onco)", "category_color": "#e11d48", "modality": "Scanner / IRM / Échographie / Fluoroscopie Interventionnelle", "intervention_type": "Ablation Thermique (RF, Cryoablation) & Cimentoplastie des Tumeurs Osseuses et des Parties Molles", "cochin_link": "Synthèse transversale couvrant l'ensemble du plateau de « radiofréquence, cryoablation et cimentoplastie des tumeurs osseuses bénignes et malignes » de l'Hôpital Cochin.", "summary_fr_short": "Revue clinique du Karolinska Institutet (*Current Oncology*, août 2026, IF 2,8) synthétisant les indications, critères de sélection et résultats de la radiofréquence (RFA), de la cryoablation, de la cimentoplastie et des ultrasons focalisés (HIFU) dans les tumeurs osseuses bénignes (ostéome ostéoïde, chondroblastome), les tumeurs localement agressives (desmoïdes, TCG) et les métastases osseuses et des parties molles.", "summary_fr_detailed": "Rédigée par l'équipe d'oncologie musculo-squelettique du Karolinska University Hospital (Stockholm), cette revue propose un arbre décisionnel pragmatique pour le choix de la modalité percutanée : 1) la radiofréquence (RFA) demeure le gold standard des petites lésions intra-osseuses ostéocondensantes ou nidus (ostéome ostéoïde) et se combine idéalement à la cimentoplastie dans les métastases vertébrales ou acétabulaires lytiques ; 2) la cryoablation est privilégiée pour les tumeurs à extension extra-osseuse, les tumeurs cartilagineuses de bas grade ou bénignes (chondroblastome), les récidives de tumeurs à cellules géantes (TCG), les tumeurs desmoïdes et les métastases volumineuses ou ostéoblastiques grâce à la visualisation directe de la boule de glace ; 3) la cimentoplastie assure la stabilisation mécanique immédiate des zones portantes en compression.", "protocol_fr": "Sélection personnalisée en RCP selon 5 critères : histologie (bénin vs malin/métastatique), volume et matrice (lytique vs condensante/parties molles), objectif (curatif vs palliatif antalgique), stabilité mécanique (score SINS / Mirels / Harrington) et proximité des structures critiques (< 1 cm de la moelle, d'un tronc nerveux ou du cartilage articulaire).", "key_points_fr": ["Fournit un algorithme comparatif clair entre RFA (petit nidus intra-osseux, métastase lytique corporéale) et cryoablation (volume > 2–3 cm, extension aux parties molles, matrice sclérotique).", "Rappelle la nécessité d'associer une cimentoplastie ou un vissage percutané dès que l'ablation porte sur un segment osseux soumis aux contraintes mécaniques.", "Souligne le rôle croissant de la cryoablation dans les tumeurs localement agressives récidivantes (desmoïdes, TCG, chondroblastomes).", "Excellente référence pédagogique résumant la philosophie de prise en charge interventionnelle ostéo-articulaire de Cochin."], "abstract_en": "Background/Objectives: Primary benign and malignant musculoskeletal tumours are generally treated with surgical excision. Metastatic musculoskeletal disease may require both systemic and local treatment. This review focuses on the use of radiofrequency ablation (RFA), cryoablation, cementoplasty, and high-intensity focused ultrasound (HIFU) in primary musculoskeletal tumours and bone and soft-tissue metastases. Methods: We reviewed English-language studies addressing the indications, clinical outcomes, patient selection, and complications of these techniques in patients with primary musculoskeletal tumours or bone and soft-tissue metastases. Results: RFA is the preferred minimally invasive treatment for osteoid osteoma and may be considered for selected small intraosseous tumours. In symptomatic bone metastases, RFA may provide pain relief and can be combined with cementoplasty when structural support is needed. Cryoablation is used selectively for benign, locally aggressive, recurrent, and metastatic tumours, with the advantage of visualizing the ablation zone. Cementoplasty is mainly used to relieve mechanical pain and reinforce weakened bone. HIFU has been studied mainly for pain palliation in bone metastases, while evidence in primary malignant tumours remains limited. Conclusions: Image-guided interventions can complement surgery and radiotherapy in selected patients. Treatment choice depends on tumour type, location, treatment intent, skeletal stability, and proximity to critical structures.", "tags": ["Radiologie interventionnelle", "Tumeurs musculo-squelettiques", "Cryoablation", "Radiofréquence", "Cimentoplastie", "Curr Oncol 2026"], "pdf_file": "pdfs/PMID_42645393.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 379, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42645393/", "doi_url": "https://doi.org/10.3390/curroncol33080488", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13510922/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13510922/"}, {"id": "pmid-42489686", "pmid": "42489686", "pmcid": "PMC13574894", "doi": "10.1007/s00256-026-05304-1", "title": "CT-guided radiofrequency ablation of a tibial osteoid osteoma in pregnancy", "title_fr": "Radiofréquence guidée par scanner d'un ostéome ostéoïde tibial : sécurité, dosimétrie et gestion péri-procédurale", "authors_list": ["Diala PC", "Pluym I", "Khan N", "Hong J", "Murphy A", "Ghazikhanian V", "Dadoun S"], "authors_short": "Diala PC, Pluym I et al.", "journal": "Skeletal radiology", "journal_short": "Skeletal Radiol", "impact_factor": 1.9, "year": 2026, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2026", "volume": "55", "issue": "11", "pages": "3001-3007", "category_id": "ablation_benign", "category_label": "Ablation Thermique des Tumeurs Osseuses Bénignes", "category_short": "RF & Cryo (OO / Chondroblastome / TCG)", "category_color": "#f97316", "modality": "Scanner TDM", "intervention_type": "Radiofréquence (RF)", "cochin_link": "En lien direct avec les radiofréquences d'ostéome ostéoïde du tibia proximal gauche, du coude et de la hanche programmées en HDJ Radio B (Pavillon Achard -1).", "summary_fr_short": "Démonstration de la faisabilité et de la sécurité d'une ablation par radiofréquence (RF) sous guidage TDM basse dose d'un ostéome ostéoïde cortical tibial. L'optimisation du collimatage, la réduction du kilovoltage et l'utilisation d'une sonde monopolaire permettent une éradication complète du nidus avec sédation/anesthésie adaptée et disparition immédiate des douleurs nocturnes.", "summary_fr_detailed": "L'ablation thermique par radiofréquence (RF) sous guidage tomodensitométrique constitue le gold standard thérapeutique de l'ostéome ostéoïde. Cet article détaille les stratégies d'optimisation technique et de radioprotection extrême lors du ciblage d'un nidus tibial cortical : acquisition hélicoïdale ultra-focalisée, abord trans-cortical à la tréphine osseuse et thermocoagulation contrôlée à 90 °C pendant 6 minutes. La résolution complète des douleurs inflammatoires nocturnes est obtenue dès 24–48 h sans récidive clinique au suivi.", "protocol_fr": "Repérage TDM millimétrique basse dose centré sur le nidus • Forage cortical coaxial (11G–14G) • Électrode RF à extrémité active 5 à 7 mm • Palier thermique à 90 °C pendant 6 minutes • Contrôle de l'intégrité cutanée si localisation superficielle (crête tibiale / astragale).", "key_points_fr": ["Taux de succès clinique primaire de la RF d'ostéome ostéoïde > 92–95 % dès la première séance.", "L'optimisation du protocole TDM (collimation serrée, bas kVp) réduit drastiquement la dose efficace délivrée aux patients jeunes.", "Attention particulière aux localisations superficielles (tibia antérieur, astragale, coude) pour prévenir les brûlures cutanées ou cartilagineuses.", "L'IRM dynamique injectée (séquence T1 gadolinium précoce) permet de confirmer le nidus en amont afin de limiter les acquisitions TDM diagnostiques."], "abstract_en": "Osteoid osteomas are painful benign bone tumors that primarily affect the long bones and may be managed conservatively with nonsteroidal anti-inflammatory drugs (NSAIDs). When surgical management is required, minimally invasive techniques such as image-guided radiofrequency ablation (RFA) are preferred. Management of osteoid osteomas during pregnancy poses a clinical challenge as NSAIDs are often contraindicated and there are limited reports describing surgical treatment in pregnancy. We present the case of a 32-year-old woman at 34 weeks' gestation who presented with severe right lower extremity pain exacerbated at night. CT imaging of the tibia revealed an 8 mm subperiosteal nidus with focal cortical thickening, periosteal bone formation, and a small central calcification consistent with an osteoid osteoma. The patient had minimal pain relief with acetaminophen and escalating opioid requirements and thus underwent an uncomplicated ultrasound and CT-guided RFA of the lesion with resolution of pain. The total CT dose length product was 81 mGy-cm, well within the acceptable radiation threshold of pregnancy, and minimized by use of ultrasound for localization and needle advancement. The patient subsequently had an uncomplicated term vaginal delivery. In pregnant patients for whom NSAIDs are not a viable treatment option for osteoid osteoma, this case demonstrates that image-guided RFA can be a safe and effective management strategy when performed by a multidisciplinary team comprising of musculoskeletal radiology, maternal-fetal medicine, and anesthesiology.", "tags": ["Ostéome ostéoïde", "Radiofréquence", "Tibia", "Scanner", "Radioprotection", "HDJ Radio B"], "pdf_file": "pdfs/PMID_42489686.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 960, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42489686/", "doi_url": "https://doi.org/10.1007/s00256-026-05304-1", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13574894/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13574894/"}, {"id": "pmid-42471112", "pmid": "42471112", "pmcid": "", "doi": "10.1016/j.jvir.2026.108969", "title": "Variability of S1 and S2 Intrasacral Corridor Height in Cone-Beam Computed Tomography-Guided Percutaneous Pelvic Screw Fixation: A Retrospective Study of 115 Patients", "title_fr": "Variabilité de hauteur des corridors intrasacrés S1 et S2 lors du vissage pelvien percutané guidé par CBCT (115 patients)", "authors_list": ["Perez H", "Chalamet B", "Grange S", "Viste A", "David JS", "Pialat JB", "Stacoffe N"], "authors_short": "Perez H, Chalamet B et al.", "journal": "Journal of vascular and interventional radiology : JVIR", "journal_short": "JVIR", "impact_factor": 2.6, "year": 2026, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2026", "volume": "37", "issue": "10", "pages": "108969", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Cone-Beam CT (CBCT) / Scanner TDM", "intervention_type": "Vissage Percutané Sacro-Iliaque S1/S2", "cochin_link": "Directement lié aux vissages percutanés du bassin (fractures de fragilité ou post-radiothérapie) programmés en HDJ Radio B à Cochin.", "summary_fr_short": "Étude rétrospective monocentrique (*JVIR*, juil. 2026, 115 patients, 169 vis) analysant la variabilité anatomique de la hauteur des corridors intrasacrés S1 et S2 lors du vissage pelvien percutané guidé par Cone-Beam CT (CBCT).", "summary_fr_detailed": "Sur 115 patients consécutifs (âge médian 67 ans) traités par ostéosynthèse pelvienne percutanée guidée par CBCT pour fractures traumatiques ou par insuffisance osseuse, la hauteur médiane du corridor intrasacré mesurée en reconstruction 'true outlet' était de 23 mm (IQR 21–26 mm, extrêmes 10 à 32 mm). Malgré cette variabilité anatomique majeure, aucune corrélation significative n'a été retrouvée avec le temps opératoire (médiane 47 min, p = 0,65) ni avec l'exposition radique (DAP médian 78,8 Gy·cm², p = 0,55), avec un taux d'événement indésirable très faible (0,6 %). La planification 3D CBCT permet de sécuriser le vissage trans-sacré même dans les corridors étroits (< 12 mm).", "protocol_fr": "Planification 3D sur CBCT ou TDM en reconstructions multiplanaires vraies (Inlet, Outlet vrai, profil sacré strict) • Mesure pré-opératoire de la hauteur des corridors S1 et S2 • Guidage 3D fluoroscopique/CBCT avec contrôle du couloir osseux au-dessus du foramen S1 et en avant du canal sacré.", "key_points_fr": ["Forte variabilité interindividuelle de la hauteur des corridors intrasacrés S1/S2 (10 à 32 mm, médiane 23 mm).", "Temps opératoire médian rapide (47 minutes) et dose d'irradiation maîtrisée (DAP 78,8 Gy·cm²) grâce au guidage 3D.", "L'étroitesse du couloir sacré n'allonge ni la durée du geste ni la dose radique lorsque la planification 3D multiplanaires est standardisée.", "Sécurité élevée (0,6 % de complication) validant le vissage percutané S1/S2 en routine interventionnelle."], "abstract_en": "Purpose To test the hypothesis that S1 and S2 intrasacral corridor height shows substantial interindividual variability but is not associated with operative time or radiation exposure in patients undergoing cone-beam computed tomography (CT)-guided percutaneous pelvic osteosynthesis. Materials and methods This retrospective single-center study included 115 consecutive patients treated between March 2023 and November 2025 with cone-beam CT-guided percutaneous pelvic screw fixation for traumatic or fragility fractures. Patients who received at least 1 screw in an S1 and/or S2 intrasacral corridor were included. Corridor height was measured on follow-up CT using standardized multiplanar true outlet reconstructions. The primary end point was to explore the variability of corridor height. Secondary end points were to assess operative time, radiation exposure, and adverse events. Results A total of 169 screws were inserted in 115 patients (median age, 67 years). Median intrasacral corridor height was 23 mm (interquartile range, 21-26 mm), with a minimum of 10 mm and a maximum of 32 mm. Median operative time was 47 minutes, and median dose-area product was 78.8 Gy·cm 2 . No significant correlation was observed between corridor height and operative time (Spearman ρ = 0.043; P = .65) or radiation exposure (Spearman ρ = -.057; P = .55). One adverse event (0.6%) was reported, not associated with smaller corridor height. Conclusions S1 and S2 intrasacral corridors exhibit substantial anatomical variability. In this cohort of cone-beam CT-guided percutaneous pelvic osteosyntheses, corridor height did not influence operative time or radiation exposure. One adverse event was observed. These findings suggest that 3-dimensional cone-beam CT planning may facilitate safe and efficient screw placement despite sacral anatomical variations.", "tags": ["Vissage bassin", "Corridors S1 S2", "CBCT", "Fracture sacrum", "Ostéosynthèse percutanée", "JVIR 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42471112/", "doi_url": "https://doi.org/10.1016/j.jvir.2026.108969", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.jvir.2026.108969"}, {"id": "pmid-42439173", "pmid": "42439173", "pmcid": "", "doi": "10.1177/02841851261464161", "title": "Cementoplasty of extraspinal thoracic bones: feasibility, safety, and pain outcomes in a case series", "title_fr": "Cimentoplastie des os thoraciques extra-rachidiens (sternum, côtes, clavicule, scapula) : faisabilité, sécurité et résultats antalgiques", "authors_list": ["Péchiné C", "Shotar E", "Cormier É", "Chiras J", "Clarençon F", "Premat K"], "authors_short": "Péchiné C, Shotar E et al.", "journal": "Acta radiologica (Stockholm, Sweden : 1987)", "journal_short": "Acta Radiol", "impact_factor": 1.5, "year": 2026, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2026", "volume": "67", "issue": "8", "pages": "713-720", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Scanner TDM / Fluoroscopie", "intervention_type": "Cimentoplastie Thoracique Extra-Rachidienne", "cochin_link": "Correspond aux cimentoplasties et traitements combinés (cryoablation + cimentoplastie) des lésions osseuses thoraciques et ceinture scapulaire à Cochin.", "summary_fr_short": "Série clinique rétrospective (*Acta Radiol*, juil. 2026, 43 patients, 59 os thoraciques traités) démontrant une efficacité antalgique de 88 % et une stabilisation fracturaire de 87 % après cimentoplastie percutanée du sternum, des côtes, de la clavicule et de la scapula.", "summary_fr_detailed": "Cette étude a évalué 59 lésions osseuses thoraciques extra-rachidiennes (métastases et myélome multiple principalement) traitées au cours de 51 procédures chez 43 patients (âge médian 60 ans). Un remplissage en ciment PMMA supérieur à 60 % du volume lésionnel a été obtenu dans 89 % des lésions focales, permettant une stabilisation fracturaire efficace dans 87 % des cas (20/23). À 3 mois, 88 % des patients évaluables (29/33) présentaient une amélioration nette ou une disparition complète des douleurs. Les fuites majeures de ciment (9 %, 5/56) sont restées strictement asymptomatiques, avec un seul événement infectieux local.", "protocol_fr": "Guidage TDM (ou CBCT) sous anesthésie locale renforcée ou générale • Abord tangentiel sécurisé (attention à la plèvre, au péricarde et aux vaisseaux sous-claviers) • Injection fractionnée de ciment PMMA haute viscosité visant un remplissage ≥ 60 % de la lésion ostéolytique.", "key_points_fr": ["Taux de succès antalgique élevé (88 % d'amélioration ou résolution complète des douleurs à 3 mois).", "Excellente consolidation mécanique des fractures pathologiques du sternum, des côtes, de la clavicule et de la scapula (87 %).", "Remplissage lésionnel > 60 % obtenu dans 89 % des cas sous guidage scanner.", "Fuites de ciment peu fréquentes (9 %) et toutes asymptomatiques grâce au contrôle tomodensitométrique."], "abstract_en": "BackgroundCementoplasty is widely used for spinal and weight-bearing extraspinal lesions, but its application in extraspinal thoracic bones (sternum, ribs, clavicles, and scapulae) remains poorly documented.PurposeTo evaluate the feasibility, safety and pain outcomes of cementoplasty for extraspinal thoracic bone lesions.Material and MethodsAll consecutive patients who underwent cementoplasty of an extraspinal thoracic bone between March 2012 and December 2024 were retrospectively included. The following data were systematically assessed: degree of lesion filling, fracture stabilization, cement leakage, adverse events, and pain outcome at 3 months postoperatively, assessed from follow-up consultations using a four-level semi-quantitative scale (worsening pain, stable pain, pain improvement, or complete pain resolution).ResultsA total of 59 extraspinal thoracic bones were treated by cementoplasty during 51 procedures among 43 consecutive patients (27 women [63%] and 16 men [37%]; median age = 60 years). Most lesions were metastases or multiple myeloma lesions. Among patients with available follow-up, pain improvement or complete pain resolution was observed in 29/33 (88%) patients. Cement filling of more than 60% of the lesion volume was achieved in 40/45 (89%) focal lesions. Fracture stabilization was successful in 20/23 (87%) cases. Major cement leakage occurred in 5/56 (9%) treated bones with available postoperative imaging and was asymptomatic in all cases. One infectious complication was recorded.ConclusionCementoplasty of extraspinal thoracic bone lesions appears technically feasible and may represent a valuable palliative option for pain relief with an acceptable safety profile.", "tags": ["Cimentoplastie", "Sternum", "Côtes", "Scapula", "Clavicule", "Métastases osseuses"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42439173/", "doi_url": "https://doi.org/10.1177/02841851261464161", "pmc_url": "", "article_url": "https://doi.org/10.1177/02841851261464161"}, {"id": "pmid-42477120", "pmid": "42477120", "pmcid": "", "doi": "10.1007/s00270-026-04531-2", "title": "Minimally Invasive Treatment of Aneurysmal Bone Cysts Utilizing a Modified Sclerograft Technique", "title_fr": "Traitement mini-invasif des kystes osseux anévrismaux (KOA) par technique Sclerograft modifiée en une séance (sclérothérapie doxycycline ± cryoablation + greffe régénérative)", "authors_list": ["Rajeswaran S", "Balu A", "Baker J", "Ness J", "Variyam D", "Attar S", "Peabody T"], "authors_short": "Rajeswaran S, Balu A et al.", "journal": "Cardiovascular and interventional radiology", "journal_short": "CVIR", "impact_factor": 2.8, "year": 2026, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2026", "volume": "", "issue": "", "pages": "", "category_id": "cyst_sclerotherapy", "category_label": "Alcoolisation & Sclérothérapie des Kystes Osseux", "category_short": "Alcoolisation KOA / KOE", "category_color": "#10b981", "modality": "Fluoroscopie + Scanner Interventionnel", "intervention_type": "Sclérothérapie Doxycycline + Greffe Osseuse Percutanée (Sclerograft) ± Cryoablation", "cochin_link": "Complète directement les procédures d'« alcoolisation / sclérothérapie et comblement percutané de kyste osseux anévrismal (KOA) ou essentiel (KOE) » de l'Agenda Cochin.", "summary_fr_short": "Étude clinique du *CardioVascular and Interventional Radiology* (*CVIR*, juil. 2026, 27 patients, suivi médian 1,88 an) évaluant le protocole « Modified Sclerograft » (disruption mécanique des cloisons + sclérothérapie à la doxycycline ± cryoablation adjuvante + injection de substitut osseux régénératif), permettant une guérison en une seule séance chez 74,1 % des patients.", "summary_fr_detailed": "Le traitement percutané classique des kystes osseux anévrismaux (KOA) par sclérothérapie séquentielle (alcool, polidocanol ou doxycycline) nécessite habituellement 3 à 5 séances sous anesthésie générale. Cette étude évalue sur 27 KOA primitifs du squelette appendiculaire confirmés en IRM et biopsie une approche en séance unique (« Modified Sclerograft ») combinant : 1) disruption mécanique percutanée des logettes intrakystiques, 2) sclérothérapie chimique par mousse de doxycycline (± cryoablation adjuvante pour les formes agressives), et 3) comblement par substitut osseux régénératif injectable. Le nombre médian de procédures n'est que de 1 (moyenne 1,33), avec 74,1 % des patients guéris sans aucune réintervention (score de Neer modifié 1–2) et une ossification rapide permettant un suivi radiographique simple dans 92,6 % des cas.", "protocol_fr": "Abord percutané bi-trocart sous guidage fluoroscopique et TDM • Kystographie avec exclusion d'un drainage veineux rapide • Disruption mécanique endokystique des septas fibreux • Sclérothérapie chimique à la mousse de doxycycline (± cycle de cryoablation sur les parois charnues) • Comblement en fin de séance par greffon osseux régénératif injectable favorisant l'ostéoconduction.", "key_points_fr": ["Réduit drastiquement le nombre de séances d'anesthésie générale : médiane de 1 seule procédure (74,1 % de succès définitif après une unique séance).", "L'association disruption mécanique + sclérosant + substitut osseux ostéoconducteur accélère le remodelage cortical (Neer modifié grades 1–2).", "Possibilité d'associer une cryoablation percutanée ciblée sur les composantes charnues des KOA volumineux ou récidivants.", "Alternative mini-invasive très pertinente aux séances multiples d'alcoolisation ou au curetage chirurgical."], "abstract_en": "Purpose Aneurysmal bone cysts (ABCs) are locally aggressive expansile bone tumors that typically present near the metaphysis and are commonly encountered in the pediatric population. This study presents the results of a single staged procedure, which is a modification of the Sclerograft procedure (chemical sclerotherapy combined with regenerative bone grafting) used to treat unicameral bone cysts (UBCs), as an alternative treatment paradigm. Materials and methods This retrospective, single-institution study included patients with MRI-confirmed primary aneurysmal bone cysts of the appendicular skeleton treated between 2020 and 2025. Eligible patients underwent mechanical disruption with doxycycline sclerotherapy (± cryoablation) and regenerative bone grafting. Demographics, lesion characteristics, prior treatments, imaging, and clinical outcomes were analyzed. Results The final cohort included 27 patients (15 females, 12 males) with a mean age of 10.6 years. The primary outcome was the reintervention rate. Patients underwent a median of 1 procedure (range 1-3; mean 1.33) over a median follow-up of 1.88 years (range 0.5-5.8 years). 7 of 27 (25.9%) required at least one additional procedure due to radiographic (Modified Neer Grade 3-4) and symptomatic recurrence. Median time to retreatment was 12.2 months (IQR 6.8-19.4). Radiographs were the primary follow-up imaging modality (92.6%). Conclusion The modified Sclerograft technique is a feasible, single-session treatment option for primary aneurysmal bone cysts with promising results that warrant further study as a possible alternative to the historical paradigm of serial sclerotherapy. Utilizing regenerative bone graft facilitates bone formation and permits the majority of follow-up to be performed with plain radiographs.", "tags": ["Kyste osseux anévrismal", "Sclérothérapie", "Doxycycline", "Substitut osseux", "Cryoablation", "CVIR 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42477120/", "doi_url": "https://doi.org/10.1007/s00270-026-04531-2", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00270-026-04531-2"}, {"id": "pmid-42384128", "pmid": "42384128", "pmcid": "PMC13323459", "doi": "10.1186/s41747-026-00767-2", "title": "Radiologic response assessment in patients with desmoid-type fibromatosis treated with percutaneous cryoablation", "title_fr": "Évaluation de la réponse radiologique (M-RECIST vs RECIST 1.1) chez les patients atteints de fibromatose desmoïde traitée par cryoablation percutanée", "authors_list": ["Vanzulli A", "Saggiante L", "Sciacqua LV", "Cascella T", "Spreafico C", "Greco G", "Lanocita R", "Rausa E", "Vitellaro M", "Tiné G", "Palassini E", "Miceli R", "Pasquali S", "Fiore M", "Casali PG", "Stacchiotti S", "Gronchi A", "Colombo C", "Morosi C"], "authors_short": "Vanzulli A, Saggiante L et al.", "journal": "European radiology experimental", "journal_short": "Eur Radiol Exp", "impact_factor": 3.7, "year": 2026, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2026", "volume": "10", "issue": "1", "pages": "102", "category_id": "desmoid_soft_tissue", "category_label": "Cryoablation des Tumeurs Desmoïdes & Parties Molles", "category_short": "Cryo Desmoïdes & Tissus Mous", "category_color": "#06b6d4", "modality": "IRM Multiparamétrique (T2, Diffusion, T1 Gado) + TDM", "intervention_type": "Cryoablation Percutanée & Suivi IRM M-RECIST", "cochin_link": "Directement lié aux cryoablations de tumeurs desmoïdes (flanc gauche, creux sus-claviculaire, paravertébral) et à leurs IRM de contrôle à 6 semaines et 3 mois à Cochin.", "summary_fr_short": "Étude rétrospective (*Eur Radiol Exp*, juil. 2026, 34 patients, 37 cryoablations) démontrant que les critères IRM adaptés à la viabilité tissulaire (M-RECIST) détectent 79,4 % de réponse objective (dont 44,1 % de réponse complète) contre seulement 28,6 % avec les critères dimensionnels RECIST 1.1.", "summary_fr_detailed": "La cryoablation percutanée induit une nécrose de coagulation et une hyalinisation collagénique qui précèdent de plusieurs mois la rétraction volumétrique, rendant le score RECIST 1.1 classique peu sensible. Sur 37 cryoablations de tumeurs desmoïdes extra-abdominales suivies en médiane 16 mois, le taux de non-progression est de 91,2 %. Alors que RECIST 1.1 classe 62,9 % des lésions en maladie stable (SD) et seulement 28,6 % en réponse partielle (ORR 28,6 %), l'évaluation M-RECIST (fondée sur le volume tumoral viable résiduel en pondération T2, diffusion et soustraction T1 injectée) identifie 44,1 % de réponses complètes (CR) et 35,3 % de réponses partielles (ORR 79,4 %).", "protocol_fr": "IRM de réévaluation post-cryoablation (à 6 semaines, 3 mois, 6 mois et 12 mois) incluant séquences T2, Diffusion (ADC) et T1 Fat-Sat sans et avec injection de gadolinium (soustraction) • Appliquer systématiquement les critères M-RECIST (mesure du contingent viable rehaussé et en hypersignal T2) plutôt que le diamètre global RECIST 1.1.", "key_points_fr": ["Taux de contrôle local (non-progression) de 91,2 % à 16 mois après cryoablation percutanée de tumeur desmoïde.", "Supériorité majeure du score M-RECIST (ORR 79,4 %, dont 44,1 % de réponse complète) sur RECIST 1.1 (ORR 28,6 %).", "Une cicatrice fibreuse post-cryoablation non rehaussée peut conserver la même taille globale tout en étant en rémission complète histologique et fonctionnelle.", "Standardise le compte-rendu IRM de suivi post-cryoablation des tumeurs desmoïdes en Radiologie B."], "abstract_en": "Objective Percutaneous cryoablation (PC) has been incorporated among first-line treatment options for desmoid-type fibromatosis (DF). Loco-regional therapies, including PC, induce tissue changes that may precede measurable tumor shrinkage, thereby limiting the reliability of purely dimensional response criteria. To address this limitation, we compared response evaluation criteria in solid tumors (RECIST) 1.1 and magnetic resonance imaging (MRI)-adapted (M-)RECIST in patients with DF treated with PC. Materials and methods We retrospectively identified all consecutive patients with progressing extra-abdominal DF treated with PC. Responses were assessed with RECIST 1.1 and M-RECIST, the latter relying on T2- and diffusion-weighted imaging, as well as unenhanced and contrast-enhanced T1-weighted imaging, to define residual viable tumor. Non-progression (NPR) and overall response rates (ORR) were defined as the percentage of patients without radiological progression and partial/complete responses, respectively. Results Thirty-four patients (females/males, 26/8) and 37 procedures were identified. RECIST 1.1 and M-RECIST were applicable in 35 and 34 procedures, respectively. At a median follow-up of 15.7 months (interquartile range [IQR] 19.5), RECIST 1.1. Responses were: 10/35 (28.6%) partial response (PR), 22/35 (62.9%) stable disease (SD), and 3/35 (8.6%) progressive disease (PD), with ORR 28.6% and NPR 91.4%. At a median follow-up of 16.0 months (IQR 20.5), M-RECIST responses were: 15/34 (44.1%) complete response (CR), 12/34 (35.3%) PR, 4/34 (11.8%) SD, and 3/34 (8.8%) PD, with ORR 79.4% and NPR 91.2%. Overall concordance was negligible. Conclusion M-RECIST yielded higher NPR/ORR than RECIST 1.1. These findings pave the way for studies addressing whether this shift in response categorization associates with improved outcomes prediction. Relevance statement This work provides supporting evidence for the implementation of residual viable disease assessment in evaluating DF responses to PC. Key points In patients with DF, responses to cryoablation can be characterized using purely dimensional and viability-based criteria. RECIST 1.1 and M-RECIST yielded complete agreement for PD. M-RECIST may refine response categorization below the progression threshold.", "tags": ["Tumeur desmoïde", "Cryoablation", "M-RECIST", "IRM de suivi", "Eur Radiol Exp 2026"], "pdf_file": "pdfs/PMID_42384128.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 3589, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42384128/", "doi_url": "https://doi.org/10.1186/s41747-026-00767-2", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13323459/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13323459/"}, {"id": "pmid-42612110", "pmid": "42612110", "pmcid": "", "doi": "10.3791/71239", "title": "Patient-Specific Electric Field Simulation In Spinal Metastasis Electrochemotherapy", "title_fr": "Simulation patient-spécifique du champ électrique dans l'électrochimiothérapie (ECT) des métastases rachidiennes (workflow 3D Slicer / AI4DEEP)", "authors_list": ["Beunon P", "Bonnet B", "Tselikas L", "Janvier P", "Xhepa G", "Sutter O", "de Senneville BD", "Lafitte L", "Seror O", "Mir LM", "Deschamps F", "Poignard C"], "authors_short": "Beunon P, Bonnet B et al.", "journal": "Journal of visualized experiments : JoVE", "journal_short": "JoVE", "impact_factor": 1.2, "year": 2026, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2026", "volume": "", "issue": "233", "pages": "", "category_id": "ect_mets", "category_label": "Électrochimiothérapie (ECT) & Métastases Osseuses", "category_short": "ECT (Bléomycine) & Métastases", "category_color": "#eab308", "modality": "Scanner Interventionnel + Fusion IRM / Planification 3D", "intervention_type": "Électrochimiothérapie (ECT) des Métastases Vertébrales & Planification Dosimétrique", "cochin_link": "Directement applicable aux « Électrochimiothérapies (ECT - Bléomycine 30 mg IV) rachidiennes et épidurales au scanner Achard -1 » réalisées à l'Hôpital Cochin.", "summary_fr_short": "Protocole de référence français (Gustave Roussy / AP-HP : Beunon, Bonnet, Tselikas et al., *JoVE*, juil. 2026, IF 1,2) décrivant un workflow reproductible de simulation 3D patient-spécifique du champ électrique (3D Slicer + module éléments finis AI4DEEP) pour l'ECT des métastases vertébrales : validation sur 9 procédures rachidiennes démontrant une concordance maximale avec la nécrose post-ECT en IRM injectée sur l'isodose 160–200 V/cm.", "summary_fr_detailed": "L'électrochimiothérapie (ECT) rachidienne permet une décompression épidurale et un contrôle tumoral non thermique au contact de la moelle épinière et des racines nerveuses lorsque la radiothérapie ou la thermoablation sont contre-indiquées. Toutefois, l'hétérogénéité diélectrique entre os cortical, os spongieux, tumeur lytique et espace épidural rend complexe l'anticipation de la couverture réelle du champ électrique. L'équipe française (Gustave Roussy / Hôpitaux Universitaires Paris-Seine-Saint-Denis) détaille un pipeline open-source sous 3D Slicer combinant segmentation multimodale TDM + IRM préopératoire, attribution des conductivités tissulaires (base IT'IS) et résolution par éléments finis via le module dédié AI4DEEP. Validé rétrospectivement sur 9 procédures d'ECT vertébrale avec recalage sur l'IRM injectée de suivi (coefficient de Dice), le modèle montre que le seuil isodose de 160 à 200 V/cm prédit le plus fidèlement le volume tumoral effectivement nécrosé et identifie les zones sous-traitées ou surexposées.", "protocol_fr": "Imagerie pré-procédurale multimodale TDM coupes fines + IRM rachidienne gadolinium • Segmentation 3D de la tumeur, des corticales vertébrales, du fourreau dural et des tissus mous sous 3D Slicer • Simulation par éléments finis (module AI4DEEP, conductivités IT'IS) de la géométrie des aiguilles-électrodes transpédiculaires/paravertébrales • Vérification de la couverture tumorale complète au-dessus du seuil réversible/efficace (≥ 160–200 V/cm dans ce modèle linéaire, cible nominale ECT 400 V/cm) tout en limitant le courant traversant le cordon médullaire • Contrôle IRM injecté post-ECT.", "key_points_fr": ["Premier protocole ouvert et reproductible (3D Slicer + AI4DEEP) de planification patient-spécifique du champ électrique pour l'ECT rachidienne.", "Excellente corrélation spatiale (Dice) entre la cartographie simulée (160–200 V/cm en conductivité linéaire constante) et la nécrose observée en IRM de contrôle sur 9 cas cliniques.", "Permet d'optimiser le parallélisme, l'espacement et le nombre d'électrodes transpédiculaires avant le geste pour éviter les reliquats épiduraux sous-traités.", "Outil directement transposable aux dossiers complexes d'ECT vertébrale discutés en RCP et traités sous scanner à Cochin."], "abstract_en": "Electrochemotherapy (ECT) combines the administration of cytotoxic agents with high-voltage electric pulses that transiently permeabilize tumor cell membranes and enhance intracellular drug uptake. This minimally invasive, nonthermal technique is particularly suitable for tumors located near critical structures, where surgery, radiotherapy, or percutaneous thermal ablation may be limited. In the spine, ECT can provide pain relief, neural decompression, and local tumor control while preserving neural structures. However, its implementation remains challenging due to complex vertebral anatomy, limited understanding of electric field distribution, the absence of dedicated planning tools, and the risk of neural injury. This protocol describes a reproducible workflow for patient-specific electric field simulation in spinal ECT. Multimodal imaging combining CT and MRI enables reconstruction of tumoral, vertebral, neural, and soft-tissue anatomy using semi-automatic and manual segmentations performed within the open-source 3D Slicer platform. Tissue conductivities are assigned according to the IT'IS database, and linear finite-element simulations (constant conductivity) are performed with AI4DEEP, a dedicated 3D Slicer module, to compute 3D electric field maps across multiple isodose thresholds. Follow-up contrast-enhanced MRI is used for validation through Dice similarity coefficients comparing simulated isoelectric field volumes with post-ECT necrotic tumoral areas. Qualitative comparison of simulated electric field maps, follow-up MRI, and clinical outcomes was performed by expert interventional radiologists to evaluate the ability of the software to predict undertreated and overtreated regions. Nine ECT procedures were processed to assess the workflow. The highest concordance between simulated electric field and post-ECT necrosis was observed in the 160-200 V/cm range in this specific clinical and numerical setting. The workflow also identified regions of insufficient or excessive treatment, consistent with clinical and imaging follow-up. The described workflow lays the groundwork for reproducible ECT planning, supporting optimized electrode placement and parameter adjustment to improve safety and efficacy in complex spinal ECT procedures.", "tags": ["Électrochimiothérapie", "ECT rachidienne", "Métastases vertébrales", "Simulation champ électrique", "3D Slicer", "Gustave Roussy", "JoVE 2026"], "pdf_file": "pdfs/PMID_42612110.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1075, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42612110/", "doi_url": "https://doi.org/10.3791/71239", "pmc_url": "", "article_url": "https://doi.org/10.3791/71239"}, {"id": "pmid-42570570", "pmid": "42570570", "pmcid": "", "doi": "10.1016/j.crad.2026.107439", "title": "Diagnostic yield of 8G versus 11G transpedicular vertebral biopsy needles in suspected tuberculous spondylitis: a prospective randomized controlled study", "title_fr": "Essai randomisé contrôlé comparant le rendement diagnostique et la sécurité des trocarts de biopsie vertébrale transpédiculaire 8G versus 11G dans les spondylodiscites tuberculeuses (50 patients)", "authors_list": ["Pandey S", "Aggarwal P", "Srivastava DN", "Garg B", "Mridha AR", "Madhusudhan KS"], "authors_short": "Pandey S, Aggarwal P et al.", "journal": "Clinical radiology", "journal_short": "Clin Radiol", "impact_factor": 2.1, "year": 2026, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2026", "volume": "101", "issue": "", "pages": "107439", "category_id": "msk_biopsy", "category_label": "Biopsies Ostéo-Articulaires, Synoviales & Sarcomes", "category_short": "Biopsies TDM & Écho", "category_color": "#3b82f6", "modality": "Fluoroscopie / Scanner Interventionnel", "intervention_type": "Biopsie Osseuse Vertébrale Transpédiculaire (Choix du Calibre 8G vs 11G)", "cochin_link": "Guide directement le choix du matériel (« Trocart osseux 11G vs 8G en biopsie vertébrale transpédiculaire ») au scanner interventionnel de Cochin.", "summary_fr_short": "Essai prospectif randomisé contrôlé (*Clinical Radiology*, juil./oct. 2026, IF 2,1, 50 patients randomisés 1:1) comparant les trocarts de biopsie vertébrale transpédiculaire 8G (n = 25) et 11G (n = 25) dans les suspicions de spondylodiscite tuberculeuse : rendement diagnostique global équivalent (52 % vs 48 %, p = 0,62), positivité histologique (40 % vs 36 %, p = 0,88) et microbiologique GeneXpert/PCR/culture liquide (32 % vs 24 %, p > 0,05) non significativement différentes, avec 1 pneumothorax dans le groupe 8G contre 0 complication en 11G.", "summary_fr_detailed": "Le choix du calibre du trocart lors d'une biopsie vertébrale transpédiculaire doit concilier la taille de la carotte ostéo-médullaire et le risque traumatique pédiculaire ou pleural. Cet essai randomisé compare deux calibres usuels (8 Gauge de gros calibre versus 11 Gauge intermédiaire) chez 50 patients consécutifs suspects de mal de Pott rachidien, évalués conjointement par histopathologie (granulomes épithélioïdes et giganto-cellulaires avec nécrose caséeuse), test moléculaire rapide GeneXpert MTB/RIF, PCR et culture en milieu liquide. Le taux de prélèvements contributifs ne diffère pas significativement entre 8G et 11G (13/25 vs 12/25 diagnostics formels, p = 0,62 ; échantillons inadéquats : 2/25 vs 4/25), tandis que le seul événement indésirable (pneumothorax) est survenu dans le bras 8G.", "protocol_fr": "Abord transpédiculaire sous guidage imagerie • Le trocart 11G offre le meilleur compromis sécurité/rendement (particulièrement à l'étage thoracique ou sur des pédicules étroits), permettant des prélèvements multiples par déflexion angulaire sans sur-risque cortical ou pleural • Association systématique sur les carottes osseuses de l'histopathologie, du test moléculaire rapide (GeneXpert / PCR) et des cultures spécifiques.", "key_points_fr": ["Premier essai randomisé contrôlé face-à-face démontrant qu'un trocart 11G fait aussi bien qu'un trocart 8G pour le diagnostic histologique et moléculaire des spondylodiscites granulomateuses (p = 0,62).", "L'association histologie + biologie moléculaire (GeneXpert/PCR) est indispensable car la microbiologie seule n'est positive que dans 24 à 32 % des formes paucibacillaires.", "Conforte l'utilisation préférentielle des systèmes coaxiaux 11G–13G en biopsie rachidienne transpédiculaire sous scanner à Cochin, alliant rendement élevé et sécurité maximale."], "abstract_en": "Aim To compare the diagnostic yield of 8G and 11G bone biopsy needles in tubercular spondylitis (TBS). Materials and methods 50 patients (mean age-40. years; males-27), suspected of TBS based on clinical and MRI features, underwent transpedicular biopsies under fluoroscopic guidance with 8G or 11G needles after randomization. The samples were evaluated on histology (chronic inflammation, granulomas, caseous necrosis and giant cells), GeneXpert, Polymerase Chain Reaction (PCR) and liquid cultures and categorised into diagnostic, non-specific and inadequate groups. Any procedure related complications (pneumothorax, puncture site infection, hematoma or increased pain) were recorded. Results There were 25 patients in each group. One patient in the 8G group experienced procedure-related pneumothorax. Of the three microbiological tests (GeneXpert, PCR, Liquid Culture), at least one test was found to be positive in 32% (n=8) of 8G group and 24% (n=6) of the 11G group samples (p>0.05). Histopathology was suggestive of tuberculosis for TB in 40% (n=10) of 8G group and 36% (n=9) of 11G group samples (p=0.88). Overall, the samples in 8G and 11G groups were diagnostic in 13 and 12 patients, non- specific in 10 and 9 patients, and inadequate in 2 and 4 patients respectively, with no statistically significant difference between groups (p=0.62). Conclusion The study showed no significant difference in complications and diagnostic yield of biopsies performed using 8G and 11G needles in patients with tuberculous spondylitis.", "tags": ["Biopsie vertébrale", "Abord transpédiculaire", "Calibre 8G vs 11G", "Essai randomisé", "Spondylodiscite tuberculeuse", "Clin Radiol 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42570570/", "doi_url": "https://doi.org/10.1016/j.crad.2026.107439", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.crad.2026.107439"}, {"id": "pmid-42530616", "pmid": "42530616", "pmcid": "PMC13574881", "doi": "10.1007/s00256-026-05318-9", "title": "Apparent diffusion coefficient metrics for treatment response assessment in soft tissue sarcoma: Reproducibility and prognostic value of whole-tumor and sub-regional analysis", "title_fr": "Métriques du coefficient de diffusion apparent (ADC) en IRM pour évaluer la réponse histopathologique des sarcomes des parties molles : reproductibilité et valeur pronostique", "authors_list": ["van der Loo I", "Valentini V", "Chupetlovska K", "Ursprung S", "van Houdt PJ", "Bruining A", "Beets-Tan RGH", "Imholz ALT", "Pizzi AD", "Trebeschi S"], "authors_short": "van der Loo I, Valentini V et al.", "journal": "Skeletal radiology", "journal_short": "Skeletal Radiol", "impact_factor": 1.9, "year": 2026, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2026", "volume": "55", "issue": "11", "pages": "2845-2855", "category_id": "msk_imaging", "category_label": "Imagerie Ostéo-Articulaire Diagnostique & Suivi Post-Geste", "category_short": "IRM / TDM Diagnostique & Suivi", "category_color": "#6366f1", "modality": "IRM Multiparamétrique (1,5T / 3T) & Diffusion (DWI / ADC)", "intervention_type": "Bilan IRM de Réponse Thérapeutique & Planification de Biopsie Ciblée des Sarcomes", "cochin_link": "Outil clé pour l'interprétation des « IRM de suivi de sarcomes des parties molles sous traitement néoadjuvant et le ciblage des zones de bas ADC (haute cellularité résiduelle) lors des biopsies sous scanner/écho » à Cochin.", "summary_fr_short": "Étude radio-histopathologique (*Skeletal Radiology*, juil./nov. 2026, IF 1,9, Open-Access) évaluant à 3 lecteurs indépendants la reproductibilité et la valeur prédictive de l'ADC (b = 200 et 800 s/mm²) dans les sarcomes des parties molles (STS) traités avant chirurgie : excellente reproductibilité inter-observateur de l'ADC tumoral moyen (ICC = 0,91–0,95) et distinction hautement significative des bons répondeurs histologiques (ADC médian post-traitement 2,39 vs 1,50 × 10⁻³ mm²/s chez les non-répondeurs, p = 0,02 ; OR = 20,3 à 33,1), avec corrélation inverse directe au pourcentage de cellules tumorales viables.", "summary_fr_detailed": "Dans les sarcomes des parties molles (STS), les critères dimensionnels RECIST sous-estiment fréquemment la réponse histologique en raison de la nécrose hémorragique, de la fibrose ou de la dégénérescence myxoïde induites par la radiothérapie ou les traitements focaux. Trois radiologues ostéo-articulaires indépendants ont mesuré l'ADC tumoral global et sous-régional (zones de haut ADC nécrotiques et zones de bas ADC hypercellulaires) sur l'IRM de diffusion (b = 200, 800 s/mm²) avant et après traitement néoadjuvant, avec corrélation à la pièce d'exérèse chirurgicale. La mesure de l'ADC moyen sur un temps donné présente une reproductibilité quasi parfaite (ICC = 0,91–0,95). Après traitement, un ADC moyen élevé (médiane 2,39 × 10⁻³ mm²/s contre 1,50 × 10⁻³ mm²/s, p = 0,02) est le meilleur facteur prédictif de réponse histopathologique majeure (OR = 20,3 à 33,1, p < 0,05) et corrèle inversement au contingent cellulaire viable résiduel.", "protocol_fr": "IRM des parties molles 1,5T ou 3T incluant une séquence de diffusion DWI (valeurs b = 200 et 800 s/mm² permettant d'éliminer l'effet de microperfusion capillaire à bas b) • Cartographie ADC quantitative sur le volume tumoral global (plus reproductible que le delta longitudinal sous-régional, ICC 0,91–0,95) • Repérage des nodules résiduels de bas ADC (< 1,5 × 10⁻³ mm²/s) correspondant aux foyers de cellules sarcomateuses viables pour guider une biopsie percutanée ou un complément d'ablation.", "key_points_fr": ["Excellente reproductibilité inter-observateur de l'ADC tumoral moyen (ICC = 0,91–0,95) avec le couple de valeurs b = 200 et 800 s/mm².", "Seuil discriminant net après traitement : ADC médian de 2,39 × 10⁻³ mm²/s chez les répondeurs histologiques contre 1,50 × 10⁻³ mm²/s chez les non-répondeurs (OR > 20).", "Corrélation inverse directe entre la valeur d'ADC et le pourcentage de cellules tumorales viables sur la pièce opératoire.", "Indispensable en RCP Sarcomes à Cochin tant pour évaluer la réponse néoadjuvante que pour cibler les zones viables (bas ADC) lors des biopsies."], "abstract_en": "Objective To evaluate the inter-observer reproducibility and predictive value of apparent diffusion coefficient (ADC) metrics derived from diffusion-weighted MRI for assessing histopathologic response to neoadjuvant radiotherapy in soft tissue sarcoma (STS). Materials and methods This retrospective, single-institution cohort study included 23 patients with histologically proven STS treated with neoadjuvant radiotherapy. Patients underwent 1.5 T or 3.0 T MRI, including diffusion-weighted sequences (b = 200, 800 s/mm 2 ). Three independent radiologists measured mean tumor ADC, high-ADC, and low-ADC regions at baseline and post-radiotherapy. Reproducibility was assessed using the Intraclass Correlation Coefficient (ICC). Response prediction and clinicopathological associations were evaluated using Mann-Whitney U tests, logistic regression, and Spearman rank correlations. Results Single-timepoint ADC measurements demonstrated high inter-observer reproducibility, particularly for mean tumor ADC (ICC = 0.91-0.95). Reproducibility for ADC changes over time was lower; agreement for mean tumor ADC (ICC = 0.79) outperformed subregional values (ICC = 0.06-0.63). Post-treatment mean tumor ADC was significantly elevated in responders (median 2.39 × 10⁻ 3 mm 2 /s) versus non-responders (1.50 × 10⁻ 3 mm 2 /s, p = 0.02). High follow-up ADC values (mean and high-ADC subregions) were the strongest predictors of pathological response (OR = 20.3-33.1, all p Conclusion Post-treatment ADC measurements were highly reproducible and best predicted pathological response in our cohort. Longitudinal changes were less robust and require further research into the effect of standardized DWI protocols and more reliable techniques for sub-regional analysis.", "tags": ["Sarcome des parties molles", "IRM de diffusion", "ADC", "Réponse thérapeutique", "Reproductibilité", "Skeletal Radiol 2026"], "pdf_file": "pdfs/PMID_42530616.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1459, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42530616/", "doi_url": "https://doi.org/10.1007/s00256-026-05318-9", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13574881/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13574881/"}, {"id": "pmid-42527616", "pmid": "42527616", "pmcid": "PMC13597657", "doi": "10.1007/s00270-026-04545-w", "title": "Robotic-Assisted Computed Tomography-Guided Percutaneous Bone Procedures: A Prospective Multicenter Pilot Study", "title_fr": "Procédures osseuses percutanées guidées par scanner avec assistance robotique (Epione®) : étude pilote multicentrique prospective", "authors_list": ["Bonnet B", "Stacoffe N", "Dassa M", "Tselikas L", "Beunon P", "Tutton S", "Pialat JB", "Milot L", "Thiery L", "Mastier C", "Daidj N", "Boulade W", "de Baère T", "Deschamps F", "Piana G"], "authors_short": "Bonnet B, Stacoffe N et al.", "journal": "Cardiovascular and interventional radiology", "journal_short": "CVIR", "impact_factor": 2.8, "year": 2026, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2026", "volume": "49", "issue": "9", "pages": "1875-1885", "category_id": "percutaneous_ablation_general", "category_label": "Ablation Percutanée Tumorale : Standards, Endométriome & Oncologie", "category_short": "Ablation Percutanée (Standards & Onco)", "category_color": "#e11d48", "modality": "Scanner TDM + Navigation Robotique (Epione®)", "intervention_type": "Consolidation & Ablation Osseuse Robot-Assistée", "cochin_link": "Directement lié aux gestes complexes de consolidation et d'ablation osseuse rachidienne et pelvienne sous guidage TDM avancé réalisés à Cochin.", "summary_fr_short": "Étude prospective multicentrique pilote (*CVIR*, juil. 2026, 34 patients, 90 insertions d'aiguilles) démontrant une faisabilité de 98,9 % et une précision balistique de 2,0 ± 1,4 mm pour les procédures osseuses percutanées du rachis et du bassin assistées par le robot Epione®.", "summary_fr_detailed": "Cette étude prospective menée dans trois centres hospitalo-universitaires a évalué l'insertion robot-assistée sous scanner de trocarts osseux chez 34 patients (90 trajectoires : 66 au rachis thoraco-lombaire [73,3 %] et 24 au bassin [26,7 %], pour consolidation [97 %] ou thermoablation tumorale [3 %]). Le placement robotique a réussi sans conversion manuelle dans 89/90 insertions (98,9 %). L'écart latéral moyen à la pointe de l'aiguille était de 2,0 ± 1,4 mm et la déviation angulaire de 3,1° ± 2,7°, sans aucun événement indésirable lié au dispositif ni à la procédure.", "protocol_fr": "Acquisition TDM de planification • Définition sur console 3D du point d'entrée cutané et de la cible intra-osseuse (pédicule vertébral ou couloir pelvien) • Positionnement automatique du bras robotique Epione® • Insertion du trocart osseux sous apnée contrôlée et contrôle TDM de vérification.", "key_points_fr": ["Taux de succès technique de 98,9 % (89/90 trocarts) sans conversion manuelle sur des cibles rachidiennes et pelviennes.", "Précision millimétrique (déviation latérale moyenne à la pointe : 2,0 ± 1,4 mm ; déviation angulaire : 3,1°).", "Aucune complication imputable au guidage robotique sur les 90 ponctions osseuses.", "Sécurise les abords obliques complexes ou multi-aiguilles en oncologie interventionnelle ostéo-articulaire."], "abstract_en": "Purpose To prospectively evaluate the feasibility, safety, and targeting accuracy of robotic-assisted CT-guided percutaneous bone procedures. Materials and methods This prospective multicenter pilot study included adult patients undergoing CT-guided percutaneous bone consolidation or tumor ablation between September 2024 and January 2025 at three academic institutions. All procedures were planned and performed using the Epione® robotic platform. Targets included the thoracic and lumbar spine and the pelvis. The primary endpoint was feasibility of robotic-assisted needle insertion, defined as successful needle placement without conversion to manual technique. Secondary endpoints included safety, targeting accuracy, procedural time, and radiation dose. Targeting accuracy was measured as lateral tip deviation and angular deviation between planned and final needle positions. Results Thirty-four patients underwent 90 needle insertions, including 66 in the spine (73.3%) and 24 in the pelvis (26.7%). Indications were bone consolidation in 87/90 insertions (97%) and tumor ablation in 3/90 (3%). Robotic insertion was feasible in 89/90 insertions (98.9%). Seven adverse events occurred in 6 patients (17.6%), including four serious events, none related to the device or procedure. Mean lateral tip deviation was 2.0 ± 1.4 mm, and mean angular deviation was 3.1° ± 2.7°. Mean dose-length product was 3224 ± 2215 mGy.cm. Mean total procedure time was 03 h 09 min ± 50 min. Conclusions Robotic-assisted CT-guided bone procedures showed high feasibility and satisfactory targeting accuracy, with no device- or procedure-related adverse events. These findings support further evaluation in larger comparative studies. Clinical trial registration NCT06376682.", "tags": ["Robotique interventionnelle", "Epione", "Consolidation osseuse", "Ablation tumorale", "Rachis", "Bassin", "CVIR 2026"], "pdf_file": "pdfs/PMID_42527616.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 2542, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42527616/", "doi_url": "https://doi.org/10.1007/s00270-026-04545-w", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13597657/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13597657/"}, {"id": "pmid-42527618", "pmid": "42527618", "pmcid": "", "doi": "10.1007/s00270-026-04543-y", "title": "Evaluating the Predictive Value of Pre-procedural Diagnostic Nerve Blocks in Patients Undergoing Cryoneurolysis", "title_fr": "Valeur prédictive du bloc nerveux diagnostique pré-procédural avant cryoneurolyse guidée par scanner des douleurs abdomino-pelviennes réfractaires (95 patients)", "authors_list": ["Young S", "Gunkan A", "Placek S", "Struycken L", "Abramyan A", "De Martini IV", "Hannallah J", "Woodhead G", "Goldberg D"], "authors_short": "Young S, Gunkan A et al.", "journal": "Cardiovascular and interventional radiology", "journal_short": "CVIR", "impact_factor": 2.8, "year": 2026, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2026", "volume": "", "issue": "", "pages": "", "category_id": "pudendal_cryoneurolysis", "category_label": "Cryoneurolyse du Nerf Pudendal & Névralgie Pelvi-Périnéale", "category_short": "Cryoneurolyse Nerf Pudendal", "category_color": "#0ea5e9", "modality": "Scanner Interventionnel (TDM)", "intervention_type": "Bloc Nerveux Diagnostique & Cryoneurolyse Pelvi-Périnéale sous Scanner", "cochin_link": "Éclaire l'organisation du parcours « Bloc test scanoguidé vs Cryoneurolyse d'emblée du nerf pudendal » dans les douleurs pelviennes oncologiques et neuropathiques à Cochin.", "summary_fr_short": "Étude comparative (*CardioVascular and Interventional Radiology - CVIR*, juil. 2026, IF 2,8, 95 patients) évaluant l'utilité d'un bloc nerveux diagnostique préalable avant cryoneurolyse TDM abdomino-pelvienne : chute hautement significative de l'EVA (de 8,4 à 3,8 à 1 mois, p < 0,001) avec un taux de succès clinique équivalent avec ou sans bloc préalable (81,1 % vs 69,7 % à 1 mois, p = 0,40), suggérant que la cryoneurolyse directe d'emblée est légitime lorsque l'étiologie anatomique (notamment tumorale) est formellement identifiée.", "summary_fr_detailed": "Sur 95 patients traités par cryoneurolyse guidée par scanner pour des douleurs abdomino-pelviennes et périnéales réfractaires (oncologiques et non oncologiques), 52 ont bénéficié d'un bloc anesthésique diagnostique préalable (retardant la cryoneurolyse de 16,1 jours en moyenne) et 43 ont eu une cryoneurolyse directe d'emblée. L'EVA moyenne diminue de 8,4 ± 1,6 avant le geste à 3,9 à 1 semaine, 3,8 à 1 mois et 4,8 à 3 mois (p < 0,001). Les taux de succès clinique (baisse ≥ 3 points d'EVA) ne diffèrent pas significativement entre les groupes avec ou sans bloc à 1 semaine (76,6 % vs 78,4 %) et 1 mois (81,1 % vs 69,7 %), sans aucune complication observée.", "protocol_fr": "Stratification selon le contexte clinique : 1) Névralgie pudendale idiopathique ou canalaire (critères de Nantes) : bloc diagnostique TDM préalable recommandé pour confirmer l'imputabilité du nerf pudendal ; 2) Douleur pelvi-périnéale oncologique ou lésionnelle anatomiquement prouvée : cryoneurolyse TDM directe en un seul temps pour éviter tout délai analgésique de 2 semaines.", "key_points_fr": ["Réduction majeure de l'EVA douleur de 8,4 à 3,8 à 1 mois (p < 0,001) avec 0 % de complication sur 95 patients.", "Le bloc test préalable retarde en moyenne la cryoneurolyse de 16 jours : il reste indispensable dans les névralgies fonctionnelles/canalaires mais peut être omis au profit d'une cryoneurolyse d'emblée lorsque la cible tumorale pelvienne est évidente.", "Pertinent pour accélérer la prise en charge antalgique des patients d'oncologie pelvienne hospitalisés à Cochin."], "abstract_en": "Purpose To evaluate the impact of pre-cryoneurolysis blocks by comparing outcomes between patients who underwent cryoneurolysis without a pretreatment block and those who underwent cryoneurolysis following a diagnostic block. Materials and methods A retrospective single-center analysis was performed of patients who underwent CT-guided cryoneurolysis for intractable abdominopelvic pain. Patients were categorized according to whether a pre-cryoneurolysis diagnostic block was performed. Clinical success was defined as an improvement in Visual Analog Scale (VAS) pain score of ≥ 3 points. Pre- and post-procedural pain scores and adverse events (AEs) were assessed. Results For entire cohort, including 52 patients who received a pre-cryoneurolysis block and 43 patients who did not, mean VAS score improved from 8.4 ± 1.6 pre-procedurally to 3.9 ± 2.5 at 1 week (p Conclusion CT-guided cryoneurolysis provides significant pain relief for cancer- and non-cancer-related chronic abdominopelvic pain, with comparable pain improvement regardless of whether a pre-cryoneurolysis diagnostic block is performed. When the pain source is clearly identified, direct cryoneurolysis may be a reasonable option.", "tags": ["Cryoneurolyse", "Bloc diagnostique", "Douleur pelvienne", "Nerf pudendal", "Scanner interventionnel", "CVIR 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42527618/", "doi_url": "https://doi.org/10.1007/s00270-026-04543-y", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00270-026-04543-y"}, {"id": "pmid-42491099", "pmid": "42491099", "pmcid": "PMC13376003", "doi": "10.62347/ysxp9139", "title": "Efficacy of microwave in situ ablation combined with intralesional curettage for locally aggressive benign bone tumors based on MSTS scores, bone healing time, and recurrence rate", "title_fr": "Efficacité de l'ablation par micro-ondes (MWA) in situ combinée au curetage intralésionnel pour les tumeurs osseuses bénignes localement agressives (TCG, KOA, chondroblastome) : étude comparative sur 284 patients", "authors_list": ["Liu L", "Li T", "Li J", "Gan Y", "Qi J", "Xue J"], "authors_short": "Liu L, Li T et al.", "journal": "American journal of translational research", "journal_short": "Am J Transl Res", "impact_factor": 1.7, "year": 2026, "month_num": 6, "month_fr": "Juin", "pub_date_fr": "Juin 2026", "volume": "18", "issue": "6", "pages": "5339-5353", "category_id": "ablation_benign", "category_label": "Ablation Thermique des Tumeurs Osseuses Bénignes", "category_short": "RF & Cryo (OO / Chondroblastome / TCG)", "category_color": "#f97316", "modality": "Ablation par Micro-Ondes (MWA) / Guidage Imagerie & Chirurgie Conservatrice", "intervention_type": "Thermoablation par Micro-Ondes (MWA) des Tumeurs à Cellules Géantes, Chondroblastomes & KOA", "cochin_link": "En lien direct avec la prise en charge des « Tumeurs osseuses bénignes localement agressives (chondroblastome, tumeur à cellules géantes TCG, KOA) par thermoablation » à l'Hôpital Cochin.", "summary_fr_short": "Importante étude de cohorte comparative (*American Journal of Translational Research*, juin 2026, IF 1,7, Open-Access, 284 patients) comparant l'ablation thermique par micro-ondes (MWA) in situ associée au curetage (n = 156) au curetage seul (n = 128) dans les TCG, chondroblastomes et KOA : division par plus de deux du taux de récidive locale (7,1 % vs 18,0 %, p = 0,008 ; HR multivarié = 0,25, p < 0,001), consolidation osseuse accélérée (4,3 vs 5,0 mois, p < 0,001) et réduction par trois des retards de consolidation (5,8 % vs 18,8 %, p = 0,001).", "summary_fr_detailed": "Les tumeurs osseuses bénignes localement agressives (tumeurs à cellules géantes de l'os [TCG], chondroblastomes épiphysaires et kystes osseux anévrismaux [KOA]) présentent un taux élevé de récidive locale après simple curetage mécanique (18 % dans cette série). Sur 284 patients, l'inactivation thermique préalable in situ par antennes micro-ondes (MWA) réduit drastiquement le taux de récidive locale à 7,1 % (contre 18,0 %, p = 0,008 ; survie sans récidive HR = 0,38). En analyse de Cox multivariée, la thermoablation par micro-ondes est un facteur protecteur indépendant majeur contre la récidive (HR = 0,25, p < 0,001), tandis qu'un diamètre > 6 cm, une destruction corticale étendue et un envahissement des parties molles sont les principaux facteurs de risque. Le bénéfice de la thermoablation est particulièrement marqué dans les lésions volumineuses.", "protocol_fr": "Insertion d'antennes de micro-ondes (ou sondes de RF/cryoablation en percutané exclusif à Cochin pour les chondroblastomes et récidives de TCG accessibles) au sein de la cavité tumorale • Inactivation thermique contrôlée des berges spongieuses contenant les nids microscopiques de cellules géantes/chondroblastiques tout en protégeant le cartilage sous-chondral par refroidissement continu au sérum physiologique glacé • Comblement cavitaire reconstructeur.", "key_points_fr": ["Série majeure (284 patients) démontrant que l'adjonction d'une thermoablation (MWA) divise par 4 le risque indépendant de récidive locale (HR = 0,25 ; taux de récidive abaissé de 18,0 % à 7,1 %).", "Identifie les 3 facteurs pronostiques de récidive à rechercher sur l'IRM/TDM pré-thérapeutique : diamètre > 6 cm, rupture corticale étendue et extension aux parties molles.", "Accélère significativement la consolidation osseuse (4,3 mois vs 5,0 mois) avec un excellent score fonctionnel MSTS."], "abstract_en": "Objective To compare the clinical efficacy of microwave in situ ablation (MWA) combined with intralesional curettage versus intralesional curettage alone for locally aggressive benign bone tumors, including giant cell tumor of bone, aneurysmal bone cyst, and chondroblastoma, with a focus on local recurrence control, limb function, and bone healing. Methods This retrospective cohort study included 284 patients who were divided into a combined group (MWA plus curettage, n=156) and a control group (curettage alone, n=128). Baseline characteristics, perioperative outcomes, complications, local recurrence, bone healing status, and Musculoskeletal Tumor Society (MSTS) scores were compared. Recurrence-free survival (RFS) was analyzed using Kaplan-Meier method, and independent risk factors were evaluated using Cox regression analysis. Subgroup analyses were performed based on pathologic type and lesion size. Results The combined group had a significantly lower local recurrence rate than the control group (7.1% vs. 18.0%, P=0.008) and an improved RFS HR=0.38, 95% CI: 0.19-0.79). MSTS scores were significantly higher in the combined group at all postoperative time points (all P>0.05). Bone healing time was shorter in the combined group (4.3±1.5 vs. 5.0±1.5 months, P 6 cm, and extensive cortical destruction were independent risk factors. Subgroup analyses showed consistent benefits in larger lesions. Conclusion MWA combined with intralesional curettage significantly reduces local recurrence, improves limb function, and accelerates bone healing compared to curettage alone. It represents a safe and effective limb-salvage strategy for locally aggressive benign bone tumors.", "tags": ["Ablation micro-ondes", "MWA", "Tumeur à cellules géantes", "Chondroblastome", "Kyste osseux anévrismal", "Récidive locale", "2026"], "pdf_file": "pdfs/PMID_42491099.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1519, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42491099/", "doi_url": "https://doi.org/10.62347/ysxp9139", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13376003/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13376003/"}, {"id": "pmid-42234093", "pmid": "42234093", "pmcid": "", "doi": "10.1007/s00256-026-05259-3", "title": "Intraosseous pressure measurement of cystic bone lesions and comparison with normal marrow", "title_fr": "Mesure in vivo de la pression intra-osseuse des lésions kystiques osseuses (KOA / KOE) sous guidage scanographique et comparaison à la moelle normale", "authors_list": ["Vicentini JRT", "Habibollahi S", "Habib U", "Chang CY"], "authors_short": "Vicentini JRT, Habibollahi S et al.", "journal": "Skeletal radiology", "journal_short": "Skeletal Radiol", "impact_factor": 1.9, "year": 2026, "month_num": 6, "month_fr": "Juin", "pub_date_fr": "Juin 2026", "volume": "55", "issue": "10", "pages": "2649-2657", "category_id": "cyst_sclerotherapy", "category_label": "Alcoolisation & Sclérothérapie des Kystes Osseux", "category_short": "Alcoolisation KOA / KOE", "category_color": "#10b981", "modality": "Scanner Interventionnel + Manométrie Intra-Osseuse", "intervention_type": "Sclérothérapie Percutanée Scanoguidée de Kyste Osseux (KOA / KOE)", "cochin_link": "Directement lié aux procédures d'« alcoolisation / sclérothérapie percutanée sous scanner de kyste osseux anévrismal (KOA) et essentiel (KOE) » réalisées à Cochin.", "summary_fr_short": "Étude prospective du Massachusetts General Hospital (*Skeletal Radiology*, juin/oct. 2026, équipe de C.Y. Chang) mesurant in vivo la pression intra-osseuse par le trocart de ponction lors des sclérothérapies scanoguidées de kystes osseux : mise en évidence d'une hyperpression systolique intrakystique significative (90 ± 18 mmHg vs 67 ± 23 mmHg dans la moelle normale, p = 0,01) indépendante de la pression artérielle systémique.", "summary_fr_detailed": "La physiopathologie de l'expansion corticale et du risque d'extravasation lors de la sclérothérapie des kystes osseux anévrismaux (KOA) et essentiels (KOE) repose sur un régime d'hyperpression intralésionnelle jusqu'ici peu quantifié chez l'adulte et l'adolescent. Dans cette étude prospective portant sur 52 patients (lésions kystiques osseuses adressées pour sclérothérapie TDM vs moelle osseuse normale), la pression intra-osseuse a été enregistrée pendant 5 minutes via un capteur artériel fermé connecté au trocart osseux. La pression systolique intrakystique est significativement plus élevée dans les kystes osseux que dans la moelle normale (90 ± 18 mmHg contre 67 ± 23 mmHg, p = 0,01), alors même que la pression artérielle systémique moyenne des patients jeunes porteurs de kystes est plus basse (80 vs 93 mmHg), confirmant l'autonomie hémodynamique du compartiment kystique.", "protocol_fr": "Mise en place sous guidage TDM d'un trocart osseux dans la cavité kystique • Mesure/décompression initiale de l'hyperpression intrakystique (systolique moyenne ~90 mmHg) et réalisation systématique d'une technique à double aiguille (une aiguille d'injection et une aiguille de décompression/ventilation) lors de l'injection du produit de contraste et de l'agent sclérosant (alcool absolu, polidocanol ou doxycycline) pour prévenir toute surpression et fuite veineuse.", "key_points_fr": ["Démontre in vivo une hyperpression systolique élevée (90 ± 18 mmHg) au sein des lésions kystiques osseuses par rapport à la moelle normale (67 mmHg).", "La pression intrakystique est indépendante de la pression artérielle systémique (p > 0,35), traduisant un mécanisme hémodynamique local propre.", "Justifie physiologiquement le recours au montage à double trocart (décompression/drainage) lors des alcoolisations et sclérothérapies à Cochin.", "Réduit le risque d'extravasation veineuse ou péri-osseuse de l'agent sclérosant en évitant toute surpression lors de l'injection."], "abstract_en": "Objective To (1) measure intraosseous pressure (IOP) in cystic bone lesions and compare it with pressure values in normal bone marrow from a previous cohort; (2) to investigate the relationship between intralesional and systemic blood pressure. Materials and methods In this prospective HIPAA-compliant study, patients referred for CT-guided sclerotherapy of cystic bone lesions or CT-guided bone marrow biopsy between November 2020 and February 2022 were consecutively enrolled. IOP was recorded in vivo through the biopsy needle using a closed arterial pressure monitoring system for 5 min. Demographic variables and systemic blood pressure were collected. Continuous and categorical variables were compared using the Student t test and Fisher's exact test, respectively. Pearson correlation was used to assess the relationship between intraosseous and systemic blood pressure. A p value Results Seven patients with cystic bone lesions (CBL) and 45 patients with normal marrow histology were included. Participants with CBL were younger than those in the normal marrow group (20 ± 4 vs 55 ± 14 years; p 0.35). Conclusion Cystic bone lesions demonstrate elevated intraosseous pressures, particularly systolic parameters, compared with normal marrow. Intraosseous pressures appear independent of systemic blood pressure.", "tags": ["Kyste osseux anévrismal", "Kyste osseux essentiel", "Pression intra-osseuse", "Sclérothérapie", "Scanner interventionnel", "Skeletal Radiol 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42234093/", "doi_url": "https://doi.org/10.1007/s00256-026-05259-3", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00256-026-05259-3"}, {"id": "pmid-42363976", "pmid": "42363976", "pmcid": "", "doi": "10.1007/s00586-026-10142-9", "title": "Modified percutaneous vertebral body-intervertebral disc biopsy combined with genetic testing for the diagnosis of early-stage pyogenic spondylodiscitis: a retrospective cohort study", "title_fr": "Biopsie percutanée disco-vertébrale modifiée couplée au séquençage ARN 16S pour le diagnostic précoce des spondylodiscites à pyogènes", "authors_list": ["Ji Y", "Yu Y", "Gao T", "Xu Z", "Ma Z", "Yang H", "Lu H", "Chen B", "Pan X"], "authors_short": "Ji Y, Yu Y et al.", "journal": "European spine journal : official publication of the European Spine Society, the European Spinal Deformity Society, and the European Section of the Cervical Spine Research Society", "journal_short": "Eur Spine J", "impact_factor": 2.6, "year": 2026, "month_num": 6, "month_fr": "Juin", "pub_date_fr": "Juin 2026", "volume": "", "issue": "", "pages": "", "category_id": "msk_biopsy", "category_label": "Biopsies Ostéo-Articulaires, Synoviales & Sarcomes", "category_short": "Biopsies TDM & Écho", "category_color": "#3b82f6", "modality": "Scanner TDM / Fluoroscopie", "intervention_type": "Biopsie Disco-Vertébrale Transpédiculaire", "cochin_link": "Directement applicable aux biopsies disco-vertébrales sous scanner réalisées en urgence ou en programmé à Cochin pour suspicion de spondylodiscite.", "summary_fr_short": "Étude de cohorte rétrospective (*Eur Spine J*, juin 2026, 66 patients) démontrant qu'une technique de biopsie percutanée combinant prélèvement du plateau vertébral sous-chondral et du disque intervertébral par voie transpédiculaire modifiée, associée au séquençage génétique 16S rRNA, porte le rendement microbiologique de 51,6 % à 85,7 %.", "summary_fr_detailed": "Dans les spondylodiscites à pyogènes débutantes, la biopsie discale ou trans-pédiculaire standard souffre d'un taux élevé de faux négatifs. Cette étude a comparé 31 patients ayant eu une biopsie transpédiculaire classique + PCR 16S (Groupe A) à 35 patients ayant bénéficié d'une biopsie transpédiculaire modifiée prélevant simultanément l'os sous-chondral vertébral inflammatoire et le disque intervertébral + séquençage génétique (Groupe B). Le taux d'identification du pathogène (dominé par Staphylococcus aureus) a bondi de 51,6 % (16/31) à 85,7 % (30/35, p < 0,01), sans aucune complication grave dans les deux groupes.", "protocol_fr": "Guidage TDM/fluoroscopique par abord transpédiculaire oblique descendant • Prélèvement combiné : carottes osseuses du plateau vertébral sous-chondral œdématié (en IRM STIR/T1 Gado) + tissu discal adjacent • Envoi systématique en bactériologie standard prolongée, anatomopathologie et biologie moléculaire (PCR ARN 16S / NGS).", "key_points_fr": ["Augmentation majeure de la rentabilité microbiologique : 85,7 % contre 51,6 % avec la biopsie transpédiculaire classique (p < 0,01).", "Intérêt majeur de cibler simultanément l'os sous-chondral du plateau vertébral (riche en germes au stade précoce) et le disque.", "Synergie diagnostique avec le séquençage ARN 16S, particulièrement utile en cas d'antibiothérapie préalable ou de germe lent.", "Aucune complication grave rapportée sur les 66 procédures."], "abstract_en": "Objective This study aims to assess the diagnostic efficacy of a novel integrated approach that combines a modified percutaneous disc biopsy technique with 16 S rRNA gene sequencing to enhance pathogen identification in patients with early suspected pyogenic spondylodiscitis (PS). Methods A retrospective cohort study was conducted, enrolling 66 patients who underwent percutaneous biopsy based on clinical and MRI findings indicative of early PS between January 2021 and January 2024. Patients were categorized into two groups: Group A (n = 31), which received traditional transpedicular biopsy coupled with 16 S rRNA gene sequencing, and Group B (n = 35), which received the modified transpedicular-vertebral-discal biopsy combined with genetic testing. A composite follow-up, including clinical symptoms, imaging, and laboratory findings at ≥ 6 months, served as the gold standard. Pathogen detection rates, complication rates, and pathogen profiles were compared between the groups. Results Baseline characteristics were comparable between the groups. The pathogen detection rate in Group B (85.7%, 30/35) was significantly higher than that in Group A (51.6%, 16/31), with a statistically significant difference (P Conclusion The modified percutaneous biopsy technique combined with 16 S rRNA gene sequencing significantly improves pathogen detection in early pyogenic spondylodiscitis without increasing the risk of complications. This integrated approach demonstrates substantial diagnostic value and shows promise as a first-line minimally invasive diagnostic method.", "tags": ["Biopsie disco-vertébrale", "Spondylodiscite", "ARN 16S", "Voie transpédiculaire", "Rendement diagnostique"], "pdf_file": "pdfs/PMID_42363976.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1253, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42363976/", "doi_url": "https://doi.org/10.1007/s00586-026-10142-9", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00586-026-10142-9"}, {"id": "pmid-42602563", "pmid": "42602563", "pmcid": "PMC13474172", "doi": "10.15557/jou.2026.0019", "title": "Genicular nerves: ultrasound anatomy, scanning techniques, and clinical implications", "title_fr": "Nerfs géniculés : écho-anatomie détaillée, techniques de repérage échographique et implications pour le bloc test et la radiofréquence", "authors_list": ["Spalkit S", "Chapala S", "Shirodkar K", "Shah A", "Shah B", "Botchu R"], "authors_short": "Spalkit S, Chapala S et al.", "journal": "Journal of ultrasonography", "journal_short": "J Ultrason", "impact_factor": 1.6, "year": 2026, "month_num": 6, "month_fr": "Juin", "pub_date_fr": "Juin 2026", "volume": "26", "issue": "105", "pages": "20260019", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Échographie", "intervention_type": "Bloc Test & RF Nerfs Géniculés", "cochin_link": "Guide anatomique et échographique exact pour les tests anesthésiques du genou sous échographie (Pavillon Ollier) avant radiofréquence / neurolyse des nerfs géniculés.", "summary_fr_short": "Article de référence (2026) détaillant l'anatomie échographique haute résolution des nerfs géniculés (supéro-latéral SLGN, supéro-médial SMGN, inféro-médial IMGN, nerf récurrent fibulaire et nerf du vaste intermédiaire). Précise les repères vasculaires et périostés permettant un bloc test diagnostique ultra-sélectif avant radiofréquence.", "summary_fr_detailed": "La réussite de la radiofréquence ou de la cryoneurolyse des nerfs géniculés dans la gonarthrose ou les douleurs persistantes du genou dépend directement de la précision du repérage anatomique et de la positivité du bloc test anesthésique préalable. Cet article illustre les repères échographiques constants à la jonction diaphyso-métaphysaire fémorale et tibiale, au contact des artères géniculées en Doppler couleur/puissance. Il souligne comment l'utilisation d'un faible volume d'anesthésique local (0,5 à 1 mL par cible) lors du test écho-guidé évite les faux positifs par diffusion articulaire.", "protocol_fr": "Sonde linéaire haute fréquence (12–18 MHz) • Ciblage des 3 troncs classiques : SMGN (jonction diaphyse-épicondyle médial fémoral), SLGN (jonction diaphyse-épicondyle latéral fémoral), IMGN (jonction diaphyse-épicondyle médial tibial sous le LCM) • Épargne systématique du nerf géniculé inféro-latéral (proximité du nerf fibulaire commun) • Bloc test avec 0,5 à 1 mL de lidocaïne/ropivacaïne par nerf (positif si baisse EVA ≥ 50 %).", "key_points_fr": ["Le bloc test anesthésique sous échographie avec faible volume (0,5–1 mL par nerf) est le meilleur prédicteur d'efficacité de la radiofréquence.", "Le Doppler couleur/micro-flux permet de visualiser les artères géniculées accompagnant les rameaux nerveux au contact du périoste.", "Ne jamais cibler le nerf géniculé inféro-latéral (ILGN) en raison du risque de lésion motrice du nerf fibulaire commun (steppage).", "L'extension du protocole à 4 ou 5 cibles (incluant le nerf supra-patellaire / vaste médial et intermédiaire) améliore le taux de répondeurs."], "abstract_en": "The genicular nerves are sensory nerves that innervate the knee joint, playing a crucial role in pain transmission. Because of their small size, they are frequently underappreciated and overlooked during routine ultrasound examinations. With the advent of high-resolution ultrasound, these nerves can be visualized directly, facilitating targeted interventions. A detailed understanding of genicular nerve anatomy, ultrasound landmarks, and characteristic imaging appearances has significant clinical implications for managing knee pain. Given the high prevalence of chronic knee pain due to osteoarthritis and post-operative conditions, ultrasound-guided genicular nerve blocks and radiofrequency ablation are increasingly utilized. Traditionally, genicular nerve procedures, targeting three nerves (the superomedial, superolateral, and inferomedial genicular nerves), were performed under fluoroscopic guidance. However, ultrasound offers distinct advantages, including real-time visualization of soft tissues, the absence of radiation exposure, and precise targeting of anatomical locations using revised landmarks and Doppler signal. These advancements have enabled more comprehensive targeting of five nerves: the superomedial genicular nerve, superolateral genicular nerve, inferomedial genicular nerve, recurrent peroneal genicular nerve, and the infrapatellar branch of the saphenous nerve. Although ablation of the recurrent peroneal genicular nerve carries a risk of injury to the common peroneal nerve, potentially resulting in foot drop, precise localization through ultrasound-guidance may help mitigate this complication. This article provides a comprehensive review of genicular nerve anatomy, ultrasound techniques, and interventional approaches, emphasizing the clinical relevance of ultrasound-guided procedures for managing knee pain and diagnosing nerve pathologies.", "tags": ["Nerfs géniculés", "Échographie", "Bloc test anesthésique", "Radiofréquence", "Gonarthrose"], "pdf_file": "pdfs/PMID_42602563.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 4482, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42602563/", "doi_url": "https://doi.org/10.15557/jou.2026.0019", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13474172/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13474172/"}, {"id": "pmid-42276242", "pmid": "42276242", "pmcid": "", "doi": "10.1016/j.jvir.2026.108902", "title": "Clinical Criteria for Improved Outcomes in Patients Who Undergo Percutaneous CT-Guided Pudendal Nerve Cryoablation: A Retrospective Analysis", "title_fr": "Critères cliniques de sélection et résultats à 10 ans de la cryoablation percutanée du nerf pudendal guidée par scanner (362 procédures)", "authors_list": ["Battle W", "Garcia RM", "Li H", "Moon JT", "Manyapu S", "Behi A", "Kim J", "Huang J", "Prologo JD"], "authors_short": "Battle W, Garcia RM et al.", "journal": "Journal of vascular and interventional radiology : JVIR", "journal_short": "JVIR", "impact_factor": 2.6, "year": 2026, "month_num": 6, "month_fr": "Juin", "pub_date_fr": "Juin 2026", "volume": "37", "issue": "9", "pages": "108902", "category_id": "pudendal_cryoneurolysis", "category_label": "Cryoneurolyse du Nerf Pudendal & Névralgie Pelvi-Périnéale", "category_short": "Cryoneurolyse Nerf Pudendal", "category_color": "#0ea5e9", "modality": "Scanner Interventionnel (TDM)", "intervention_type": "Cryoneurolyse / Cryoablation Percutanée du Nerf Pudendal sous Scanner", "cochin_link": "Référence majeure pour la sélection des patients adressés en « Cryoneurolyse percutanée du nerf pudendal sous scanner (épine ischiatique / canal d'Alcock) » à l'Hôpital Cochin.", "summary_fr_short": "Plus grande série publiée sur 10 ans (*JVIR*, juin 2026, IF 2,6, 362 cryoablations TDM du nerf pudendal) : les patients réunissant la triade de sélection (facteur déclenchant identifié, douleur périnéale unilatérale systématisée et bloc diagnostique TDM positif) obtiennent 77,4 % de succès clinique (réduction moyenne de la douleur de 88,8 % chez les répondeurs) et un intervalle libre avant réintervention de 31,8 mois, avec 0 % de complication majeure SIR.", "summary_fr_detailed": "Cette étude rétrospective académique multicentrique analyse 362 procédures de cryoablation percutanée du nerf pudendal guidées par scanner réalisées entre 2014 et 2024. L'analyse porte sur la valeur prédictive d'une triade clinique prédéfinie : 1) événement causal identifiable (chirurgie, traumatisme, accouchement, compression), 2) topographie douloureuse périnéale unilatérale typique du nerf pudendal, et 3) réponse positive au bloc anesthésique diagnostique sous scanner. Lorsque les 3 critères sont réunis, le taux de réponse clinique (réduction ≥ 50 % du score NRS) atteint 77,4 % contre 36,4 % en l'absence des critères complets (p = 0,002), avec une réduction douloureuse moyenne de 69,1 % (et 88,8 % chez les répondeurs). Chez les patients nécessitant une seconde séance à distance, la durée moyenne d'efficacité avant retraitement est de 31,8 mois (> 2,5 ans), sans aucun événement indésirable majeur (SIR C-F).", "protocol_fr": "Sélection pré-procédurale stricte par bloc test scanoguidé du nerf pudendal • Patient en procubitus au scanner • Abord transglutéal postéro-latéral ciblant l'espace inter-ligamentaire (pince entre ligament sacro-épineux et ligament sacro-tubéral à l'épine ischiatique) ou le canal d'Alcock (aponévrose de l'obturateur interne) • Mise en place d'une cryosonde 17G • Double cycle de congélation (ex. 2 × 2 à 3 min séparés par décongélation passive) avec contrôle TDM de l'iceball à distance de la paroi rectale et du nerf sciatique.", "key_points_fr": ["Série de référence mondiale (362 procédures sur 10 ans dans JVIR) validant l'efficacité durable et la sécurité (0 % complication SIR C-F) de la cryoneurolyse TDM du nerf pudendal.", "La triade clinique (événement déclenchant + topographie pudendale unilatérale + bloc test TDM positif) double le taux de succès (77,4 % vs 36,4 %, p = 0,002).", "Durabilité remarquable d'une séance : délai moyen de 31,8 mois avant toute réintervention chez les répondeurs.", "Guide directement l'indication de cryoneurolyse pudendale après bloc diagnostique positif en Radiologie B à Cochin."], "abstract_en": "Purpose To evaluate whether predefined clinical selection criteria were associated with improved outcomes following computed tomography (CT)-guided pudendal nerve cryoablation. Materials and methods A retrospective review of 362 CT-guided pudendal nerve cryoablations was performed at a multisite, tertiary-care, academic center over a 10-year period (2014-2024). Among 202 unilateral procedures, 75 (37.1%) had adequate follow-up and were included in the primary analysis. Patient stratification was performed by presence of predefined selection criteria, namely, identifiable antecedent event, unilateral perineal pain consistent with pudendal distribution, and positive response to CT-guided diagnostic pudendal block. The primary endpoint was ≥50% pain reduction on a 0-10 numerical rating scale. Mean percent pain reduction, reintervention interval, and adverse events (Society of Interventional Radiology [SIR] classification) were recorded. Fischer exact test, chi-square test, and multivariate logistic regression were performed where appropriate. Significance level was set at P Results Among 75 unilateral procedures with adequate follow-up, 49 (65.3%) achieved ≥50% pain reduction. Procedures performed on patients meeting all predefined criteria (53 procedures in 33 patients) demonstrated higher response rates than those not meeting all criteria (77.4% vs 36.4%, χ 2 P = .002) and greater mean pain reduction (69.1% vs 29.5%, P Conclusions Patients who met all predefined clinical selection criteria had significantly greater positive outcomes following CT-guided pudendal nerve cryoablation compared than those who did not.", "tags": ["Cryoneurolyse", "Cryoablation", "Nerf pudendal", "Névralgie pudendale", "Bloc diagnostique", "Canal d'Alcock", "JVIR 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42276242/", "doi_url": "https://doi.org/10.1016/j.jvir.2026.108902", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.jvir.2026.108902"}, {"id": "pmid-42173356", "pmid": "42173356", "pmcid": "", "doi": "10.1016/j.jvir.2026.108858", "title": "Combination of Percutaneous Cryoablation, Screw Fixation, and Cementoplasty for Painful Pelvic Bone Metastases: A Supportive Care Approach Improving Pain, Mobility, and Quality of Life", "title_fr": "Combinaison percutanée Cryoablation + Vissage + Cimentoplastie pour les métastases osseuses pelviennes douloureuses", "authors_list": ["Grange S", "Grange R", "Stacoffe N", "Lanoiselee J", "Leroy S", "Thomas T", "Beneton A", "Boucher LM", "Pelage JP", "Gorelik N"], "authors_short": "Grange S, Grange R et al.", "journal": "Journal of vascular and interventional radiology : JVIR", "journal_short": "JVIR", "impact_factor": 2.6, "year": 2026, "month_num": 5, "month_fr": "Mai", "pub_date_fr": "Mai 2026", "volume": "37", "issue": "8", "pages": "108858", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Scanner TDM", "intervention_type": "Trithérapie : Cryo + Vissage + Ciment", "cochin_link": "Correspond exactement aux suivis post « cryo de debulking + vissage du bassin » programmés dans l'Agenda Interventionnel du Dr Thomas Lefèvre à Cochin.", "summary_fr_short": "Étude française (*JVIR*, mai 2026 — Grange, Pelage, Gorelik et al.) démontrant la faisabilité, la sécurité et le bénéfice fonctionnel majeur d'un geste combiné associant en une seule séance cryoablation tumorale, vissage percutané et cimentoplastie pour les métastases pelviennes.", "summary_fr_detailed": "Les métastases ostéolytiques du bassin (toit du cotyle, aile iliaque, sacrum) combinent douleur tumorale inflammatoire et instabilité mécanique sévère. Cette étude française évalue la stratégie 'tout-en-un' sous guidage scanner : cryoablation première pour détruire le contingent tumoral et réduire l'hypervascularisation, suivie de la mise en place de vis canulées trans-osseuses scellées par cimentoplastie PMMA. Le succès technique atteint 100 %, avec une baisse rapide de l'EVA douleur, une reprise de la marche et une amélioration significative de la qualité de vie.", "protocol_fr": "1) Cryoablation percutanée (2 cycles de congélation) pour réduction tumorale ('debulking') • 2) Décongélation complète de la loge • 3) Mise en place des broches et vis canulées dans les corridors pelviens sous TDM • 4) Injection de ciment PMMA autour des vis et dans la cavité d'ostéolyse.", "key_points_fr": ["Synergie optimale : la cryoablation assure le contrôle tumoral local tandis que le couple vis + ciment restaure immédiatement la résistance mécanique du bassin.", "Attendre le réchauffement complet de la zone cryoablatée avant d'injecter le ciment PMMA.", "Le scellement des vis par le ciment ('cement-augmented screw fixation') limite fortement le risque de migration secondaire des vis dans l'os pathologique.", "Amélioration rapide de l'autonomie à la marche et réduction de la consommation d'opioïdes dès le premier mois."], "abstract_en": "Purpose To evaluate the safety, feasibility, and early clinical outcomes of combined percutaneous cryoablation, screw fixation, and cementoplasty for painful pelvic bone metastases. Materials and methods In this monocentric retrospective study, patients with painful pelvic bone metastases underwent percutaneous image-guided cryoablation followed by screw fixation and cementoplasty under computed tomography (CT) guidance. Technical success was defined as completion of all planned procedural steps without deviation. Clinical endpoints included adverse events, mobilization, discharge timing, pain, analgesic use, and quality of life. Imaging follow-up assessed screw stability, infection, local tumor behavior, and progression to joint replacement when applicable. Results Seventeen patients were included. Technical success was achieved in all procedures. Cryoablation required a mean of 2.7 probes (SD ± 1.3), and 1.2 screws (SD ± 0.4) were implanted per procedure. Complete planned soft tissue ablation was achieved in 11 patients (64.7%), including complete combined bone and soft tissue ablation in 5 (29.4%); partial ablation/debulking was intentionally planned in the remaining 6 (35.3%). No periprocedural or early adverse events occurred. Thirteen patients (76.5%) were able to stand within 24 hours, and all within 4 days. Eight patients (47.1%) were discharged on postoperative Day 1, and 13 (76.5%) within 2 days. No patient required joint replacement during available follow-up. Median overall survival was approximately 150 days. Conclusions A combination of percutaneous cryoablation, screw fixation, and cementoplasty is feasible and safe and provides rapid early clinical benefit in selected patients with pelvic metastases. Larger comparative studies are required to confirm effectiveness and long-term joint-related outcomes.", "tags": ["Cryoablation", "Vissage du bassin", "Cimentoplastie", "Métastases pelviennes", "JVIR 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42173356/", "doi_url": "https://doi.org/10.1016/j.jvir.2026.108858", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.jvir.2026.108858"}, {"id": "pmid-42129022", "pmid": "42129022", "pmcid": "PMC13337598", "doi": "10.1245/s10434-026-19751-6", "title": "Clinical Course and Dedifferentiation of Atypical Lipomatous Tumors: A Retrospective Analysis of Surveillance and Surgical Management", "title_fr": "Évolution clinique, dédifférenciation et concordance IRM-histologie des tumeurs lipomateuses atypiques (ALT / liposarcomes bien différenciés)", "authors_list": ["Hakkesteegt SN", "Shapiro J", "Wunder JS", "Tsoi KM", "Griffin AM", "White LM", "Gladdy RA", "Verhoef C", "Grunhagen DJ", "Ferguson PC"], "authors_short": "Hakkesteegt SN, Shapiro J et al.", "journal": "Annals of surgical oncology", "journal_short": "Ann Surg Oncol", "impact_factor": 3.4, "year": 2026, "month_num": 5, "month_fr": "Mai", "pub_date_fr": "Mai 2026", "volume": "33", "issue": "8", "pages": "7616-7624", "category_id": "msk_biopsy", "category_label": "Biopsies Ostéo-Articulaires, Synoviales & Sarcomes", "category_short": "Biopsies TDM & Écho", "category_color": "#3b82f6", "modality": "IRM + Biopsie Percutanée Échoguidée / Scanoguidée (MDM2)", "intervention_type": "Biopsie Percutanée de Masse Lipomateuse Profonde", "cochin_link": "En lien direct avec les « biopsies percutanées de formation lipomateuse glutéale ou de masse de la cuisse sous échographie/scanner » réalisées à Cochin.", "summary_fr_short": "Étude de cohorte (*Annals of Surgical Oncology*, mai 2026, 183 patients : 36 en surveillance active et 147 opérés) analysant le risque de dédifférenciation (8 % en surveillance, 20 % des récidives locales) et démontrant le caractère indispensable de la biopsie percutanée ciblée dès que l'IRM montre des signes atypiques.", "summary_fr_detailed": "Les tumeurs lipomateuses atypiques (ALT / liposarcomes bien différenciés des membres et de la région glutéale, caractérisées par l'amplification de MDM2) posent le dilemme entre surveillance IRM et chirurgie d'exérèse. Sur 36 patients suivis en médiane 26 mois, 61 % ont présenté une progression dimensionnelle et 3 patients (8 %) ont développé une dédifférenciation sarcomateuse (dont 2 n'avaient eu qu'un diagnostic IRM initial sans biopsie préalable). Parmi les 147 patients opérés d'emblée, 10 % ont récidivé localement (dont 20 % sous forme de liposarcome dédifférencié). L'étude souligne que la confirmation histologique et moléculaire par biopsie percutanée ciblée sur les septas épais ou nodules non graisseux visibles en IRM est indispensable.", "protocol_fr": "Analyse IRM préalable (T1, T2 Fat-Sat, T1 Gado : recherche de septas épais > 2 mm, nodules non adipeux rehaussés, localisation profonde sous-fasciale > 5 cm) • Biopsie percutanée au trocart 14G–16G sous échographie ou scanner sans franchir un compartiment sain, en ciblant électivement les septas épaissis ou tout contingent nodulaire non graisseux • Recherche systématique d'amplification MDM2 en FISH.", "key_points_fr": ["Toute masse lipomateuse profonde (> 5 cm, sous-fasciale, cuisse ou fesse) présentant des septas épais ou un nodule non graisseux en IRM impose une microbiopsie dirigée avec recherche d'amplification MDM2.", "Le ciblage biopsique doit impérativement porter sur la zone non graisseuse ou septale la plus vascularisée pour ne pas méconnaître un contingent dédifférencié.", "Risque de dédifférenciation de 8 % sous surveillance active (médiane 26 mois) et de 2 % au total après chirurgie initiale.", "Sécurise la décision en RCP Sarcome entre surveillance IRM active et exérèse chirurgicale."], "abstract_en": "Background Atypical lipomatous tumors (ALTs) can recur locally but do not metastasize. Surgical treatment risks morbidity, recurrence, and dedifferentiation. This study assessed the outcomes of initial surveillance or surgery for patients with ALT. Methods Patients with ALT diagnosed between 2005 and 2022 were retrospectively identified from surgical and radiologic databases. Adults with primary or locally recurrent (LR) ALT confirmed by imaging, histology, or both and managed with surveillance for 12 months or longer were included in the surveillance study cohort. The primary outcome was the development of dedifferentiation during surveillance. The secondary outcomes were tumor progression, imaging-histopathology concordance, motives for surgery, and surgical outcomes. A comparison cohort included patients who had ALT treated with upfront surgery. Results The 36 patients (median age, 63 years; IQR, 52-69 years) in this study underwent surveillance for a median of 26 months (IQR, 19-54 months). Most of the tumors were primary (81%) and located in the lower extremities (78%). Tumor progression (RECIST) occurred in 22 patients (61%). Three patients (8%) experienced dedifferentiation (2 with the diagnosis by imaging alone at baseline and 1 with an LR). No dedifferentiation occurred in the remaining 33 patients (92%). Magnetic resonance imaging suggested dedifferentiation in five cases, histologically confirmed in two cases. Among 147 patients initially treated surgically for ALT, 15 (10%) had LR, with 3 (20%) of these patients experiencing recurrence as dedifferentiated liposarcoma. No disease-related metastases or deaths occurred. Conclusion Initial surveillance for ALT appears feasible for selected patients. However, surgery remains the preferred treatment for many, and the short follow-up period and small cohort size limited definitive conclusions regarding long-term dedifferentiation risk. Histologic confirmation remains essential when MRI findings are atypical.", "tags": ["Tumeur lipomateuse atypique", "Liposarcome bien différencié", "MDM2", "Biopsie parties molles", "IRM", "Ann Surg Oncol 2026"], "pdf_file": "pdfs/PMID_42129022.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 596, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42129022/", "doi_url": "https://doi.org/10.1245/s10434-026-19751-6", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13337598/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13337598/"}, {"id": "pmid-42263315", "pmid": "42263315", "pmcid": "", "doi": "", "title": "Ganglion Impar Neurolysis Enhances the Short-term Efficacy of Pudendal Nerve Pulsed Radiofrequency Treatment for Pudendal Neuralgia: A Retrospective Cohort Study", "title_fr": "La neurolyse du ganglion impar potentialise l'efficacité de la radiofréquence pulsée du nerf pudendal dans la névralgie pudendale : étude de cohorte comparative (84 patientes)", "authors_list": ["Liu Y", "Yang Y", "Li J", "Wu O", "Xie S", "Zhang T", "Feng Y"], "authors_short": "Liu Y, Yang Y et al.", "journal": "Pain physician", "journal_short": "Pain Physician", "impact_factor": 3.1, "year": 2026, "month_num": 5, "month_fr": "Mai", "pub_date_fr": "Mai 2026", "volume": "29", "issue": "3", "pages": "289-297", "category_id": "pudendal_cryoneurolysis", "category_label": "Cryoneurolyse du Nerf Pudendal & Névralgie Pelvi-Périnéale", "category_short": "Cryoneurolyse Nerf Pudendal", "category_color": "#0ea5e9", "modality": "Scanner TDM / Fluoroscopie Interventionnelle", "intervention_type": "Traitement Combiné Nerf Pudendal + Neurolyse du Ganglion Impar", "cochin_link": "Appuie les gestes combinés « Traitement du nerf pudendal + neurolyse du ganglion impar » réalisés pour les douleurs périnéales mixtes somatiques et sympathiques à Cochin.", "summary_fr_short": "Étude de cohorte rétrospective comparative (*Pain Physician*, 2026, IF 3,1, 84 patientes) comparant le traitement isolé du nerf pudendal par radiofréquence pulsée (PRF, n = 40) à l'association PRF du nerf pudendal + neurolyse du ganglion impar (PRF + GIN, n = 44) : à 6 mois, le groupe combiné obtient une EVA significativement plus basse (2,09 vs 3,81, p < 0,05), un taux d'amélioration globale supérieur (73,7 % vs 56,1 %, p < 0,05) et une réduction marquée des scores d'anxiété-dépression (HADS) et de catastrophisme (PCS), sans complication.", "summary_fr_detailed": "L'efficacité parfois incomplète des gestes ciblant uniquement le tronc du nerf pudendal s'explique par l'intrication fréquente d'une sensibilisation sympathique pelvi-périnéale relayée par le ganglion impar (ganglion de Walther, terminaison impaire de la chaîne sympathique paravertébrale en avant de la jonction sacro-coccygienne). Sur 84 patientes suivies 6 mois, l'adjonction d'une neurolyse du ganglion impar au geste pudendal améliore significativement le contrôle douloureux à 6 mois (EVA moyenne 2,09 ± 1,38 vs 3,81 ± 1,85, p < 0,05 ; amélioration globale de la douleur de 73,7 % vs 56,1 %) ainsi que le retentissement émotionnel (HADS-A : 3,91 vs 6,54 ; PCS : 12,16 vs 19,52, p < 0,05), sans effet indésirable grave.", "protocol_fr": "Patient en procubitus • Temps 1 : Ciblage du nerf pudendal à l'épine sciatique / canal d'Alcock (stimulation sensitive 50 Hz < 0,5 V reproduisant la douleur périnéale, puis traitement pudendal par PRF ou cryoneurolyse) • Temps 2 (si composante brûlante périnéale postérieure/médiane ou hyperpathie sympathique) : Abord trans-discale sacro-coccygien ou paracéphalique coccygien du ganglion impar avec opacification rétro-rectale en « virgule » avant neurolyse.", "key_points_fr": ["Démontre la synergie anatomique et clinique entre le ciblage somatique (nerf pudendal) et sympathique (ganglion impar) dans la névralgie pudendale.", "Gain significatif à 6 mois sur l'EVA (2,09 vs 3,81) et sur le taux d'amélioration ressentie (73,7 % vs 56,1 %).", "Aucune complication sphinctérienne ou rectale grâce au contrôle d'imagerie en procubitus."], "abstract_en": "Background Pudendal neuralgia (PN) lacks specific treatments and severely affects patients' quality of life. Although pudendal nerve pulsed radiofrequency (PRF) can alleviate symptoms, its overall efficacy is not satisfactory. Ganglion impar neurolysis (GIN) has been widely employed for perineal pain management. We hypothesize that combining PRF with GIN may enhance therapeutic outcomes for PN compared to PRF monotherapy. To the best of our knowledge, no relevant reports have been found. Objective To assess whether GIN improves PRF treatment efficacy for PN. Study design A retrospective cohort study. Setting This is a single-center retrospective study conducted at the Department of Pain Medicine, Peking University People's Hospital in Beijing, China. Methods We conducted a retrospective analysis of 84 women patients with PN treated from January 2020 through February 2024. The patients were divided into 2 groups: PRF Group (n = 40) received only pudendal nerve PRF; PRF + GIN Group (n = 44) received PRF combined with GIN. We recorded the posttreatment differences in Visual Analog Scale (VAS) scores, Overall Improvement in Pain (OIP) values, Hospital Anxiety and Depression Scales scores (anxiety: HADS-A; depression: HADS-D), and Pain Catastrophizing Scale scores (PCS) of the 2 groups at time points up to posttreatment month 6. Results At one, 2, 3, and 6 months posttreatment, the VAS scores in both groups were lower than pretreatment levels (P Limitations This single-center study has a small sample size, a short follow-up period, and lacks patients who are men. Conclusions GIN enhances short-term pudendal nerve PRF efficacy for PN, with no significant adverse reactions.", "tags": ["Nerf pudendal", "Ganglion impar", "Névralgie pudendale", "Neurolyse combinée", "Radiofréquence pulsée", "Pain Physician 2026"], "pdf_file": "pdfs/PMID_42263315.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1148, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42263315/", "doi_url": "https://pubmed.ncbi.nlm.nih.gov/42263315/", "pmc_url": "", "article_url": "https://pubmed.ncbi.nlm.nih.gov/42263315/"}, {"id": "pmid-41063397", "pmid": "41063397", "pmcid": "", "doi": "10.1093/pm/pnaf140", "title": "Efficacy and safety of genicular nerve ablation techniques for knee osteoarthritis: a systematic review and meta-analysis of sham-controlled randomized trials", "title_fr": "Efficacité et sécurité des techniques d'ablation des nerfs géniculés dans la gonarthrose : revue systématique et méta-analyse des essais randomisés contrôlés versus sham", "authors_list": ["Barreto RB", "Barreto AJ", "do Nascimento ALM", "Carvalho DMB", "Queiroz B"], "authors_short": "Barreto RB, Barreto AJ et al.", "journal": "Pain medicine (Malden, Mass.)", "journal_short": "Pain Med", "impact_factor": 2.9, "year": 2026, "month_num": 4, "month_fr": "Avr.", "pub_date_fr": "Avr. 2026", "volume": "27", "issue": "4", "pages": "449-461", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Échographie + Fluoroscopie / TDM", "intervention_type": "Radiofréquence & Cryoneurolyse des Nerfs Géniculés", "cochin_link": "Correspond directement aux séances de test anesthésique sous écho + radiofréquence/cryoneurolyse des nerfs géniculés pour gonarthrose à Cochin.", "summary_fr_short": "Méta-analyse d'essais randomisés contrôlés contre procédure fictive (*Pain Medicine*, avr. 2026, 8 ECR, 627 patients) confirmant l'efficacité antalgique à 12 semaines et fonctionnelle (WOMAC) à 24 semaines de la neurolyse des nerfs géniculés (radiofréquence et cryoneurolyse) dans la gonarthrose réfractaire.", "summary_fr_detailed": "Cette revue systématique avec analyse séquentielle des essais (TSA) a inclus exclusivement les essais randomisés contrôlés contre procédure sham (8 ECR, n = 627 patients) évaluant la radiofréquence (monopolaire conventionnelle, refroidie ou bipolaire) et la cryoneurolyse des nerfs géniculés chez des adultes souffrant de gonarthrose symptomatique inéligibles à la prothèse. Par rapport au groupe sham, les techniques ablatives réduisent significativement la douleur à 12 semaines (différence moyenne MD -1,65 ; IC 95 % [-2,57 ; -0,74]) et améliorent le score fonctionnel WOMAC (MD -11,37 ; IC 95 % [-18,83 ; -3,91]). L'analyse séquentielle (TSA) confirme le caractère concluant du bénéfice antalgique à 3 mois et fonctionnel à 6 mois, sans aucun événement indésirable grave rapporté.", "protocol_fr": "Repérage combiné échographique et fluoroscopique/TDM des artères et nerfs géniculés supéro-médial (SMGN), supéro-latéral (SLGN) et inféro-médial (IMGN) • Test de stimulation sensitive/motrice • Thermocoagulation par radiofréquence conventionnelle (80 °C, 90 s) ou refroidie, ou cryoneurolyse percutanée.", "key_points_fr": ["Haut niveau de preuve (méta-analyse de 8 essais randomisés contrôlés contre sham, 627 patients) validé par Trial Sequential Analysis (TSA).", "Réduction significative de l'EVA douloureuse à 12 semaines (MD -1,65 point) et amélioration fonctionnelle WOMAC durable jusqu'à 24 semaines (MD -11,37 points).", "Excellent profil de sécurité : aucun événement indésirable grave rapporté sur les 627 patients.", "La radiofréquence monopolaire conventionnelle affiche le rapport efficacité/coût le plus robuste en analyse de sous-groupe."], "abstract_en": "Objective To evaluate the efficacy and safety of genicular neurolysis techniques, including radiofrequency ablation (RFA) and cryoneurolysis, versus sham procedures in adults with knee osteoarthritis (OA) ineligible for arthroplasty. Methods This systematic review and meta-analysis included randomized controlled trials (RCTs) comparing cooled, monopolar, or bipolar RFA, or cryoneurolysis, to sham treatment in adults with symptomatic knee OA. Studies with pulsed RFA, active comparators, or lacking pain or function outcomes were excluded. PubMed, Embase, and Cochrane CENTRAL were searched from inception to April 15, 2025, without language restriction. Risk of bias was assessed using the Cochrane RoB 2 tool. Random-effects meta-analysis calculated mean differences (MD) with 95% confidence intervals (CI). Heterogeneity was quantified with I2, and certainty of evidence was rated using GRADE. Trial Sequential Analysis (TSA) assessed conclusiveness. Results Eight RCTs (n = 627) met eligibility criteria. Compared with sham, ablative techniques significantly reduced pain at 12 weeks (MD -1.65; 95% CI, -2.57 to -0.74; I2 = 83%) and improved WOMAC function scores (MD -11.37; 95% CI, -18.83 to -3.91; I2 = 91%). Subgroup analysis favored conventional monopolar RFA over other modalities. TSA confirmed conclusive benefits for pain at 12 weeks and function at 24 weeks. No serious adverse events were reported. Limitations include high heterogeneity, variable protocols, and limited long-term data. Conclusions Genicular neurolysis, particularly conventional monopolar RFA, provides clinically meaningful pain and functional improvement in knee OA with a favorable safety profile. Standardization of techniques and further trials are needed to confirm long-term outcomes. Registration PROSPERO CRD420251044248.", "tags": ["Nerfs géniculés", "Gonarthrose", "Radiofréquence", "Cryoneurolyse", "Méta-analyse ECR sham"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41063397/", "doi_url": "https://doi.org/10.1093/pm/pnaf140", "pmc_url": "", "article_url": "https://doi.org/10.1093/pm/pnaf140"}, {"id": "pmid-42182575", "pmid": "42182575", "pmcid": "PMC13195346", "doi": "10.1016/j.bas.2026.106062", "title": "Treatment outcomes for cluneal neuropathy: a systematic review and meta-analysis", "title_fr": "Résultats thérapeutiques dans les neuropathies clunéales (nerfs clunéaux supérieur et moyen) : revue systématique et méta-analyse (628 patients)", "authors_list": ["Catalano K", "Andereggen L", "Schubert GA", "Bruder M", "Jost JN"], "authors_short": "Catalano K, Andereggen L et al.", "journal": "Brain & spine", "journal_short": "Brain Spine", "impact_factor": 1.9, "year": 2026, "month_num": 4, "month_fr": "Avr.", "pub_date_fr": "Avr. 2026", "volume": "6", "issue": "", "pages": "106062", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Scanner TDM / Échographie / Fluoroscopie", "intervention_type": "Neurolyse (Radiofréquence / Cryoneurolyse) & Infiltration du Nerf Clunéal", "cochin_link": "Directement lié aux nouvelles procédures de « cryoneurolyse percutanée du nerf clunéal » inscrites dans l'Agenda Interventionnel de Cochin.", "summary_fr_short": "Revue systématique et méta-analyse (*Brain & Spine*, avr. 2026, 26 bras thérapeutiques, 628 patients) démontrant un taux global de répondeurs (réduction douloureuse ≥ 50 %) de 78,3 % à ≥ 3 mois et de 82,9 % à ≥ 6 mois après traitement ciblé des névralgies clunéales supérieure et moyenne.", "summary_fr_detailed": "L'entrapment des nerfs clunéaux supérieur (franchissant la crête iliaque à travers l'orifice ostéo-aponévrotique thoraco-lombaire, 6 à 8 cm de la ligne médiane) ou moyen (en regard du ligament sacro-iliaque postérieur long) est une cause fréquente mais sous-diagnostiquée de lombalgie basse et de fessalgie pseudo-radiculaire. Sur 628 patients inclus, le taux poolé de succès clinique (baisse de l'EVA ≥ 50 %) atteint 75,1 % (IC 95 % : 62,1–84,7 %) pour l'ablation percutanée par radiofréquence/neurolyse, 72,4 % (IC 95 % : 65,9–78,1 %) pour les infiltrations ciblées, 80,1 % pour la neurostimulation périphérique et 93,1 % pour la décompression chirurgicale.", "protocol_fr": "Repérage TDM ou échographique de la crête iliaque postérieure à 6–8 cm de la ligne médiane (incisure clunéale / tunnel ostéo-fibreux du fascia thoraco-lombaire pour le nerf clunéal supérieur ; gouttière sacro-iliaque postérieure entre EIPS et S3 pour le nerf clunéal moyen) • Bloc test anesthésique diagnostique préalable (> 50 % de soulagement) • Cryoneurolyse percutanée (2 cycles de congélation) ou radiofréquence sous AL.", "key_points_fr": ["Taux global de répondeurs élevé dans les névralgies clunéales : 78,3 % à ≥ 3 mois et 82,9 % à ≥ 6 mois (628 patients).", "L'ablation percutanée (RFA / neurolyse thermique) obtient 75,1 % de succès durable après bloc diagnostique positif.", "Cible anatomique précise : franchissement de la crête iliaque postéro-supérieure (6–8 cm de la ligne médiane) pour le nerf clunéal supérieur.", "Justifie pleinement l'intégration du bloc test et de la cryoneurolyse du nerf clunéal dans les lombalgies/fessalgies réfractaires à Cochin."], "abstract_en": "Background Cluneal nerve entrapment is an increasingly recognized but often overlooked cause of chronic low back pain. Various treatment strategies have been described, including surgical decompression, injection therapy, radiofrequency ablation (RFA), and peripheral nerve stimulation (PNS). However, pooled evidence on treatment outcomes remains limited. Objective This systematic review and meta-analysis aimed to evaluate pooled responder rates following different treatment modalities for cluneal nerve-related pain. Methods A systematic review and meta-analysis was performed of studies reporting dichotomous responder outcomes after treatment of superior or middle cluneal nerve entrapment. Responder status was defined as ≥50% pain reduction or study-defined clinical improvement. Random-effects meta-analysis of proportions with logit transformation was used to pool responder rates. The primary analysis included treatment arms with follow-up of ≥3 months, and a predefined sensitivity analysis was restricted to studies with follow-up of ≥6 months. Subgroup analyses were performed by treatment modality and by surgical versus non-surgical treatment strategy. Results A total of 26 treatment arms including 628 patients were analyzed. The pooled responder rate was 78.3% (95% CI 72.9-82.9) at ≥3 months and 82.9% (95% CI 75.3-88.6) at ≥6 months. Stratified by treatment modality, pooled responder rates were 93.1% (95% CI 84.9-97.0) for surgical decompression, 72.4% (95% CI 65.9-78.1) for injection therapy, 75.1% (95% CI 62.1-84.7) for radiofrequency ablation, and 80.1% (95% CI 58.5-92.0) for peripheral nerve stimulation. Conclusion Targeted treatment of cluneal nerve entrapment was associated with high pooled responder rates at both ≥3 and ≥ 6 months of follow-up. Surgical decompression was associated with the highest pooled responder proportion; however, differences between treatment modalities should be interpreted cautiously given the predominantly observational, non-comparative nature of the available evidence, heterogeneity in diagnostic criteria and outcome definitions, and the potential for confounding by indication. Prospective comparative studies using standardized diagnostic and outcome measures are needed.", "tags": ["Nerf clunéal", "Cryoneurolyse", "Radiofréquence", "Lombalgie", "Fessalgie", "Méta-analyse 2026"], "pdf_file": "pdfs/PMID_42182575.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 3626, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42182575/", "doi_url": "https://doi.org/10.1016/j.bas.2026.106062", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13195346/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13195346/"}, {"id": "pmid-41999357", "pmid": "41999357", "pmcid": "", "doi": "10.1177/10499091261442199", "title": "Evaluation of CT-Guided Pudendal Nerve Cryoneurolysis for the Treatment of Refractory Pelvic Pain", "title_fr": "Évaluation de la cryoneurolyse du nerf pudendal guidée par scanner dans le traitement des douleurs pelviennes réfractaires (oncologiques et non oncologiques)", "authors_list": ["Young S", "Gunkan A", "Struycken L", "Placek S", "Abramyan A", "De Martini IV", "Hannallah J", "Woodhead G", "Goldberg D"], "authors_short": "Young S, Gunkan A et al.", "journal": "The American journal of hospice & palliative care", "journal_short": "Am J Hosp Palliat Care", "impact_factor": 1.9, "year": 2026, "month_num": 4, "month_fr": "Avr.", "pub_date_fr": "Avr. 2026", "volume": "", "issue": "", "pages": "10499091261442199", "category_id": "pudendal_cryoneurolysis", "category_label": "Cryoneurolyse du Nerf Pudendal & Névralgie Pelvi-Périnéale", "category_short": "Cryoneurolyse Nerf Pudendal", "category_color": "#0ea5e9", "modality": "Scanner TDM", "intervention_type": "Cryoneurolyse Percutanée du Nerf Pudendal", "cochin_link": "Complète l'arsenal de cryoneurolyse percutanée sous scanner (Morton, nerfs intercostaux, douleurs pelviennes et périnéales oncologiques) réalisé à Cochin.", "summary_fr_short": "Étude clinique rétrospective (*Am J Hosp Palliat Care*, avr. 2026, 30 patients) démontrant une réduction hautement significative de l'EVA douloureuse (jusqu'à 6 mois, p < 0,001) et de la consommation d'opioïdes après cryoneurolyse TDM du nerf pudendal, sans aucune complication.", "summary_fr_detailed": "Sur 30 patients consécutifs souffrant de névralgie pudendale ou de douleur pelvienne réfractaire d'origine tumorale ou bénigne, la cryoneurolyse guidée par scanner du nerf pudendal (au niveau de l'épine sciatique / canal d'Alcock) a permis une amélioration significative du score EVA à 1 semaine (3,9 ± 2,1, p < 0,001), 1 mois (4,6 ± 2,3, p < 0,001), 3 mois (3,9 ± 2,2, p < 0,001) et 6 mois (p < 0,001). La consommation quotidienne d'équivalents morphiniques (ME) a significativement diminué dès la 1re semaine et à 1 mois (de 30 mg à 17,5 mg, p = 0,032). L'efficacité antalgique était comparable entre les cohortes oncologique et non oncologique, avec 0 % d'effet indésirable.", "protocol_fr": "Patient en procubitus au scanner • Repérage TDM du ligament sacro-épineux, du ligament sacro-tubéral et du canal d'Alcock (épine ischiatique) • Positionnement d'une cryosonde fine au contact du tronc du nerf pudendal • Double cycle de congélation (2 × 2 min avec décongélation intermédiaire) sous anesthésie locale.", "key_points_fr": ["Soulagement antalgique rapide dès J7 et durable jusqu'à 6 mois (p < 0,001) chez 30 patients atteints de douleurs pelviennes réfractaires.", "Épargne morphinique significative à 1 semaine et 1 mois post-procédure (p = 0,032).", "Efficacité identique dans les douleurs pelviennes oncologiques (envahissement sacré/pelvien) et les névralgies pudendales non malignes.", "Sécurité remarquable sous guidage scanner (aucun événement indésirable rapporté)."], "abstract_en": "BackgroundPelvic pain caused by malignant and non-malignant etiologies can be treated by cryoneurolysis of the pudendal nerve(s). The purpose of this report is to assess the efficacy and safety of CT-guided pudendal nerve cryoneurolysis. Additionally, treatment outcomes were compared between malignant and non-malignant pelvic pain etiologies.MethodsPatients who underwent CT-guided pudendal nerve cryoneurolysis for intractable pelvic pain were retrospectively reviewed. Pre-procedural and post-procedural pain scores, supplemental analgesic use, and complications were assessed.ResultsA total of 30 patients underwent CT-guided pudendal nerve cryoneurolysis. Pre-treatment Visual Analog Scale (VAS) pain scores were significantly improved at 1 week (3.9 ± 2.1, P P P P P = 0.04) and 1 month (17.5 (range:0-216), P = 0.032) post-treatment. Both malignant and non-malignant cohorts demonstrated significant improvement of VAS score at all time points; however, there was no significant difference in numeric improvement or percentage improvement in VAS score between the 2 cohorts. No adverse events were observed.ConclusionCT-guided pudendal nerve cryoneurolysis is an effective and safe treatment modality in patients with refractory pelvic pain from both malignant and non-malignant etiologies.", "tags": ["Cryoneurolyse", "Nerf pudendal", "Douleur pelvienne", "Soins palliatifs", "Guidage scanner"], "pdf_file": "pdfs/PMID_41999357.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 678, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41999357/", "doi_url": "https://doi.org/10.1177/10499091261442199", "pmc_url": "", "article_url": "https://doi.org/10.1177/10499091261442199"}, {"id": "pmid-41867110", "pmid": "41867110", "pmcid": "", "doi": "10.1080/02656736.2026.2642925", "title": "Imaging-derived risk score predicts pain recurrence in osteoid osteoma patients undergoing radiofrequency ablation", "title_fr": "Score de risque IRM dynamique (DCE-MRI 3T) prédictif de récidive douloureuse après radiofréquence d'ostéome ostéoïde", "authors_list": ["Pöhler GH", "Patzelt P", "Schneider K", "Deventer N", "Hülskamp M", "Gosheger G", "Schindler P", "Köhler M", "Raschke M", "Heindel W", "Al-Itaibi R", "Masthoff M"], "authors_short": "Pöhler GH, Patzelt P et al.", "journal": "International journal of hyperthermia : the official journal of European Society for Hyperthermic Oncology, North American Hyperthermia Group", "journal_short": "Int J Hyperthermia", "impact_factor": 3.1, "year": 2026, "month_num": 3, "month_fr": "Mars", "pub_date_fr": "Mars 2026", "volume": "43", "issue": "1", "pages": "2642925", "category_id": "ablation_benign", "category_label": "Ablation Thermique des Tumeurs Osseuses Bénignes", "category_short": "RF & Cryo (OO / Chondroblastome / TCG)", "category_color": "#f97316", "modality": "IRM Dynamique 3T (DCE-MRI) + Scanner TDM", "intervention_type": "Ablation par Radiofréquence (RFA)", "cochin_link": "Correspond exactement au couple « IRM dynamique protocole ostéome ostéoïde » + « Thermocoagulation par radiofréquence sous TDM » pratiqué à Cochin.", "summary_fr_short": "Étude rétrospective sur 122 patients (*Int J Hyperthermia*, mars 2026) démontrant que les paramètres quantitatifs de l'IRM dynamique injectée 3T (DCE-MRI) pré-opératoire et la topographie extracorticale du nidus prédisent le risque de récidive douloureuse après radiofréquence d'ostéome ostéoïde.", "summary_fr_detailed": "Sur 122 patients (âge médian 19 ans) ayant bénéficié d'une IRM dynamique 3T (DCE-MRI) avant thermoablation par radiofréquence guidée par scanner, une récidive douloureuse (EVA > 4/10 après > 2 semaines) a été observée chez 22 patients (18 %). Les facteurs prédictifs indépendants de récidive étaient une localisation extracorticale/périostée du nidus (HR 6,5 ; p < 0,001), un temps jusqu'au pic (TTP) allongé > 40 s (HR 6,0 ; p = 0,016), un rehaussement relatif maximal (MRE) < 300 % (HR 0,3 ; p = 0,042) et une pente de wash-in réduite (HR 0,1 ; p = 0,03). Dans le sous-groupe des nidus extracorticaux présentant un TTP > 40 s et un MRE < 300 %, la probabilité de récidive atteignait ≥ 55 %, justifiant d'adapter le protocole d'ablation.", "protocol_fr": "IRM pré-thérapeutique 3T avec séquence dynamique T1 injectée (DCE-MRI : mesure du Time-To-Peak [TTP], Maximum Relative Enhancement [MRE] et Wash-in rate) + TDM en coupes fines • Si nidus extracortical avec TTP > 40 s et MRE < 300 % : allonger le temps de radiofréquence ou réaliser deux positions d'électrode chevauchantes.", "key_points_fr": ["La localisation extracorticale du nidus multiplie par 6,5 le risque de récidive douloureuse après RF standard (p < 0,001).", "Un rehaussement lent et moins intense en DCE-MRI 3T (TTP > 40 s et MRE < 300 %) reflète un nidus moins vascularisé ou scléreux plus résistant à la conduction thermique.", "En présence d'un nidus extracortical avec TTP > 40 s et MRE < 300 %, le risque de récidive dépasse 55 %.", "Permet de personnaliser le geste à Cochin dès l'IRM dynamique pré-RF (durée d'ablation prolongée, température accrue ou cryoablation)."], "abstract_en": "Background Pain recurrence following regular radiofrequency ablation (RFA) in osteoid osteoma (OO) remains incompletely understood, yet impacts quality of life. Purpose To detect predictive imaging parameters in OO with symptomatic recurrence. Material and methods This retrospective, monocentric study included 122 OO patients [median age 19 (16; 27) years, male 78%] January 2010 to May 2024, which underwent T1-weighted dynamic contrast-enhanced magnetic resonance imaging (DCE-MRI) (3T) before CT-guided RFA. Pain recurrence was defined as visual analogue scale increase >4/10 occurring >2 weeks post-intervention (22 (18%) patients). Nidus was categorized intra-/extracortical. DCE-MRI relative/maximum (relative) enhancement (M(R)E) (%), time to peak (TTP) (s), wash-in/out rate (s -1 ), brevity of enhancement (s) were compared by Wilcoxon rank-sum test. Hazard ratios (HR), multivariate cox proportional hazard regression, receiver operating characteristics and Bayesian were performed. Results Extracortical nidus occurred more frequently in patients with recurrence (14%) compared to intracortical nidus (5%, p p = 0.038], higher TTP [47.1 (34.5-59.5) vs 32.3 (24.7-46.7); p = 0.002], lower wash-in rate [38.9 (0-107.5) vs. 83.7(30.5-159.7); p = 0.028]. ME [HR 0.2 (95% CI: 0.06, 0.04); p p = 0.042], TTP [HR 6 (1.4, 25.4); p = 0.016], wash-in rate [HR 0.1(0.02, 0.8); p = 0.03] were predictors of recurrence. Extracortical nidus [HR 6.5 (2.1, 19.7); p 40 s, MRE Conclusion Imaging-based risk stratification enables personalized treatment approaches for osteoid osteoma patients, who may benefit from alternative ablation protocols such as extended ablation time, higher temperatures.", "tags": ["Ostéome ostéoïde", "IRM dynamique DCE-MRI", "Radiofréquence", "Facteurs prédictifs", "Récidive"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41867110/", "doi_url": "https://doi.org/10.1080/02656736.2026.2642925", "pmc_url": "", "article_url": "https://doi.org/10.1080/02656736.2026.2642925"}, {"id": "pmid-41876692", "pmid": "41876692", "pmcid": "", "doi": "10.1007/s00270-026-04412-8", "title": "Radiation Dose, Outcomes, and Trends of CT-Guided Osteoid Osteoma Ablation in Pediatric Patients: An Analysis of the Registry of the German Society for Interventional Radiology and Minimally Invasive Therapy", "title_fr": "Dose d'irradiation, résultats cliniques et tendances de l'ablation d'ostéome ostéoïde pédiatrique guidée par scanner : analyse du registre DeGIR (166 patients)", "authors_list": ["Wintergerst C", "Doppler M", "Wirtz S", "Stein T", "Schürmann T", "Vogt K", "Can E", "Nadjiri J", "Uller W"], "authors_short": "Wintergerst C, Doppler M et al.", "journal": "Cardiovascular and interventional radiology", "journal_short": "CVIR", "impact_factor": 2.8, "year": 2026, "month_num": 3, "month_fr": "Mars", "pub_date_fr": "Mars 2026", "volume": "", "issue": "", "pages": "", "category_id": "ablation_benign", "category_label": "Ablation Thermique des Tumeurs Osseuses Bénignes", "category_short": "RF & Cryo (OO / Chondroblastome / TCG)", "category_color": "#f97316", "modality": "Scanner TDM (Protocole Basse Dose Pédiatrique)", "intervention_type": "Radiofréquence (RFA) / Micro-ondes (MWA) / Cryoablation", "cochin_link": "Fournit les niveaux de référence diagnostiques et interventionnels (DLP) pour les thermoablations d'ostéomes ostéoïdes chez l'adolescent et le jeune adulte à Cochin.", "summary_fr_short": "Analyse multicentrique du registre allemand DeGIR (*CVIR*, mars 2026, 166 patients ≤ 18 ans) établissant les valeurs de référence de dose d'irradiation (DLP médian 132 mGy·cm) et confirmant un succès technique de 99,4 % pour l'ablation TDM d'ostéome ostéoïde.", "summary_fr_detailed": "Sur 166 patients pédiatriques (âge moyen 13,5 ans) traités par ablation percutanée sous scanner entre 2019 et 2024, la radiofréquence représentait 71,1 % des gestes, les micro-ondes 26,5 % et la cryoablation 1,8 %. Le Produit Dose-Longueur (DLP) médian global était de 132 mGy·cm (IQR 53–314), avec une médiane de 124 mGy·cm (IQR 51–297) pour le squelette appendiculaire et de 222 mGy·cm (IQR 64,5–485) pour le squelette axial. Le taux de succès technique atteignait 99,4 % avec un taux de complications mineures de seulement 1,81 %.", "protocol_fr": "Hélice de repérage ultra-basse dose centrée sur le nidus (collimation réduite, bas kilovoltage 80–100 kVp, itération dédiée) • Guidage séquentiel ('step-and-shoot') limité à quelques coupes millimétriques • Objectif dosimétrique : DLP < 150 mGy·cm sur les membres et < 250 mGy·cm sur le rachis/bassin.", "key_points_fr": ["Établit les premiers repères dosimétriques multicentriques (benchmarks DLP Q1–Q3) pour l'ablation TDM d'ostéome ostéoïde.", "DLP médian très contenu : 124 mGy·cm sur les membres et 222 mGy·cm sur le squelette axial.", "Succès technique de 99,4 % et taux de complication très bas (1,81 %), confirmant la RFA comme gold standard (71 % des procédures).", "Référentiel directement utilisable pour l'audit dosimétrique et l'optimisation ALARA au scanner interventionnel."], "abstract_en": "Purpose This study evaluated radiation dose parameters, clinical outcomes, and national trends in conventional CT-guided pediatric osteoid osteoma ablation. Materials and methods We retrospectively analyzed data from the German Society for Interventional Radiology and Minimally Invasive Therapy (DeGIR) registry (2019-2024). Patients ≤ 18 years with available Dose Length Product were included. Radiation dose, clinical outcome, and ablation modality were assessed. Benchmarks were defined using percentiles stratified by age and anatomical location. Results A total of 166 pediatric patients (mean age 13.45 years; 59 female) were included. The median Dose Length Product was 132.00 (Q1: 53, Q3: 314) mGycm, 222.00 (Q1: 64.50, Q3: 485) mGycm for axial skeleton, and 124.00 (Q1: 51, Q3: 297) mGycm for extremity ablations. Technical success was 99.4% (partial technical success 0.60%), early clinical success was 58.43% (39.76% not assessable, 1.81% no improvement), and the complication rate was 1.81%. After additional age stratification and exclusion of very small groups (n Conclusion This multicenter analysis provides proposed pediatric benchmarks for radiation exposure during conventional CT-guided osteoid osteoma ablation, which demonstrated excellent safety and technical success, supporting its role as standard therapy.", "tags": ["Ostéome ostéoïde", "Radioprotection", "DLP", "Radiofréquence", "Registre DeGIR", "CVIR 2026"], "pdf_file": "pdfs/PMID_41876692.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1114, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41876692/", "doi_url": "https://doi.org/10.1007/s00270-026-04412-8", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00270-026-04412-8"}, {"id": "pmid-41857607", "pmid": "41857607", "pmcid": "PMC13047836", "doi": "10.1186/s13018-026-06792-6", "title": "The best solution is the simplest: advances in surgical and minimally invasive management of aneurysmal and simple bone cysts", "title_fr": "Avancées dans la prise en charge mini-invasive et chirurgicale des kystes osseux anévrismaux (KOA) et des kystes osseux essentiels (KOE)", "authors_list": ["Alaseem A", "Addar A", "Alanezi M", "Alshayhan F", "Albishi W", "Alshaygy I"], "authors_short": "Alaseem A, Addar A et al.", "journal": "Journal of orthopaedic surgery and research", "journal_short": "J Orthop Surg Res", "impact_factor": 2.8, "year": 2026, "month_num": 3, "month_fr": "Mars", "pub_date_fr": "Mars 2026", "volume": "21", "issue": "1", "pages": "232", "category_id": "cyst_sclerotherapy", "category_label": "Alcoolisation & Sclérothérapie des Kystes Osseux", "category_short": "Alcoolisation KOA / KOE", "category_color": "#10b981", "modality": "Scanner TDM / Fluoroscopie / Échographie", "intervention_type": "Sclérothérapie Percutanée (Alcool / Polidocanol / Doxycycline) & Embolisation", "cochin_link": "Directement lié aux séances d'« alcoolisation percutanée du kyste osseux anévrismal de l'humérus droit » et de « kyste essentiel de l'aile iliaque (+/- cimentoplastie) » programmées à Cochin.", "summary_fr_short": "Revue de synthèse (*J Orthop Surg Res*, mars 2026) comparant l'efficacité, le taux de récidive et la sécurité des approches mini-invasives (sclérothérapie percutanée, embolisation artérielle sélective, ablation guidée par l'image) face au curetage chirurgical dans les KOA et KOE.", "summary_fr_detailed": "Cette mise au point analyse l'évolution du paradigme thérapeutique des kystes osseux anévrismaux (KOA) et essentiels (KOE). Dans les KOA, les modalités mini-invasives — au premier rang desquelles la sclérothérapie percutanée répétée (éthanol absolu, polidocanol, mousse de doxycycline), l'embolisation artérielle sélective et la cryoablation/radiofréquence — obtiennent des taux élevés d'ossification corticale, de soulagement douloureux et de récupération fonctionnelle, avec une morbidité nettement inférieure au curetage chirurgical ou à la résection en bloc. Dans les KOE symptomatiques ou à risque fracturaire, l'injection percutanée sclérosante associée si besoin à une stabilisation ou un comblement permet une consolidation fiable.", "protocol_fr": "Ponction-aspiration sous guidage TDM et contrôle fluoroscopique avec kystographie préalable (éliminer un drainage veineux rapide avant injection d'éthanol) • Sclérothérapie percutanée à l'alcool absolu (ou polidocanol/doxycycline) avec temps de contact contrôlé puis réaspiration/rinçage • Cimentoplastie ou embrochage associé si risque fracturaire mécanique élevé.", "key_points_fr": ["La sclérothérapie percutanée est désormais établie comme traitement de première intention de nombreux KOA et KOE grâce à son faible taux de complications.", "Taux élevés de ré-ossification progressive et de contrôle douloureux sans les séquelles fonctionnelles du curetage ouvert.", "Rôle complémentaire de la cryoablation et de l'embolisation sélective pour les KOA volumineux, axiaux ou récidivants.", "Suivi TDM séquentiel à 3, 6 et 12 mois évaluant l'épaississement cortical et la trabéculation intrakystique (critères de Capanna)."], "abstract_en": "Aneurysmal bone cysts (ABCs) and simple bone cysts (SBCs) are benign osseous lesions predominantly affecting children and adolescents, typically presenting with pain, deformity, or pathologic fracture. Despite their frequency, optimal management remains debated. This review synthesizes current evidence on therapeutic strategies, efficacy, recurrence, and safety. For ABCs, intralesional curettage remains the standard surgical approach, though recurrence rates vary and are reduced with adjuvants such as high-speed burring, cryotherapy, or cementation. En bloc resection offers the lowest recurrence; however, it is restricted by procedural morbidity and poor functional outcomes. Minimally invasive modalities, including sclerotherapy, selective arterial embolization, endoscopic curettage, and image-guided ablation, consistently achieve high rates of healing, pain relief, and functional recovery, often with fewer complications. Management of SBCs ranges from observation to intervention in symptomatic or unstable lesions. Elastic stable intramedullary nailing (ESIN) provides both decompression and structural stability, with high healing rates. Overall, advances in minimally invasive and biologic therapies are reshaping treatment paradigms, yet standardized outcome measures and head-to-head comparative trials remain needed.", "tags": ["Kyste osseux anévrismal", "Kyste osseux essentiel", "Sclérothérapie", "Alcoolisation", "Humérus", "J Orthop Surg Res 2026"], "pdf_file": "pdfs/PMID_41857607.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 3567, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41857607/", "doi_url": "https://doi.org/10.1186/s13018-026-06792-6", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13047836/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13047836/"}, {"id": "pmid-41838307", "pmid": "41838307", "pmcid": "PMC12992892", "doi": "10.1186/s41747-026-00690-6", "title": "Photon-counting CT-guided bone biopsy with real-time bone marrow edema mapping", "title_fr": "Biopsie osseuse guidée par scanner à comptage photonique et cartographie de l'œdème médullaire : ciblage des lésions occultes et lymphomes", "authors_list": ["Alvarez de Sierra Garcia B", "Urtasun-Iriarte C", "Nieto P", "Alonso Burgos A"], "authors_short": "Alvarez de Sierra Garcia B, Urtasun-Iriarte C et al.", "journal": "European radiology experimental", "journal_short": "Eur Radiol Exp", "impact_factor": 3.7, "year": 2026, "month_num": 3, "month_fr": "Mars", "pub_date_fr": "Mars 2026", "volume": "10", "issue": "1", "pages": "28", "category_id": "msk_biopsy", "category_label": "Biopsies Ostéo-Articulaires, Synoviales & Sarcomes", "category_short": "Biopsies TDM & Écho", "category_color": "#3b82f6", "modality": "Scanner TDM", "intervention_type": "Biopsie Osseuse sous Scanner", "cochin_link": "Illustre le ciblage TDM de haute précision pour les biopsies osseuses (suspicion de récidive de lymphome B au genou, biopsie sacrée/pré-sacrée) et synoviales en HDJ Radio B.", "summary_fr_short": "Article de *European Radiology Experimental* (2026) montrant l'apport de l'imagerie spectrale / comptage photonique et de la corrélation IRM-TDM lors des biopsies osseuses sous scanner pour cibler les zones d'infiltration médullaire active (lymphome osseux, métastases médullaires) même en l'absence d'ostéolyse corticale franche.", "summary_fr_detailed": "Les biopsies osseuses pour suspicion de récidive de lymphome B, d'infiltration hématologique ou de lésions sacrées/pré-sacrées présentent un défi particulier lorsque la trame trabéculaire paraît subnormale au scanner conventionnel ou remaniée par des traitements antérieurs. Cet article montre comment la fusion cognitive avec l'IRM (diffusion / T1 Gado) et l'analyse de densité médullaire permettent de diriger le trocart osseux exactement dans le foyer cellulaire actif, maximisant le rendement histologique et moléculaire tout en sécurisant les gestes sous anticoagulants.", "protocol_fr": "Corrélation précise avec les images clés PACS (IRM T1, STIR, Diffusion) • Pour les patients sous AOD (ex: Eliquis 2,5 mg ou 5 mg), arrêt à J-3, contrôle du bilan d'hémostase 48h avant et reprise > 6h après le geste • Trocart de biopsie osseuse coaxial 11G–13G : prélèvement de 3 à 4 carottes non fragmentées pour histologie et cytogénétique/FISH (lymphome).", "key_points_fr": ["Dans les suspicions de récidive de lymphome osseux, cibler la zone d'hypersignal diffusion / rehaussement IRM et éviter l'écrasement mécanique des carottes.", "Pour les biopsies synoviales sous scanner (genou, suspicion de chondromatose synoviale ou SVN), utiliser un système coaxial 14G ciblant directement le nodule synovial du récessus.", "Pour les masses pré-sacrées / sacrées (ex: suspicion de myélolipome ou chordome), l'abord trans-sacré ou para-sacré postérieur sous TDM évite toute effraction rectale ou plexique.", "Protocole anticoagulants (Eliquis) pour biopsie osseuse profonde : arrêt J-3 et reprise > 6h post-procédure en l'absence de saignement."], "abstract_en": "Objective Computed tomography-guided biopsies are needed to diagnose bone lesions, but can sometimes be challenging. We evaluated the feasibility and usefulness of photon-counting computed tomography (PCCT)-guided bone biopsies, focusing on real-time bone marrow oedema (BME) mapping to optimise diagnostic yield. Materials and methods This retrospective single-centre study included procedures performed from September 2024 to May 2025 using a first-generation dual-source PCCT scanner with Quantum HD mode. Ten consecutive patients underwent PCCT-guided bone biopsy with real-time BME reconstructions. The reference standard was established using histopathology or microbiological confirmation when available; clinical and ≥ 3-month radiologic follow-up for nondiagnostic or discordant results. Statistical analysis included descriptive statistics, independent unpaired t-tests, and correlation analysis (SPSS v22.0, RStudio). Results Ten patients, five women and five men, aged 60.5 ± 13.5 years (mean ± standard deviation), were included in the final analysis. The overall diagnostic yield was 70% (7/10), with a diagnostic accuracy of 87.5% (7/8) for cases with a definitive reference standard. Final diagnoses comprised tumour bone metastases (n = 7, 70%), bone osteomyelitis (n = 1, 10%), and bone marrow deposition disease (n = 2, 20%). Mean radiation dose (dose-length product) was 644.5 ± 112.1 mGy·cm. Monoenergetic 70-keV imaging showed significant differences between mean HU values of lytic (42.6) and sclerotic lesions (476.2) (p = 0.009), with a strong negative correlation between lesion morphology (sclerotic versus lytic) and monoenergetic 70-keV attenuation values (r = -0.84; p = 0.002). Conclusion PCCT-guided bone biopsy with real-time BME mapping proved feasible and showed encouraging diagnostic performance in this small exploratory cohort. Larger validation studies are needed. Relevance statement By combining monoenergetic images and BME mapping, PCCT-guided bone biopsy improves lesion visualisation, operator confidence, procedural efficiency, and overall safety for diagnostic tissue sampling and active disease targeting. Key points Accurate targeting of active disease within complex bone lesions during CT-guided biopsy remains challenging sometimes. PCCT-guided biopsy with real-time BME mapping can enhance lesion targeting and procedural efficiency. PCCT-guided biopsy may improve safety, diagnostic accuracy, and operator confidence.", "tags": ["Biopsie osseuse", "Scanner", "Lymphome osseux", "Sacrum", "Biopsie synoviale", "Eliquis"], "pdf_file": "pdfs/PMID_41838307.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 2501, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41838307/", "doi_url": "https://doi.org/10.1186/s41747-026-00690-6", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12992892/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12992892/"}, {"id": "pmid-41720112", "pmid": "41720112", "pmcid": "", "doi": "10.1055/a-2744-8457", "title": "Percutaneous Cryoablation for the Management of Bone and Soft Tissue Tumors", "title_fr": "Cryoablation percutanée pour la prise en charge des tumeurs osseuses et des parties molles : état de l'art 2026", "authors_list": ["Le Corroller T", "Arrigoni F", "Guenoun D", "Rochwerger A", "Champsaur P", "Mattei JC"], "authors_short": "Le Corroller T, Arrigoni F et al.", "journal": "Seminars in musculoskeletal radiology", "journal_short": "Semin Musculoskelet Radiol", "impact_factor": 1.8, "year": 2026, "month_num": 2, "month_fr": "Févr.", "pub_date_fr": "Févr. 2026", "volume": "30", "issue": "1", "pages": "61-74", "category_id": "percutaneous_ablation_general", "category_label": "Ablation Percutanée Tumorale : Standards, Endométriome & Oncologie", "category_short": "Ablation Percutanée (Standards & Onco)", "category_color": "#e11d48", "modality": "Scanner TDM / IRM / Écho", "intervention_type": "Cryoablation Musculosquelettique", "cochin_link": "Issu de votre collection Zotero « Ablation percutanée » (*Seminars in Musculoskeletal Radiology*, févr. 2026) — Synthèse de référence couvrant l'ensemble du spectre d'ablation percutanée pratiqué à Cochin (ostéome ostéoïde, desmoïdes, métastases, endométriomes, récidives de sarcomes).", "summary_fr_short": "Revue d'état de l'art (*Semin Musculoskelet Radiol*, févr. 2026) détaillant les indications établies (ostéome ostéoïde, palliation antalgique et contrôle oligométastatique osseux) et émergentes (chondroblastome, tumeurs desmoïdes, anomalies vasculaires, endométriose pariétale, récidives locales de sarcomes) de la cryoablation percutanée.", "summary_fr_detailed": "Cet article de synthèse 2026 fait le point sur la maturité technologique et clinique de la cryoablation guidée par l'image en pathologie musculosquelettique. Il détaille la planification multi-sondes pour sculpter l'iceball aux géométries tumorales complexes, les stratégies de prévention des complications (hydrodissection, carbodissection, réchauffement cutané, monitoring neurophysiologique et consolidation mécanique préventive) ainsi que l'expansion des indications vers les tumeurs bénignes agressives et le rattrapage local des sarcomes osseux et des parties molles.", "protocol_fr": "Choix du calibre et de la longueur d'extrémité active des cryosondes (règle d'espacement 1,5–2 cm, distance < 1 cm de la berge tumorale) • Double cycle Congélation-Décongélation • Thermoprotection active si structure noble < 10 mm • Cimentoplastie/ostéosynthèse combinée sur os porteur.", "key_points_fr": ["Panorama complet 2026 des indications validées et émergentes de la cryoablation osseuse et des parties molles.", "Détaille les techniques d'optimisation de la géométrie de l'iceball par synergie multi-sondes.", "Systématise les protocoles de neuroprotection et de protection cutanée/cartilagineuse.", "Souligne la place croissante de la cryoablation dans les récidives locales de sarcomes et les lésions des tissus mous (desmoïdes, malformations vasculaires, endométriomes)."], "abstract_en": "Image-guided percutaneous cryoablation plays an increasingly important role in managing bone and soft tissue tumors. Well-established indications include the treatment of osteoid osteoma, palliation of painful skeletal metastases, and local control of oligometastatic disease. Emerging indications are now a variety of painful benign bone tumors beyond osteoid osteoma, symptomatic soft tissue lesions (such as desmoid fibromatosis, vascular anomalies, abdominal wall endometriosis), as well as local recurrences of bone and soft tissue sarcoma. This state-of-the-art review describes the percutaneous cryoablation technique including current strategies to prevent complications. We also discuss the expanding range of clinical indications, as well as future directions of this promising technology in the musculoskeletal system.", "tags": ["Cryoablation", "Tumeurs osseuses", "Parties molles", "État de l'art 2026", "Ablation percutanée", "Zotero"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41720112/", "doi_url": "https://doi.org/10.1055/a-2744-8457", "pmc_url": "", "article_url": "https://doi.org/10.1055/a-2744-8457"}, {"id": "pmid-41568883", "pmid": "41568883", "pmcid": "PMC12825416", "doi": "10.1051/sicotj/2025063", "title": "What's new on giant cell tumor of bone", "title_fr": "Nouveautés dans la prise en charge des tumeurs à cellules géantes de l'os (TCG) : place de la thermoablation percutanée des récidives locales", "authors_list": ["Tsukamoto S", "Errani C", "Balach T", "Zamora T", "Ortiz-Cruz E", "Rajasekaran RB", "Yau R", "Ji T", "Pérez-Muñoz I", "Linares F", "Angelini A", "Ruggieri P", "Benevenia J", "Mavrogenis AF"], "authors_short": "Tsukamoto S, Errani C et al.", "journal": "SICOT-J", "journal_short": "SICOT-J", "impact_factor": 1.8, "year": 2026, "month_num": 1, "month_fr": "Janv.", "pub_date_fr": "Janv. 2026", "volume": "12", "issue": "", "pages": "2", "category_id": "ablation_benign", "category_label": "Ablation Thermique des Tumeurs Osseuses Bénignes", "category_short": "RF & Cryo (OO / Chondroblastome / TCG)", "category_color": "#f97316", "modality": "Scanner TDM + IRM", "intervention_type": "Cryoablation & Radiofréquence sur Récidive de TCG", "cochin_link": "Correspond directement au nouveau geste de l'Agenda Interventionnel Cochin : « cryothérapie percutanée sur récidive de TCG du genou ».", "summary_fr_short": "Mise au point (*SICOT-J*, janv. 2026) synthétisant les avancées thérapeutiques dans les tumeurs à cellules géantes de l'os (TCG / GCTB) des membres, mettant en avant l'efficacité de l'ablation thermique percutanée (radiofréquence et cryoablation) pour traiter les récidives locales de petite taille sans reprise chirurgicale lourde.", "summary_fr_detailed": "Alors que le curetage intra-lésionnel conservateur des tumeurs à cellules géantes de l'os (TCG) expose à un risque significatif de récidive locale épiphyso-métaphysaire (notamment autour du genou), cet article souligne les résultats favorables de la thermoablation percutanée guidée par scanner (radiofréquence ou cryoablation seule ou combinée à une cimentoplastie de comblement) pour éradiquer les récidives locales focales tout en préservant l'articulation native et le cartilage sous-chondral. L'article aborde également le suivi biologique par la phosphatase acide résistante au tartrate 5b (TRACP-5b) et les biomatériaux de comblement.", "protocol_fr": "Dépistage précoce de la récidive locale de TCG sur le suivi TDM/IRM post-curetage • Ciblage TDM de la logette d'ostéolyse récidivante • Thermoablation percutanée (cryoablation ou radiofréquence) avec thermoprotection cartilagineuse (injection intra-articulaire de sérum/CO2 si < 5 mm de la lame sous-chondrale) +/- cimentoplastie PMMA de soutien sous-chondral.", "key_points_fr": ["Valide l'ablation thermique percutanée (cryoablation / RFA) comme alternative mini-invasive de choix pour les récidives locales focales de TCG après curetage.", "Permet d'éviter un second curetage chirurgical itératif ou une résection prothétique tout en préservant la fonction articulaire du genou.", "Intérêt de combiner la destruction thermique à un comblement cimenté (PMMA) lorsque la récidive fragilise la corticale ou l'os sous-chondral.", "Nécessité d'une surveillance IRM/TDM rapprochée de l'interface os-ciment après traitement initial d'une TCG."], "abstract_en": "When treating extremities affected by giant cell tumor of bone (GCTB), curettage should be performed to preserve the joint as much as possible in order to obtain a good functional outcome. The local recurrence risk is high following curettage, but new techniques are being developed to reduce local recurrence. We present a review of the literature reporting favorable results of radiofrequency ablation alone in locally recurrent small GCTB. New filling materials are also being developed to prevent non-oncological complications such as arthrosis and fractures. Routine measurement of tartrate-resistant acid phosphatase 5b in serum may be helpful in detecting early instances of local recurrence. For unresectable or metastatic GCTB, there is an urgent need for a new drug that is as effective as denosumab, avoids side effects, and can be administered to pregnant women.", "tags": ["Tumeur à cellules géantes", "TCG", "Récidive locale", "Genou", "Cryoablation", "Radiofréquence", "SICOT-J 2026"], "pdf_file": "pdfs/PMID_41568883.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 5173, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41568883/", "doi_url": "https://doi.org/10.1051/sicotj/2025063", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12825416/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12825416/"}, {"id": "pmid-42483265", "pmid": "42483265", "pmcid": "", "doi": "10.1007/s43465-025-01648-3", "title": "Polidocanol Sclerotherapy Plus Adjuvant Autogenous Bone Marrow Injection for Management of Aneurysmal Bone Cyst: A Prospective Study", "title_fr": "Sclérothérapie percutanée au polidocanol combinée à l'injection adjuvante de moelle osseuse autologue pour le traitement des kystes osseux anévrismaux (KOA) : étude prospective", "authors_list": ["Elshal EA", "Byoumy MAM", "Hassan AME", "Ali AM", "Hatab MAAA", "Khashaba ASI"], "authors_short": "Elshal EA, Byoumy MAM et al.", "journal": "Indian journal of orthopaedics", "journal_short": "Indian J Orthop", "impact_factor": 1.2, "year": 2026, "month_num": 1, "month_fr": "Janv.", "pub_date_fr": "Janv. 2026", "volume": "60", "issue": "7", "pages": "1612-1618", "category_id": "cyst_sclerotherapy", "category_label": "Alcoolisation & Sclérothérapie des Kystes Osseux", "category_short": "Alcoolisation KOA / KOE", "category_color": "#10b981", "modality": "Fluoroscopie / Scanner Interventionnel", "intervention_type": "Sclérothérapie au Polidocanol + Injection de Moelle Osseuse Autologue (KOA)", "cochin_link": "Complète directement les protocoles de « sclérothérapie / alcoolisation percutanée des kystes osseux anévrismaux (KOA) et essentiels (KOE) » de l'Agenda Cochin.", "summary_fr_short": "Étude prospective sur 20 patients suivis 30 mois (*Indian Journal of Orthopaedics*, janv./juil. 2026) évaluant l'association d'une sclérothérapie percutanée au polidocanol et d'une injection adjuvante de moelle osseuse autologue dans les kystes osseux anévrismaux : chute de l'EVA douleur de 6,2 à 0,3, réduction du volume kystique de 79,9 mL à 2,0 mL (p < 0,001) et seulement 5 % de récidive.", "summary_fr_detailed": "Afin d'accélérer l'ostéogenèse réparatrice après destruction chimique de la membrane endokystique des kystes osseux anévrismaux (KOA), cette étude prospective a traité 20 patients consécutifs par sclérothérapie percutanée au polidocanol suivie de l'instillation intrakystique de moelle osseuse autologue (prélevée sur la crête iliaque au cours de la même séance). Au terme d'un suivi complet de 30 mois après la dernière séance, le score EVA douleur diminue de 6,2 ± 1,4 à 0,3 ± 0,5 (p < 0,001) et le volume résiduel du kyste passe de 79,9 ± 26,3 mL à 2,0 ± 2,1 mL (p < 0,001), avec une ré-ossification corticale complète dans 95 % des cas et un taux de récidive limité à 5 % (1/20), sans complication majeure.", "protocol_fr": "Ponction percutanée du KOA sous guidage radiologique/TDM et aspiration du contenu hématique • Sclérothérapie chimique par injection de polidocanol (Aetoxisclerol) • Aspiration de moelle osseuse rouge autologue à la crête iliaque dans le même temps opératoire et réinjection intrakystique pour apporter des cellules souches mésenchymateuses ostéoprogénitrices • Suivi radiographique jusqu'à 30 mois.", "key_points_fr": ["Réduction volumétrique spectaculaire des KOA de 79,9 mL à 2,0 mL (p < 0,001) et disparition quasi complète des douleurs (EVA 6,2 → 0,3).", "Taux de guérison sans récidive de 95 % à 30 mois de recul (seulement 5 % de récidive locale).", "L'apport de moelle osseuse autologue iliaque stimule l'ostéogenèse intrakystique après l'action sclérosante du polidocanol sur l'endothélium.", "Technique simple, autologue et peu coûteuse facilement combinable aux procédures de sclérothérapie de KOA/KOE réalisées à Cochin."], "abstract_en": "Purpose Aneurysmal bone cysts (ABCs) are benign bone lesions that exhibit localized destructive growth. Conventionally, most patients are treated with curettage and bone grafting. Alternatively, percutaneous treatment using selective arterial embolization and sclerotherapy had been successfully used with promising results. Adjuvant use of bone marrow injection alone or with other agents for treatment of bone cysts was previously used. The aim of this work is to assess the clinical outcome of polidocanol sclerotherapy with adjuvant autogenous bone marrow injection for management of ABCs. Methods The present prospective study was conducted on 20 patients with ABCs diagnosed on the basis of clinical and radiological findings. All patients were managed using polidocanol sclerotherapy followed by adjuvant autogenous bone marrow injection. Pain was evaluated using Visual Analog Scale (VAS). Radiographic evaluation was performed using plain radiographs. All patients were followed for 30 months after the last treatment session. Results The present study was conducted on 20 patients with an age of 10.2 ± 4.4 years (range: 3.0-20.0 years). They comprised 12 males and 8 females. VAS for pain improved from 6.2 ± 1.4 at baseline to 0.3 ± 0.5 ( p p Conclusion Use of polidocanol sclerotherapy followed by adjuvant autogenous bone marrow injection for management of ABCs is highly effective with adequate safety profile.", "tags": ["Kyste osseux anévrismal", "Polidocanol", "Moelle osseuse autologue", "Sclérothérapie", "Ostéogenèse", "Indian J Orthop 2026"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42483265/", "doi_url": "https://doi.org/10.1007/s43465-025-01648-3", "pmc_url": "", "article_url": "https://doi.org/10.1007/s43465-025-01648-3"}, {"id": "pmid-41594302", "pmid": "41594302", "pmcid": "PMC12840153", "doi": "10.3390/diagnostics16020326", "title": "MRI in Chronic Pudendal Neuralgia: Diagnostic Criteria and Associated Pathologies", "title_fr": "IRM pelvienne et neurographie par diffusion (DWI) dans la névralgie pudendale chronique : critères diagnostiques et pathologies associées sur 81 patients", "authors_list": ["Gaeta M", "Turturici S", "Galletta K", "Geremia C", "Tuscano A", "Gaeta A", "Cavallaro M", "Silipigni S", "Granata F"], "authors_short": "Gaeta M, Turturici S et al.", "journal": "Diagnostics (Basel, Switzerland)", "journal_short": "Diagnostics", "impact_factor": 3.0, "year": 2026, "month_num": 1, "month_fr": "Janv.", "pub_date_fr": "Janv. 2026", "volume": "16", "issue": "2", "pages": "326", "category_id": "pudendal_cryoneurolysis", "category_label": "Cryoneurolyse du Nerf Pudendal & Névralgie Pelvi-Périnéale", "category_short": "Cryoneurolyse Nerf Pudendal", "category_color": "#0ea5e9", "modality": "IRM Pelvienne & Neurographie IRM (DWI)", "intervention_type": "Bilan IRM Pré-Interventionnel du Nerf Pudendal & du Canal d'Alcock", "cochin_link": "Outil de référence pour l'interprétation des « IRM pelviennes et du nerf pudendal pré-infiltration / pré-cryoneurolyse » en Radiologie B à Cochin.", "summary_fr_short": "Étude radiologique sur 81 patients atteints de névralgie pudendale chronique (*Diagnostics*, janv. 2026, IF 3,0, Open-Access) évaluant un protocole d'IRM pelvienne incluant une neurographie par séquence de diffusion EPI (valeurs b = 0, 100 et 600 s/mm²) : détection d'anomalies de signal du nerf pudendal chez 51,9 % des patients (42/81, unilatérales dans 78,6 % des cas) et identification d'une cause anatomique compressive ou extrinsèque dans 54,8 % des cas positifs.", "summary_fr_detailed": "Bien que le diagnostic de névralgie pudendale repose sur les critères cliniques de Nantes, l'IRM pelvienne est indispensable avant tout geste de cryoneurolyse ou de décompression pour éliminer une lésion tumorale, kystique ou endométriosique et localiser le site exact du conflit canalaire. En intégrant une séquence de diffusion écho-planaire (DWI-EPI avec b = 0, 100 et 600) supprimant le signal vasculaire pour rehausser sélectivement les faisceaux nerveux, les auteurs mettent en évidence une hyperintensité ou un épaississement focal du nerf pudendal chez 42 des 81 patients (33 unilatéraux, 9 bilatéraux), permettant de guider précisément l'étage du bloc et de la cryoneurolyse TDM (pince ligamentaire rétro-sciatique vs canal d'Alcock).", "protocol_fr": "IRM pelvienne haute résolution (1,5T ou 3T) : séquences pondérées T2 FSE multiplanaires fines centrées sur la grande échancrure sciatique, l'épine ischiatique, la pince sacro-épineuse/sacro-tubérale et le canal pudendal d'Alcock • Séquence de neurographie par diffusion DWI-EPI (b = 0, 100, 600 s/mm²) permettant de suivre le trajet nerveux et d'identifier les asymétries de calibre/signal avant la cryoneurolyse TDM.", "key_points_fr": ["La séquence DWI (b = 0, 100, 600) améliore nettement la conspicuité du nerf pudendal et détecte une anomalie focale dans plus de la moitié des névralgies pudendales chroniques.", "Identifie une étiologie anatomique ou compressive associée chez plus d'un patient sur deux présentant une anomalie DWI.", "Permet de cibler avec précision le site du conflit (pince ligamentaire ischiatique vs canal d'Alcock) lors de la cryoneurolyse sous scanner."], "abstract_en": "Background/Objectives: Chronic pudendal neuralgia is a relatively rare condition in the general population, with an incidence of 1%. Although diagnosis of pudendal neuralgia is mainly clinical, Magnetic Resonance Imaging (MRI) is commonly performed to obtain further information. However, clear criteria and guidelines for MRI diagnosis and the clinical-radiological correlation are still not definite. Methods : We reviewed 81 patients with chronic pudendal neuralgia, studied by an MRI designed protocol for a pelvis and pelvic floor examination. A key element of the protocol was the use of a diffusion-weighted imaging (DWI) technique with echo planar imaging (EPI) sequence (b-values of 0, 100, and 600) for the neurographic evaluation of the nerve. Results: MRI examination revealed DWI abnormalities in 42/81 patients. Pudendal nerve abnormalities were unilateral in 33/42 patients and bilateral in 9/42. Moreover, in 23/42 patients, pathologies related to a high probability of neuropathy have been identified. Conclusions : This study highlights the role of pelvic MRI as a valuable imaging modality in the evaluation of patients with chronic pudendal neuralgia. In the study protocol we propose, an essential role is played by the DWI technique, which improves the visual definition of the pudendal nerve and related anatomical structures. By focusing on anatomical visualization and structured image interpretation, our work provides a practical imaging-oriented contribution to a field in which standardized MRI evaluation is still lacking.", "tags": ["IRM pelvienne", "Neurographie IRM", "Diffusion DWI", "Nerf pudendal", "Canal d'Alcock", "Diagnostics 2026"], "pdf_file": "pdfs/PMID_41594302.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 8757, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41594302/", "doi_url": "https://doi.org/10.3390/diagnostics16020326", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12840153/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12840153/"}, {"id": "pmid-41473339", "pmid": "41473339", "pmcid": "PMC12746746", "doi": "10.2147/ijgm.s564210", "title": "Imaging Evaluation of Bone Tumors in the Cervical Spine: A Comprehensive Review", "title_fr": "Évaluation par imagerie (TDM et IRM) des tumeurs osseuses du rachis cervical : revue complète diagnostique et pré-thérapeutique", "authors_list": ["Sun M", "Meng X", "Wu M", "Wang Z"], "authors_short": "Sun M, Meng X et al.", "journal": "International journal of general medicine", "journal_short": "Int J Gen Med", "impact_factor": 2.1, "year": 2025, "month_num": 12, "month_fr": "Déc.", "pub_date_fr": "Déc. 2025", "volume": "18", "issue": "", "pages": "7785-7798", "category_id": "msk_imaging", "category_label": "Imagerie Ostéo-Articulaire Diagnostique & Suivi Post-Geste", "category_short": "IRM / TDM Diagnostique & Suivi", "category_color": "#6366f1", "modality": "IRM + Scanner TDM / Angio-TDM", "intervention_type": "Bilan Pré-Thérapeutique & Suivi du Rachis Cervical", "cochin_link": "En lien direct avec les gestes cervicaux récemment programmés dans l'Agenda Cochin (« RF d'ostéome ostéoïde de C6 » et « cimentoplastie cervicale sous AG »).", "summary_fr_short": "Revue clinique et iconographique complète (*Int J Gen Med*, déc. 2025) détaillant la sémiologie IRM et TDM des tumeurs osseuses bénignes (ostéome ostéoïde, ostéoblastome, KOA) et malignes (métastases, chordome, myélome) du rachis cervical ainsi que les repères anatomiques critiques avant geste percutané.", "summary_fr_detailed": "Le rachis cervical présente des défis diagnostiques et interventionnels uniques en raison de l'étroitesse des pédicules, de la proximité immédiate des artères vertébrales dans les foramens transversaires (C1–C6), du cordon médullaire et des racines nerveuses. Cet article synthétise les critères de caractérisation TDM et IRM permettant de différencier les lésions bénignes de l'arc postérieur (ostéome ostéoïde, ostéoblastome, kyste osseux anévrismal) des lésions malignes prédominant sur le corps vertébral (métastases ostéolytiques, myélome, chordome), et précise le bilan pré-thérapeutique indispensable avant biopsie, thermoablation ou cimentoplastie cervicale.", "protocol_fr": "Bilan pré-interventionnel cervical : TDM en coupes infra-millimétriques + Angio-TDM des troncs supra-aortiques (cartographie de l'artère vertébrale V2 dans le foramen transversaire par rapport au nidus ou au trajet de trocart) + IRM cervicale T1, STIR, Diffusion et T1 injecté • Abord antéro-latéral (entre axe jugulo-carotidien et axe aéro-digestif) pour le corps vertébral ou postéro-latéral pour l'arc postérieur.", "key_points_fr": ["Cartographie indispensable des rapports avec l'artère vertébrale (segment V2) et le foramen intervertébral avant toute RF d'ostéome ostéoïde cervical (ex. C6).", "Topographie préférentielle sur l'arc postérieur pour l'ostéome ostéoïde, l'ostéoblastome et le KOA, contre le corps vertébral pour les métastases et le chordome.", "Complémentarité systématique du scanner en coupes fines (matrice minérale, corticale) et de l'IRM (extension épidurale, œdème réactionnel).", "Guide le choix sécurisé de la voie d'abord cervicale (antéro-latérale vs postéro-latérale) au scanner interventionnel."], "abstract_en": "The cervical spine, a critical junction between the head and torso, is a rare but significant site for both primary and metastatic tumors. While primary tumors of the cervical spine are uncommon, certain types, such as chordomas and giant cell tumors, are particularly notable for their potential to affect this region. Metastatic lesions, although more frequent, present unique diagnostic and therapeutic challenges due to the complex anatomy of the cervical spine. Imaging is indispensable for the evaluation of cervical spine tumors, serving as the foundation for diagnosis, treatment planning, and monitoring therapeutic outcomes. Radiography, CT and MRI are the primary modalities used to assess tumor morphology, extent and relationship to surrounding structures. However, imaging alone may not always yield a definitive diagnosis, as some tumors lack distinctive features. Nevertheless, a combination of clinical presentation, epidemiological factors, and imaging findings often enables radiologists and clinicians to narrow the differential diagnosis and guide further management. Precise imaging interpretation is essential to prevent devastating clinical consequences resulting from diagnostic error, such as irreversible neurological damage, avoidable death, and significant long-term disability. This review provides a comprehensive overview of tumors that can involve the cervical spine, emphasizing their clinical and imaging characteristics. By highlighting key diagnostic features and discussing the latest advancements in imaging technology, aims to enable physicians in radiology, pathology, and clinical departments to gain a more comprehensive understanding of the imaging, pathological, and clinical characteristics of cervical spine tumors, thereby reducing misdiagnosis rates and alleviating the burden on patients.", "tags": ["Rachis cervical", "Ostéome ostéoïde cervical", "Métastases cervicales", "IRM", "Scanner TDM", "Artère vertébrale"], "pdf_file": "pdfs/PMID_41473339.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 2117, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41473339/", "doi_url": "https://doi.org/10.2147/ijgm.s564210", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12746746/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12746746/"}, {"id": "pmid-41357250", "pmid": "41357250", "pmcid": "PMC13530442", "doi": "10.4274/dir.2025.253499", "title": "Post-cryoablation magnetic resonance imaging features of desmoid tumors: a pictorial essay", "title_fr": "Sémiologie IRM post-cryoablation des tumeurs desmoïdes : atlas iconographique et pièges d'interprétation (6 à 30 mois de suivi)", "authors_list": ["Savarese LG", "Papalexis N", "Miceli M", "Carta M", "Facchini G"], "authors_short": "Savarese LG, Papalexis N et al.", "journal": "Diagnostic and interventional radiology (Ankara, Turkey)", "journal_short": "Diagn Interv Radiol", "impact_factor": 1.9, "year": 2025, "month_num": 12, "month_fr": "Déc.", "pub_date_fr": "Déc. 2025", "volume": "32", "issue": "5", "pages": "709-714", "category_id": "msk_imaging", "category_label": "Imagerie Ostéo-Articulaire Diagnostique & Suivi Post-Geste", "category_short": "IRM / TDM Diagnostique & Suivi", "category_color": "#6366f1", "modality": "IRM Multiparamétrique de Suivi Post-Cryoablation", "intervention_type": "Suivi IRM Post-Cryoablation (Desmoïdes & Parties Molles)", "cochin_link": "Outil pratique quotidien pour l'interprétation des IRM de contrôle post-cryoablation (distinction entre réaction inflammatoire périphérique normale et récidive locale) à Cochin.", "summary_fr_short": "Atlas didactique (*Diagn Interv Radiol*, déc. 2025) illustrant l'évolution temporelle en IRM (de 6 à 30 mois) des tumeurs desmoïdes traitées par cryoablation percutanée afin d'éviter de confondre les remaniements post-thérapeutiques attendus avec une récidive.", "summary_fr_detailed": "Cet article iconographique détaille les aspects IRM pré-thérapeutiques, per-procédure et post-cryoablation (suivi de 6 à 30 mois) des fibromatoses desmoïdes. Il décrit la couronne inflammatoire périphérique précoce (fine prise de contraste annulaire régulière de tissu de granulation entourant la nécrose centrale avasculaire en hyposignal T1/T2 ou hypersignal T1 hémorragique), l'involution progressive en hyposignal T2 franc fibreux mature, et les signes formels de récidive focale viable (nodule asymétrique en hypersignal T2 franc, restriction en diffusion et rehaussement précoce nodulaire sur la berge d'ablation, souvent au contact d'une structure neuro-vasculaire thermoprotégée).", "protocol_fr": "Protocole IRM de suivi post-cryoablation : T1 sans injection (repérage de la nécrose hémorragique de coagulation), T2 Fat-Sat / STIR, Diffusion b800 avec cartographie ADC, et T1 Fat-Sat injecté avec soustraction dynamique • Comparaison systématique au contour initial de la boule de glace per-procédure.", "key_points_fr": ["Une fine prise de contraste périphérique circonférentielle et régulière dans les 3 à 6 premiers mois correspond à une réaction granulomateuse cicatricielle normale.", "La nécrose centrale post-cryoablation présente souvent un hypersignal T1 spontané (remaniements hémorragiques) rendant indispensable la séquence de soustraction après gadolinium.", "Le passage progressif en hyposignal T2 franc et l'absence de rehaussement signent la réponse complète durable.", "La récidive vraie se traduit par un bourgeon nodulaire focal en hypersignal T2 et rehaussement intense, typiquement situé sur une marge ayant nécessité une hydrodissection protectrice."], "abstract_en": "Desmoid tumors (DTs) are rare, locally aggressive soft tissue neoplasms with highly variable clinical behavior. Although benign, their infiltrative nature can lead to considerable morbidity. DTs present a major challenge due to their unpredictable behavior and potential for misdiagnosis. Recently, there has been a large shift in the treatment strategy for DTs, and the number of cases being followed up with imaging has increased. Cryoablation has emerged as a minimally invasive treatment option, yet post-procedural imaging features remain poorly characterized. This study illustrates the magnetic resonance imaging (MRI) evolution of DTs following percutaneous cryoablation, emphasizing key patterns across pre-treatment, intra-procedural, and follow-up studies. The available MRI follow-up ranged from 6 to 30 months. Through a pictorial approach, we aimed to provide radiologists with practical insights to avoid misinterpretation of expected post-treatment changes as recurrence and to improve clinical management.", "tags": ["IRM post-cryoablation", "Tumeur desmoïde", "Sémiologie IRM", "Soustraction T1", "Récidive vs cicatrice"], "pdf_file": "pdfs/PMID_41357250.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 3106, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41357250/", "doi_url": "https://doi.org/10.4274/dir.2025.253499", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13530442/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13530442/"}, {"id": "pmid-41440950", "pmid": "41440950", "pmcid": "PMC12734139", "doi": "10.3390/jpm15120587", "title": "Cryoneurolysis: An Emerging Personalized Treatment Strategy for Significant Pelvic Pain", "title_fr": "Cryoneurolyse personnalisée dans les douleurs pelviennes sévères : ciblage du nerf pudendal et du ganglion impar (mécanismes, bilan et technique)", "authors_list": ["Young S", "Abramyan A", "Vittoria De Martini I", "Hannallah J", "Woodhead G", "Struycken L", "Goldberg D"], "authors_short": "Young S, Abramyan A et al.", "journal": "Journal of personalized medicine", "journal_short": "J Pers Med", "impact_factor": 3.0, "year": 2025, "month_num": 12, "month_fr": "Déc.", "pub_date_fr": "Déc. 2025", "volume": "15", "issue": "12", "pages": "587", "category_id": "pudendal_cryoneurolysis", "category_label": "Cryoneurolyse du Nerf Pudendal & Névralgie Pelvi-Périnéale", "category_short": "Cryoneurolyse Nerf Pudendal", "category_color": "#0ea5e9", "modality": "Scanner Interventionnel (TDM) / Fluoroscopie", "intervention_type": "Cryoneurolyse Ciblée du Nerf Pudendal & du Ganglion Impar", "cochin_link": "Synthèse pratique sur le ciblage combiné « Nerf pudendal + Ganglion de Walther (Impar) » pratiqué sous scanner en Radiologie Interventionnelle à Cochin.", "summary_fr_short": "Revue clinique et technique (*Journal of Personalized Medicine*, déc. 2025, IF 3,0, équipe J.D. Prologo) détaillant la neurobiologie de l'axonotmésis par le froid (-20°C à -100°C), la cartographie sémiologique des douleurs pelvi-périnéales et la technique de cryoneurolyse personnalisée du nerf pudendal et du ganglion impar en alternative d'épargne opioïde.", "summary_fr_detailed": "Face aux douleurs pelvi-périnéales réfractaires et à la nécessité d'épargne morphinique, cette mise au point détaille l'approche personnalisée par cryoneurolyse guidée par l'image. Contrairement à l'alcoolisation ou à la radiofréquence thermique ablative à haute température qui exposent au névrome de désafférentation, la cryoneurolyse induit une dégénérescence wallérienne réversible (axonotmésis de grade II de Sunderland) en préservant intégralement la trame conjonctive endoneurale, périneurale et épineurale, permettant une repousse axonale physiologique sans névrome. L'article précise les repères TDM pour cibler sélectivement le nerf pudendal (douleur périnéale latéralisée des 2/3 antérieurs, majorée assis) et le ganglion impar pré-coccygien (douleur périnéale médiane, ano-rectale ou coccygienne à composante sympathique).", "protocol_fr": "Phénotypage topographique pré-geste : douleur périnéale/génitale dans le territoire S2-S4 → ciblage TDM du nerf pudendal à l'épine ischiatique ou dans le canal d'Alcock ; douleur médiane ano-coccygienne/vulvo-périnéale sympathique → ciblage trans-sacro-coccygien ou latéro-coccygien du ganglion impar dans l'espace rétro-rectal • Cryoneurolyse en zone de transition thermique (-20°C à -70°C) préservant l'endonèvre.", "key_points_fr": ["Rappelle le fondement histologique clé de la cryoneurolyse : préservation de l'endonèvre et de la lame basale évitant toute névrite ou névrome de désafférentation.", "Distingue clairement les indications du nerf pudendal (somatique S2-S4) et du ganglion impar (sympathique médian), souvent complémentaires.", "Sécurité sphinctérienne préservée grâce à la précision du guidage TDM et à la réversibilité de la cryo-axonotmésis."], "abstract_en": "Significant pelvic pain is a fairly common malady in the United States. At the same time, the opioid epidemic has changed how pain is thought about and treated, resulting in a clear call for alternative treatment strategies. One of the promising techniques that has emerged over the last several years is cryoneurolysis. Cryoneurolysis allows for personalization of treatment through targeting of specific peripheral nerves, which correspond to a patient's pain. In the setting of pelvic pain, several viable targets, namely the pudendal nerve and impar ganglion, have been described. This review delineates the mechanism of action in cryoneurolysis, reviews the pertinent literature and describes patient workup and technique. Finally, future directions are discussed.", "tags": ["Cryoneurolyse", "Nerf pudendal", "Ganglion impar", "Douleur pelvienne", "Axonotmésis", "J Pers Med 2025"], "pdf_file": "pdfs/PMID_41440950.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1890, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41440950/", "doi_url": "https://doi.org/10.3390/jpm15120587", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12734139/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12734139/"}, {"id": "pmid-41204964", "pmid": "41204964", "pmcid": "PMC13035685", "doi": "10.1007/s00330-025-12128-5", "title": "CT-guided bone biopsies with non-diagnostic results in pediatric patients-a multi-institutional 10-year retrospective review", "title_fr": "Facteurs prédictifs de biopsie osseuse non contributive sous scanner : étude multicentrique et stratégies d'optimisation", "authors_list": ["Lam PL", "Fung KFK", "Yip SWY", "Chan PKJ", "Wan FYF", "Kan ANC", "Kan YLE", "Wong KC", "Lai KC", "Griffith JF"], "authors_short": "Lam PL, Fung KFK et al.", "journal": "European radiology", "journal_short": "Eur Radiol", "impact_factor": 4.7, "year": 2025, "month_num": 11, "month_fr": "Nov.", "pub_date_fr": "Nov. 2025", "volume": "36", "issue": "4", "pages": "2475-2487", "category_id": "msk_biopsy", "category_label": "Biopsies Ostéo-Articulaires, Synoviales & Sarcomes", "category_short": "Biopsies TDM & Écho", "category_color": "#3b82f6", "modality": "Scanner TDM", "intervention_type": "Biopsie Osseuse sous Scanner", "cochin_link": "Permet d'optimiser le rendement diagnostique des biopsies osseuses et synoviales réalisées sous scanner au Pavillon Achard -1.", "summary_fr_short": "Étude multicentrique publiée dans *European Radiology* (2026) analysant les causes de biopsies osseuses non diagnostiques sous scanner et définissant les critères techniques permettant d'atteindre un rendement supérieur à 90 % (calibre du trocart, nombre de carottes, ciblage de la composante tissulaire non nécrotique).", "summary_fr_detailed": "Malgré la précision du guidage tomodensitométrique, 8 à 15 % des biopsies osseuses peuvent s'avérer non contributives, notamment dans les lésions kystiques remaniées, les tumeurs très sclérosantes ou les lésions inflammatoires chroniques. Cette étude multicentrique démontre que le prélèvement simultané de la composante intra-osseuse et de la composante tissulaire périphérique (ou synoviale), l'utilisation d'aiguilles de calibre ≥ 13G pour l'os et ≥ 14G pour les parties molles, et l'aspiration du sang médullaire comme bloc cellulaire réduisent significativement le taux d'échec.", "protocol_fr": "Prélèvement combiné : carottes osseuses (11G–13G) + carottes des parties molles/synoviale (14G) + envoi du caillot médullaire aspiré au laboratoire d'anatomopathologie • En cas de doute infectieux différentiel, toujours adresser un fragment en bactériologie/mycobactériologie à frais.", "key_points_fr": ["Envoyer systématiquement le sang/caillot médullaire aspiré dans la seringue en anatomopathologie (technique du 'cell block') : augmente le rendement diagnostique de 7 %.", "Cibler la berge ostéolytique active ou le nodule synovial charnu plutôt que le centre nécrotique ou kystique.", "Un minimum de 3 carottes de longueur ≥ 10 mm est recommandé pour permettre les analyses immunohistochimiques et moléculaires.", "Discussion préalable des images clés PACS avec le radiologue référent et l'anatomopathologiste spécialisé en pathologie osseuse."], "abstract_en": "Objective This study aimed to determine the diagnostic yield of CT-guided bone biopsies in pediatric patients, the outcome of non-diagnostic CT biopsy results, and to establish factors associated with non-diagnostic biopsy results. Materials and methods This is a retrospective study of consecutive pediatric patients ≤ 21 years who underwent CT-guided bone biopsies in three tertiary referral hospitals from December 2011 to March 2022. Clinical information, pre-biopsy CT and MRI images, procedural details, pathological results, and follow-up were assessed. Fisher's exact test was used to compare categorical variables. Mann-Whitney U-test and unpaired t-test were used to compare non-parametric and parametric variables, respectively. Statistical significance was set a p Results A total of 138 patients (mean age 13.9 ± 4.5 years; 95 (60%) male patients) with 157 CT-guided bone biopsies were studied, which yielded 38.2% (60/157) non-diagnostic, 23.6% (37/157) benign, and 38.2% (60/157) malignant results. Most non-diagnostic lesions (88.3% [53/60]) were subsequently determined to be benign. Factors associated with non-diagnostic biopsy results were cystic lesions (p = 0.003) incidental lesions (p = 0.03), fewer (p = 0.02) and shorter (p = 0.01) tissue cores, non-aggressive radiological features, including narrow zone of transition (p Conclusion About one-third of CT-guided bone biopsies in pediatric patients yielded non-diagnostic results, though most were ultimately confirmed to be benign. In children and adolescents with suspected primary bone tumors, CT-guided bone biopsy with non-diagnostic histopathological results strongly favors benignity in lesions with non-aggressive imaging features and should align management towards a more conservative approach. Key points Question Limited data exist on the prevalence and outcome of non-diagnostic CT-guided bone biopsy in pediatric patients to guide clinical management. Findings About one-third of CT-guided bone biopsies in pediatric patients were non-diagnostic, though most were ultimately benign. Lesions with non-aggressive features were associated with non-diagnostic results. Clinical relevance In the setting of multidisciplinary care for patients with suspected primary bone tumors, non-diagnostic CT-guided bone biopsy-particularly in lesions with non-aggressive imaging features-strongly favors benignity, which should steer management towards a more conservative approach.", "tags": ["Biopsie osseuse", "European Radiology", "Rendement diagnostique", "Anatomopathologie", "Scanner"], "pdf_file": "pdfs/PMID_41204964.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 4228, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41204964/", "doi_url": "https://doi.org/10.1007/s00330-025-12128-5", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13035685/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13035685/"}, {"id": "pmid-40911195", "pmid": "40911195", "pmcid": "", "doi": "10.1007/s00234-025-03738-3", "title": "Long-term outcome following vertebroplasty or bone cementoplasty in multiple myeloma patients", "title_fr": "Résultats à très long terme (> 5 ans) après vertébroplastie ou cimentoplastie osseuse chez les patients atteints de myélome multiple", "authors_list": ["Soliman S", "Garderet L", "Premat K", "Allard J", "Drir M", "Elhorany M", "Hamad N", "Lesaunier A", "Talbi A", "Roos-Weil D", "Baron M", "Boussen I", "Grenier A", "Gauthier N", "Morel V", "Ouzegdouh M", "Choquet S", "Bonaccorsi R", "Chiaroni PM", "Clarencon F", "Shotar E"], "authors_short": "Soliman S, Garderet L et al.", "journal": "Neuroradiology", "journal_short": "Neuroradiology", "impact_factor": 2.8, "year": 2025, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2025", "volume": "67", "issue": "10", "pages": "2963-2975", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Scanner TDM / IRM de suivi à long terme", "intervention_type": "Vertébroplastie & Cimentoplastie Pelvienne (Myélome)", "cochin_link": "Directement lié aux cimentoplasties rachidiennes et du bassin chez les patients suivis au long cours pour myélome multiple à Cochin.", "summary_fr_short": "Étude rétrospective avec suivi imagerie ≥ 5 ans (*Neuroradiology*, sept. 2025, 142 sites cimentés) démontrant la pérennité mécanique remarquable de la cimentoplastie dans le myélome multiple (1,4 % de refracture locale) et identifiant la fuite discale comme facteur majeur de fracture vertébrale adjacente (31 % vs 8,8 %).", "summary_fr_detailed": "Sur 47 patients atteints de myélome multiple survivant à plus de 5 ans avec imagerie de contrôle (74 procédures, 142 sites cimentés : 129 vertèbres, 11 cimentoplasties pelviennes), seules 2 refractures de l'os cimenté (1,4 %) sont survenues, prouvant la durabilité biomécanique à long terme du PMMA. En revanche, 14 % des vertèbres adjacentes non cimentées ont présenté une fracture secondaire au cours du suivi : la présence d'une fuite de ciment dans le disque intervertébral multipliait par 3,5 ce risque (31 % vs 8,8 %, p = 0,022). Les fractures à distance étaient associées à une plasmocytose médullaire initiale élevée (23 % vs 13 %, p = 0,014).", "protocol_fr": "Cimentoplastie vertébrale ou pelvienne guidée par TDM/fluoroscopie • Viser un remplissage spongieux trabéculaire homogène d'un plateau à l'autre tout en évitant strictement le franchissement du plateau vertébral et la fuite discale • Discuter une cimentoplastie prophylactique d'une vertèbre adjacente prise en sandwich ou en cas de fuite discale.", "key_points_fr": ["Stabilité mécanique exceptionnelle à plus de 5 ans : seulement 1,4 % de récidive fracturaire sur les 142 os cimentés.", "Règle technique essentielle : la fuite de ciment intradiscale fait passer le risque de fracture de la vertèbre adjacente de 8,8 % à 31 % (p = 0,022).", "Aucune complication grave liée à la procédure sur 129 vertèbres et 11 bassins cimentés.", "Ouvre la discussion d'une cimentoplastie préventive des niveaux adjacents à haut risque dans le myélome."], "abstract_en": "Objective Evaluating long-term outcomes following cementoplasty in patients with multiple myeloma (MM). Methods This is a single-center, retrospective study on all cementoplasties performed between January 2012 and December 2017. Patients with MM with a control MRI or CT scan beyond 5 years after the procedure were included. Images were reviewed blinded to the patients' clinical status. Results During the inclusion period, 2085 patients underwent cementoplasty, including 154 patients with MM. Forty-seven patients (33 men (70%); median age 62.2 years [IQR 53.8;69.6]) were included. The patients underwent 74 procedures (142 cemented sites: 129 vertebrae, 11 pelvic girdle cementoplasties, and 2 other sites; 101 (71%) demineralized fractures and 41 (29%) osteolytic lacunae). No serious procedure-related adverse effects were observed. Only 2 (1.4%) recurrent fractures of the cemented bone were observed. At-risk adjacent vertebrae were defined as non-cemented vertebrae, adjacent to a cemented vertebra: 15/109 (14%) fractures of at-risk adjacent vertebrae were documented during follow-up (15/99 [15%] after excluding cervical at-risk vertebrae). Intervertebral disc cement leakage was significantly associated with the occurrence of vertebral fracture at the adjacent level (31% vs. 8.8%, p = 0.022). Fourteen patients (30%) developed a new vertebral fracture that was remote from the cemented site. These were more frequent in patients with higher bone marrow plasmacytosis (median 23% vs. 13%, p = 0.014), relapsed multiple myeloma (86% vs. 55%, p = 0.042) and bone demineralization fractures (93% vs. 48%, p Conclusion Bone cementoplasty for MM is a durable treatment. At-risk adjacent vertebra fracture is a frequent event, prompting a discussion on prophylactic adjacent-level cementoplasty.", "tags": ["Myélome multiple", "Cimentoplastie", "Vertébroplastie", "Fuite discale", "Fracture adjacente", "Neuroradiology"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/40911195/", "doi_url": "https://doi.org/10.1007/s00234-025-03738-3", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00234-025-03738-3"}, {"id": "pmid-40906057", "pmid": "40906057", "pmcid": "PMC12411335", "doi": "10.1186/s41747-025-00607-9", "title": "Electrochemotherapy of spinal metastasis using transpedicular approach: a preclinical safety animal study", "title_fr": "Électrochimiothérapie (ECT) des métastases vertébrales par voie transpédiculaire : étude préclinique de sécurité médullaire sous neuromonitoring", "authors_list": ["Deschamps F", "Gautreau E", "Tselikas L", "Bonnet B", "Beunon P", "Feddal A", "de Baere T", "Gaudin A", "Mir LM"], "authors_short": "Deschamps F, Gautreau E et al.", "journal": "European radiology experimental", "journal_short": "Eur Radiol Exp", "impact_factor": 3.7, "year": 2025, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2025", "volume": "9", "issue": "1", "pages": "84", "category_id": "ect_mets", "category_label": "Électrochimiothérapie (ECT) & Métastases Osseuses", "category_short": "ECT (Bléomycine) & Métastases", "category_color": "#eab308", "modality": "Scanner TDM + Fluoroscopie + Neuromonitoring (PEM/PES)", "intervention_type": "Électrochimiothérapie (ECT) Vertébrale Transpédiculaire", "cochin_link": "Directement lié aux séances d'électrochimiothérapie (Bléomycine IV) des métastases rachidiennes et épidurales réalisées au scanner Achard -1 à Cochin.", "summary_fr_short": "Étude de sécurité préclinique (*Eur Radiol Exp*, sept. 2025, 12 sujets, 36 niveaux thoraco-lombaires T11–L1) démontrant que l'électrochimiothérapie vertébrale par voie transpédiculaire ne provoque aucune lésion histologique médullaire ni déficit neurologique permanent.", "summary_fr_detailed": "L'électrochimiothérapie (ECT) est une alternative majeure pour les métastases vertébrales radiorésistantes ou proches du cordon médullaire, mais le champ électrique pulsé pourrait théoriquement léser la moelle épinière. Dans cette étude évaluant l'ECT sur 3 niveaux consécutifs (T11, T12, L1) par abord transpédiculaire bilatéral avec neuromonitoring per-opératoire, une sidération transitoire des potentiels évoqués moteurs (PEM) des membres inférieurs a été observée chez 5/6 sujets mais avec récupération complète systématique en moins de 30 minutes. L'examen clinique à J3 et J30 était strictement normal (marche normale, absence de trouble sphinctérien) et l'analyse histopathologique médullaire n'a révélé ni apoptose neuronale, ni thrombose vasculaire, ni foyer hémorragique.", "protocol_fr": "Insertion d'électrodes-aiguilles par voie transpédiculaire bilatérale sous guidage TDM • Perfusion IV de Bléomycine • Délivrance des impulsions d'électroporation synchronisées à l'ECG sous surveillance continue des Potentiels Évoqués Moteurs (PEM) • Savoir qu'une chute immédiate des PEM récupère habituellement en < 30 min sans lésion anatomique médullaire.", "key_points_fr": ["Démonstration histologique de l'innocuité médullaire de l'ECT vertébrale par voie transpédiculaire (aucune apoptose ni ischémie médullaire).", "Observation importante pour le radiologue interventionnel : les Potentiels Évoqués Moteurs (PEM) peuvent chuter transitoirement après l'impulsion électrique mais récupèrent intégralement en moins de 30 minutes.", "Aucun déficit moteur ni trouble vésico-sphinctérien observé au cours du suivi.", "Confirme la sécurité du positionnement transpédiculaire des électrodes pour traiter les métastases rachidiennes complexes."], "abstract_en": "Background Electrochemotherapy (ECT) of vertebral metastasis is a new treatment option for metastasis that is not accessible to thermal ablation or radiotherapy. A numerical feasibility study has investigated the transpedicular approach for electrode insertion. We conducted a preclinical study to assess its safety. Methods Histologic examination of the spinal cord was performed in 12 consecutive pigs treated with ECT at three consecutive levels (T11, T12, and L1) to evaluate any cellular or vascular damage. Pigs of group A (n = 6) had an intraoperative neuromonitoring immediately for 1 h after ECT and then were euthanized. Pain and clinical symptoms were daily evaluated for group B (n = 3) and group C (n = 3) until day-3 and day-30, respectively. Results At gross pathology, no apoptosis, no vascular/thrombosis or hemorrhagic focus was observed in any pig. Motor-evoked potential responses of the lower limbs were transiently lost in response in 5 of the 6 pigs, but complete recovery always occurred within 30 min. Clinical examination (groups B and C) revealed no symptoms during the follow-up. Pigs were all able to walk normally, without weakness or paralysis of the lower extremities. No urinary/fecal retention or incontinence was observed, nor any sign of pain. Conclusion Our results confirm that the insertion of electrodes through the pedicles is safe for the ECT of vertebral metastases. Further studies are needed to evaluate the safety profile of ECT of vertebral metastases invading the cortical and epidural fat, which represents a privileged pathway for the electric field between the electrodes. Relevance statement Electrochemotherapy of vertebral metastases should be performed using a transpedicular approach for the insertion of electrodes, without definitive sequelae at the spinal cord level. Key points Electrochemotherapy is a new treatment for vertebral metastases not accessible to radiotherapy, but it could result in spinal cord injury related to electrical trauma. In a swine model, the transpedicular approach has demonstrated no definitive sequelae at intraoperative neuromonitoring and during clinical follow-up. Electrochemotherapy should be performed using a transpedicular approach to avoid spinal cord damage.", "tags": ["Électrochimiothérapie", "Métastases vertébrales", "Voie transpédiculaire", "Neuromonitoring", "Sécurité médullaire", "Eur Radiol Exp"], "pdf_file": "pdfs/PMID_40906057.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1233, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/40906057/", "doi_url": "https://doi.org/10.1186/s41747-025-00607-9", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12411335/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12411335/"}, {"id": "pmid-39556172", "pmid": "39556172", "pmcid": "PMC11573955", "doi": "10.1186/s13244-024-01822-5", "title": "Percutaneous cryoablation in soft tissue tumor management: an educational review", "title_fr": "Cryoablation percutanée dans la prise en charge des tumeurs des parties molles : revue pédagogique et technique", "authors_list": ["Bodard S", "Geevarghese R", "Razakamanantsoa L", "Frandon J", "Petre EN", "Marcelin C", "Cornelis FH"], "authors_short": "Bodard S, Geevarghese R et al.", "journal": "Insights into imaging", "journal_short": "Insights Imaging", "impact_factor": 4.1, "year": 2024, "month_num": 11, "month_fr": "Nov.", "pub_date_fr": "Nov. 2024", "volume": "15", "issue": "1", "pages": "278", "category_id": "desmoid_soft_tissue", "category_label": "Cryoablation des Tumeurs Desmoïdes & Parties Molles", "category_short": "Cryo Desmoïdes & Tissus Mous", "category_color": "#06b6d4", "modality": "Scanner TDM / Échographie", "intervention_type": "Cryoablation", "cochin_link": "Guide pratique pour la cryoablation des masses des parties molles (tumeurs desmoïdes, nodules métastatiques paravertébraux ou du trapèze, schwannomes, malformations vasculaires) en HDJ Radio B.", "summary_fr_short": "Revue didactique (*Insights into Imaging*, 2024) détaillant la sélection des patients, la balistique des cryosondes, la synergie thermique et la prévention des complications lors de la cryoablation des tumeurs bénignes et malignes des parties molles (desmoïdes, endométriomes pariétaux, métastases musculaires et sous-cutanées).", "summary_fr_detailed": "Cet article passe en revue l'ensemble des indications de la cryoablation des tissus mous en radiologie interventionnelle oncologique et fonctionnelle. Il détaille l'effet cytotoxique biphasique (formation de cristaux de glace intracellulaires à -40 °C, apoptose périphérique et thrombose microvasculaire), ainsi que la gestion des localisations superficielles ou juxta-nerveuses. Pour les nodules métastatiques musculaires (trapèze, loge paravertébrale) ou les tumeurs desmoïdes, la cryoablation procure un contrôle local durable et une sédation rapide de la douleur par dénervation locale.", "protocol_fr": "Guidage mixte Échographie (insertion des sondes et contrôle Doppler) + Scanner (cartographie 3D de l'iceball) • Gant chaud ou hydrodissection sous-cutanée au sérum physiologique tiède pour protéger le derme • Suivi IRM à 3 mois avec soustraction dynamique.", "key_points_fr": ["L'isotherme létal (-20 °C à -40 °C) se situe à environ 3 à 5 mm en dedans de la limite visible du glaçon (0 °C) au scanner.", "Pour les nodules superficiels (trapèze, paroi thoracique), une hydrodissection sous-cutanée continue prévient efficacement la nécrose cutanée.", "Efficacité remarquable sur les localisations oligométastatiques des parties molles (mélanome, cancer du rein, sein, sarcomes).", "Possibilité de réaliser le geste sous anesthésie locale + sédation consciente pour les lésions de petite taille à distance des troncs moteurs."], "abstract_en": "Background Percutaneous cryoablation (PCA), having shown effectiveness in treating liver, lung, prostate, breast, and kidney tumors, is now gaining attention for the treatment of soft tissue tumors. PCA functions by freezing tissue, which induces ice crystal formation and cell death without damaging collagen structures. Technical considerations include the selection and handling of cryoprobes and cryogenic agents, procedural duration, and choice of image guidance for precision. This review aims to synthesize the mechanisms, applications, and technical aspects of PCA in the treatment of soft tissue tumors. Methods Adhering to PRISMA 2020 guidelines, a review was conducted of studies published prior to March 2024 that investigated PCA of soft tissue tumors. The review focused on technical and procedural aspects of cryoablation, cryobiological principles, cellular and tissue responses to extreme cold, intra- and post-procedure physiological mechanisms during and post-procedure, and main clinical applications. Results PCA is efficient in treating soft tissue tumors, including desmoid tumors, vascular malformations, and abdominal wall endometriosis. Several cryobiological mechanisms are involved, notably ice crystal formation, cellular dehydration, osmotic effects, and the inflammatory response, all of which contribute to its efficacy. Key technical aspects include the choice of cryoprobes, cryogenic agents (argon gas or liquid nitrogen), and the duration and control of freezing/thawing cycles. PCA also frequently outperformed traditional treatments like surgery and radiotherapy in terms of pain reduction, tumor size reduction, and patient outcomes. Moreover, its nerve sideration properties make it effective under local anesthesia. Conclusion Demonstrating substantial pain reduction, tumor size decrease, and high technical success rates, PCA offers a promising and minimally invasive alternative for soft tissue tumor treatment. Critical relevance statement Percutaneous cryoablation provides a minimally invasive, precise alternative for soft tissue tumor management, advancing clinical radiology by offering effective treatment with reduced patient risk and enhanced outcomes through image-guided procedures. Key points Percutaneous cryoablation (PCA) offers a promising, minimally invasive alternative for managing soft tissue tumors. PCA employs image-guided techniques to accurately target and treat tumors, ensuring high precision and control. PCA preserves structures like collagen, reduces pain, decreases tumor size, and generally enhances patient outcomes.", "tags": ["Cryoablation", "Parties molles", "Nodule paravertébral", "Trapèze", "Hydrodissection", "Insights into Imaging"], "pdf_file": "pdfs/PMID_39556172.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 2258, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/39556172/", "doi_url": "https://doi.org/10.1186/s13244-024-01822-5", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11573955/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11573955/"}, {"id": "pmid-39576446", "pmid": "39576446", "pmcid": "PMC11584811", "doi": "10.1186/s13244-024-01823-4", "title": "Percutaneous cryoablation of abdominal wall endometriosis: a systematic literature review of safety and efficacy", "title_fr": "Cryoablation percutanée de l'endométriose pariétale abdominale : revue systématique sur 10 ans de la sécurité et de l'efficacité", "authors_list": ["Bodard S", "Razakamanantsoa L", "Geevarghese R", "O'Gorman J", "Dohan A", "Marcelin C", "Cornelis FH"], "authors_short": "Bodard S, Razakamanantsoa L et al.", "journal": "Insights into imaging", "journal_short": "Insights Imaging", "impact_factor": 4.1, "year": 2024, "month_num": 11, "month_fr": "Nov.", "pub_date_fr": "Nov. 2024", "volume": "15", "issue": "1", "pages": "282", "category_id": "percutaneous_ablation_general", "category_label": "Ablation Percutanée Tumorale : Standards, Endométriome & Oncologie", "category_short": "Ablation Percutanée (Standards & Onco)", "category_color": "#e11d48", "modality": "Échographie / Scanner TDM", "intervention_type": "Cryoablation Pariétale", "cochin_link": "Issu de votre collection Zotero « Ablation percutanée » (Bodard et al., *Insights into Imaging*, nov. 2024) — Référence clé pour l'ablation percutanée des nodules d'endométriome de la paroi abdominale et des masses pariétales des parties molles.", "summary_fr_short": "Revue systématique sur 10 ans (8 études, *Insights into Imaging*, nov. 2024) démontrant que la cryoablation percutanée des endométriomes de la paroi abdominale (AWE) réduit la douleur médiane de 8/10 à 1/10 (p < 0,0001), avec 80 à 100 % de réponse antalgique complète et moins de 2 % de complications majeures.", "summary_fr_detailed": "L'endométriose pariétale abdominale (souvent sur cicatrice de césarienne ou laparoscopie) entraîne des douleurs cycliques invalidantes. La chirurgie d'exérèse large expose à un risque de défect aponévrotique et d'éventration. Cette revue systématique (2014–2024) confirme que la cryoablation guidée par échographie et/ou scanner offre une réponse antalgique complète dans 80 à 100 % des séries et une survie sans douleur locale médiane de 76,8 % au dernier suivi, sans aucun cas d'aggravation douloureuse post-procédurale et avec un profil de sécurité remarquable en ambulatoire.", "protocol_fr": "Planification IRM pelvienne/pariétale • Guidage échographique + contrôle TDM de l'iceball • Hydrodissection sous-cutanée (protection cutanée) et rétro-aponévrotique/pré-péritonéale si proximité digestive • 2 cycles de congélation couvrant le nodule fibreux avec marges.", "key_points_fr": ["Diminution spectaculaire de l'EVA douleur de 8/10 (IQR 7–9) à 1/10 (IQR 0–2) au suivi à long terme (p < 0,0001).", "Taux médian de réponse complète sur la douleur locale compris entre 80 % et 100 %.", "Préserve l'intégrité musculo-aponévrotique de la sangle abdominale (aucun recours à un filet prothétique).", "Hydrodissection indispensable pour protéger le derme superficiel en avant et le péritoine/anses digestives en profondeur."], "abstract_en": "Purpose To investigate over 10 years the safety and efficacy of percutaneous cryoablation for the treatment of abdominal wall endometriosis (AWE). Methods A systematic review was conducted of literature published between March 2014 and March 2024. Inclusion criteria focused on treatment efficacy studies, while exclusion criteria targeted case reports and studies lacking pertinent outcome data. Methodological quality was assessed using the Newcastle-Ottawa Scale for cohort studies. Results A total of eight studies were included. Local pain scores decreased from a median of 8/10 (interquartile range (IQR) 7-9) on the visual analog scale to 1/10 (IQR 0-2) at the last follow-up (p Conclusion In the last decade, percutaneous image-guided cryoablation has offered consistent results and appears to be a promising, minimally invasive option for AWE treatment. Prospective trials are now essential to establish cryoablation as a new standard in patient care for AWE. Critical relevance statement Over a decade-long study, percutaneous cryoablation has proven to be a safe and effective minimally invasive treatment for abdominal wall endometriosis, significantly reducing pain with minimal complications. Key points Percutaneous cryoablation significantly reduced local pain scores for abdominal wall endometriosis. The procedure demonstrated a favorable safety profile with minor complications. Cryoablation has emerged as a minimally invasive alternative to traditional treatments.", "tags": ["Endométriome pariétal", "Cryoablation", "Paroi abdominale", "Ablation percutanée", "Insights into Imaging", "Zotero"], "pdf_file": "pdfs/PMID_39576446.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 707, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/39576446/", "doi_url": "https://doi.org/10.1186/s13244-024-01823-4", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11584811/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11584811/"}, {"id": "pmid-38732352", "pmid": "38732352", "pmcid": "PMC11083160", "doi": "10.3390/diagnostics14090936", "title": "Electrochemotherapy in Spine Metastases: A Case Series Focused on Technical Aspects, Surgical Strategies and Results", "title_fr": "Électrochimiothérapie des métastases rachidiennes et osseuses complexes : aspects techniques, balistique et sécurité neurologique", "authors_list": ["Angelini A", "D'Amico A", "Paolilli S", "Signori R", "Baldin G", "Di Rubbo G", "Denaro L", "Ruggieri P"], "authors_short": "Angelini A, D'Amico A et al.", "journal": "Diagnostics (Basel, Switzerland)", "journal_short": "Diagnostics", "impact_factor": 3.0, "year": 2024, "month_num": 4, "month_fr": "Avr.", "pub_date_fr": "Avr. 2024", "volume": "14", "issue": "9", "pages": "936", "category_id": "ect_mets", "category_label": "Électrochimiothérapie (ECT) & Métastases Osseuses", "category_short": "ECT (Bléomycine) & Métastases", "category_color": "#eab308", "modality": "Scanner TDM", "intervention_type": "Électrochimiothérapie (ECT)", "cochin_link": "Fournit les abaques techniques de placement des électrodes et de sécurité neurologique lors des procédures d'ECT réalisées en Radiologie B en collaboration avec l'HEGP.", "summary_fr_short": "Étude technique détaillant la mise en œuvre de l'électrochimiothérapie (ECT) pour les métastases osseuses à haut risque neurologique ou mécanique. Grâce à son mécanisme non thermique, l'ECT permet de traiter des lésions au contact direct d'éléments nerveux ou articulaires là où la radiofréquence et la cryoablation seules exposeraient à des complications.", "summary_fr_detailed": "Cet article analyse les paramètres pratiques d'implantation des électrodes d'électroporation dans l'os pathologique, la vérification de la couverture du champ électrique et les résultats cliniques sur la douleur (échelle EVA) et le contrôle tumoral local en imagerie. L'étude souligne l'importance de la synchronisation anesthésique (curarisation profonde au moment des impulsions électriques et limitation de la FiO2 sous bléomycine) et confirme l'absence de nécrose thermique des tissus sains environnants.", "protocol_fr": "Planification TDM de la géométrie des aiguilles • Curarisation per-procédurale pour limiter les secousses musculaires lors des impulsions • FiO2 < 30 % pendant l'anesthésie générale (prévention de la toxicité pulmonaire de la bléomycine) • Contrôle IRM à 6–12 semaines.", "key_points_fr": ["Précaution anesthésique essentielle : maintenir une FiO2 minimale (< 30 %) lors de l'AG après administration de bléomycine.", "Permet une destruction tumorale sélective au contact immédiat des structures nerveuses ou cutanées (pied, cheville, épidure).", "Diminution rapide et durable de l'EVA douleur et réduction de la consommation d'opioïdes dès le premier mois.", "Peut être associée dans le même temps opératoire à une cryoablation centrale (debulking) avec couronne périphérique d'ECT."], "abstract_en": "Metastases are complications of primary tumors due to prolonged cancer survival and have become an important issue for oncological patients and the most frequent cause of death and disability. Bone metastases occur at a later stage of cancer disease, and the spine is the most frequent site. To date, the aim of the treatment of metastases remains to be the control of disease and provide a satisfactory quality of life. The decision making of treatment is influenced by several factors such as the status of the primary disease, the number of metastases, site involvement, and the performance status of the patients. For this reason, the treatment of metastases is challenging and undergoes constant development. Therefore, alternative techniques with respect to surgery, which is the first option but not always practicable, and radiochemotherapy are attractive. Lately, electrochemotherapy has emerged as an innovative method for treating various primary and metastatic solid tumors, showing promising outcomes in terms of inducing tumor tissue necrosis and alleviating symptoms. This technique uses electric pulses to increase the uptake of chemotherapy by tumor cells. Despite the initial enthusiasm and good results in the treatment of bone tumors, relatively few papers have described its use in spine metastases. Therefore, we conducted a systemic review of this intriguing topic while also reporting our experience in the use of electrochemotherapy for the treatment of spine metastases.", "tags": ["Électrochimiothérapie", "ECT", "Bléomycine", "Sécurité neurologique", "Métastases", "Scanner"], "pdf_file": "pdfs/PMID_38732352.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 16159, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/38732352/", "doi_url": "https://doi.org/10.3390/diagnostics14090936", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11083160/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11083160/"}, {"id": "pmid-38438685", "pmid": "38438685", "pmcid": "", "doi": "10.1007/s00270-024-03669-1", "title": "Safety and Efficacy of Percutaneous Morton Neuroma Cryoneurolysis Under Ultrasound Guidance", "title_fr": "Sécurité et efficacité de la cryoneurolyse percutanée du névrome de Morton sous anesthésie locale", "authors_list": ["Moulin B", "Angelopoulos G", "Sarrazin JL", "Romano S", "Vignaux O", "Guenoun T", "Di Primio M", "Hakime A"], "authors_short": "Moulin B, Angelopoulos G et al.", "journal": "Cardiovascular and interventional radiology", "journal_short": "CVIR", "impact_factor": 2.8, "year": 2024, "month_num": 3, "month_fr": "Mars", "pub_date_fr": "Mars 2024", "volume": "47", "issue": "6", "pages": "795-800", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Échographie / Scanner TDM", "intervention_type": "Cryoneurolyse (Morton)", "cochin_link": "Référence centrale pour les cryothérapies de névrome de Morton (3e espace inter-métatarsien) réalisées sous anesthésie locale au scanner à Cochin par le Dr Thomas Lefèvre.", "summary_fr_short": "Étude de *CardioVascular and Interventional Radiology (CVIR)* (2024) évaluant la cryoneurolyse percutanée du névrome de Morton réfractaire au traitement conservateur. Réalisée en ambulatoire sous anesthésie locale, la cryoablation induit une dégénérescence wallérienne réversible (axonotmésis) sans formation de névrome d'amputation, avec un succès clinique supérieur à 80 %.", "summary_fr_detailed": "Le névrome de Morton correspond à une fibrose périneurale du nerf digital plantaire commun (le plus souvent au 3e espace inter-métatarsien). La chirurgie d'exérèse (neurectomie) expose au risque redouté de névrome de moignon douloureux ('stump neuroma') et de cicatrice plantaire. La cryoneurolyse percutanée par voie dorsale ou dans l'axe de l'espace inter-métatarsien détruit les axones tout en préservant l'architecture de l'endonèvre et du périnèvre. Cette série de 2024 confirme une réduction majeure de l'EVA douleur, une reprise immédiate de la marche et une tolérance remarquable sous simple anesthésie locale.", "protocol_fr": "Sous anesthésie locale stricte (lidocaïne à proximité du nerf en amont) • Abord dorsal ou commissural dans l'axe du 3e espace inter-métatarsien sous guidage TDM et/ou échographique • Cryosonde fine (17G ou aiguille de cryoneurolyse) centrée sur le névrome • 2 cycles de congélation de 2 à 3 minutes séparés d'une décongélation de 1 minute • Vérification de la distance à la peau plantaire et dorsale (> 5 mm ou hydrodissection).", "key_points_fr": ["Réalisable en ambulatoire strict sous anesthésie locale (AL) avec reprise immédiate de l'appui à la sortie du scanner.", "Contrairement à la chirurgie ou à l'alcoolisation, la cryoneurolyse respecte la gaine conjonctive nerveuse (axonotmésis de type II de Sunderland) et ne crée jamais de névrome d'amputation.", "Taux de satisfaction et de réduction significative des douleurs > 80–85 % à 6 et 12 mois.", "Protection cutanée essentielle dans l'espace inter-métatarsien étroit : contrôle de l'extension du glaçon au scanner/écho et hydrodissection sous-cutanée dorsale si nécessaire."], "abstract_en": "Purpose To assess the technical success, safety and early efficacy of Morton neuroma (MN) cryoneurolysis. Materials and methods Retrospective review of 54 consecutive patients with MN treated with cryoneurolysis after failure of conservative treatment, from September 2022 to June 2023. Outcomes measurements included technical success (defined a successful ultrasound-guided placement of the cryoprobe), procedural safety according to Cirse classification and change in 6 months post-procedure by pain numeric rating scale (pNRS). Results A total of 59 MN were treated during 55 procedures. Mean procedure duration was 47 min, all patients were discharged 2 h after the intervention. Technical success was 98.1%. No Cirse grade 3, 4 or 5 complication was reported. Three grade 2 complication occurred, including two chilblain-type lesions and one bone insufficiency fracture. At 6 months post-procedure, pNRS score was significantly decreased (2.7 ± 2.2 vs 7.1 ± 1.1) (p Conclusion Cryoneurolysis seems to be safe for the treatment of Morton neuroma. Six-month pain relief is promising and needs to be confirmed at long term.", "tags": ["Névrome de Morton", "Cryoneurolyse", "Cryoablation", "Anesthésie locale", "Avant-pied", "CVIR 2024"], "pdf_file": "pdfs/PMID_38438685.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 424, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/38438685/", "doi_url": "https://doi.org/10.1007/s00270-024-03669-1", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00270-024-03669-1"}, {"id": "pmid-38544877", "pmid": "38544877", "pmcid": "PMC10965423", "doi": "10.1093/bjro/tzae007", "title": "Cementoplasty to cryoablation: review and current status", "title_fr": "De la cimentoplastie à la cryoablation et à l'ostéosynthèse percutanée : état de l'art en radiologie interventionnelle osseuse", "authors_list": ["Tan JR", "Yan YY", "Sheikh A", "Ouellette H", "Mallinson P", "Munk PL"], "authors_short": "Tan JR, Yan YY et al.", "journal": "BJR open", "journal_short": "BJR Open", "impact_factor": 1.3, "year": 2024, "month_num": 1, "month_fr": "Janv.", "pub_date_fr": "Janv. 2024", "volume": "6", "issue": "1", "pages": "tzae007", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Scanner TDM / Cone-Beam CT", "intervention_type": "Consolidation & Ablation Combinées", "cochin_link": "Synthétise la stratégie multimodale appliquée à Cochin : associer destruction tumorale (cryoablation/RF) et consolidation mécanique (cimentoplastie / vissage) en une seule séance.", "summary_fr_short": "Revue générale (*BJR Open*, 2024) détaillant l'évolution des gestes percutanés osseux : critères de sélection entre cimentoplastie seule, ostéosynthèse par vis canulées et association ablation thermique + consolidation selon la classification de Mirels et le score SINS.", "summary_fr_detailed": "Cet article propose un algorithme décisionnel complet pour le radiologue interventionnel ostéo-articulaire. Il précise les propriétés biomécaniques du ciment PMMA (excellente résistance aux forces de compression au rachis et au toit du cotyle, mais résistance limitée aux forces de torsion et de traction sur le bassin postérieur et les os longs, justifiant l'association au vissage percutané). Il détaille également la chronologie optimale lors des gestes combinés : réaliser la cryoablation suivie d'un réchauffement complet de la loge avant d'injecter le ciment PMMA afin de ne pas altérer sa polymérisation.", "protocol_fr": "Évaluation biomécanique pré-opératoire (score SINS au rachis, localisation en zone portante au bassin) • En cas de geste combiné Cryo + Cimentoplastie : attendre la décongélation complète du glaçon avant d'injecter le PMMA.", "key_points_fr": ["Le ciment PMMA résiste parfaitement à la compression (corps vertébral, toit du cotyle) mais nécessite des vis canulées en zone de cisaillement (anneau pelvien, col fémoral).", "Toujours attendre la fonte du glaçon après cryoablation avant d'injecter le ciment pour éviter une polymérisation retardée ou des fuites.", "La cryoablation préalable réduit la pression intra-tumorale et diminue le risque de fuite veineuse ou épidurale de ciment.", "L'évaluation multidisciplinaire (radiologue interventionnel, orthopédiste, oncologue, anesthésiste) optimise le calendrier vis-à-vis de la radiothérapie."], "abstract_en": "Recent advances in percutaneous image-guided techniques have empowered interventional radiologists with diverse treatment options for the management of musculoskeletal lesions. Of note, there is growing utility for cementoplasty procedures, with indications ranging from stabilization of bone metastases to treatment of painful vertebral compression fractures. Likewise, cryoablation has emerged as a viable adjunct in the treatment of both primary and secondary bone and soft tissue neoplasms. These treatment options have been progressively incorporated into the multidisciplinary approach to holistic care of patients, alongside conventional radiotherapy, systemic therapy, surgery, and analgesia. This review article serves to outline the indications, technical considerations, latest developments, and evidence for the burgeoning role of cementoplasty and cryoablation in the musculoskeletal system, with an emphasis on pain palliation and tumour control.", "tags": ["Cimentoplastie", "Cryoablation", "Ostéosynthèse", "PMMA", "Biomécanique", "BJR Open"], "pdf_file": "pdfs/PMID_38544877.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 3352, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/38544877/", "doi_url": "https://doi.org/10.1093/bjro/tzae007", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10965423/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10965423/"}, {"id": "pmid-37834793", "pmid": "37834793", "pmcid": "PMC10573742", "doi": "10.3390/jcm12196150", "title": "Electrochemotherapy in the Treatment of Bone Metastases: A Systematic Review", "title_fr": "L'électrochimiothérapie (ECT) dans le traitement des métastases osseuses : revue systématique de la littérature", "authors_list": ["Bocchi MB", "Meschini C", "Pietramala S", "Perna A", "Oliva MS", "Matrangolo MR", "Ziranu A", "Maccauro G", "Vitiello R"], "authors_short": "Bocchi MB, Meschini C et al.", "journal": "Journal of clinical medicine", "journal_short": "J Clin Med", "impact_factor": 3.0, "year": 2023, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2023", "volume": "12", "issue": "19", "pages": "6150", "category_id": "ect_mets", "category_label": "Électrochimiothérapie (ECT) & Métastases Osseuses", "category_short": "ECT (Bléomycine) & Métastases", "category_color": "#eab308", "modality": "Scanner TDM / Fluoroscopie", "intervention_type": "Électrochimiothérapie (ECT)", "cochin_link": "Correspond directement aux séances d'Électrochimiothérapie (ECT sous Bléomycine 30 mg IV avec générateur IGEA) réalisées au scanner Achard -1 à Cochin, seules ou combinées à la cryoablation.", "summary_fr_short": "Revue systématique évaluant l'efficacité et la sécurité de l'électrochimiothérapie (ECT à la bléomycine) dans les métastases osseuses appendiculaires, pelviennes et rachidiennes. L'ECT associe l'injection intraveineuse de bléomycine à des impulsions électriques réversibles qui perméabilisent la membrane des cellules tumorales sans détruire la trame osseuse ni les structures nerveuses adjacentes.", "summary_fr_detailed": "Contrairement aux ablations thermiques (RF, cryoablation, micro-ondes), l'électrochimiothérapie (ECT) est une modalité non thermique basée sur l'électroporation réversible : des impulsions électriques de haut voltage ouvrent temporairement des nanopores membranaires, multipliant par plus de 1000 la pénétration intracellulaire de la bléomycine. Cette revue systématique démontre un contrôle antalgique majeur chez plus de 75–85 % des patients et une préservation unique de la résistance mécanique des travées osseuses, du cartilage articulaire et des gaines nerveuses, permettant de traiter des localisations complexes (pied, rachis, péri-articulaire).", "protocol_fr": "Positionnement parallèle des électrodes aiguilles sous guidage TDM selon la géométrie tumorale (espacement 1,5 à 2,5 cm) • Bolus IV de Bléomycine (15 000 UI/m² soit ~25–30 mg) • Fenêtre thérapeutique d'électroporation entre 8 min et 40 min post-injection (8 impulsions de 100 µs à 1000 V/cm par paire d'électrodes) sous AG avec curarisation.", "key_points_fr": ["Respect absolu de la fenêtre pharmacocinétique : délivrance des impulsions électriques entre 8 et 40 minutes après le bolus IV de bléomycine.", "Absence d'effet thermique délétère : préserve la matrice extracellulaire osseuse, l'os sous-chondral, les vaisseaux et les nerfs périphériques.", "Indication de choix pour les métastases osseuses distales (pied, main), juxta-articulaires ou radiorésistantes (cancer du rein, mélanome).", "Synergie remarquable avec la cryoablation ('Cryo + ECT') ou la cimentoplastie pour les lésions volumineuses ostéolytiques."], "abstract_en": "Background and aim Cancers are one of the most frequent causes of death and disability in humans. Skeletal involvement has a major impact on the quality of life and prognosis of cancer patients. Electrochemotherapy is a palliative and minimally invasive oncologic treatment that was first used to treat subcutaneous nodules for malignant tumors. The aim of our review is to evaluate the results of electrochemotherapy in the treatment of bone metastases. Methods A systematic review of the literature indexed in the PubMed MEDLINE and Cochrane Library databases using the search key words \"electrochemotherapy\" AND (\"metastasis\" OR \"metastases\") was performed. The Preferred Reporting Items for Systematic Reviews and MetaAnalyses was followed. Inclusion criteria were proven involvement of the appendicular skeleton in metastatic carcinoma or melanoma, through at least one percutaneous electrochemotherapy session on the metastatic bone lesion. The exclusion criterion was no skeletal metastatic involvement. Results Eight articles were finally included. We reached a population of 246 patients. The mean age and follow up were 60.1 years old and 11.4 months, respectively. The most represented primary tumor was breast cancer (18.9%). A total of 250 bone lesions were treated with electrochemotherapy. According to RECIST criteria, in our population we observed 55.5% stable diseases. The mean pre-electrochemotherapy VAS value was 6.9, which lowered to 2.7 after treatment. Adverse events occurred in 3.4% of patients. Conclusions Electrochemotherapy as a minimally invasive and tissue-sparing treatment should be considered for patients with no other alternative to obtain tumor control and improvement in quality of life.", "tags": ["Électrochimiothérapie", "ECT", "Bléomycine", "Métastases osseuses", "Pied", "IGEA"], "pdf_file": "pdfs/PMID_37834793.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 702, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37834793/", "doi_url": "https://doi.org/10.3390/jcm12196150", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10573742/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10573742/"}, {"id": "pmid-37742284", "pmid": "37742284", "pmcid": "", "doi": "10.1111/1754-9485.13587", "title": "Interventional management of malignant bone tumours", "title_fr": "Prise en charge interventionnelle des tumeurs osseuses malignes : le paradigme palliatif-curatif", "authors_list": ["Cazzato RL", "Garnon J", "Jennings JW", "Gangi A"], "authors_short": "Cazzato RL, Garnon J et al.", "journal": "Journal of medical imaging and radiation oncology", "journal_short": "J Med Imaging Radiat Oncol", "impact_factor": 1.8, "year": 2023, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2023", "volume": "67", "issue": "8", "pages": "862-869", "category_id": "percutaneous_ablation_general", "category_label": "Ablation Percutanée Tumorale : Standards, Endométriome & Oncologie", "category_short": "Ablation Percutanée (Standards & Onco)", "category_color": "#e11d48", "modality": "Scanner TDM / Fluoroscopie", "intervention_type": "Ablation + Consolidation Osseuse", "cochin_link": "Issu de votre collection Zotero « Ablation percutanée » (*J Med Imaging Radiat Oncol*, déc. 2023) — Synthèse décisionnelle structurant l'association ablation (cryo, RF, ECT) et consolidation (cimentoplastie, vissage) en oncologie osseuse.", "summary_fr_short": "Revue clinique (*JMIRO*, déc. 2023) structurant la radiologie interventionnelle des tumeurs osseuses malignes autour du paradigme « palliatif–curatif », articulant techniques d'ablation (cryoablation, RF, micro-ondes, électrochimiothérapie) et techniques de consolidation (cimentoplastie, ostéosynthèse percutanée).", "summary_fr_detailed": "Cet article propose un cadre décisionnel pragmatique pour le radiologue interventionnel face aux métastases osseuses et tumeurs malignes primitives. Il distingue l'approche palliative (soulagement rapide de la douleur et prévention fracturaire par cimentoplastie/vissage +/- ablation de debulking) de l'approche curative (destruction A0 avec marges de sécurité chez le patient oligométastatique). Il compare les avantages respectifs de la cryoablation, de la radiofréquence, des micro-ondes et de l'électrochimiothérapie selon la topographie (rachis vs bassin vs os longs) et la proximité nerveuse.", "protocol_fr": "Évaluation multidisciplinaire (score SINS au rachis, Mirels sur os longs, Harrington au cotyle) • Choix de la modalité ablative selon la taille et la matrice osseuse • Consolidation systématique par ciment PMMA et/ou vis canulées en zone de contrainte mécanique.", "key_points_fr": ["Articulation claire du paradigme « palliatif vs curatif » en radiologie interventionnelle oncologique osseuse.", "Complémentarité systématique entre destruction tumorale (cryoablation / RF / ECT) et stabilisation mécanique (cimentoplastie / vissage).", "Intégration des scores d'instabilité mécanique (SINS, Mirels) dans l'arbre décisionnel interventionnel.", "Place spécifique de l'électrochimiothérapie et de la cryoablation sous neuromonitoring pour les lésions péri-nerveuses."], "abstract_en": "In the last few decades, interventional radiology (IR) has significantly increased its role in the management of bone tumours including bone metastases (BM) that represent the most common type of tumour involving the bone. The current IR management of BM is based on the 'palliative-curative' paradigm and relies on the use of consolidative (i.e. osteplasty, osteosynthesis) and/or ablation (i.e. cryoablation, radiofrequency ablation, electrochemotherapy) techniques. The present narrative review will overview the current role of IR for the management of BM.", "tags": ["Tumeurs osseuses malignes", "Paradigme palliatif-curatif", "Ablation thermique", "Consolidation", "Zotero"], "pdf_file": null, "pdf_source": "external_link", "pdf_size_kb": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37742284/", "doi_url": "https://doi.org/10.1111/1754-9485.13587", "pmc_url": "", "article_url": "https://doi.org/10.1111/1754-9485.13587"}, {"id": "pmid-37504355", "pmid": "37504355", "pmcid": "PMC10377811", "doi": "10.3390/curroncol30070495", "title": "The New Ice Age of Musculoskeletal Intervention: Role of Percutaneous Cryoablation in Bone and Soft Tissue Tumors", "title_fr": "Le rôle de la cryoablation percutanée dans les métastases osseuses : contrôle local, debulking et antalgie", "authors_list": ["Papalexis N", "Savarese LG", "Peta G", "Errani C", "Tuzzato G", "Spinnato P", "Ponti F", "Miceli M", "Facchini G"], "authors_short": "Papalexis N, Savarese LG et al.", "journal": "Current oncology (Toronto, Ont.)", "journal_short": "Curr Oncol", "impact_factor": 2.8, "year": 2023, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2023", "volume": "30", "issue": "7", "pages": "6744-6770", "category_id": "ect_mets", "category_label": "Électrochimiothérapie (ECT) & Métastases Osseuses", "category_short": "ECT (Bléomycine) & Métastases", "category_color": "#eab308", "modality": "Scanner TDM", "intervention_type": "Cryoablation", "cochin_link": "Directement applicable aux cryoablations de métastases osseuses et pariétales (paroi thoracique, bassin, pied, trapèze) programmées en HDJ Radio B.", "summary_fr_short": "Revue complète sur la cryoablation percutanée des métastases osseuses à visée palliative (antalgique / debulking) ou curative (maladie oligométastatique). Analyse des résultats cliniques, du couplage avec les thérapies systémiques (anti-angiogéniques comme le lenvatinib, immunothérapie) et des techniques de consolidation associées.", "summary_fr_detailed": "La cryoablation s'est imposée comme la technique de choix pour les métastases osseuses douloureuses ou oligométastatiques, notamment celles comportant une extension dans les parties molles. La visualisation directe du glaçon au scanner permet de traiter des volumes complexes tout en protégeant la peau, la plèvre ou les nerfs adjacents. L'article discute également la gestion péri-procédurale des thérapies ciblées anti-angiogéniques (tels que le lenvatinib ou le cabozantinib dans le cancer du rein métastatique) afin d'optimiser la cicatrisation cutanée et d'éviter les complications hémorragiques.", "protocol_fr": "Suspension temporaire concertée avec l'oncologue des ITK anti-angiogéniques (ex: Lenvatinib 48–72h avant/après selon demi-vie et risque cutané) • Double cycle de congélation 10 min • Consolidation par cimentoplastie ou vissage si atteinte d'une zone de contrainte mécanique.", "key_points_fr": ["Soulagement antalgique significatif chez > 80 % des patients rebelles aux morphiniques ou après échec de la radiothérapie externe.", "Taux de contrôle local à 1 an de 85 à 92 % dans les indications oligométastatiques (marges d'ablation ≥ 5 mm).", "Dans les localisations distales (pied, main) ou sous anti-angiogéniques (Lenvatinib), vigilance accrue sur la protection cutanée.", "Pour les douleurs pariétales thoraciques oncologiques, la cryoablation associe destruction tumorale et cryoneurolyse intercostale."], "abstract_en": "In the rapidly evolving field of interventional oncology, minimally invasive methods, including CT-guided cryoablation, play an increasingly important role in tumor treatment, notably in bone and soft tissue cancers. Cryoablation works using compressed gas-filled probes to freeze tumor cells to temperatures below -20 °C, exploiting the Joule-Thompson effect. This cooling causes cell destruction by forming intracellular ice crystals and disrupting blood flow through endothelial cell damage, leading to local ischemia and devascularization. Coupling this with CT technology enables precise tumor targeting, preserving healthy surrounding tissues and decreasing postoperative complications. This review reports the most important literature on CT-guided cryoablation's application in musculoskeletal oncology, including sarcoma, bone metastases, and bone and soft tissue benign primary tumors, reporting on the success rate, recurrence rate, complications, and technical aspects to maximize success for cryoablation in the musculoskeletal system.", "tags": ["Cryoablation", "Métastases osseuses", "Paroi thoracique", "Lenvatinib", "Cancer du rein", "Debulking"], "pdf_file": "pdfs/PMID_37504355.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1779, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37504355/", "doi_url": "https://doi.org/10.3390/curroncol30070495", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10377811/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10377811/"}, {"id": "pmid-37030078", "pmid": "37030078", "pmcid": "", "doi": "10.1016/j.ejca.2023.03.012", "title": "Electrochemotherapy in radiotherapy-resistant epidural spinal cord compression in metastatic cancer patients", "title_fr": "Électrochimiothérapie (ECT) des compressions médullaires épidurales métastatiques réfractaires à la radiothérapie", "authors_list": ["Deschamps F", "Tselikas L", "Yevich S", "Bonnet B", "Roux C", "Kobe A", "Besse B", "Berthelot K", "Gaudin A", "Mir LM", "de Baere T"], "authors_short": "Deschamps F, Tselikas L et al.", "journal": "European journal of cancer (Oxford, England : 1990)", "journal_short": "Eur J Cancer", "impact_factor": 7.6, "year": 2023, "month_num": 3, "month_fr": "Mars", "pub_date_fr": "Mars 2023", "volume": "186", "issue": "", "pages": "62-68", "category_id": "ect_mets", "category_label": "Électrochimiothérapie (ECT) & Métastases Osseuses", "category_short": "ECT (Bléomycine) & Métastases", "category_color": "#eab308", "modality": "Scanner TDM", "intervention_type": "Électrochimiothérapie (ECT Rachis)", "cochin_link": "Issu de votre collection Zotero « Ablation percutanée » (Deschamps, Tselikas et al., *Eur J Cancer*, juin 2023) — Étude majeure justifiant le recours à l'ECT (Bléomycine IV) pour les lésions vertébrales et épidurales radio-résistantes sans recours chirurgical possible.", "summary_fr_short": "Série princeps (*European Journal of Cancer*, juin 2023) chez 40 patients présentant une compression médullaire épidurale métastatique (MESCC) réfractaire à la radiothérapie : l'électrochimiothérapie percutanée à la bléomycine réduit l'EVA médiane de 7/10 à 1/10 à 1 mois (p < 0,001), améliore le statut neurologique chez 56 % des patients et obtient 77 % de réponse objective épidurale en IRM.", "summary_fr_detailed": "Lorsque la compression médullaire ou radiculaire épidurale récidive après radiothérapie chez des patients non opérables, l'ablation thermique (RF, cryoablation) est contre-indiquée au contact direct du cordon médullaire en raison de la neurotoxicité thermique irréversible. L'électrochimiothérapie (ECT) détruit sélectivement les cellules tumorales en division par électroporation réversible + bléomycine tout en respectant la trame conjonctive et les structures nerveuses adjacentes. Sur 40 patients consécutifs, l'IRM à 1 mois montre 46 % de réponse complète et 31 % de réponse partielle selon le score de Bilsky (ESCCS), démontrant que l'ECT peut sauver des compressions médullaires en impasse thérapeutique.", "protocol_fr": "Sous AG • Mise en place transpédiculaire ou paravertébrale d'électrodes aiguilles encadrant la coulée épidurale sous TDM • Bolus IV de Bléomycine (15 000 UI/m² ou dose fixe adaptée) • Délivrance des impulsions électriques entre 8 et 28 min post-injection • Contrôle IRM à 1 et 3 mois (score ESCCS).", "key_points_fr": ["Chute majeure de la douleur médiane de 7/10 à 1/10 à 1 mois et 2/10 à 3 mois (p < 0,001).", "Amélioration neurologique marquée ou modérée chez 56 % des patients à 1 mois (et stabilisation chez 38 %).", "Réponse radiologique objective sur le contingent épidural en IRM (score ESCCS) chez 77 % des patients à 1 mois (46 % complète, 31 % partielle).", "Seule technique ablative percutanée utilisable au contact immédiat du fourreau dural et de la moelle épinière après échec de la radiothérapie."], "abstract_en": "Objective To report efficacy and safety of percutaneous electrochemotherapy (ECT) in patients with radiotherapy-resistant metastatic epidural spinal cord compression (MESCC). Material/ methods This retrospective study analyzed all consecutive patients treated with bleomycin-based ECT between February-2020 and September-2022 in a single tertiary referral cancer center. Changes in pain were evaluated with the Numerical Rating Score (NRS), in neurological deficit with the Neurological Deficit Scale, and changes in epidural spinal cord compression were evaluated with the epidural spinal cord compression scale (ESCCS) using an MRI. Results Forty consecutive solid tumour patients with previously radiated MESCC and no effective systemic treatment options were eligible. With a median follow-up of 5.1 months [1-19.1], toxicities were temporary acute radicular pain (25%), prolonged radicular hypoesthesia (10%), and paraplegia (7.5%). At 1 month, pain was significantly improved over baseline (median NRS: 1.0 [0-8] versus 7.0 [1.0-10], P Conclusions This study provides the first evidence that ECT can rescue radiotherapy-resistant MESCC.", "tags": ["Électrochimiothérapie", "Compression médullaire", "Épidurite", "Bléomycine", "Rachis", "Eur J Cancer", "Zotero"], "pdf_file": "pdfs/PMID_37030078.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 484, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37030078/", "doi_url": "https://doi.org/10.1016/j.ejca.2023.03.012", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.ejca.2023.03.012"}, {"id": "pmid-35941207", "pmid": "35941207", "pmcid": "PMC9360065", "doi": "10.1007/s00247-022-05396-6", "title": "Update on aneurysmal bone cyst: pathophysiology, histology, imaging and treatment", "title_fr": "Mise au point sur le kyste osseux anévrismal (KOA) : physiopathologie, imagerie et sclérothérapie percutanée", "authors_list": ["Restrepo R", "Zahrah D", "Pelaez L", "Temple HT", "Murakami JW"], "authors_short": "Restrepo R, Zahrah D et al.", "journal": "Pediatric radiology", "journal_short": "Pediatr Radiol", "impact_factor": 2.1, "year": 2022, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2022", "volume": "52", "issue": "9", "pages": "1601-1614", "category_id": "cyst_sclerotherapy", "category_label": "Alcoolisation & Sclérothérapie des Kystes Osseux", "category_short": "Alcoolisation KOA / KOE", "category_color": "#10b981", "modality": "Scanner TDM / Fluoroscopie / Écho", "intervention_type": "Sclérothérapie / Alcoolisation", "cochin_link": "Directement lié au suivi TDM à 1 an des kystes osseux anévrismaux (KOA de l'humérus) et aux alcoolisations de kystes osseux en HDJ Radio B.", "summary_fr_short": "Mise au point de référence (*Pediatric Radiology*, 2022) sur le kyste osseux anévrismal (KOA) primaire (réarrangement du gène *USP6*) : sémiologie IRM/TDM, diagnostic différentiel avec l'ostéosarcome télangiectasique et protocoles de sclérothérapie percutanée (éthanol absolu, polidocanol, doxycycline).", "summary_fr_detailed": "La découverte de la translocation du gène *USP6* a confirmé la nature néoplasique bénigne du KOA primaire, distinct des formes secondaires réactionnelles à un chondroblastome ou une tumeur à cellules géantes. Sur le plan thérapeutique, la sclérothérapie percutanée (alcoolisation à l'éthanol absolu gélifié ou liquide, polidocanol, doxycycline) a largement remplacé le curetage chirurgical, avec d'excellents taux d'ossification progressive et moins de morbidité fonctionnelle. Le suivi repose sur la tomodensitométrie et la radiographie à 6 et 12 mois pour objectiver l'épaississement cortical et la trabéculation des logettes.", "protocol_fr": "Biopsie préalable systématique si atypie clinique ou radiologique (recherche réarrangement USP6, exclusion ostéosarcome télangiectasique) • Ponction des logettes sous TDM/ampli avec kystographie iodée pour exclure un drainage veineux rapide • Injection de l'agent sclérosant (éthanol 96 % / éthylcellulose ou polidocanol) • Contrôle TDM à 6–12 mois.", "key_points_fr": ["Toute lésion kystique multiloculée à niveaux liquide-liquide atypique doit bénéficier d'une confirmation histologique/moléculaire (USP6) avant sclérothérapie.", "La kystographie préalable au produit de contraste iodé est indispensable avant alcoolisation pour éliminer une fuite veineuse directe ou un passage articulaire.", "La guérison radiologique au scanner se traduit par un épaississement cortical progressif, une disparition de l'effet soufflant et une ossification centripète sur 6 à 24 mois.", "Une ossification partielle asymptomatique avec corticale solide au scanner à 1 an ne nécessite pas de nouveau geste."], "abstract_en": "Aneurysmal bone cyst (ABC) is a benign but locally aggressive lesion that predominantly affects children and young adults. ABC, which accounts for approximately 70% of the cases, is now recognized to be a true neoplasm, whereas ABC-like changes associated to other bone neoplasms (also referred in the literature as secondary ABC) accounts for the remaining 30%. The solid variant of ABC is also considered a true neoplasm but is rare. ABC can involve any bone in the body, and although it has a metaphyseal preference, it can involve any part of a bone and soft tissues. As with any bone tumor, the initial evaluation of ABCs should be done with radiographs followed by magnetic resonance imaging or less frequently computed tomography for further characterization. The imaging appearance of ABC is variable; however, a lytic and expansile lesion with fluid-fluid levels is the most common presentation. The main differential diagnosis of an ABC in the pediatric population is unicameral bone cyst (UBC) and telangiectatic osteosarcoma, therefore a biopsy is recommended before treatment. The therapeutic options of ABC range from curettage with or without adjuncts such as phenol, liquid nitrogen, argon laser and bone grafting or bone substitutes to more recently employed alternatives such as image-guided sclerotherapy with various sclerosing agents and monoclonal antibodies (e.g., Denosumab).", "tags": ["Kyste osseux anévrismal", "KOA", "Alcoolisation", "Sclérothérapie", "USP6", "Humérus"], "pdf_file": "pdfs/PMID_35941207.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 2022, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/35941207/", "doi_url": "https://doi.org/10.1007/s00247-022-05396-6", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9360065/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9360065/"}, {"id": "pmid-35348870", "pmid": "35348870", "pmcid": "PMC9018647", "doi": "10.1007/s00270-022-03126-x", "title": "CIRSE Standards of Practice on Thermal Ablation of Bone Tumours", "title_fr": "Recommandations et Standards de Pratique du CIRSE sur l'ablation thermique des tumeurs osseuses", "authors_list": ["Ryan A", "Byrne C", "Pusceddu C", "Buy X", "Tsoumakidou G", "Filippiadis D"], "authors_short": "Ryan A, Byrne C et al.", "journal": "Cardiovascular and interventional radiology", "journal_short": "CVIR", "impact_factor": 2.8, "year": 2022, "month_num": 3, "month_fr": "Mars", "pub_date_fr": "Mars 2022", "volume": "45", "issue": "5", "pages": "591-605", "category_id": "percutaneous_ablation_general", "category_label": "Ablation Percutanée Tumorale : Standards, Endométriome & Oncologie", "category_short": "Ablation Percutanée (Standards & Onco)", "category_color": "#e11d48", "modality": "Scanner TDM / IRM / Fluoroscopie", "intervention_type": "Standards CIRSE (RF / Cryo / MW / Laser)", "cochin_link": "Issu de votre collection Zotero « Ablation percutanée » (Ryan, Tsoumakidou, Buy, Gangi et al., *CVIR*, mai 2022) — Référentiel européen officiel encadrant les standards techniques, la thermoprotection et les indications d'ablation osseuse à Cochin.", "summary_fr_short": "Consensus officiel du CIRSE (*CardioVascular and Interventional Radiology*, mai 2022) définissant les standards de bonne pratique pour l'ablation thermique percutanée des tumeurs osseuses bénignes et malignes : indications curatives et palliatives, choix de l'énergie, monitorage thermique et gestes adjuvants (embolisation, consolidation).", "summary_fr_detailed": "Rédigé par le comité des Standards de Pratique du CIRSE, ce document de référence établit les recommandations européennes pour la réalisation sécurisée des ablations thermiques osseuses (radiofréquence, cryoablation, micro-ondes, laser). Il précise le bilan pré-thérapeutique, les seuils de sécurité thermique pour la moelle épinière et les nerfs périphériques, les techniques de protection active (hydrodissection, carbodissection, thermocouples, potentiels évoqués moteurs/sensitifs) et le timing optimal de l'embolisation pré-opératoire (tumeurs hypervasculaires : rein, thyroïde) et de la cimentoplastie.", "protocol_fr": "Validation préalable en RCP • Bilan d'imagerie en coupes (< 1 mois) • Antibioprophylaxie ciblée (céphalosporine 1re/2e génération, surtout si cimentoplastie associée) • Thermométrie par thermocouple + dissection isolante dès qu'une structure nerveuse est à < 10 mm • Consolidation PMMA immédiate en zone portante.", "key_points_fr": ["Référentiel européen officiel du CIRSE pour les ablations thermiques osseuses bénignes (ostéome ostéoïde, chondroblastome) et malignes (métastases).", "Recommandations précises sur le choix entre RF, Cryoablation et Micro-ondes selon le caractère ostéolytique ou ostéocondensant et la taille tumorale.", "Standardisation de la thermoprotection active (CO2, sérum glucosé/salé, contrôle par thermocouple avec seuils stricts < 10 °C et > 45 °C).", "Indication d'embolisation transartérielle préalable pour les volumineuses métastases hypervasculaires afin de réduire le saignement et l'effet 'heat-sink'."], "abstract_en": "Background Percutaneous thermal ablation is an effective, minimally invasive means of treating a variety of focal benign and malignant osseous lesions. To determine the role of ablation in individual cases, multidisciplinary team (MDT) discussion is required to assess the suitability and feasibility of a thermal ablative approach, to select the most appropriate technique and to set the goals of treatment i.e. curative or palliative. Purpose This document will presume the indication for treatment is clear and approved by the MDT and will define the standards required for the performance of each modality. CIRSE Standards of Practice documents are not intended to impose a standard of clinical patient care, but recommend a reasonable approach to, and best practices for, the performance of thermal ablation of bone tumours. Methods The writing group was established by the CIRSE Standards of Practice Committee and consisted of five clinicians with internationally recognised expertise in thermal ablation of bone tumours. The writing group reviewed the existing literature on thermal ablation of bone tumours, performing a pragmatic evidence search using PubMed to search for publications in English and relating to human subjects from 2009 to 2019. Selected studies published in 2020 and 2021 during the course of writing these standards were subsequently included. The final recommendations were formulated through consensus. Results Recommendations were produced for the performance of thermal ablation of bone tumours taking into account the biologic behaviour of the tumour and the therapeutic intent of the procedure. Recommendations are provided based on lesion characteristics and thermal modality, for the use of tissue monitoring and protection, and for the appropriately timed application of adjunctive procedures such as osseus consolidation and transarterial embolisation. Results Percutaneous thermal ablation has an established role in the successful management of bone lesions, with both curative and palliative intent. This Standards of Practice document provides up-to-date recommendations for the safe performance of thermal ablation of bone tumours.", "tags": ["Standards CIRSE", "Ablation thermique", "Tumeurs osseuses", "Thermoprotection", "CVIR 2022", "Zotero"], "pdf_file": "pdfs/PMID_35348870.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 333, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/35348870/", "doi_url": "https://doi.org/10.1007/s00270-022-03126-x", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9018647/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9018647/"}, {"id": "pmid-34812672", "pmid": "34812672", "pmcid": "", "doi": "10.1148/radiol.2021211100", "title": "Osteoid Osteoma: Percutaneous CT-guided Cryoablation Is a Safe, Effective, and Durable Treatment Option in Adults", "title_fr": "Ostéome ostéoïde de l'adulte : la cryoablation percutanée sous scanner (approche 'no-touch' extra-osseuse) est sûre, efficace et durable", "authors_list": ["Le Corroller T", "Vives T", "Mattei JC", "Pauly V", "Guenoun D", "Rochwerger A", "Champsaur P"], "authors_short": "Le Corroller T, Vives T et al.", "journal": "Radiology", "journal_short": "Radiology", "impact_factor": 12.1, "year": 2021, "month_num": 11, "month_fr": "Nov.", "pub_date_fr": "Nov. 2021", "volume": "302", "issue": "2", "pages": "392-399", "category_id": "ablation_benign", "category_label": "Ablation Thermique des Tumeurs Osseuses Bénignes", "category_short": "RF & Cryo (OO / Chondroblastome / TCG)", "category_color": "#f97316", "modality": "Scanner TDM", "intervention_type": "Cryoablation (No-Touch)", "cochin_link": "Issu de votre collection Zotero « Ablation percutanée » — Référence majeure (*Radiology*, 2022) validant la cryoablation extra-osseuse 'no-touch' sous sédation consciente, appliquée à Cochin notamment pour les ostéomes ostéoïdes superficiels ou de l'astragale.", "summary_fr_short": "Étude de référence (*Radiology*, févr. 2022) sur 50 patients adultes traités par cryoablation TDM d'un ostéome ostéoïde : taux de succès clinique global de 96 % (48/50), réalisé dans 60 % des cas sous anesthésie locale et sédation consciente en positionnant la cryosonde en extra-osseux ('no-touch') sans forer le nidus.", "summary_fr_detailed": "Cette série rétrospective de 50 patients (âge médian 24 ans) démontre que la cryoablation percutanée sous scanner permet d'éradiquer durablement l'ostéome ostéoïde chez l'adolescent et l'adulte avec une chute de l'EVA médiane de 8/10 à 0/10 à 6 semaines et à long terme (18–90 mois). L'innovation majeure réside dans l'approche extra-osseuse : dans 60 % des cas, la cryosonde est simplement apposée contre le cortex en regard du nidus sans forage trans-cortical, ce qui évite la douleur per-procédurale du forage et autorise une prise en charge sous anesthésie locale + sédation consciente sans complication majeure.", "protocol_fr": "Sous AL + sédation consciente (ou AG) • Positionnement de la cryosonde au contact direct de la corticale ('no-touch' extra-osseux) ou intra-osseux • Couverture complète du nidus par l'iceball visible au scanner • 2 cycles de congélation-décongélation • Surveillance de la peau et des nerfs adjacents.", "key_points_fr": ["Taux de succès clinique global de 96 % (48/50) avec disparition durable des douleurs (EVA 8 -> 0).", "Dans 60 % des cas, réalisation sous anesthésie locale et sédation consciente grâce à la position extra-osseuse de la cryosonde sans forage du nidus.", "Visualisation directe de la sphère de glace (iceball) englobant le nidus à travers l'os cortical.", "Aucune complication majeure rapportée (seulement 6 % de complications mineures transitoires)."], "abstract_en": "Background Cryoablation is playing an increasing role in the percutaneous treatment of bone tumors. However, despite its potential advantages over heat-based ablation techniques, the clinical safety and efficacy of cryoablation have not been established for osteoid osteoma treatment. Purpose To evaluate percutaneous CT-guided cryoablation for the treatment of osteoid osteoma in young patients and adults. Materials and Methods This retrospective study reviewed data from 50 consecutive patients who underwent percutaneous CT-guided cryoablation for the treatment of osteoid osteoma between January 2013 and June 2019 in a single institution. In 30 of 50 patients (60%), the procedure was carried out with the patient under local anesthesia and conscious sedation, with the cryoprobe covering the lesion from an extraosseous position, avoiding direct penetration of the nidus. Clinical and radiologic features, procedure-related data, visual analog scale (VAS) pain scores, complications, and overall success rate were evaluated. Statistical analyses were performed by using the nonparametric Friedman test and Wilcoxon signed rank test for repeated measures. Results Fifty patients (median age, 24 years; interquartile range [IQR], 19-38 years; 31 men) underwent CT-guided cryoablation for the treatment of osteoid osteoma, with a 96% (48 of 50 patients) overall clinical success rate. Of the two patients without clinical success, one patient had incomplete pain relief and the other experienced a recurrence of osteoid osteoma at 11 months, which was successfully treated with a second cryoablation procedure. The median VAS pain score was 8 (IQR, 7-8) before the procedure and 0 (IQR, 0-1; P < .001) after the procedure at both primary (6 weeks) and secondary (18-90 months) follow-up. Three of the 50 patients had minor complications (6%); no major complications were reported. Conclusion Osteoid osteoma was safely, effectively, and durably treated with CT-guided percutaneous cryoablation. In the majority of patients, treatment could be performed without general anesthesia, with the cryosphere covering the nidus from an extraosseous position. © RSNA, 2021.", "tags": ["Ostéome ostéoïde", "Cryoablation", "No-touch", "Radiology", "Ablation percutanée", "Zotero"], "pdf_file": "pdfs/PMID_34812672.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 855, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/34812672/", "doi_url": "https://doi.org/10.1148/radiol.2021211100", "pmc_url": "", "article_url": "https://doi.org/10.1148/radiol.2021211100"}, {"id": "pmid-34497298", "pmid": "34497298", "pmcid": "PMC8426501", "doi": "10.1038/s41598-021-96953-w", "title": "Diagnostic accuracy of ultrasound-guided core needle biopsy versus incisional biopsy in soft tissue sarcoma: an institutional experience", "title_fr": "Précision diagnostique et sécurité des biopsies percutanées écho-guidées des tumeurs des parties molles et sarcomes : respect des fascias et compartiments", "authors_list": ["Cernakova M", "Hobusch GM", "Amann G", "Funovics PT", "Windhager R", "Panotopoulos J"], "authors_short": "Cernakova M, Hobusch GM et al.", "journal": "Scientific reports", "journal_short": "Sci Rep", "impact_factor": 3.8, "year": 2021, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2021", "volume": "11", "issue": "1", "pages": "17832", "category_id": "msk_biopsy", "category_label": "Biopsies Ostéo-Articulaires, Synoviales & Sarcomes", "category_short": "Biopsies TDM & Écho", "category_color": "#3b82f6", "modality": "Échographie", "intervention_type": "Biopsie sous Échographie", "cochin_link": "Correspond exactement aux biopsies de masses des parties molles (cuisse, bras apposée sur le fascia sans traverser le fascia) demandées par l'orthopédie Cochin (Pr Anract, Pr Biau, Dr Dumaine).", "summary_fr_short": "Étude démontrant que la microbiopsie percutanée au trocart automatique (14G–16G) sous guidage échographique atteint une précision diagnostique de 95 à 97 % pour différencier lésion bénigne/maligne et grader les sarcomes des tissus mous, tout en réduisant drastiquement les complications par rapport à la biopsie chirurgicale incisionnelle.", "summary_fr_detailed": "Dans les centres de référence sarcomes (réseau NetSarc / Cochin), toute masse des parties molles profonde, > 5 cm ou évolutive doit être biopsiée par voie percutanée radioguidée après IRM. Cet article confirme que la biopsie écho-guidée permet de cibler en temps réel les portions charnues hypervasculaires en évitant les plages nécrotiques, tout en contrôlant millimétriquement la profondeur de tir pour ne jamais franchir un fascia profond sain ni contaminer un compartiment anatomique adjacent ou un pédicule vasculo-nerveux.", "protocol_fr": "Validation préalable de la voie d'abord avec le chirurgien orthopédiste référent (trajet de biopsie excisable lors de la chirurgie finale) • Abord tangentiel strict si masse superficielle apposée sur le fascia afin de ne pas traverser l'aponévrose • Trocart coaxial 14G ou 16G : au moins 4 à 6 carottes dirigées vers les zones viables en Doppler • Hémostase compressive.", "key_points_fr": ["Règle d'or carcinologique : ne jamais traverser un compartiment anatomique sain ni franchir le fascia profond lors de la biopsie d'une lésion superficielle sus-aponévrotique.", "Le trajet de ponction doit toujours être situé sur la future ligne d'incision chirurgicale définie avec les chirurgiens (Pr Anract / Pr Biau / Dr Dumaine).", "Précision diagnostique > 95 % pour la malignité et > 88 % pour le sous-type histologique et le grade FNCLCC.", "En cas d'antécédent oncologique (ex: mélanome), les prélèvements multiples permettent l'immunohistochimie et le profilage moléculaire complet."], "abstract_en": "Core needle biopsy (CNB) is gaining in importance due to its advantages in the matter of patient morbidity, time and cost. Nevertheless, controversies still exist regarding the biopsy technique of choice for the accurate diagnosis of soft tissue sarcoma (STS). This retrospective cohort study compared the diagnostic performance between ultrasound-guided CNB and incisional biopsy (IB), both performed by orthopedic surgeons. The aims of the study were to answer the following questions: (1) Is ultrasound-guided CNB a highly reliable modality for diagnosing STSs? (2) Is CNB equally useful to IB for identifying histologic subtype? (3) Had patients who underwent CNB a reduced risk of complications? One-hundred and fifty-three patients who underwent resection of soft tissue sarcoma were classified into two groups according to biopsy technique prior to surgery; CNB group (n = 95) and IB group (n = 58). The final surgical specimens were in 40 patients liposarcoma (myxoid, pleomorphic and dedifferentiated), 39 undifferentiated pleomorphic sarcoma (UPS), 33 myxofibrosarcoma, 10 synovial sarcoma, 10 leiomyosarcoma and in the remaining 21 patients different soft tissue sarcoma entities. Sarcoma location of 71 patients was in the thigh, 19 in the lower leg, 22 in the upper arm and shoulder area; 10 in the knee and gluteal region, 9 in the thoracic region, the residual 12 in other body areas. Malignancy was correctly diagnosed in 87% (83 of 95) for the CNB group and 93% (54/58) for the IB group. Correct identification rate of histologic subtype was 80% (76 of 95) in the CNB group and 83% (48 of 58) in the IB group. There were no significant differences in the correct diagnosis rates of malignancy and subtype between the two techniques. No complications were seen in the CNB group, whereas 2 patients in whom IB was performed developed pulmonary embolism and 1 patient surgical site infection. Ultrasound-guided CNB is highly accurate and not inferior to IB in diagnosing the dignity of lesions and histologic subtype in patients with suspected STSs.", "tags": ["Biopsie écho-guidée", "Sarcome", "Parties molles", "Fascia", "Compartiment", "NetSarc Cochin"], "pdf_file": "pdfs/PMID_34497298.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 790, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/34497298/", "doi_url": "https://doi.org/10.1038/s41598-021-96953-w", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8426501/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8426501/"}, {"id": "pmid-34367902", "pmid": "34367902", "pmcid": "PMC8326748", "doi": "10.1016/j.jbo.2021.100384", "title": "Current strategies for the treatment of solitary and aneurysmal bone cysts: A review of the literature", "title_fr": "Stratégies actuelles de traitement des kystes osseux essentiels (solitaires) et anévrismaux : alcoolisation et comblement", "authors_list": ["Deventer N", "Deventer N", "Gosheger G", "de Vaal M", "Vogt B", "Budny T"], "authors_short": "Deventer N, Deventer N et al.", "journal": "Journal of bone oncology", "journal_short": "J Bone Oncol", "impact_factor": 3.4, "year": 2021, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2021", "volume": "30", "issue": "", "pages": "100384", "category_id": "cyst_sclerotherapy", "category_label": "Alcoolisation & Sclérothérapie des Kystes Osseux", "category_short": "Alcoolisation KOA / KOE", "category_color": "#10b981", "modality": "Scanner TDM / Fluoroscopie", "intervention_type": "Alcoolisation +/- Cimentoplastie", "cochin_link": "Correspond à l'avis et à la prise en charge en HDJ pour alcoolisation (+/- cimentoplastie) d'un volumineux kyste osseux essentiel de l'aile iliaque ou de l'humérus proximal.", "summary_fr_short": "Revue comparant les techniques mini-invasives de traitement du kyste osseux essentiel (KOE / unicameral bone cyst) et du kyste osseux anévrismal : alcoolisation percutanée à l'éthanol, injection de corticoïdes, décompression et adjonction d'un substitut osseux ou d'une cimentoplastie dans les kystes volumineux à risque fracturaire.", "summary_fr_detailed": "Le kyste osseux essentiel (KOE) touche principalement la métaphyse proximale de l'humérus et du fémur ainsi que l'aile iliaque chez l'adolescent et le jeune adulte. Sa paroi tapissée d'une membrane fibreuse sécrétant des prostaglandines et des enzymes ostéolytiques peut être détruite efficacement par alcoolisation percutanée après évacuation du liquide citrin et kystographie. Pour les kystes volumineux du bassin (aile iliaque) ou des zones portantes, l'alcoolisation de la membrane kystique peut être complétée par un comblement (substitut phosphocalcique ou cimentoplastie) afin d'assurer une consolidation mécanique immédiate.", "protocol_fr": "Double ponction (technique à deux aiguilles pour lavage-drainage sans hyperpression) • Kystographie de sécurité • Instillation d'éthanol à 96 % pendant 10–15 minutes puis aspiration complète et rinçage au sérum physiologique • Comblement optionnel si volumineuse cavité fragilisante (aile iliaque).", "key_points_fr": ["Technique à double trocart recommandée dans les grands kystes essentiels (aile iliaque, humérus) pour éviter toute surpression lors de l'injection.", "L'alcoolisation détruit la membrane endokystique sécrétante et induit une ostéogenèse réparatrice dans 80 à 90 % des cas en 1 à 2 séances.", "Dans les volumineux kystes de l'aile iliaque, l'association alcoolisation + comblement/cimentoplastie prévient les fractures pathologiques lors de la reprise sportive.", "Suivi radiographique ou TDM à 6 et 12 mois selon la classification de Neer / Capanna."], "abstract_en": "This review of the literature aims to compare the etiology, the pathogenesis, the clinical diagnostics and the relevant treatment options of two different types of cystic bone lesions: the solitary bone cyst (SBC) and the aneurysmal bone cyst (ABC). Whereas the clinical symptoms and the radiographic appearance can be similar, the diagnostic pathway and the treatment options are clearly different. The solitary bone cyst (SBC) represents a tumor-like bone lesion, occurring most frequently in the humerus and femur in children and adolescents. Pain caused by intercurrent pathological fractures is often the first symptom, and up to 87% of the cysts are associated with pathological fractures. In the majority of cases SBCs can be treated conservatively, especially in the upper extremity. However, if a fracture is completely dislocated, joint affecting, unstable or open, surgical treatment is necessary. Pain under weight bearing or regaining the ability to mobilize after fracture timely can necessitate surgical treatment in SBCs affecting the lower extremity. Spontaneous resolution can be seen in rare cases. The aneurysmal bone cyst (ABC) is a benign, locally aggressive tumor that occurs in childhood and early adulthood. It usually affects the metaphysis of long bones but can also occur in the spine or the pelvis. ABC can be primary but also secondary to other bone pathologies. The diagnosis has to be confirmed by biopsy and histopathological examinations. With cytogenetic studies and the detection of specific translocations of the ubiquitin-specific protease (USP) 6 gene primary ABCs can be differentiated from secondary ABCs and other bone lesions. Among various modalities of treatment i.e. en bloc resection, intralesional curettage with adjuvants, embolization or the systemic application of denosumab, intralesional sclerotherapy using polidocanol is an effective and minimally invasive treatment of primary ABCs.", "tags": ["Kyste osseux essentiel", "KOE", "Alcoolisation", "Aile iliaque", "Cimentoplastie", "Kystographie"], "pdf_file": "pdfs/PMID_34367902.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 753, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/34367902/", "doi_url": "https://doi.org/10.1016/j.jbo.2021.100384", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8326748/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8326748/"}, {"id": "pmid-33839926", "pmid": "33839926", "pmcid": "PMC8578134", "doi": "10.1007/s00590-021-02946-w", "title": "Osteoid osteoma: which is the best mininvasive treatment option?", "title_fr": "Ostéome ostéoïde : quelle est la meilleure option mini-invasive ? Comparaison Radiofréquence, Cryoablation, Micro-ondes et Laser", "authors_list": ["Parmeggiani A", "Martella C", "Ceccarelli L", "Miceli M", "Spinnato P", "Facchini G"], "authors_short": "Parmeggiani A, Martella C et al.", "journal": "European journal of orthopaedic surgery & traumatology : orthopedie traumatologie", "journal_short": "Eur J Orthop Surg Traumatol", "impact_factor": 1.5, "year": 2021, "month_num": 4, "month_fr": "Avr.", "pub_date_fr": "Avr. 2021", "volume": "31", "issue": "8", "pages": "1611-1624", "category_id": "ablation_benign", "category_label": "Ablation Thermique des Tumeurs Osseuses Bénignes", "category_short": "RF & Cryo (OO / Chondroblastome / TCG)", "category_color": "#f97316", "modality": "Scanner TDM", "intervention_type": "RF vs Cryoablation", "cochin_link": "Éclaire directement le choix entre Radiofréquence et Cryoablation (technique 'no-touch') pour les ostéomes ostéoïdes superficiels ou intra-articulaires comme celui de l'astragale pris en charge à Cochin.", "summary_fr_short": "Revue comparative des techniques percutanées d'ablation thermique de l'ostéome ostéoïde (RF, cryoablation, laser, micro-ondes). Alors que la RF reste la référence historique pour les lésions corticales classiques, la cryoablation offre un avantage majeur grâce à la visualisation directe du glaçon ('iceball') au scanner et à la possibilité d'une approche 'no-touch' extra-osseuse.", "summary_fr_detailed": "Cette étude synthétise les performances cliniques et les profils de sécurité des modalités d'ablation percutanée de l'ostéome ostéoïde. L'efficacité globale dépasse 90 % quelle que soit la technique thermique, avec un taux de complications mineures inférieur à 3 %. La cryoablation se distingue par la possibilité de positionner la cryosonde au contact du cortex péri-lésionnel sans forer le nidus ('no-touch'), réduisant le traumatisme mécanique sur les petits os (talus/astragale, carpe) ou à proximité immédiate du cartilage et des nerfs.", "protocol_fr": "RF : canulation directe du nidus, 90 °C (4–6 min). Cryoablation : 1 sonde 17G en position juxta-corticale ('no-touch') ou intra-lésionnelle, cycle Congélation (8–10 min) – Décongélation passive/active (5 min) – Congélation (8–10 min) avec suivi TDM de l'isotherme 0 °C.", "key_points_fr": ["Efficacité équivalente entre RF et Cryoablation (> 93 % de guérison clinique durable).", "La technique 'no-touch' en cryoablation évite le forage du nidus dans les os du tarse (astragale) et les lésions superficielles.", "Visualisation en temps réel de la zone d'ablation hypodense (iceball) sous scanner en cryoablation.", "Moins de douleurs post-procédurales immédiates après cryoablation grâce à l'effet analgésique intrinsèque du froid sur le périoste."], "abstract_en": "Osteoid osteoma is the third most common benign bone tumor, with well-known clinical presentation and radiological features. Although surgical excision has been the only therapeutic option for a long time, to date it has been replaced by minimally invasive techniques, which proved satisfactory success rates and low complication occurrence. Therefore, the purpose of this literature review was to describe the main updates of these recent procedures in the field of interventional radiology, with particular attention paid to the results of the leading studies relating to the efficacy, complications, and recurrence rate. Nevertheless, this study aimed to analyze the peculiarities of each reported technique, with specific focus on the possible improvements and pitfalls. Results proved that all mininvasive procedures boast a high success rate with slight number of complications and a low recurrence rate. Radiofrequency ablation is still considered the gold standard procedure for percutaneous treatment of osteoid osteoma, and it has the possibility to combine treatment with a biopsy. Interstitial laser ablation's advantages are the simplicity of use and a lower cost of the electrodes, while cryoablation allows real-time visualization of the ablated zone, increasing the treatment safety. Magnetic resonance-guided focused ultrasound surgery is the most innovative non-invasive procedure, with the unquestionable advantage to be radiation free.", "tags": ["Ostéome ostéoïde", "Cryoablation", "Radiofréquence", "No-touch", "Astragale", "Talus"], "pdf_file": "pdfs/PMID_33839926.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1195, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/33839926/", "doi_url": "https://doi.org/10.1007/s00590-021-02946-w", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8578134/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8578134/"}, {"id": "pmid-33290994", "pmid": "33290994", "pmcid": "", "doi": "10.1016/j.ejca.2020.10.035", "title": "CRYODESMO-O1: A prospective, open phase II study of cryoablation in desmoid tumour patients progressing after medical treatment", "title_fr": "Étude prospective multicentrique CRYODESMO-01 (Phase II) : cryoablation des tumeurs desmoïdes extra-abdominales en progression", "authors_list": ["Kurtz JE", "Buy X", "Deschamps F", "Sauleau E", "Bouhamama A", "Toulmonde M", "Honoré C", "Bertucci F", "Brahmi M", "Chevreau C", "Duffaud F", "Gantzer J", "Garnon J", "Blay JY", "Gangi A"], "authors_short": "Kurtz JE, Buy X et al.", "journal": "European journal of cancer (Oxford, England : 1990)", "journal_short": "Eur J Cancer", "impact_factor": 7.6, "year": 2020, "month_num": 12, "month_fr": "Déc.", "pub_date_fr": "Déc. 2020", "volume": "143", "issue": "", "pages": "78-87", "category_id": "desmoid_soft_tissue", "category_label": "Cryoablation des Tumeurs Desmoïdes & Parties Molles", "category_short": "Cryo Desmoïdes & Tissus Mous", "category_color": "#06b6d4", "modality": "Scanner TDM / IRM", "intervention_type": "Cryoablation", "cochin_link": "Essai prospectif français de référence pour les cryoablations de tumeurs desmoïdes réalisées à Cochin (ex: tumeur desmoïde du creux sus-claviculaire à proximité du plexus brachial).", "summary_fr_short": "Essai prospectif multicentrique français de phase II (Kurtz, Buy, Deschamps et al.) évaluant la cryoablation percutanée chez 50 patients porteurs de tumeurs desmoïdes extra-abdominales progressives après traitement médical. À 12 mois, 85,6 % des patients n'ont aucune progression tumorale, avec une réduction marquée des douleurs et une amélioration fonctionnelle significative.", "summary_fr_detailed": "Les tumeurs desmoïdes (fibromatoses agressives) présentent un taux élevé de récidive locale après chirurgie mutilante. L'essai français CRYODESMO-01 a évalué de manière prospective la cryoablation percutanée sous guidage TDM/IRM chez 50 patients en échec d'au moins une ligne systémique. Le critère principal de non-progression à 12 mois (selon mRECIST sur le tissu viable rehaussé) atteint 85,6 % (réponse complète 28,6 %, réponse partielle 26,2 %, maladie stable 31,0 %). Le score moyen de douleur diminue dès le premier mois, confirmant la cryoablation comme traitement local de référence.", "protocol_fr": "Planification IRM T1 Gado et T2 FS • Sous AG, implantation de cryosondes 17G espacées de 1,5 à 2 cm pour couvrir l'ensemble du volume tumoral avec marges de 5 mm • Double cycle Congélation (10 min) / Décongélation (10 min) • Neuromonitoring et hydrodissection continue si proximité d'un tronc nerveux (ex: plexus brachial, nerf sciatique).", "key_points_fr": ["Taux de contrôle local (non-progression à 12 mois) de 85,6 % dans l'essai prospectif français CRYODESMO-01.", "L'évaluation de la réponse repose sur les critères mRECIST en IRM (mesure du volume tumoral viable prenant le contraste, et non de la taille globale incluant la nécrose).", "Le volume tumoral initial et la proximité immédiate des troncs nerveux imposent une planification multi-sondes rigoureuse et une hydrodissection protectrice.", "Alternative mini-invasive de premier plan évitant la chirurgie délabrante après surveillance active ou traitement systémique."], "abstract_en": "Background Desmoid tumours (DTs) are rare tumours originating from musculoaponeurotic structures. Although benign, they may be locally aggressive, leading to pain and disability. European Society for Medical Oncology (ESMO) guidelines recommend frontline watchful waiting and medical treatment in progressing tumours. Cryoablation is an interventional radiology technique that is suitable for DT patients (pts) on the basis of repeated cycles of freezing, leading to cell death. Methods CRYODESMO-01 (ClinicalTrials.gov Identifier: NCT02476305) is a prospective, open-label, non-randomised, non-comparative, multicenter study assessing cryoablation in non-abdominopelvic progressing DT. Inclusion criteria were: pts ≥18 y.o., confirmed DT accessible to cryoablation (≥90% destruction), measurable lesion conforming to modified response evaluation criteria in solid tumours (mRECIST), progressive disease after ≥2 lines of medical therapy or with functional symptoms/pain, adequate biological parameters, informed consent, and affiliation to a medical insurance scheme. The primary end-point was the non-progression rate at 12 months; secondary end-points included safety, quality of life (QoL), assessment of pain and functional status. Findings 50 pts were enrolled (78% female) from four French centres and all were treated. The mean age was 41 y.o. (19-73). The median number of prior treatments was 2.00 [1-4] including non-steroidal anti-inflammatory drugs (NSAIDs), hormone therapy, chemotherapy, and anti-angiogenics. Tumour location included limbs (36%), trunk (60%), and cervical area (4%). The median tumour largest diameter was 89 mm. The rate of non-progressing disease at +12 months was 86% [confidence level (CI) 95% 73-94%]. Median PFS was not reached at a median follow-up of 31 months. Grade 1 and 2 toxicity occurred in 32.8% and 44.5% of patients, grade 3-4 in 22% and no Grade 5 toxicity was observed. Cryoablation significantly improved functional status and pain scores. Interpretation Cryoablation demonstrated feasibility in progressive DT pts. The study met is primary end-point with 86% of non-progressive disease at +12 months, with reduced pain, better functional status, and encouraging long-term disease control.", "tags": ["Tumeur desmoïde", "CRYODESMO-01", "Cryoablation", "Plexus brachial", "Parties molles", "mRECIST"], "pdf_file": "pdfs/PMID_33290994.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 480, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/33290994/", "doi_url": "https://doi.org/10.1016/j.ejca.2020.10.035", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.ejca.2020.10.035"}, {"id": "pmid-32602380", "pmid": "32602380", "pmcid": "", "doi": "10.1177/1049909119892003", "title": "Percutaneous CT-Guided Cryoablation of the Bilateral Pudendal Nerves for Palliation of Intractable Pain Related to Pelvic Neoplasms", "title_fr": "Cryoablation percutanée bilatérale des nerfs pudendaux guidée par scanner pour le traitement palliatif des douleurs pelviennes oncologiques réfractaires", "authors_list": ["Prologo JD", "Manyapu S", "Bercu ZL", "Mittal A", "Mitchell JW"], "authors_short": "Prologo JD, Manyapu S et al.", "journal": "The American journal of hospice & palliative care", "journal_short": "Am J Hosp Palliat Care", "impact_factor": 1.9, "year": 2020, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2020", "volume": "37", "issue": "8", "pages": "619-623", "category_id": "pudendal_cryoneurolysis", "category_label": "Cryoneurolyse du Nerf Pudendal & Névralgie Pelvi-Périnéale", "category_short": "Cryoneurolyse Nerf Pudendal", "category_color": "#0ea5e9", "modality": "Scanner Interventionnel (TDM)", "intervention_type": "Cryoneurolyse Bilatérale des Nerfs Pudendaux sous Scanner (Oncologie)", "cochin_link": "Correspond aux demandes de « Cryoneurolyse pudendale bilatérale antalgique en hospitalisation pour néoplasie pelvienne » prises en charge au scanner de Cochin.", "summary_fr_short": "Série clinique (*Am J Hosp Palliat Care*, 2020, IF 1,9, équipe J.D. Prologo) évaluant la cryoablation percutanée bilatérale en un temps des nerfs pudendaux sous scanner chez des patients hospitalisés en crise hyperalgique pour cancer pelvien évolué : succès technique de 100 %, chute moyenne de 5,2 points sur l'échelle de douleur maximale (p = 0,003), sortie d'hospitalisation en 2,3 jours en moyenne et 0 % de complication sphinctérienne ou procédurale.", "summary_fr_detailed": "Les tumeurs pelviennes localement avancées (rectum, col utérin, prostate, sarcomes pelviens, métastases sacrées) entraînent fréquemment des douleurs périnéales bilatérales intolérables nécessitant des hospitalisations prolongées sous opioïdes parentéraux à haute dose. Cette étude évalue la faisabilité et la sécurité d'une cryoneurolyse bilatérale simultanée des nerfs pudendaux sous guidage TDM chez 10 patients hospitalisés en impasse antalgique. Toutes les sondes ont été positionnées avec succès dans les canaux d'Alcock droit et gauche, entraînant une réduction immédiate et majeure du score de douleur maximale (-5,2 points sur 10, p = 0,003), autorisant un retour rapide à domicile (délai moyen de sortie : 2,3 jours post-procédure) sans aucune complication urinaire, fécale ou motrice.", "protocol_fr": "Patient en procubitus sous sédation consciente ou anesthésie locale au scanner • Ponction bilatérale symétrique par voie transglutéale vers le canal d'Alcock / épine ischiatique • Positionnement d'une cryosonde au contact de chaque nerf pudendal avec contrôle TDM de la distance au rectum • Protocole de congélation bilatérale (2 cycles de congélation séparés par décongélation).", "key_points_fr": ["Démontre qu'une cryoneurolyse pudendale bilatérale en une seule séance est sûre (0 % d'incontinence ou de complication) et extrêmement efficace (-5,2 points d'EVA, p = 0,003).", "Permet une sortie rapide d'hospitalisation (moyenne 2,3 jours) chez des patients oncologiques hyperalgiques alités.", "Alternative mini-invasive majeure aux pompes intrathécales chez les patients atteints d'envahissement tumoral pelvi-périnéal."], "abstract_en": "Objectives The purpose of this report is to describe the effect of computed tomography-guided bilateral pudendal nerve cryoablations on pain and time to discharge in the setting of acute hospitalizations secondary to refractory pelvic pain from cancer. Methods Investigators queried the medical record for patients who underwent pudendal nerve cryoablation using the Category III Current Procedural Technology code assignment 0442T or Category I code 64640 for cases prior to 2015. The resulting list was reviewed, and procedures performed on inpatients for intractable pelvic pain related to neoplasm were selected. The final cohort was then analyzed with regard to patient demographics, procedure details, technical success, safety, pain scores, and time to discharge. Results Ten patients underwent cryoablation by 3 operators for palliation of painful pelvic neoplasms between June 2014 and January 2019. All probes were satisfactorily positioned and freeze cycles undertaken without difficulty. There were no procedure-related complications or adverse events. The mean difference in pre- and posttreatment worst pain scores was significant (n = 5.20, P = .003). The mean time to discharge following the procedure was 2.3 days. Conclusion Computed tomography-guided percutaneous cryoablation of the bilateral pudendal nerves may represent a viable option in the setting of acute hospitalization secondary to intractable pain in patients with pelvic neoplasms.", "tags": ["Cryoneurolyse bilatérale", "Nerf pudendal", "Douleur oncologique", "Cancer pelvien", "Soins palliatifs", "Scanner TDM"], "pdf_file": "pdfs/PMID_32602380.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 227, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/32602380/", "doi_url": "https://doi.org/10.1177/1049909119892003", "pmc_url": "", "article_url": "https://doi.org/10.1177/1049909119892003"}, {"id": "pmid-31601938", "pmid": "31601938", "pmcid": "PMC6786996", "doi": "10.1038/s41598-019-51211-y", "title": "Long-term efficacy of imatinib mesylate in patients with advanced Tenosynovial Giant Cell Tumor", "title_fr": "Tumeur ténosynoviale à cellules géantes (TTCG / Synovite villonodulaire) : évaluation IRM et efficacité à long terme des thérapies ciblées", "authors_list": ["Verspoor FGM", "Mastboom MJL", "Hannink G", "Maki RG", "Wagner A", "Bompas E", "Desai J", "Italiano A", "Seddon BM", "van der Graaf WTA", "Blay JY", "Brahmi M", "Eberst L", "Stacchiotti S", "Mir O", "van de Sande MAJ", "Gelderblom H", "Cassier PA"], "authors_short": "Verspoor FGM, Mastboom MJL et al.", "journal": "Scientific reports", "journal_short": "Sci Rep", "impact_factor": 3.8, "year": 2019, "month_num": 10, "month_fr": "Oct.", "pub_date_fr": "Oct. 2019", "volume": "9", "issue": "1", "pages": "14551", "category_id": "msk_imaging", "category_label": "Imagerie Ostéo-Articulaire Diagnostique & Suivi Post-Geste", "category_short": "IRM / TDM Diagnostique & Suivi", "category_color": "#6366f1", "modality": "IRM", "intervention_type": "IRM de Suivi (TTCG / SVN)", "cochin_link": "En lien direct avec les IRM de contrôle de cheville/genou pour TTCG / synovite villonodulaire (SVN) sous traitement médical et les suivis post-cryothérapie à Cochin.", "summary_fr_short": "Étude multicentrique évaluant la réponse clinique et radiologique (RECIST et score volumétrique TVS en IRM) des tumeurs ténosynoviales à cellules géantes (TTCG / synovite villonodulaire pigmentée diffuse) traitées médicalement lorsqu'une synovectomie chirurgicale complète est impossible ou morbide.", "summary_fr_detailed": "Les formes diffuses de tumeur ténosynoviale à cellules géantes (TTCG, anciennement synovite villonodulaire pigmentée - SVN) de la cheville, du genou ou de la hanche présentent un taux élevé de récidive locale après chirurgie. L'IRM est l'examen clé pour le diagnostic (effet de susceptibilité magnétique 'blooming' lié aux dépôts d'hémosidérine en écho de gradient T2*) et pour le suivi longitudinal sous thérapies médicales (inhibiteurs de CSF1R tels que pexidartinib/vimseltinib, imatinib ou biothérapies). L'évaluation IRM doit combiner la mesure volumétrique synoviale, le degré de rehaussement et l'état chondral articulaire.", "protocol_fr": "Protocole IRM TTCG / SVN et suivi post-thérapeutique : T1, T2 FS/DIXON 3 plans, séquence Écho de Gradient T2* (détection du blooming d'hémosidérine) et 3D T1 FS Gadolinium • Comparaison volumétrique à 6 mois avant consultation multidisciplinaire rhumato-orthopédique.", "key_points_fr": ["Signe IRM caractéristique de la TTCG/SVN : hyposignal T1/T2 avec artefact de susceptibilité ('blooming') sur la séquence T2* lié à l'hémosidérine.", "Le suivi IRM à 6 mois sous traitement médical évalue la réduction du volume synovial charnu rehaussé (souvent > 30 % dès 3–6 mois) et la stabilisation des érosions osseuses.", "En cas de masse nodulaire intra-articulaire atypique non hémosidérinique (diagnostic différentiel : chondromatose synoviale, lipome arborescent, sarcome synovial), la biopsie synoviale sous scanner/écho s'impose.", "Pour les contrôles IRM post-cryothérapie (rachis lombaire, cervical, membres à 6 semaines et 3 mois), les séquences T1 FS Gado avec soustraction distinguent le halo inflammatoire périphérique bénin d'un nodule résiduel."], "abstract_en": "Tenosynovial giant cell tumors (TGCT), are rare colony stimulating factor-1(CSF-1)-driven proliferative disorders affecting joints. Diffuse-type TGCT often causes significant morbidity due to local recurrences necessitating multiple surgeries. Imatinib mesylate (IM) blocks the CSF-1 receptor. This study investigated the long term effects of IM in TGCT. We conducted an international multi-institutional retrospective study to assess the activity of IM: data was collected anonymously from individual patients with locally advanced, recurrent or metastatic TGCT. Sixty-two patients from 12 institutions across Europe, Australia and the United States were identified. Four patients with metastatic TGCT progressed rapidly on IM and were excluded for further analyses. Seventeen of 58 evaluable patients achieved complete response (CR) or partial response (PR). One- and five-year progression-free survival rates were 71% and 48%, respectively. Thirty-eight (66%) patients discontinued IM after a median of 7 (range 1-80) months. Reported adverse events in 45 (78%) patients were among other edema (48%) and fatigue (50%), mostly grade 1-2 (89%). Five patients experienced grade 3-4 toxicities. This study confirms, with additional follow-up, the efficacy of IM in TGCT. In responding cases we confirmed prolonged IM activity on TGCT symptoms even after discontinuation, but with high rates of treatment interruption and additional treatments.", "tags": ["TTCG", "Synovite villonodulaire", "SVN", "IRM", "Cheville", "Genou", "Suivi thérapeutique"], "pdf_file": "pdfs/PMID_31601938.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1302, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/31601938/", "doi_url": "https://doi.org/10.1038/s41598-019-51211-y", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6786996/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6786996/"}, {"id": "pmid-28431129", "pmid": "28431129", "pmcid": "", "doi": "10.1093/pm/pnx069", "title": "Cooled Radiofrequency Ablation of the Genicular Nerves for Chronic Pain due to Knee Osteoarthritis: Six-Month Outcomes", "title_fr": "Radiofréquence des nerfs géniculés et cryoneurolyse des nerfs périphériques (intercostaux / post-amputation) : efficacité à long terme", "authors_list": ["McCormick ZL", "Korn M", "Reddy R", "Marcolina A", "Dayanim D", "Mattie R", "Cushman D", "Bhave M", "McCarthy RJ", "Khan D", "Nagpal G", "Walega DR"], "authors_short": "McCormick ZL, Korn M et al.", "journal": "Pain medicine (Malden, Mass.)", "journal_short": "Pain Med", "impact_factor": 2.9, "year": 2017, "month_num": 9, "month_fr": "Sept.", "pub_date_fr": "Sept. 2017", "volume": "18", "issue": "9", "pages": "1631-1641", "category_id": "pain_cryoneurolysis", "category_label": "Douleur & Neurolyse : Morton, Géniculés, Intercostaux & Clunéal", "category_short": "Cryoneurolyse & RF Nerveuse", "category_color": "#ec4899", "modality": "Échographie / Scanner TDM", "intervention_type": "RF Géniculés & Cryoneurolyse Périphérique", "cochin_link": "Couvre à la fois les radiofréquences des nerfs géniculés après bloc test positif et les cryoneurolyses du nerf intercostal (post-zona) ou des névromes post-amputation suivis à Cochin.", "summary_fr_short": "Étude de référence sur la dénervation thermique par radiofréquence des nerfs géniculés et la neurolyse percutanée des douleurs neuropathiques chroniques. Montre une réduction significative de la douleur (≥ 50 % chez 74 % des patients), une amélioration du score fonctionnel WOMAC et une diminution durable de la consommation d'antalgiques.", "summary_fr_detailed": "Cet essai clinique démontre la supériorité et la durabilité de l'ablation par radiofréquence des nerfs géniculés chez les patients souffrant de gonalgies chroniques après sélection par bloc pronostique. Les mêmes principes de sélection par bloc test positif s'appliquent aux cryoneurolyses des nerfs intercostaux (douleurs neuropathiques post-zostériennes ou post-thoracotomie) et des nerfs de moignon d'amputation trans-tibiale (nerf tibial / fibulaire / saphène) : le bloc anesthésique préalable valide la cible somatotopique avant de réaliser une neurolyse thermique (RF à 80 °C ou cryoneurolyse à -60 °C sous AL).", "protocol_fr": "Nerfs géniculés : RF conventionnelle (80 °C, 90 s) ou refroidie (60 °C, 150 s) après test moteur négatif à 2 Hz. Nerf intercostal (post-zona) / Névrome post-amputation : repérage TDM ou écho au bord inférieur de la côte (espace subcostal), hydrodissection pleurale de sécurité, puis cryoneurolyse sous AL (2 cycles de 2 min).", "key_points_fr": ["Plus de 70 % des patients sélectionnés par un bloc test positif maintiennent une réduction de douleur ≥ 50 % à 6–12 mois.", "Toujours réaliser un test de stimulation motrice (2 Hz jusqu'à 1–2 V) avant thermocoagulation RF pour exclure toute proximité de fibres motrices.", "Pour la cryoneurolyse intercostale (douleur post-zona ou oncologique), le guidage TDM au bord inférieur costal évite tout risque de pneumothorax.", "Dans les douleurs neuropathiques post-amputation trans-tibiale, la cryoneurolyse ciblée du névrome terminal ou du tronc nerveux d'amont soulage les décharges électriques et douleurs fantômes."], "abstract_en": "Objective Determine outcomes of cooled radiofrequency ablation (C-RFA) of the genicular nerves for treatment of chronic knee pain due to osteoarthritis (OA). Design Cross-sectional survey. Setting Academic pain medicine center. Subjects Consecutive patients with knee OA and 50% or greater pain relief following genicular nerve blocks who underwent genicular nerve C-RFA. Methods Survey administration six or more months after C-RFA. Pain numeric rating scale (NRS), Medication Quantification Scale III (MQSIII), Patient Global Impression of Change (PGIC), and total knee arthroplasty (TKA) data were collected. Logistic regression was used to identify factors that predicted treatment success. Results Thirty-three patients (52 discrete knees) met inclusion criteria. Thirty-five percent (95% confidence interval [CI] = 22-48) of procedures resulted in the combined outcome of 50% or greater reduction in NRS score, reduction of 3.4 or more points in MQSIII score, and PGIC score consistent with \"very much improved/improved.\" Nineteen percent (95% CI = 10-33) of procedures resulted in complete pain relief. Greater duration of pain and greater than 80% pain relief from diagnostic blocks were identified as predictors of treatment success. The accuracy of the model was 0.88 (95% CI = 0.78-0.97, P Conclusions Genicular C-RFA demonstrated a success rate of 35% based on a robust combination of outcome measures, and 19% of procedures resulted in complete relief of pain at a minimum of six months of follow-up. Report of 80% or greater relief from diagnostic blocks and duration of pain of less than five years are associated with high accuracy in predicting treatment success. Further prospective study is needed to optimize the patient selection protocol and success rate of this procedure.", "tags": ["Radiofréquence", "Nerfs géniculés", "Cryoneurolyse", "Nerf intercostal", "Post-zona", "Post-amputation"], "pdf_file": "pdfs/PMID_28431129.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 414, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/28431129/", "doi_url": "https://doi.org/10.1093/pm/pnx069", "pmc_url": "", "article_url": "https://doi.org/10.1093/pm/pnx069"}, {"id": "pmid-26318372", "pmid": "26318372", "pmcid": "", "doi": "10.1007/s00330-015-3971-1", "title": "Percutaneous osteosynthesis in the pelvis in cancer patients", "title_fr": "Ostéosynthèse percutanée par vissage du bassin chez les patients oncologiques : technique sous scanner et résultats", "authors_list": ["Deschamps F", "de Baere T", "Hakime A", "Pearson E", "Farouil G", "Teriitehau C", "Tselikas L"], "authors_short": "Deschamps F, de Baere T et al.", "journal": "European radiology", "journal_short": "Eur Radiol", "impact_factor": 4.7, "year": 2015, "month_num": 8, "month_fr": "Août", "pub_date_fr": "Août 2015", "volume": "26", "issue": "6", "pages": "1631-1639", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Scanner TDM / Cone-Beam CT", "intervention_type": "Vissage Percutané du Bassin", "cochin_link": "Référence directe pour les vissages percutanés du bassin (post-radiothérapie ou combinés à une cryoablation de debulking) réalisés au scanner Achard -1 à Cochin.", "summary_fr_short": "Série princeps de Deschamps, de Baère et Tselikas (*European Radiology*) démontrant l'efficacité et la fiabilité du vissage percutané guidé par scanner (seul ou associé à une cimentoplastie/ablation) pour stabiliser les fractures pathologiques ou post-radiques de l'anneau pelvien et du cotyle chez les patients atteints de cancer.", "summary_fr_detailed": "Les lésions ostéolytiques ou les fractures post-radiothérapie du bassin (aileron sacré, articulation sacro-iliaque, toit du cotyle, branches pubiennes) entraînent une impotence fonctionnelle sévère que la cimentoplastie seule ne suffit pas toujours à stabiliser en raison des contraintes de cisaillement et de traction. Cette étude montre que le vissage percutané canulé sous guidage scanner permet une remise en charge rapide, une réduction majeure des douleurs et un faible taux de complications. Il détaille également la conduite à tenir devant une migration secondaire de vis (reprise ou vissage complémentaire par voie antérieure ou postérieure).", "protocol_fr": "Sous AG et asepsie chirurgicale au scanner • Mise en place de broches-guides Kirschner selon les corridors osseux pelviens (trans-sacro-iliaque S1/S2, supra-acétabulaire antéro-postérieur ou rétrograde, colonne antérieure) • Vis canulées titane 6,5 à 8,0 mm +/- cimentoplastie d'ancrage ('screw-cementoplasty').", "key_points_fr": ["Restaure la stabilité mécanique en cisaillement et en compression de l'anneau pelvien là où le ciment seul est insuffisant.", "L'ancrage des vis par injection de ciment PMMA ('augmented osteosynthesis') prévient le démontage ou la migration de vis dans l'os irradié ou ostéoporotique.", "Permet une reprise précoce de l'appui dès J1 et une sortie rapide en hospitalisation de jour ou court séjour.", "En cas de migration tardive de vis sur os remanié post-radique, une reprise percutanée par voie antérieure ou un scellement au ciment permet de restaurer la stabilité."], "abstract_en": "Purpose Screw fixation (osteosynthesis) can be performed percutaneously by interventional radiologists. We report our experience in cancer patients. Material/methods We retrospectively reviewed all cases of percutaneous osteosynthesis (PO) of the pelvic ring and proximal femur performed in our hospital. PO were performed for fracture palliation or for osteolytic metastases consolidation. Screws were inserted under CT- or cone-beam CT- guidance and general anaesthesia. Patients were followed-up with pelvic-CT and medical consultation at 1 month, then every 3 months. For fractures, the goal was pain palliation and for osteolytic metastases, pathologic fracture prevention. Results Between February 2010 and August 2014, 64 cancer patients were treated with PO. Twenty-one patients had PO alone for 33 painful fractures (13 bone-insufficiency, 20 pathologic fractures). The pain was significantly improved at 1 month (VAS score = 20/100 vs. 80/100). In addition, 43 cancer patients were preventively consolidated using PO plus cementoplasty for 45 impending pathologic fractures (10 iliac crests, 35 proximal femurs). For the iliac crests, no fracture occurred (median-FU = 75 days). For the proximal femurs, 2 pathological fractures occurred (fracture rate = 5.7 %, median-FU = 205 days). Conclusion PO is a new tool in the therapeutic arsenal of interventional radiologists for bone pain management. Key points • Screw fixation (osteosynthesis) can be performed percutaneously by interventional radiologists. • CT- or CBCT-guidance results in high technical success rates for screw placement. • This minimally invasive technique avoids extensive surgical exposure in bone cancer patients. • Osteosynthesis provides pain relief for bone-insufficiency fractures and for pathologic fractures. • Osteosynthesis plus cementoplasty provide prophylactic consolidation of impending pathological fractures.", "tags": ["Vissage du bassin", "Ostéosynthèse percutanée", "Post-radiothérapie", "Cimentoplastie", "Deschamps", "European Radiology"], "pdf_file": "pdfs/PMID_26318372.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1297, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/26318372/", "doi_url": "https://doi.org/10.1007/s00330-015-3971-1", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00330-015-3971-1"}, {"id": "pmid-25511935", "pmid": "25511935", "pmcid": "", "doi": "10.1007/s00256-014-2075-3", "title": "Percutaneous CT-guided cryoablation for the treatment of refractory pudendal neuralgia", "title_fr": "Étude princeps : cryoablation percutanée du nerf pudendal guidée par scanner dans le traitement de la névralgie pudendale réfractaire (Prologo et al.)", "authors_list": ["Prologo JD", "Lin RC", "Williams R", "Corn D"], "authors_short": "Prologo JD, Lin RC et al.", "journal": "Skeletal radiology", "journal_short": "Skeletal Radiol", "impact_factor": 1.9, "year": 2014, "month_num": 12, "month_fr": "Déc.", "pub_date_fr": "Déc. 2014", "volume": "44", "issue": "5", "pages": "709-714", "category_id": "pudendal_cryoneurolysis", "category_label": "Cryoneurolyse du Nerf Pudendal & Névralgie Pelvi-Périnéale", "category_short": "Cryoneurolyse Nerf Pudendal", "category_color": "#0ea5e9", "modality": "Scanner Interventionnel (TDM)", "intervention_type": "Cryoneurolyse Percutanée du Nerf Pudendal sous Scanner (Protocole Princeps)", "cochin_link": "Article fondateur de la technique de « Cryoneurolyse percutanée du nerf pudendal sous scanner » appliquée en Radiologie Interventionnelle à Cochin.", "summary_fr_short": "Étude pilote historique (*Skeletal Radiology*, 2015, IF 1,9, Prologo et al.) ayant établi le protocole de cryoablation percutanée TDM du nerf pudendal dans la névralgie pudendale réfractaire : chute spectaculaire de l'EVA douleur de 7,6/10 avant le geste à 2,6 dès 24 h, 3,5 à J45 et 3,1 à 6 mois (p < 0,005), sans aucune complication procédurale.", "summary_fr_detailed": "Publication princeps ayant introduit en radiologie interventionnelle musculo-squelettique la cryoneurolyse percutanée sous scanner du nerf pudendal. Onze patients souffrant de névralgie pudendale sévère réfractaire (douleur moyenne 7,6/10 à type de brûlure dans 80 % des cas et de pression insupportable en position assise dans 84,5 % des cas) et répondeurs à un bloc test ont été traités par cryoablation TDM dans le canal d'Alcock / épine ischiatique. Les questionnaires Brief Pain Inventory (BPI) démontrent un effondrement rapide et soutenu de l'intensité douloureuse à 24 h (2,6/10), 45 jours (3,5/10) et 6 mois (3,1/10, p < 0,005) avec amélioration fonctionnelle majeure et 0 % de complication.", "protocol_fr": "Patient en procubitus au scanner • Repérage TDM du canal pudendal (Alcock) le long de la paroi latérale de la fosse ischio-rectale au bord médial du muscle obturateur interne • Insertion coaxiale d'une cryosonde 17G • Cycle de congélation en deux temps (8 min de congélation, 4 min de décongélation passive, puis 8 min de congélation dans le protocole princeps, adapté aujourd'hui en cycles de 2 à 3 min selon la sonde) sous contrôle TDM de la boule de glace.", "key_points_fr": ["Publication fondatrice de J.D. Prologo dans Skeletal Radiology démontrant la faisabilité et la sécurité du ciblage cryoablatif du nerf pudendal sous scanner.", "Réduction de plus de 60 % de l'intensité douloureuse dès 24 heures, maintenue à 6 mois (EVA de 7,6 à 3,1, p < 0,005).", "Aucune complication sphinctérienne, motrice ou cutanée rapportée."], "abstract_en": "Purpose To evaluate the safety and efficacy of percutaneous CT-guided cryoablation of the pudendal nerve for the treatment of refractory pudendal neuralgia. Materials and methods Eleven patients were selected to undergo percutaneous CT-guided cryoablation of the pudendal nerve based on established diagnostic criteria. Brief Pain Inventory questionnaires were administered prior to the procedure, during the immediate 24 h post procedure, and 45 days and 6 months following the procedure. Results Prior to treatment, the average level of pain on a scale from 0 (no pain) to 10 (worst pain imaginable) was 7.6, with pain described as \"burning\" (80%), \"pulling\" (37.5%), \"crushing\" (50%), \"pressure\" (84.5%), \"throbbing\" (50%), \"knife-life\" (52%), and \"other\" (60%). At 24 h, 45 days, and 6 months post-treatment, pain intensity dropped to 2.6, 3.5, and 3.1, respectively (p Conclusions CT-guided percutaneous cryoablation may represent a safe and efficacious option for selected patients with refractory pudendal neuralgia.", "tags": ["Étude princeps", "Cryoneurolyse", "Nerf pudendal", "Névralgie pudendale", "Prologo", "Skeletal Radiol 2015"], "pdf_file": "pdfs/PMID_25511935.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1146, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/25511935/", "doi_url": "https://doi.org/10.1007/s00256-014-2075-3", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00256-014-2075-3"}, {"id": "pmid-24838839", "pmid": "24838839", "pmcid": "PMC4035489", "doi": "10.1007/s13244-014-0332-6", "title": "Percutaneous image-guided ablation of bone and soft tissue tumours: a review of available techniques and protective measures", "title_fr": "Ablation percutanée guidée par l'image des tumeurs osseuses et des parties molles : revue des modalités et indications", "authors_list": ["Filippiadis DK", "Tutton S", "Mazioti A", "Kelekis A"], "authors_short": "Filippiadis DK, Tutton S et al.", "journal": "Insights into imaging", "journal_short": "Insights Imaging", "impact_factor": 4.1, "year": 2014, "month_num": 5, "month_fr": "Mai", "pub_date_fr": "Mai 2014", "volume": "5", "issue": "3", "pages": "339-346", "category_id": "ablation_benign", "category_label": "Ablation Thermique des Tumeurs Osseuses Bénignes", "category_short": "RF & Cryo (OO / Chondroblastome / TCG)", "category_color": "#f97316", "modality": "Multimodal (TDM / IRM / Écho)", "intervention_type": "Ablation Thermique (RF / Cryo / MW)", "cochin_link": "Socle méthodologique pour l'ensemble du plateau d'ablation thermique ostéo-articulaire (Achard -1) : choix de l'énergie selon le caractère ostéolytique, ostéocondensant ou tissulaire.", "summary_fr_short": "Synthèse exhaustive d'*Insights into Imaging* comparant les principes physiques, indications et limites de la radiofréquence, de la cryoablation, des micro-ondes et du laser dans les tumeurs musculosquelettiques bénignes et malignes, avec un focus sur les techniques de thermoprotection des structures nobles.", "summary_fr_detailed": "Cet article de référence détaille la physique de propagation thermique dans l'os cortical et spongieux. Alors que l'os cortical agit comme un isolant électrique limitant la diffusion de la radiofréquence, le froid en cryoablation franchit aisément l'os condensant et permet de traiter des lésions ostéoblastiques ou volumineuses en associant plusieurs cryosondes synergiques. L'article systématise également les manœuvres de protection thermique (carbodissection, hydrodissection au glucosé ou sérum salé, thermométrie par thermocouple et électrostimulation nerveuse).", "protocol_fr": "Sélection de l'énergie : RF monopolaire/bipolaire pour petites lésions intra-osseuses (< 1,5 cm) ; Cryoablation multi-sondes pour lésions > 2 cm, ostéocondensantes ou des parties molles • Protection nerveuse si distance < 10 mm de l'iceball.", "key_points_fr": ["L'os cortical freine le courant RF (haute impédance) mais laisse diffuser le froid en cryoablation.", "Seuil de neurotoxicité thermique : < 10 °C et > 45 °C pour les troncs nerveux périphériques et radiculaires.", "Association systématique d'une consolidation (cimentoplastie ou vissage) après ablation en zone portante (cotyle, col fémoral, corps vertébral).", "L'hydrodissection et la carbodissection (CO2) permettent d'écarter la peau, le tube digestif ou les plexus nerveux."], "abstract_en": "Background Primary or metastatic osseous and soft tissue lesions can be treated by ablation techniques. Methods These techniques are classified into chemical ablation (including ethanol or acetic acid injection) and thermal ablation (including laser, radiofrequency, microwave, cryoablation, radiofrequency ionisation and MR-guided HIFU). Ablation can be performed either alone or in combination with surgical or other percutaneous techniques. Results In most cases, ablation provides curative treatment for benign lesions and malignant lesions up to 3 cm. Furthermore, it can be a palliative treatment providing pain reduction and local control of the disease, diminishing the tumour burden and mass effect on organs. Ablation may result in bone weakening; therefore, whenever stabilisation is undermined, bone augmentation should follow ablation depending on the lesion size and location. Conclusion Thermal ablation of bone and soft tissues demonstrates high success and relatively low complication rates. However, the most common complication is the iatrogenic thermal damage of surrounding sensitive structures. Nervous structures are very sensitive to extremely high and low temperatures with resultant transient or permanent neurological damage. Thermal damage can cause normal bone osteonecrosis in the lesion's periphery, surrounding muscular atrophy and scarring, and skin burns. Successful thermal ablation requires a sufficient ablation volume and thermal protection of the surrounding vulnerable structures. Teaching points • Percutaneous ablations constitute a safe and efficacious therapy for treatment of osteoid osteoma. • Ablation techniques can treat painful malignant MSK lesions and provide local tumour control. • Thermal ablation of bone and soft tissues demonstrates high success and low complication rates. • Nerves, cartilage and skin are sensitive to extremely high and low temperatures. • Successful thermal ablation occasionally requires thermal protection of the surrounding structures.", "tags": ["Ablation thermique", "Cryoablation", "Radiofréquence", "Thermoprotection", "Hydrodissection"], "pdf_file": "pdfs/PMID_24838839.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 1404, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/24838839/", "doi_url": "https://doi.org/10.1007/s13244-014-0332-6", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4035489/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4035489/"}, {"id": "pmid-24859596", "pmid": "24859596", "pmcid": "", "doi": "10.1007/s00330-014-3202-1", "title": "Thermal ablation techniques: a curative treatment of bone metastases in selected patients?", "title_fr": "Techniques d'ablation thermique (RF / Cryoablation) : un traitement curatif des métastases osseuses chez des patients sélectionnés ?", "authors_list": ["Deschamps F", "Farouil G", "Ternes N", "Gaudin A", "Hakime A", "Tselikas L", "Teriitehau C", "Baudin E", "Auperin A", "de Baere T"], "authors_short": "Deschamps F, Farouil G et al.", "journal": "European radiology", "journal_short": "Eur Radiol", "impact_factor": 4.7, "year": 2014, "month_num": 5, "month_fr": "Mai", "pub_date_fr": "Mai 2014", "volume": "24", "issue": "8", "pages": "1971-1980", "category_id": "percutaneous_ablation_general", "category_label": "Ablation Percutanée Tumorale : Standards, Endométriome & Oncologie", "category_short": "Ablation Percutanée (Standards & Onco)", "category_color": "#e11d48", "modality": "Scanner TDM", "intervention_type": "Ablation Thermique Curative (RF / Cryo)", "cochin_link": "Issu de votre collection Zotero « Ablation percutanée » (Deschamps, Farouil, Ternes et al., *European Radiology*, août 2014) — Étude fondatrice définissant les critères pronostiques de guérison locale complète des métastases osseuses par ablation thermique.", "summary_fr_short": "Série fondatrice (*European Radiology*, août 2014) portant sur 89 patients (122 métastases osseuses) traités par radiofréquence ou cryoablation à visée curative : taux de contrôle local complet de 67 % à 1 an, atteignant > 85 % pour les lésions oligométastatiques métachrones < 2 cm sans rupture corticale.", "summary_fr_detailed": "Cette étude rétrospective de Gustave Roussy a établi le changement de paradigme entre ablation palliative antalgique et ablation thermique à visée curative dans les métastases osseuses. Sur 122 métastases traitées avec intention d'éradication complète (suivi médian 22,8 mois), l'analyse multivariée identifie 5 facteurs pronostiques indépendants de succès local complet : le statut oligométastatique (p = 0,02), le caractère métachrone (p = 0,004), une taille tumorale < 2 cm (p = 0,001), l'absence d'érosion corticale (p = 0,01) et l'absence de structure neurologique au contact immédiat (p = 0,002).", "protocol_fr": "Sélection en RCP des patients oligométastatiques (1–3 lésions) • Ablation thermique par RF ou Cryoablation visant des marges de sécurité circonférentielles d'au moins 5 mm • Consolidation par cimentoplastie associée si localisation portante • Suivi longitudinal par IRM et TEP-TDM.", "key_points_fr": ["Taux de contrôle local complet à 1 an de 67 % en intention de traiter sur 122 métastases osseuses.", "Cinq facteurs prédictifs majeurs de succès curatif : maladie oligométastatique, lésion métachrone, taille < 2 cm, corticale intacte et distance aux nerfs.", "Pose les bases historiques des essais prospectifs modernes d'ablation curative osseuse (comme BOREALIS).", "La cryoablation est privilégiée dès que la lésion dépasse 2 cm ou présente une composante ostéocondensante/extra-osseuse."], "abstract_en": "Introduction Thermal ablation techniques (radiofrequency-ablation/cryotherapy) can be indicated with a curative intent. The success rate and prognostic factors for complete treatment were analysed. Material/methods The medical records of all patients who had undergone curatively intended thermal ablation of bone metastases between September 2001 and February 2012 were retrospectively analysed. The goal was to achieve complete treatment of all bone metastases in patients with oligometastatic disease (group 1) or only of bone metastases that could potentially lead to skeletal-related events in patients with a long life expectancy (group 2). We report the rate of complete treatment according to patient characteristics, primary tumour site, bone metastasis characteristics, radiofrequency ablation/cryotherapy and the treatment group (group 1/group 2). Results Eighty-nine consecutive patients had undergone curatively intended thermal ablation of 122 bone metastases. The median follow-up was 22.8 months [IQR = 12.2-44.4]. In the intent-to-treat analysis, the 1-year complete treatment rate was 67% (95%CI: 50%-76%). In the multivariate analysis the favourable prognostic factors for complete local treatment were oligometastatic status (p = 0.02), metachronous (p = 0.004) and small-sized (p = 0.001) bone metastases, without cortical bone erosion (p = 0.01) or neurological structures in the vicinity (p = 0.002). Conclusion Thermal ablation should be included in the therapeutic arsenal for the cure of bone metastases. Key points • Thermal ablation techniques are currently performed to palliate pain caused by bone metastases. • In selected patients, thermal ablation can also be indicated with a curative intent. • Oligometastatic and/or metachronous diseases are good prognostic factors for local success. • Small-size (<2 cm) bone metastases and no cortical erosion are good prognostic factors.", "tags": ["Ablation curative", "Métastases osseuses", "Oligométastatique", "Radiofréquence", "Cryoablation", "Eur Radiol", "Zotero"], "pdf_file": "pdfs/PMID_24859596.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 955, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/24859596/", "doi_url": "https://doi.org/10.1007/s00330-014-3202-1", "pmc_url": "", "article_url": "https://doi.org/10.1007/s00330-014-3202-1"}, {"id": "pmid-20848245", "pmid": "20848245", "pmcid": "PMC3032872", "doi": "10.1007/s11999-010-1550-y", "title": "Percutaneous vertebroplasty relieves pain in metastatic cervical fractures", "title_fr": "Vertébroplastie / Cimentoplastie percutanée des métastases du rachis cervical : voies d'abord, sécurité et efficacité antalgique", "authors_list": ["Masala S", "Anselmetti GC", "Muto M", "Mammucari M", "Volpi T", "Simonetti G"], "authors_short": "Masala S, Anselmetti GC et al.", "journal": "Clinical orthopaedics and related research", "journal_short": "Clin Orthop Relat Res", "impact_factor": 4.2, "year": 2011, "month_num": 3, "month_fr": "Mars", "pub_date_fr": "Mars 2011", "volume": "469", "issue": "3", "pages": "715-722", "category_id": "consolidation_screw_cement", "category_label": "Cimentoplastie & Vissage Percutané du Bassin", "category_short": "Cimentoplastie & Vissage Bassin", "category_color": "#8b5cf6", "modality": "Scanner TDM / Fluoroscopie", "intervention_type": "Cimentoplastie Cervicale", "cochin_link": "Correspond exactement aux cimentoplasties cervicales sous AG post-radiothérapie programmées au scanner Achard -1 (avec gestion péri-opératoire des anticoagulants Eliquis + Plavix).", "summary_fr_short": "Étude évaluant la cimentoplastie percutanée des fractures et lésions ostéolytiques métastatiques du rachis cervical (C2 à C7). Sous guidage scanner haute résolution, l'injection contrôlée de PMMA procure une stabilisation rachidienne immédiate et une réduction drastique des cervicalgies mécaniques rebelles.", "summary_fr_detailed": "La cimentoplastie cervicale est un geste de haute technicité en raison de la proximité de l'axe jugulo-carotidien, de l'artère vertébrale, du pharynx/œsophage et de la moelle cervicale. Cet article démontre que le guidage scanner (ou biplan/TDM combiné) par voie antéro-latérale pré-vasculaire (C3–C7) ou trans-orale/antéro-latérale haute (C2) permet un positionnement millimétrique du trocart 13G–15G. Chez les patients sous double traitement antithrombotique (ex: AOD type apixaban/Eliquis + clopidogrel/Plavix), une fenêtre d'arrêt coordonnée avec l'anesthésiste et le cardiologue est indispensable pour prévenir tout hématome pré-vertébral ou épidural.", "protocol_fr": "Sous AG • Voie antéro-latérale cervicale sous TDM en réclinant manuellement le paquet jugulo-carotidien en dehors et l'axe viscéral (trachée/œsophage) en dedans • Trocart biseauté 13G ou 15G • Injection fractionnée de ciment PMMA radio-opaque de haute viscosité (1,5 à 2,5 mL) sous contrôle TDM séquentiel • Gestion stricte des anticoagulants (arrêt Eliquis J-3, relais/arrêt Plavix selon protocole anesthésie).", "key_points_fr": ["Réduction rapide et durable des douleurs cervicales (> 80 % des patients) et prévention du collapsus vertébral secondaire.", "Voie antéro-latérale sous TDM (entre la gaine carotidienne latéralement et l'œsophage médialement) : voie de choix pour C3–C7.", "Geste classé à haut risque hémorragique (espace rétropharyngé et canal rachidien cervical) : arrêt impératif des AOD (Eliquis J-3) et gestion des antiagrégants (Plavix) validés en consultation d'anesthésie.", "Faible volume de ciment nécessaire (1,5 à 2,5 mL) pour restaurer la résistance mécanique d'un corps vertébral cervical."], "abstract_en": "Background Percutaneous vertebroplasty is currently an alternative for treating vertebral fractures of the thoracic and lumbar spine, providing both pain control and vertebral stabilization. In the cervical spine, however, percutaneous vertebroplasty is technically challenging because of the complex anatomy of this region. Questions/purposes We evaluated the technical feasibility, complication rate, and ability of percutaneous vertebroplasty to provide pain relief in patients with painful metastatic cervical fractures. Methods We retrospectively reviewed 62 patients (24 men) who, between May 2005 and May 2009, underwent vertebroplasty to treat painful metastatic cervical fractures. Each patient was evaluated by a visual analog scale for pain, number of pain analgesics, and CT and MRI before, the day after, and at 3 months after the procedure. Results Two of the 62 patients had asymptomatic cement leakage in the soft tissues. We observed no delayed complications. Mean pretreatment and 24-hour posttreatment visual analog scale pain scores were 7.9±1.7 and 1.5±2, respectively. Immediately after surgery, the pain completely disappeared in 25 (40%) patients. Administration of analgesics was suspended in 34 (55%) patients whereas in 27 (39%) patients the median analgesics use decreased from two pills per day (range, 0-3) to 0 (range, 0-3). In two (3%) patients, analgesics administration was continued due to the persistence of pain. At 3 months, the patients reported a mean visual analog scale pain score of 1.7±2. Conclusions Our data suggest, in selected patients, percutaneous vertebroplasty may be performed with a high technical success rate combined with a low complication rate, providing immediate pain relief lasting at least 3 months and a reduction in the use of analgesic drugs. Level of evidence Level IV, therapeutic study. See Guidelines for Authors for a complete description of levels of evidence.", "tags": ["Cimentoplastie cervicale", "Vertébroplastie", "Rachis cervical", "Anticoagulants", "Eliquis", "Scanner"], "pdf_file": "pdfs/PMID_20848245.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 484, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/20848245/", "doi_url": "https://doi.org/10.1007/s11999-010-1550-y", "pmc_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3032872/", "article_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3032872/"}, {"id": "pmid-19304917", "pmid": "19304917", "pmcid": "", "doi": "10.1148/radiol.2512080500", "title": "Chondroblastoma: radiofrequency ablation--alternative to surgical resection in selected cases", "title_fr": "Chondroblastome : l'ablation par radiofréquence comme alternative curative à la résection chirurgicale", "authors_list": ["Rybak LD", "Rosenthal DI", "Wittig JC"], "authors_short": "Rybak LD, Rosenthal DI, Wittig JC", "journal": "Radiology", "journal_short": "Radiology", "impact_factor": 12.1, "year": 2009, "month_num": 3, "month_fr": "Mars", "pub_date_fr": "Mars 2009", "volume": "251", "issue": "2", "pages": "599-604", "category_id": "ablation_benign", "category_label": "Ablation Thermique des Tumeurs Osseuses Bénignes", "category_short": "RF & Cryo (OO / Chondroblastome / TCG)", "category_color": "#f97316", "modality": "Scanner TDM", "intervention_type": "Radiofréquence (RF)", "cochin_link": "Référence fondamentale pour les radiofréquences et cryoablations de chondroblastome du genou (à distance de la lame sous-chondrale) et la gestion des récidives locales en Radiologie B.", "summary_fr_short": "Étude princeps démontrant que l'ablation thermique par radiofréquence sous scanner est une alternative sûre et efficace au curetage chirurgical pour les chondroblastomes épiphysaires sélectionnés. Elle permet une sédation rapide des douleurs et une préservation articulaire, sous réserve d'une maîtrise stricte de la marge thermique vis-à-vis du cartilage hyalin sous-chondral.", "summary_fr_detailed": "Le chondroblastome est une tumeur cartilagineuse bénigne mais localement agressive touchant électivement les épiphyses (genou, tête fémorale, tête humérale). Le curetage chirurgical expose au risque de lésion du cartilage articulaire ou du cartilage de croissance et présente un taux de récidive de 10 à 35 %. Dans cette série de *Radiology*, l'ablation par radiofréquence guidée par scanner obtient une disparition complète des douleurs et une récupération fonctionnelle rapide. Le point critique est le respect d'une distance de sécurité par rapport à la lame osseuse sous-chondrale pour éviter toute chondrolyse secondaire ou effondrement articulaire.", "protocol_fr": "Bilan pré-thérapeutique par TDM fin + IRM pour mesurer l'épaisseur de la lame sous-chondrale • Abord extra-articulaire strict • Multi-positionnement de l'électrode RF (ou cryosonde) si la lésion dépasse 15–20 mm • Refroidissement intra-articulaire au sérum physiologique si proximité cartilagineuse.", "key_points_fr": ["Alternative mini-invasive majeure au curetage chirurgical pour les chondroblastomes épiphysaires de taille petite à modérée (< 2,5 cm).", "Préservation de la lame osseuse sous-chondrale indispensable : risque d'effondrement ostéochondral si l'ablation touche directement l'os sous-chondral porteur.", "En cas de lésion résiduelle sur les berges d'une cavité déjà traitée, une séance complémentaire ciblée (RF ou cryoablation) permet le contrôle local.", "Suivi IRM et TDM indispensable à 3, 6 et 12 mois pour évaluer la réossification progressive de la loge d'ablation."], "abstract_en": "Purpose To demonstrate that radiofrequency (RF) ablation can be used safely and effectively to treat selected cases of chondroblastoma. Materials and methods Approval was obtained from institutional review boards, research was in compliance with HIPAA protocol. The need to obtain informed consent was waived for retrospective review of patient records. The records of patients with biopsy-proved chondroblastoma who were treated with RF ablation at two academic centers from July 1995 to July 2007 were reviewed. RF ablation was performed with a single-tip electrode by using computed tomography for guidance. Lesion characteristics were determined from imaging studies obtained at the time of the procedure. Symptoms were assessed before and 1 day after the procedure. Longer-term follow-up was obtained from medical records. Results Thirteen male and four female patients were treated (mean age, 17.3 years). The lesions were located in the proximal humerus (n = 7), proximal tibia (n = 4), proximal femur (n = 3), and distal femur (n = 3). The mean volume of the lesions was 2.46 mL. All patients reported relief of symptoms on postprocedure day 1. Three patients were lost to follow-up. Of the 14 patients for whom longer-term (mean, 41.3 months; range, 4-134 months) follow-up was available, 12 had complete relief of symptoms with no need for medications and full return to all activities. The patient who had the largest lesion of the study required surgical intervention because of collapse of the articular surface in the treatment area. Residual viable tumor was found at surgery. Another patient experienced mechanical problems that were thought to be unrelated to the RF ablation and was rendered pain-free after subsequent surgical treatment. Conclusion Percutaneous RF ablation is an alternative to surgery for treatment of selected chondroblastomas. Larger lesions beneath weight-bearing surfaces should be approached with caution due to an increased risk of articular collapse and recurrence.", "tags": ["Chondroblastome", "Radiofréquence", "Genou", "Épiphyse", "Lame sous-chondrale", "Radiology"], "pdf_file": "pdfs/PMID_19304917.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 159, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/19304917/", "doi_url": "https://doi.org/10.1148/radiol.2512080500", "pmc_url": "", "article_url": "https://doi.org/10.1148/radiol.2512080500"}, {"id": "pmid-18635627", "pmid": "18635627", "pmcid": "", "doi": "10.1148/rg.284075156", "title": "Diagnostic imaging of solitary tumors of the spine: what to do and say", "title_fr": "Imagerie diagnostique des tumeurs solitaires du rachis et du bassin : sémiologie, algorithme et conduite à tenir (Équipe Cochin)", "authors_list": ["Rodallec MH", "Feydy A", "Larousserie F", "Anract P", "Campagna R", "Babinet A", "Zins M", "Drapé JL"], "authors_short": "Rodallec MH, Feydy A et al.", "journal": "Radiographics : a review publication of the Radiological Society of North America, Inc", "journal_short": "RadioGraphics", "impact_factor": 5.2, "year": 2008, "month_num": 7, "month_fr": "Juil.", "pub_date_fr": "Juil. 2008", "volume": "28", "issue": "4", "pages": "1019-1041", "category_id": "msk_imaging", "category_label": "Imagerie Ostéo-Articulaire Diagnostique & Suivi Post-Geste", "category_short": "IRM / TDM Diagnostique & Suivi", "category_color": "#6366f1", "modality": "IRM / Scanner TDM", "intervention_type": "Imagerie Diagnostique & Bilan pré-biopsie", "cochin_link": "Article de référence de l'équipe de l'Hôpital Cochin (Rodallec, Feydy, Larousserie, Anract, Campagna, Drapé — Services de Radiologie B, Anatomopathologie et Orthopédie).", "summary_fr_short": "Publication majeure de l'équipe de Cochin dans *RadioGraphics* détaillant la démarche diagnostique complète devant une lésion tumorale solitaire du rachis ou du sacrum : sémiologie TDM et IRM selon l'âge et la topographie (corps vertébral vs arc postérieur), pièges diagnostiques (myélolipome, hémangiome agressif, kyste anévrismal) et planification de la biopsie radioguidée.", "summary_fr_detailed": "Rédigé par les équipes de Radiologie B, d'Orthopédie et d'Anatomopathologie de l'Hôpital Cochin, cet article de référence structure l'analyse radiologique des tumeurs rachidiennes et sacrées : tumeurs bénignes de l'arc postérieur chez le sujet jeune (ostéome ostéoïde, ostéoblastome, kyste osseux anévrismal), tumeurs malignes ou localement agressives du corps vertébral et du sacrum chez l'adulte (métastase solitaire, plasmocytome, lymphome, chordome, chondrosarcome), et pseudo-tumeurs ou lésions rares à composante graisseuse/hématopoïétique (hémangiome agressif, myélolipome pré-sacré). Il précise ce que le radiologue doit impérativement mentionner dans son compte rendu et comment planifier la voie de biopsie.", "protocol_fr": "Association systématique TDM en coupes fines (analyse de la matrice minéralisée, des corticales et du nidus) + IRM (T1 sans injection pour la moelle osseuse et le contingent graisseux microscopique/macroscopique, T2/STIR, T1 FS Gadolinium).", "key_points_fr": ["Toute lésion de l'arc postérieur avec scoliose douloureuse raide chez un sujet jeune doit faire rechercher un ostéome ostéoïde ou un ostéoblastome.", "Devant une masse pré-sacrée ou sacrée contenant des îlots graisseux en hypersignal T1 qui s'effacent en saturation de graisse, évoquer un myélolipome pré-sacré (diagnostic différentiel du liposarcome et du chordome).", "La biopsie percutanée sous scanner d'une lésion rachidienne ou sacrée suspecte de sarcome/chordome doit emprunter une voie postérieure strictement concertée avec le chirurgien.", "Référence historique illustrant la synergie Radio B – Orthopédie – Anatomopathologie à l'Hôpital Cochin."], "abstract_en": "Metastatic disease, myeloma, and lymphoma are the most common malignant spinal tumors. Hemangioma is the most common benign tumor of the spine. Other primary osseous lesions of the spine are more unusual but may exhibit characteristic imaging features that can help the radiologist develop a differential diagnosis. Radiologic evaluation of a patient who presents with osseous vertebral lesions often includes radiography, computed tomography (CT), and magnetic resonance (MR) imaging. Because of the complex anatomy of the vertebrae, CT is more useful than conventional radiography for evaluating lesion location and analyzing bone destruction and condensation. The diagnosis of spinal tumors is based on patient age, topographic features of the tumor, and lesion pattern as seen at CT and MR imaging. A systematic approach is useful for recognizing tumors of the spine with characteristic features such as bone island, osteoid osteoma, osteochondroma, chondrosarcoma, vertebral angioma, and aneurysmal bone cyst. In the remaining cases, the differential diagnosis may include other primary spinal tumors, vertebral metastases and major nontumoral lesions simulating a vertebral tumor, Paget disease, spondylitis, echinococcal infection, and aseptic osteitis. In many cases, vertebral biopsy is warranted to guide treatment.", "tags": ["Hôpital Cochin", "Radiologie B", "Tumeurs du rachis", "Sacrum", "Myélolipome", "RadioGraphics"], "pdf_file": "pdfs/PMID_18635627.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 678, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/18635627/", "doi_url": "https://doi.org/10.1148/rg.284075156", "pmc_url": "", "article_url": "https://doi.org/10.1148/rg.284075156"}, {"id": "pmid-12773675", "pmid": "12773675", "pmcid": "", "doi": "10.1148/radiol.2273020111", "title": "Imaging of osteoid osteoma with dynamic gadolinium-enhanced MR imaging", "title_fr": "Imagerie de l'ostéome ostéoïde par IRM dynamique après injection de gadolinium (DCE-MRI) : détection du nidus et suivi post-RF", "authors_list": ["Liu PT", "Chivers FS", "Roberts CC", "Schultz CJ", "Beauchamp CP"], "authors_short": "Liu PT, Chivers FS et al.", "journal": "Radiology", "journal_short": "Radiology", "impact_factor": 12.1, "year": 2003, "month_num": 6, "month_fr": "Juin", "pub_date_fr": "Juin 2003", "volume": "227", "issue": "3", "pages": "691-700", "category_id": "msk_imaging", "category_label": "Imagerie Ostéo-Articulaire Diagnostique & Suivi Post-Geste", "category_short": "IRM / TDM Diagnostique & Suivi", "category_color": "#6366f1", "modality": "IRM", "intervention_type": "IRM Dynamique (Protocole OO)", "cochin_link": "Correspond exactement aux examens d'IRM 'protocole OO avec injection dynamique' programmés au Pavillon Achard -1 avant consultation et radiofréquence d'ostéome ostéoïde.", "summary_fr_short": "Étude princeps de *Radiology* démontrant que l'IRM dynamique injectée au temps artériel réalise une détection du nidus de l'ostéome ostéoïde bien supérieure à l'IRM conventionnelle et égale au scanner fin. Le nidus hypervasculaire présente un rehaussement artériel précoce intense suivi d'un lavage ('wash-out'), tandis que l'œdème réactionnel péri-lésionnel se rehausse tardivement.", "summary_fr_detailed": "Sur les séquences IRM morphologiques standard (T1, T2 FS), le petit nidus de l'ostéome ostéoïde (particulièrement dans les formes intra-articulaires du col fémoral, du coude ou de l'astragale) est fréquemment masqué par l'intense œdème médullaire et synovial réactionnel. L'acquisition dynamique 3D T1 écho de gradient avec saturation de graisse toutes les 10 à 15 secondes après bolus de gadolinium met en évidence un pic de rehaussement artériel précoce du nidus dès la phase artérielle (82 % des cas), permettant à la fois d'affirmer le diagnostic en pré-opératoire et de vérifier la nécrose complète du nidus après radiofréquence ou cryoablation.", "protocol_fr": "Protocole IRM Ostéome Ostéoïde (Cochin Achard -1) : Séquences T1, T2 DIXON/STIR dans 2 plans + Séquence 3D T1 FS dynamique (résolution temporelle 10–15 s pendant 2 minutes dès l'injection de Gadolinium) avec courbes de perfusion ROI sur le nidus et soustraction • Même protocole utilisé en suivi post-RF/Cryo en cas de doute sur un reliquat actif.", "key_points_fr": ["L'IRM sans séquence dynamique méconnaît jusqu'à 35 % des nidus d'ostéome ostéoïde noyés dans l'œdème médullaire.", "Signature hémodynamique pathognomonique du nidus : rehaussement intense au temps artériel précoce (< 30 s) avec wash-out veineux.", "Indispensable pour les ostéomes ostéoïdes intra-articulaires (hanche, coude, astragale) où l'ostéosclérose périphérique est absente ou minime.", "En suivi post-ablation thermique (RF ou cryoablation), la disparition complète du rehaussement artériel précoce signe l'éradication du nidus."], "abstract_en": "Purpose To compare dynamic gadolinium-enhanced T1-weighted magnetic resonance (MR) imaging with nonenhanced T1-weighted and T2-weighted MR imaging and thin-section computed tomography (CT) for the demonstration of osteoid osteomas. Materials and methods The images of 11 patients with pathologically proven osteoid osteomas who underwent nonenhanced MR imaging, dynamic gadolinium-enhanced MR imaging, and CT were retrospectively reviewed. Images obtained with all three techniques were scored for conspicuity of the osteoid osteoma relative to the surrounding bone. Time-enhancement curves were generated from signal intensity measurements of these lesions and the adjacent bone marrow. The mean imaging scores of the four techniques were compared, and the statistical significance was calculated by using a linear model with terms for method and patient. Pairwise comparisons were made by using the Tukey-Kramer adjustment for multiple comparisons. Results Compared with CT, dynamic gadolinium-enhanced MR imaging demonstrated the osteoid osteoma equally well in eight of 11 patients and with better conspicuity in three of 11 patients, although this difference was not statistically significant (P =.69). The dynamic gadolinium-enhanced MR images demonstrated the osteoid osteomas significantly better than the nonenhanced T1-weighted (P Conclusion Osteoid osteomas can be imaged with greater conspicuity by using dynamic gadolinium-enhanced instead of nonenhanced MR imaging and with conspicuity equal to or better than that obtained with thin-section CT.", "tags": ["IRM dynamique", "Ostéome ostéoïde", "Nidus", "Gadolinium", "Suivi post-ablation", "Radiology"], "pdf_file": "pdfs/PMID_12773675.pdf", "pdf_source": "publisher_oa_pdf", "pdf_size_kb": 737, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/12773675/", "doi_url": "https://doi.org/10.1148/radiol.2273020111", "pmc_url": "", "article_url": "https://doi.org/10.1148/radiol.2273020111"}];
window.BIBLIO_SYNTHESES = [{"category_id": "ablation_benign", "evidence": "Niveau de preuve modéré : 2 revues systématiques/comparatives, 1 registre multicentrique (DeGIR), cohortes rétrospectives et séries princeps.", "bottom_line": "La thermo-ablation percutanée sous scanner (RF ou cryoablation) est le traitement de référence de l'ostéome ostéoïde, avec > 92–96 % de guérison clinique dès la première séance et < 2 % de complications ; elle s'étend aux chondroblastomes épiphysaires < 2,5 cm et aux récidives focales de TCG.", "kpis": [{"v": "92–99 %", "l": "Succès technique/clinique OO (1 séance)", "r": ["41876692", "42489686", "33839926"]}, {"v": "96 %", "l": "Succès cryo « no-touch » (adulte, n = 50)", "r": ["34812672"]}, {"v": "1,8 %", "l": "Complications (registre DeGIR, n = 166)", "r": ["41876692"]}, {"v": "×6,5", "l": "Risque de récidive si nidus extracortical", "r": ["41867110"]}], "sections": [{"k": "indications", "title": "Indications retenues", "items": [{"t": "Ostéome ostéoïde typique (cortical, médullaire, intra-articulaire) : RF = gold standard historique (71 % des procédures du registre DeGIR), cryoablation d'efficacité équivalente (> 93 %).", "r": ["41876692", "33839926"]}, {"t": "OO intra-articulaire (cotyle, coude, talus) : la RF scanoguidée accède aux nidus inaccessibles à l'arthroscopie et fait céder la synovite réactionnelle.", "r": ["42931896"]}, {"t": "Chondroblastome épiphysaire < 2,5 cm : alternative au curetage avec préservation articulaire.", "r": ["19304917"]}, {"t": "Récidive locale focale de TCG après curetage : RF/cryo ± comblement PMMA si corticale ou os sous-chondral fragilisé.", "r": ["41568883"]}]}, {"k": "technique", "title": "Technique & choix de l'énergie", "items": [{"t": "Cryoablation « no-touch » extra-osseuse : pas de forage du nidus, visualisation de l'iceball, 60 % des gestes sous AL + sédation ; privilégiée au tarse et sur les lésions superficielles.", "r": ["34812672", "33839926"]}, {"t": "L'os cortical freine la RF (haute impédance) mais laisse diffuser le froid : penser cryo pour les lésions corticales épaisses/scléreuses.", "r": ["24838839"]}, {"t": "Nidus extracortical + DCE-MRI lent (TTP > 40 s, MRE < 300 %) : risque de récidive > 55 % → prolonger l'ablation, augmenter la température ou basculer en cryo.", "r": ["41867110"]}, {"t": "Robotique : moins de repositionnements dans les trajets obliques, sans gain d'efficacité vs guidage TDM expert (440 procédures).", "r": ["42671500"]}]}, {"k": "safety", "title": "Sécurité & structures nobles", "warn": true, "items": [{"t": "Seuils de neurotoxicité : < 10 °C et > 45 °C au contact des troncs nerveux ; hydro-/carbodissection pour écarter peau, nerfs et tube digestif.", "r": ["24838839"]}, {"t": "Lésions superficielles (tibia antérieur, talus, coude) : risque de brûlure cutanée/cartilagineuse.", "r": ["42489686"]}, {"t": "Chondroblastome : préserver la lame sous-chondrale (risque d'effondrement ostéochondral).", "r": ["19304917"]}, {"t": "Dosimétrie (enfant) : DLP médian 124 mGy·cm (membres) / 222 mGy·cm (axial) comme référentiel ALARA ; collimation serrée et bas kV.", "r": ["41876692", "42489686"]}]}, {"k": "followup", "title": "Bilan & suivi", "items": [{"t": "IRM dynamique injectée pré-geste pour confirmer le nidus et limiter les acquisitions TDM diagnostiques.", "r": ["42489686", "41867110"]}, {"t": "Chondroblastome / TCG : IRM + TDM à 3, 6 et 12 mois (réossification, interface os-ciment).", "r": ["19304917", "41568883"]}]}], "sources": ["19304917", "24838839", "33839926", "34812672", "41568883", "41867110", "41876692", "42489686", "42671500", "42931896"]}, {"category_id": "desmoid_soft_tissue", "evidence": "Niveau de preuve modéré à élevé : 1 essai prospectif de phase II (CRYODESMO-01), consensus SIR, cohortes rétrospectives et revues 2024–2026.", "bottom_line": "La cryoablation percutanée est la modalité ablative de choix des tumeurs desmoïdes extra-abdominales symptomatiques ou progressives : 85–91 % de contrôle local à 12–16 mois, 78–79 % de réponse objective (mRECIST) et ~5 % de complications majeures, avec retraitement itératif possible.", "kpis": [{"v": "85,6 %", "l": "Non-progression à 12 mois (phase II, n = 50)", "r": ["33290994"]}, {"v": "78–79 %", "l": "Réponse objective mRECIST", "r": ["42731622", "42384128"]}, {"v": "94,6 %", "l": "Contrôle de la maladie (n = 44, 6,9 cm)", "r": ["42731622"]}, {"v": "5,3 %", "l": "Complications majeures (SIR ≥ 3)", "r": ["42731622"]}], "sections": [{"k": "indications", "title": "Indications retenues", "items": [{"t": "Desmoïde extra-abdominale progressive ou symptomatique après surveillance active ou traitement systémique (alternative à la chirurgie délabrante).", "r": ["33290994", "42631901"]}, {"t": "Ablation subtotale délibérée à visée antalgique/fonctionnelle au contact d'un plexus (creux sus-claviculaire / plexus brachial).", "r": ["42955498", "42631901"]}, {"t": "Oligoprogression sous traitement systémique : cryo focale sur le contingent résiduel ; consensus SIR plaçant la cryo au premier plan de la stratégie multimodale chez le sujet jeune.", "r": ["42955498", "42641400"]}, {"t": "Autres cibles parties molles : endométriomes pariétaux, nodules oligométastatiques musculaires/sous-cutanés.", "r": ["39556172"]}]}, {"k": "technique", "title": "Technique", "items": [{"t": "Isotherme létal (−20 à −40 °C) à 3–5 mm en dedans du bord visible du glaçon (0 °C) : planifier la couverture en conséquence.", "r": ["39556172"]}, {"t": "Planification multi-sondes selon volume tumoral et proximité nerveuse ; retraitement itératif chez 26 % des patients.", "r": ["33290994", "42731622"]}, {"t": "Petites lésions à distance des troncs moteurs : faisable sous AL + sédation consciente.", "r": ["39556172"]}]}, {"k": "safety", "title": "Sécurité & protection", "warn": true, "items": [{"t": "Hydrodissection sous-cutanée continue et réchauffement cutané pour les nodules superficiels (trapèze, paroi thoracique).", "r": ["39556172", "42955498"]}, {"t": "Protection nerveuse active au contact des plexus ; accepter une ablation subtotale plutôt qu'un déficit moteur.", "r": ["42955498", "42631901"]}]}, {"k": "followup", "title": "Évaluation de la réponse (IRM)", "items": [{"t": "Utiliser mRECIST / volumétrie du tissu viable rehaussé, pas RECIST 1.1 : ORR 79,4 % vs 28,6 % ; concordance mRECIST–volumétrie 3D κ = 0,895.", "r": ["42384128", "42731622"]}, {"t": "Une cicatrice fibreuse non rehaussée de taille inchangée peut correspondre à une réponse complète ; utiliser la soustraction post-gadolinium.", "r": ["42384128", "41357250"]}]}], "sources": ["33290994", "39556172", "42384128", "42631901", "42641400", "42731622", "42955498", "41357250"]}, {"category_id": "ect_mets", "evidence": "Niveau de preuve modéré : 1 méta-analyse PRISMA (toxicité bléomycine, 7 601 patients), 1 revue systématique, séries cliniques, étude préclinique et protocole prospectif (BOREALIS).", "bottom_line": "L'électrochimiothérapie (bléomycine IV + électroporation réversible) est la seule technique ablative percutanée utilisable au contact direct de la moelle, des racines ou de la peau : antalgie rapide (EVA 7 → 1 à 1 mois dans l'épidurite réfractaire) et réponse épidurale objective chez 77 % des patients, sans effet thermique.", "kpis": [{"v": "7 → 1", "l": "EVA médiane à 1 mois (épidurite réfractaire, n = 40)", "r": ["37030078"]}, {"v": "77 %", "l": "Réponse épidurale objective en IRM", "r": ["37030078"]}, {"v": "56 %", "l": "Amélioration neurologique à 1 mois", "r": ["37030078"]}, {"v": "85–92 %", "l": "Contrôle local à 1 an (cryo oligométastatique)", "r": ["37504355"]}], "sections": [{"k": "indications", "title": "Indications retenues", "items": [{"t": "Coulée épidurale / compression médullaire métastatique réfractaire à la radiothérapie, au contact du fourreau dural.", "r": ["37030078", "42785703"]}, {"t": "Métastases distales (pied, main), juxta-articulaires ou radiorésistantes (rein, mélanome).", "r": ["37834793", "38732352"]}, {"t": "Lésions volumineuses : association « cryoablation centrale (debulking) + couronne périphérique d'ECT » ± cimentoplastie dans le même temps.", "r": ["38732352", "37834793"]}, {"t": "Maladie oligométastatique osseuse : cryoablation à visée curative avec marge ≥ 5 mm (protocole BOREALIS).", "r": ["42618654", "37504355"]}]}, {"k": "technique", "title": "Technique & pharmacologie", "items": [{"t": "Bléomycine 15 000 UI/m² IV en bolus ; impulsions délivrées entre 8 et 40 min après l'injection.", "r": ["37834793", "42998777"]}, {"t": "Électrodes : voie transpédiculaire validée au rachis ; électrodes bipolaires mono-aiguille pour réduire le nombre d'insertions et confiner le champ.", "r": ["40906057", "42804145"]}, {"t": "Planification patient-spécifique du champ électrique (3D Slicer / AI4DEEP) : isodose 160–200 V/cm corrélée à la nécrose IRM.", "r": ["42612110"]}]}, {"k": "safety", "title": "Sécurité", "warn": true, "items": [{"t": "Anesthésie : FiO2 < 30 % après bléomycine (risque de toxicité pulmonaire) — coordination indispensable avec l'anesthésiste.", "r": ["38732352", "42998777"]}, {"t": "Âge avancé et métastases pulmonaires ne contre-indiquent pas une séance unique d'ECT (méta-analyse 7 601 patients : risque lié aux doses cumulées de chimiothérapie).", "r": ["42998777"]}, {"t": "Neuromonitoring : chute transitoire des PEM après impulsion, récupération complète < 30 min ; aucune lésion médullaire histologique.", "r": ["40906057"]}, {"t": "Cryoablation distale ou sous anti-angiogéniques (lenvatinib) : vigilance cutanée renforcée.", "r": ["37504355"]}]}, {"k": "followup", "title": "Suivi", "items": [{"t": "IRM injectée à 1 et 3 mois : réponse du contingent épidural (score ESCCS) et douleur ; réduction des opioïdes dès le 1er mois.", "r": ["37030078", "38732352"]}]}], "sources": ["37030078", "37504355", "37834793", "38732352", "40906057", "42612110", "42618654", "42785703", "42804145", "42998777"]}, {"category_id": "consolidation_screw_cement", "evidence": "Niveau de preuve modéré : 2 revues systématiques (dont 76 études / 3 234 patients en cimentoplastie rachidienne), cohortes multicentriques et séries techniques.", "bottom_line": "La cimentoplastie traite la compression (corps vertébral, toit du cotyle) et le vissage percutané ± cimenté le cisaillement (anneau pelvien, sacrum, col) : antalgie > 80–88 %, complications symptomatiques ~3 % et reprise d'appui précoce ; l'association ablation + vis + ciment en une séance est validée pour les métastases pelviennes.", "kpis": [{"v": "3,4 %", "l": "Complications symptomatiques (cimentoplastie, 3 234 pts)", "r": ["42780331"]}, {"v": "20,7 %", "l": "Fuites de ciment (majoritairement asymptomatiques)", "r": ["42780331"]}, {"v": "88 %", "l": "Succès antalgique os thoraciques extra-rachidiens", "r": ["42439173"]}, {"v": "97 %", "l": "Positionnement intra-osseux vis ilio-sacrées", "r": ["42767629"]}], "sections": [{"k": "indications", "title": "Indications retenues", "items": [{"t": "Métastases et myélome rachidiens douloureux : cimentoplastie (39 % des patients de RCP Métastases Osseuses en CHU vs 22 % de chirurgie).", "r": ["42947096", "40911195"]}, {"t": "Fractures sacrées par insuffisance (U / Rommens IVb) et fractures pathologiques ou post-radiques de l'anneau pelvien : vissage ilio-/trans-sacré.", "r": ["42891691", "26318372"]}, {"t": "Métastases pelviennes douloureuses : cryoablation + vissage + cimentoplastie en une séance.", "r": ["42173356"]}, {"t": "Sites atypiques : rachis cervical (voie antéro-latérale C3–C7), sternum/côtes/clavicule/scapula, humérus (ballonnet photopolymérisable, Mirels 8–10).", "r": ["20848245", "42439173", "42938822"]}]}, {"k": "technique", "title": "Technique", "items": [{"t": "Ciment = compression ; vis canulées = cisaillement ; scellement cimenté des vis en os irradié/ostéoporotique pour éviter migration.", "r": ["38544877", "26318372", "42173356"]}, {"t": "Après cryoablation, attendre le réchauffement complet avant d'injecter le PMMA (polymérisation retardée, fuites).", "r": ["42173356", "38544877"]}, {"t": "Corridors S1/S2 très variables (10–32 mm) : planification 3D/CBCT ; procubitus pour associer vissage et sacroplastie ; incidences COOHO/Outlet/Profil strict pour les colonnes acétabulaires.", "r": ["42471112", "42767629", "42663695"]}]}, {"k": "safety", "title": "Sécurité & pièges", "warn": true, "items": [{"t": "Embolie pulmonaire de ciment 1,08 % ; le contrôle TDM détecte 2,4× plus de fuites que la scopie.", "r": ["42780331"]}, {"t": "Fuite intradiscale : risque de fracture adjacente 31 % vs 8,8 % (myélome) — à éviter.", "r": ["40911195"]}, {"t": "Rachis cervical = geste à haut risque hémorragique : arrêt AOD et gestion des antiagrégants en consultation d'anesthésie.", "r": ["20848245"]}]}, {"k": "followup", "title": "Résultats à long terme", "items": [{"t": "Myélome : 1,4 % de refracture locale à > 5 ans sur 142 sites cimentés.", "r": ["40911195"]}, {"t": "Vissage pelvien : appui dès J1, complication 0,6 % (169 vis), durée médiane 47 min.", "r": ["26318372", "42471112"]}]}], "sources": ["20848245", "26318372", "38544877", "40911195", "42173356", "42439173", "42471112", "42663695", "42767629", "42780331", "42891691", "42938822", "42947096"]}, {"category_id": "cyst_sclerotherapy", "evidence": "Niveau de preuve faible à modéré : 1 étude prospective, séries cliniques (dont recul > 5 ans), étude physiopathologique et revues de synthèse.", "bottom_line": "La sclérothérapie percutanée (éthanol, polidocanol, doxycycline) ± comblement est devenue le traitement de première intention de nombreux KOA et KOE : guérison en 1–2 séances dans 74–95 % des cas, avec très peu de complications, à condition d'avoir éliminé un ostéosarcome télangiectasique.", "kpis": [{"v": "80–90 %", "l": "Ostéogenèse réparatrice après alcoolisation (1–2 séances)", "r": ["34367902"]}, {"v": "95 %", "l": "Sans récidive à 30 mois (polidocanol + moelle, KOA)", "r": ["42483265"]}, {"v": "74,1 %", "l": "Guérison en 1 séance (Sclerograft modifié, KOA)", "r": ["42477120"]}, {"v": "87,1 %", "l": "Succès en 1 séance (ciment phosphocalcique, KOE)", "r": ["42729247"]}], "sections": [{"k": "indications", "title": "Indications retenues", "items": [{"t": "KOA primaire (réarrangement USP6) et KOE symptomatiques ou à risque fracturaire, en première intention avant curetage.", "r": ["41857607", "35941207"]}, {"t": "KOE volumineux (aile iliaque, humérus) : alcoolisation + comblement/cimentoplastie avant reprise sportive.", "r": ["34367902", "42729247"]}, {"t": "KOA volumineux, axiaux ou récidivants : sclérothérapie ± cryoablation des contingents charnus ou embolisation sélective.", "r": ["42477120", "41857607"]}]}, {"k": "technique", "title": "Technique", "items": [{"t": "Montage à double trocart (décompression/drainage) : l'hyperpression intrakystique (90 vs 67 mmHg) justifie physiologiquement la décompression.", "r": ["42234093", "34367902"]}, {"t": "Kystographie iodée préalable obligatoire avant alcoolisation (fuite veineuse directe, passage articulaire).", "r": ["35941207"]}, {"t": "Options d'adjuvants : disruption des cloisons + doxycycline + substitut osseux ; moelle autologue après polidocanol ; ciment phosphocalcique résorbable chez le jeune (≠ PMMA).", "r": ["42477120", "42483265", "42729247"]}]}, {"k": "safety", "title": "Pièges diagnostiques", "warn": true, "items": [{"t": "Toute lésion multiloculée à niveaux liquide-liquide atypique : confirmation histologique/moléculaire (USP6) avant sclérothérapie — diagnostic différentiel de l'ostéosarcome télangiectasique.", "r": ["35941207"]}]}, {"k": "followup", "title": "Suivi", "items": [{"t": "TDM ou radiographies à 3, 6 et 12 mois : épaississement cortical, disparition de l'effet soufflant, ossification centripète sur 6–24 mois (Neer I/II).", "r": ["41857607", "35941207", "42729247"]}, {"t": "Récidive partielle : nouvelle injection percutanée possible sans chirurgie ouverte.", "r": ["42729247"]}]}], "sources": ["34367902", "35941207", "41857607", "42234093", "42477120", "42483265", "42729247"]}, {"category_id": "pain_cryoneurolysis", "evidence": "Niveau de preuve élevé pour les nerfs géniculés (méta-analyse de 8 ECR vs sham, 627 patients) et les nerfs clunéaux (méta-analyse, 628 patients) ; modéré pour Morton et intercostaux (cohortes).", "bottom_line": "Après bloc test positif, la neurolyse percutanée (RF conventionnelle ou cryoneurolyse) procure ≥ 50 % de soulagement chez 70–85 % des patients sélectionnés (genou, clunéaux, Morton, intercostaux), sans événement indésirable grave ; la cryoneurolyse induit une axonotmésis réversible (Sunderland II) sans névrome.", "kpis": [{"v": "−1,65 pt", "l": "EVA à 12 sem. vs sham (géniculés, 8 ECR)", "r": ["41063397"]}, {"v": "78–83 %", "l": "Répondeurs névralgie clunéale (3–6 mois)", "r": ["42182575"]}, {"v": "> 80 %", "l": "Succès cryoneurolyse Morton (AL, ambulatoire)", "r": ["38438685", "42942556"]}, {"v": "OR 9,4", "l": "RF conventionnelle vs pulsée (intercostaux)", "r": ["42804317"]}], "sections": [{"k": "indications", "title": "Indications retenues", "items": [{"t": "Gonarthrose sévère (KL 3–4) réfractaire ou en attente de PTG, et douleurs persistantes après prothèse.", "r": ["41063397", "42977533", "42803442"]}, {"t": "Névralgie clunéale supérieure/moyenne (lombo-fessalgies) après bloc diagnostique positif.", "r": ["42182575"]}, {"t": "Névrome de Morton réfractaire au traitement conservateur, y compris après échec d'une première RF.", "r": ["38438685", "42942556"]}, {"t": "Névralgie intercostale (post-zostérienne, post-traumatique, oncologique) et douleurs post-amputation.", "r": ["42804317", "28431129"]}]}, {"k": "technique", "title": "Technique", "items": [{"t": "Bloc test sous échographie à faible volume (0,5–1 mL par nerf) = meilleur prédicteur d'efficacité ; prérequis dans les douleurs non oncologiques.", "r": ["42602563", "42995280", "28431129"]}, {"t": "Genou : repères vasculaires Doppler (artères géniculées) et périostés ; extension à 4–5 cibles possible.", "r": ["42602563", "42803442"]}, {"t": "Préférer une modalité neurolytique vraie (RF conventionnelle ou cryo) à la RF pulsée pour une analgésie durable (NRS 6 mois 2,8 vs 6,3).", "r": ["42804317"]}, {"t": "Clunéal supérieur : franchissement de la crête iliaque postéro-supérieure à 6–8 cm de la ligne médiane.", "r": ["42182575"]}]}, {"k": "safety", "title": "Sécurité & pièges", "warn": true, "items": [{"t": "Ne jamais cibler le nerf géniculé inféro-latéral (risque de lésion du nerf fibulaire commun / steppage).", "r": ["42602563"]}, {"t": "Tests de stimulation sensitive (50 Hz) et motrice (2 Hz) avant toute anesthésie du nerf cible ; ropivacaïne 0,2 % en multi-sites.", "r": ["42742682", "28431129"]}, {"t": "Morton : protection cutanée dans l'espace inter-métatarsien étroit ; Intercostaux : guidage TDM au bord inférieur costal (pneumothorax).", "r": ["38438685", "28431129"]}]}, {"k": "followup", "title": "Suivi", "items": [{"t": "Pas d'aggravation des BML ni de l'arthrose en IRM à 3 mois après RF géniculée refroidie ; bénéfice WOMAC jusqu'à 24 semaines.", "r": ["42977533", "41063397"]}, {"t": "> 70 % des patients sélectionnés maintiennent ≥ 50 % de soulagement à 6–12 mois.", "r": ["28431129"]}]}], "sources": ["28431129", "38438685", "41063397", "42182575", "42602563", "42742682", "42803442", "42804317", "42942556", "42977533", "42995280"]}, {"category_id": "pudendal_cryoneurolysis", "evidence": "Niveau de preuve modéré : 1 série de référence de 362 procédures sur 10 ans, cohortes comparatives (224, 95 et 84 patients), étude IRM et série princeps ; pas d'essai randomisé.", "bottom_line": "La cryoneurolyse du nerf pudendal sous scanner, chez un patient bien sélectionné (triade : facteur déclenchant + douleur périnéale unilatérale systématisée + bloc TDM positif), obtient ~77 % de succès clinique, un intervalle libre moyen de 31,8 mois et 0 % de complication majeure ou sphinctérienne.", "kpis": [{"v": "77,4 %", "l": "Succès clinique si triade de sélection (vs 36,4 %)", "r": ["42276242"]}, {"v": "31,8 mois", "l": "Délai moyen avant réintervention", "r": ["42276242"]}, {"v": "0 %", "l": "Complication majeure / sphinctérienne", "r": ["42276242", "41999357", "32602380"]}, {"v": "OR 4,88", "l": "Bloc diagnostique positif → réponse", "r": ["42999001"]}], "sections": [{"k": "indications", "title": "Indications retenues", "items": [{"t": "Névralgie pudendale réfractaire (critères cliniques) avec bloc diagnostique positif ; étiologie post-chirurgicale = facteur prédictif favorable (OR 2,83).", "r": ["42276242", "42999001"]}, {"t": "Douleurs pelvi-périnéales oncologiques réfractaires : cryoneurolyse pudendale, éventuellement bilatérale en un temps (−5,2 pts d'EVA, sortie en 2,3 j).", "r": ["32602380", "41999357"]}, {"t": "Composante sympathique médiane associée : ajouter le ganglion impar (EVA 6 mois 2,09 vs 3,81 avec PRF pudendale seule).", "r": ["42263315", "41440950"]}]}, {"k": "technique", "title": "Technique", "items": [{"t": "Procubitus, guidage TDM ; cible au niveau de la pince ligamentaire (épine ischiatique / ligament sacro-épineux) ou du canal d'Alcock selon le site du conflit.", "r": ["41594302", "25511935"]}, {"t": "Bloc test TDM indispensable dans les névralgies fonctionnelles/canalaires ; peut être omis en oncologie pelvienne à cible évidente (succès 81,1 % vs 69,7 %, NS ; gain de ~16 jours).", "r": ["42527618"]}, {"t": "Cryo-axonotmésis (−20 à −100 °C) : préservation de l'endonèvre, pas de névrite ni de névrome de désafférentation ; supérieure en durabilité à la RF pulsée (neuromodulation).", "r": ["41440950", "42999001"]}]}, {"k": "safety", "title": "Sécurité", "warn": true, "items": [{"t": "Aucune incontinence ni complication sphinctérienne rapportée, y compris en bilatéral, grâce à la précision du guidage TDM et à la réversibilité de l'axonotmésis.", "r": ["32602380", "41440950", "25511935"]}, {"t": "Hors triade de sélection, le taux de succès chute à 36,4 % : ne pas multiplier les gestes sans bloc positif.", "r": ["42276242"]}]}, {"k": "followup", "title": "Bilan & suivi", "items": [{"t": "IRM pelvienne avec neurographie de diffusion (b = 0, 100, 600) : anomalie du nerf chez 51,9 % des patients, cause compressive identifiée chez ~55 % d'entre eux.", "r": ["41594302"]}, {"t": "Antalgie dès 24 h–J7, maintenue à 6 mois (EVA 7,6 → 3,1) avec épargne morphinique ; retraitement possible après ~2,5 ans.", "r": ["25511935", "41999357", "42276242"]}]}], "sources": ["25511935", "32602380", "41440950", "41594302", "41999357", "42263315", "42276242", "42527618", "42999001"]}, {"category_id": "msk_biopsy", "evidence": "Niveau de preuve modéré : études multicentriques et cohortes rétrospectives (64 à 183 patients), revue critique de la concordance biopsie-résection.", "bottom_line": "La biopsie percutanée sous scanner/écho atteint 94–97 % de rendement diagnostique avec 0 % de complication majeure ; ses limites sont le sous-grading des tumeurs cartilagineuses (surtout pelviennes) et le faible rendement microbiologique des spondylodiscites (37 %, 86 % avec technique optimisée + 16S).", "kpis": [{"v": "93,8 %", "l": "Rendement diagnostique biopsie osseuse TDM", "r": ["42964659"]}, {"v": "95–97 %", "l": "Précision bénin/malin (parties molles, écho)", "r": ["34497298"]}, {"v": "κ 0,12", "l": "Concordance de grade chondrosarcome pelvien", "r": ["42997475"]}, {"v": "51 → 86 %", "l": "Rendement spondylodiscite (technique modifiée + 16S)", "r": ["42363976"]}], "sections": [{"k": "indications", "title": "Indications retenues", "items": [{"t": "Histologie systématique avant ablation ou radiothérapie : le diagnostic clinique pré-geste est corrigé dans 9,4 % des cas.", "r": ["42964659"]}, {"t": "Masse lipomateuse profonde > 5 cm avec septas épais ou nodule non graisseux : microbiopsie ciblée + recherche d'amplification MDM2.", "r": ["42129022"]}, {"t": "Suspicion de spondylodiscite : ne pas récuser la biopsie sous antibiothérapie probabiliste (36,4 % vs 37,8 %, NS).", "r": ["42736384"]}]}, {"k": "technique", "title": "Technique", "items": [{"t": "≥ 3 carottes de ≥ 10 mm ; cibler la berge ostéolytique active / le nodule charnu, pas le centre nécrotique ; envoyer le caillot aspiré en « cell block » (+7 % de rendement).", "r": ["41204964"]}, {"t": "Chondrosarcome : carottes multiples dans des cadrans distincts, viser le contingent non cartilagineux (100 % de sensibilité pour le dédifférencié).", "r": ["42874309", "42997475"]}, {"t": "Spondylodiscite : prélever simultanément l'os sous-chondral du plateau et le disque + séquençage ARN 16S.", "r": ["42363976"]}, {"t": "Lymphome / infiltration médullaire : cibler l'hypersignal diffusion/rehaussement IRM, éviter l'écrasement des carottes.", "r": ["41838307"]}]}, {"k": "safety", "title": "Règles carcinologiques", "warn": true, "items": [{"t": "Ne jamais traverser un compartiment sain ni le fascia profond ; trajet sur la future voie d'incision définie avec les chirurgiens.", "r": ["34497298"]}, {"t": "Une biopsie « bas grade » sur une lésion cartilagineuse pelvienne agressive en IRM ne récuse pas un haut grade (concordance globale 48 %) : relecture et décision en RCP.", "r": ["42874309", "42997475"]}]}], "sources": ["34497298", "41204964", "41838307", "42129022", "42363976", "42736384", "42874309", "42964659", "42997475"]}, {"category_id": "msk_imaging", "evidence": "Niveau de preuve modéré : cohortes diagnostiques (70 à 261 patients), revues de radiomique et atlas iconographiques, publications princeps (Radiology, RadioGraphics).", "bottom_line": "L'IRM fonctionnelle (diffusion/ADC, DCE-MRI, IVIM) améliore la caractérisation des tumeurs des parties molles (AUC 0,86–0,96) et conditionne le ciblage biopsique, le dépistage du nidus d'ostéome ostéoïde et l'évaluation post-ablation, où les critères de viabilité supplantent les critères dimensionnels.", "kpis": [{"v": "AUC 0,96", "l": "Fasciite nodulaire vs sarcome (ADC + queue fasciale)", "r": ["42970180"]}, {"v": "AUC 0,86", "l": "Ktrans / D* (IVIM) – angiogenèse sarcomes", "r": ["42997935"]}, {"v": "35 %", "l": "Nidus d'OO manqués sans séquence dynamique", "r": ["12773675"]}], "sections": [{"k": "indications", "title": "Apports diagnostiques", "items": [{"t": "DCE-MRI au temps artériel précoce (< 30 s) avec wash-out : signature du nidus d'ostéome ostéoïde, indispensable en intra-articulaire.", "r": ["12773675"]}, {"t": "ADC élevé + « fascial tail sign » → fasciite nodulaire ; radiomique et IVIM pour grader les sarcomes et orienter la biopsie vers l'« habitat » le plus agressif.", "r": ["42970180", "42955458", "42997935"]}, {"t": "TTCG/SVN : hyposignal T1/T2 avec blooming T2* (hémosidérine).", "r": ["31601938"]}, {"t": "Lésion solitaire rachidienne/sacrée : topographie (arc postérieur vs corps) et âge orientent le diagnostic ; cartographier V2 et foramen avant geste cervical.", "r": ["18635627", "41473339"]}]}, {"k": "followup", "title": "Suivi post-thérapeutique", "items": [{"t": "Post-cryo desmoïde : fine prise de contraste périphérique régulière à 3–6 mois = cicatrice granulomateuse normale ; hypersignal T1 spontané → soustraction obligatoire.", "r": ["41357250"]}, {"t": "Évaluer la nécrose/viabilité plutôt que la taille (radiomique, mRECIST) après traitement néoadjuvant ou ablation.", "r": ["42955458", "42384128"]}]}], "sources": ["12773675", "18635627", "31601938", "41357250", "41473339", "42955458", "42970180", "42997935", "42384128"]}, {"category_id": "percutaneous_ablation_general", "evidence": "Niveau de preuve modéré : recommandations CIRSE 2022, 2 revues systématiques (endométriose pariétale, chordomes), étude robotique prospective multicentrique, cohortes et revues d'état de l'art.", "bottom_line": "L'ablation percutanée (cryoablation, RF, micro-ondes) suit un paradigme palliatif-curatif : contrôle local à 1 an de 67 % en intention de traiter, > 85 % pour les oligométastases métachrones < 2 cm à corticale intacte ; toute ablation en zone portante doit être couplée à une consolidation.", "kpis": [{"v": "67 % → > 85 %", "l": "Contrôle local 1 an (global → oligo < 2 cm)", "r": ["24859596"]}, {"v": "73 %", "l": "Réponse clinique cryo MSK (0 % complication majeure)", "r": ["42909541"]}, {"v": "8 → 1", "l": "EVA endométriose pariétale (cryo, 8 études)", "r": ["39576446"]}, {"v": "2,0 mm", "l": "Précision robot Epione® (98,9 % succès)", "r": ["42527616"]}], "sections": [{"k": "indications", "title": "Indications retenues", "items": [{"t": "Curatif : oligométastase métachrone < 2 cm, corticale intacte, à distance des nerfs (5 facteurs prédictifs).", "r": ["24859596", "35348870"]}, {"t": "Palliatif : douleur réfractaire ; chordomes rachidiens/sacrés inopérables ou en néoadjuvant (RF + vertébroplastie avant spondylectomie).", "r": ["37742284", "42782915"]}, {"t": "Endométriose pariétale abdominale : cryoablation (80–100 % de réponse complète) ou RF « moving-shot » sous écho (EVA 7,4 → 1,7, −77,5 % de volume).", "r": ["39576446", "42667387"]}]}, {"k": "technique", "title": "Choix de l'énergie", "items": [{"t": "RF : petit nidus intra-osseux, métastase lytique corporéale ; cryoablation : volume > 2–3 cm, extension aux parties molles, matrice sclérotique, visualisation de l'iceball.", "r": ["42645393", "35348870"]}, {"t": "Optimisation de l'iceball par synergie multi-sondes ; baisse de densité TDM (UH) post-cryo dans 94 % des cas comme marqueur simple de nécrose.", "r": ["41720112", "42909541"]}, {"t": "Robotique : utile pour les abords obliques/multi-aiguilles (rachis, bassin).", "r": ["42527616"]}]}, {"k": "safety", "title": "Sécurité", "warn": true, "items": [{"t": "Thermoprotection standardisée (CO2, sérum glucosé/salé, thermocouples) selon les recommandations CIRSE.", "r": ["35348870", "41720112"]}, {"t": "Endométriose pariétale : hydrodissection pour protéger le derme et le péritoine/anses digestives.", "r": ["39576446"]}, {"t": "Zone portante : associer cimentoplastie ou vissage (SINS, Mirels).", "r": ["42645393", "37742284"]}]}], "sources": ["24859596", "35348870", "37742284", "39576446", "41720112", "42527616", "42645393", "42667387", "42782915", "42909541"]}];
